window.__D("text/zohar-chadash/c000",{"p":[[9514011001,"<p>(בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, אָמַר רִבִּי יִצְחָק, מִכָּאן מַשְׁמַע, דַּעֲקָרָן קוּדְשָׁא בְּרִיךְ הוּא לְהַנֵּי נְטִיעָן, וְשָׁתֵיל לוֹן. דִּכְתִיב יְהִי.</p>"],[9514011002,"<p>רַבִּי יְהוּדָה אוֹמֵר אוֹר שֶׁכְּבָר הָיָה, תְּנַן. מַשְׁמַע דִּכְתִיב וַיְהִי אוֹר. וְהָיָה לָא כְתִיב, אֶלָּא וַיְהִי.</p>"],[9514011003,"<p>וְכַד אִסְתַּכַּל קוּדְשָׁא בְּרִיךְ הוּא בְּאִינוּן דָּרִין דְּרַשִּׁיעַיָא, דְּלָא יִתְחֲזוֹן לְהַהוּא נְהוֹרָא, גָּנִיז לֵיהּ. הֲדָא הוּא דִכְתִיב (איוב ל״ח:ט״ו) וַיִּמְנַע מֵרְשָׁעִים אוֹרָם. וּלְמַאן גָּנִיז לֵיה. לְצַדִּיקַיָא. לְצַדִּיקַיָא דַּוְקָא, כְּמָא דִכְתִיב, (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִּיק וּלְיִשְׂרֵי לֵב שִׂמְחָה. וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, הֲדָא הוּא דִכְתִיב, (ישעיהו מלכים א ב׳:כ״ב) מִי הֵעִיר מִמִּזְרָח.</p>"],[9514011004,"<p>וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, מַאי רָאָה. אָמַר רִבִּי חִיָּיא כִּדְקָא אֲמָרָן, חָמָא בְּעוֹבָדֵיהוֹן דְּרַשִׁיעַיָא, וּגְנִיז לֵיהּ. רַבִּי אַבָּא אֲמַר, וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, לִגְנֹז אוֹתוֹ. וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, דְּלָא אִשְׁתְּכַח בֵּיהּ רִיתְחָא. כְּתִיב הָכָא כִּי טוֹב, וּכְתִיב הָתָם (במדבר כ״ד:א׳) כִּי טוֹב בְּעֵינֵי ה' לְבָרֵךְ אֶת יִשְׂרָאֵל. וְסֵיפֵיהּ דִּקְרָא אוֹכַח, דִּכְתִיב, (בראשית א׳:ד׳) וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחשֶׁךְ. וּבְגִין כָּךְ לָא אִשְׁתְּכַח בֵּיהּ רִיתְחָא, וְאַף עַל גַּב דְּשָׁתֵּיף לוֹן קוּדְשָׁא בְּרִיךְ הוּא כַּחֲדָא.</p>"],[9514011005,"<p>תָּא חֲזֵי, נְהִירוּ עִלָּאָה לְמֶהֱוֵי נָהֵיר הַאי אוֹר. וּמֵהַהוּא נְהִירוּ חֵידוּ דְּכֹלָּא בֵּיהּ. וְהוּא יָמִינָא לְאִתְעַטְרָא גְּלוּפֵי גִּלּוּפִין בַּהֲדֵיהּ. וְהָא אִתְּמָר, דִּכְתִיב (תהילים ל״א:כ׳) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ, דָּא אוֹר קַדְמָאָה, דְּגָנֵיז קוּדְשָׁא בְּרִיךְ הוּא לְצַדִּיקַיָא, לְאִינוּן דַּחֲלֵי חַטָאָה כִּדְקָאֲמָרָן. וַיְהִי עֶרֶב, מִסִּטְרָא דְּחשֶׁךְ. וַיְהִי בֹקֶר, מִסִּטְרָא דְּאוֹר. וּמִגּוֹ דְּאִינוּן דְּמִשְׁתַּתְּפִין כַּחֲדָא, כְּתִיב יוֹם אֶחָד.</p>"],[9514011006,"<p>ר' יְהוּדָה אוֹמֵר, מַאי טַעְמָא בְּכָל יוֹמָא וְיוֹמָא כְּתִיב, וַיְהִי עֶרֶב וַיְהִי בֹקֶר. לְמִנְדַע, דְּהָא לֵית יוֹמָא בְּלָא לֵילְיָא, וְלֵית לֵילְיָא בְּלָא יוֹמָא, וְלָא אִתְיְהֵיב לְאַפְרָשָׁא.</p>"],[9514011007,"<p>אָמַר רִבִּי יוֹסֵי, הַהוּא יוֹם דְּנָפַק אוֹר קַדְמָאָה, אִתְפַּשַּׁט בְּכּוּלְהוּ יוֹמֵי, דִּכְתִיב יוֹם בְּכּוּלְהוּ. אָמַר רִבִּי אֶלְעָזָר, מִמַּשְׁמַע דִּכְתִיב בְּכּוּלְהוּ בֹּקֶר, וְלָאו בֹּקֶר אֶלָּא מִסִּטְרָא דְּאוֹר קַדְמָאָה. רַבִּי שִׁמְעוֹן אֲמַר, יוֹמָא קַדְמָאָה אָזֵיל עִם כּוּלְהוּ, וְכּוּלְהוּ בֵּיהּ בְּגִין לְאַחֲזָאָה דְּלָאו בְּהוּ פֵּירוּדָא, וְכוֹלָּא חָד.</p>"],[9514011008,"<p>וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר, אִתְפַּשְׁטוּתָא דְּהַאי אוֹר לְתַתָּא. וְאִלֵּין אִינוּן מַלְאָכַיָא דְּאִתְבְּרִיאוּ בְּיוֹמָא קַדְמָאָה, דְּאִית לוֹן קִיּוּמָא לְאִתְקָיְימָא בְּסִטְרָא יָמִינָא.</p>"],[9514011009,"<p>(בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר. אֶת, לְאַכְלָלָא אַסְפַּקְלַרְיָא דְּלָא נָהֲרָא, עִם אַסְפַּקְלַרְיָא דְנָהֲרָא, דְּאִתְּמָר בֵּיהּ כִּי טוֹב. אָמַר רִבִּי אֶלְעָזָר, אֶת, לְאַכְלָלָא וּלְאַסְגָּאָה אִינוּן מַלְאָכִין, דְּאַתְיָין מִסִּטְרָא דְּאוֹר דָּא, וְכוֹלְהוֹ נָהִירִין בְּקַדְמִיתָא, בְּקִיּוּמָא שְׁלִים.</p>"],[9514011010,"<p>(בראשית א) יְהִי רָקִיעַ בְּתוֹךְ הַמַּיִם, אָמַר רִבִּי יְהוּדָה, בְּהַאי אִתְפְּרִישׁוּ מַיִין עִילָּאִין מִמַּיִין תַּתָּאִין. רָקִיעַ, פְּשִׁיטוּתָא דְּמַיִין. וְהָא אִיתְּמָר וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם בֵּין מַיִין עִילָּאִין לְמַיִין תַּתָּאִין.</p>"],[9514011011,"<p>(בראשית א׳:ז׳) וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ. דַּעֲבֵיד בָּהּ עֲבִידְתָּא בִּסְגִיאוּ עִלָּאָה. וַיְהִי רָקִיעַ לָא כְתִיב, אֶלָּא וַיַּעַשׂ, דְּאַסְגֵי לֵיהּ בִּרְבוּ סַגְיָא.</p>"],[9514011012,"<p>אָמַר רִבִּי יִצְחָק, בַּשֵּׁנִי אִתְבְּרֵי בֵּיהּ גֵּיהִנֹּם, לְחַיָּיבֵי עָלְמָא. בַּשֵּׁנִי אִתְבְּרֵי בֵּיהּ מַחְלוֹקֶת. בַּשֵּׁנִי לָא אִשְׁתְּלֵים בֵּיהּ עֲבִידְתָּא. בְּגִינֵי כָךְ לָא כְתִיב בֵּיהּ כִּי טוֹב, עַד דְּאָתָא יוֹם תְּלִיתָאי, דְּאִשְׁתְּלֵים בֵּיהּ עֲבִידְתָּא. וּבְגִין כָּךְ כְּתִיב בֵּיהּ כִּי טוֹב, תְּרֵי זִמְנֵי. חַד, עַל אַשְׁלָמוּת עֲבִידְתָּא דְּיוֹם שֵׁנִי. וְחַד, לְגַרְמֵיהּ דְּיוֹם תְּלִיתָאי. אִתְתַּקַּן יוֹם שֵׁנִי בְּיוֹם שְׁלִישִׁי, וְאִתְפְּרֵישׁ בֵּיהּ מַחְלוֹקֶת, וּבֵיהּ אִשְׁתְּלִימוּ רַחֲמֵי עַל חַיָּיבֵי גֵּיהִנֹּם. בְּיוֹמָא תְּלִיתָאָה מִשְׁתַּכְּכוּ שְׁבִיבֵי דְּגֵיהִנֹּם, בְּגִינֵי כָךְ אִיתְכְּלֵיל יוֹם שֵׁנִי, וְאִשְׁתְּלֵים בֵּיהּ.</p>"],[9514011013,"<p>רַבִּי חִיָּיא הֲוָה יָתֵיב קַמֵּיהּ דְּר\"שׁ, אָמַר לֵיהּ, הַאי אוֹר בְּיוֹם רִאשׁוֹן, וְחוֹשֶׁךְ בְּיוֹם שֵׁנִי, וְאִתְפְּרִישׁוּ מַיָא וּמַחְלוֹקֶת הֲוָה בֵּיהּ. אַמַּאי לָא אִשְׁתְּלֵים בְּיוֹם רִאשׁוֹן, דְּהָא יָמִינָא כָּלֵיל לִשְׂמָאלָא. אָמַר לֵיהּ, עַל דָּא הֲוָה הַהוּא מַחְלוֹקֶת, וּתְלִיתָאָה בָּעֵי לְמֵיעַל בֵּינַיְיהוּ, לְאַכְרָעָא וּלְאַסְגָּאָה בְּהוּ שְׁלָם.</p>"],[9514011014,"<p>(שם) וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא אִתְחַבְּרוּתָא דְּמַיִין עִילָּאִין בְּתַתָּאִין לְמֶעְבַּד פֵּירִין. מַיִין עִילָּאִין פָּרִין וְרָבְיָין, וְעַבְדִּין אִיבִּין. וְתַתָּאִין קָרָאן לוֹן לְעִילָּאִין, כְּנוּקְבָא לְגַבֵּי דְכוּרָא, בְּגִין דְּמַיִין עִלָּאִין דְּכוּרִין, וְתַתָּאִין נוּקְבִין.</p>"],[9514011015,"<p>רַבִּי שִׁמְעוֹן אֲמַר, כָּל דָּא הוּא לְעֵילָא, וְהוּא לְתַתָּא. אָמַר רִבִּי יוֹסֵי, אִי הָכֵי אֱלֹהִים דְּקָאֲמַר, מַאן אֱלֹהִים. אָמַר לֵיהּ אֱלֹהִים סְתָם, אֱלֹהִים חַיִּים לְעֵילָא. וְאִי תֵימָא לְתַתָּא, אֶלָּא לְתַתָּא אִיהוּ תּוֹלְדוֹת, כְּמָה דְאַתְּ אָמֵר (שם ב) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, וְאַמְרִינָן בְּה\"א בְּרָאָם. וְהַהוּא דִּלְעֵילָא, אֲבָהָן דְּכוֹלָּא הוּא. אִיהִי עָבִיד עֲבֵידְתָּא, וְעַל דָּא אַרְעָא עֲבֵידַת תּוֹלְדוֹת, דְּהָא הִיא מִתְעַבְּרָא כְּנוּקְבָא מִן דְּכוּרָא.</p>"],[9514011016,"<p>ר' אֶלְעָזָר אֲמַר, כָּל חֵילִין הֲווֹ בְּאַרְעָא, וְלָא אֲפֵיקַת חֵילָהָא וְאִינוּן תּוֹלְדוֹת, עַד יוֹם הַשִּׁשִּׁי, דִּכְתִיב (שם א) תּוֹצֵא הָאָרֶץ וְגו'. וְאִי תֵימָא הָא כְתִיב וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא. אֶלָּא אֲפֵיקַת תִּיקּוּן חֵילָהָא לְאִתְיַשְּׁבָא כִּדְקָא יָאוֹת. וְכֹלָּא הֲוָה גָּנִיז בָּהּ עַד דְּאִצְטְרִיךְ. דְּהָא בְּקַדְמִיתָא כְּתִיב תֹּהוּ וָבֹהוּ צַדְיָא וְרֵיקַנְיָא כְּתַרְגּוּמוֹ, וּלְבָתַר אִתְתַּקָּנַת וְאִתְיַשְּׁבַת וְקַבֵּילַת זַרְעָא וּדְשָׁאִין וְעִשְׂבִּין וְאִילָנִין כִּדְקָא יָאוֹת. וַאֲפֵיקַת לוֹן לְבָתַר הָכֵי. וּמְאוֹרוֹת נָמֵי לֹא שִׁמְשׁוּ נְהוֹרָא דִּילְהוֹן עַד דְּאִצְטְרִיךְ.</p>"],[9514011017,"<p>(שם) יְהִי מְאוֹרוֹת בִּרְקִיעַ הַשָּׁמַיִם, מְאֹרֹת כְּתִיב חָסֵר, לְאַכְלָלָא חִיוְיָא בִּישָׁא דְּאַטֵיל זוּהֲמָא וְעָבִיד פֵּירוּדָא, דְּלָא מְשַׁמֵּשׁ שִׁמְשָׁא בְּסִיהֲרָא. מְאֹרֹת: לְוָוטִין. וְעַל דָּא גָּרֵים דְּאִתְלַטְיָא אַרְעָא, דִּכְתִיב אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךָ. וּבְגִין כָּךְ מְאֹרֹת כְּתִיב.</p>"],[9514011018,"<p>יְהִי מְאֹרֹת, דָּא סִיהֲרָא. בִּרְקִיעַ הַשָּׁמָיִם, דָּא שִׁמְשָׁא. וְתַרְוַויְהוּ בִּכְלָלָא חָדָא לְאִזְדַּוְוגָא, לְאַנְהָרָא עָלְמִין לְעֵילָא וְתַתָּא, מַשְׁמַע דִּכְתִיב עַל הָאָרֶץ, וְלֹא כְּתִיב בָּאָרֶץ, דְּמַשְׁמַע לְעֵילָא וְתַתָּא. חוּשְׁבַּן דְּכוֹלָּא בְּסִיהֲרָא הוּא.</p>"],[9514011019,"<p>רַבִּי שִׁמְעוֹן אֲמַר גִּימַטְרִיָּאוֹת וְחוּשְׁבַּן תְּקוּפוֹת וְעִיבּוּרִין, כֹּלָּא הוּא בְּרָזָא דְּסִיהֲרָא, דְּהָא לְעֵילָא לָאו אִיהוּ. אָמַר לֵיהּ ר' אֶלְעָזָר, וְלָא, כַּמָּה חוּשְׁבְּנִין קָא עַבְדֵּי חַבְרַיָיא. אָמַר לֵיהּ, לָאו הָכֵי, אֶלָּא חוּשְׁבָּנָא קָיְימָא בְּסִיהֲרָא, וּמִתַּמָּן יֵיעוֹל בַּר נָשׁ לְמִנְדַע לְעֵילָא. אָמַר לֵיהּ, וְהָא כְתִיב (שם) וְהָיוּ לְאוֹתוֹת וּלְמוֹעֲדִים. אָמַר לֵיהּ לְאֹתֹת כְּתִיב חָסֵר. אָמַר לֵיהּ וְהָא כְתִיב וְהָיוּ. אָמַר לֵיהּ הַוְויָין, דְּכָלְהוֹ דִּיהוֹן בָּהּ, כְּאִסְקוֹפָה דָּא דְּאִתְמַלְיָיא מִכּוֹלָּא, אֲבָל חוּשְׁבְּנָא דְּכֹלָּא, בְּסִיהֲרָא הוּא.</p>"],[9514011020,"<p>תָּא חֲזֵי, נְקוּדָה חָדָא שֵׁירוּתָא מִתַּמָּן לְמִימְנֵי, דְּהָא מַה דִּלְגוֹ מֵהַהוּא נְקוּדָה, לָא אִתְיְידַע, וְלָא אִתְיְיהֵיב לְמִימְנֵי. וְאִית נְקוּדָה לְעֵילָא, סָתִים וְלָא אִתְגַּלְּיָיא כְּלָל, וְלָא אִתְיְידָע, וּמִתַּמָּן שֵׁירוּתָא לְמִימְנֵי, כָּל סָתִים וַעֲמִיקָא. הָכֵי נָמֵי אִית נְקוּדָה לְתַתָּא דְאִתְגַּלְּיָיא, וּמִתַּמָּן הוּא שֵׁירוּתָא לְכָל חוּשְׁבְּנָא וּלְכָל מִנְיָן.</p>"],[9514011021,"<p>וְעַל דָּא הָכָא הוּא אֲתַר, לְכָל תְּקוּפוֹת וְגִימַטְרִיָּאוֹת עִיבּוּרִין זְמַנִּין חַגֵּי וְשַׁבַּתֵּי. וְיִשְׂרָאֵל דְּדָבְקוּ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, עָבְדִין חוּשְׁבְּנָא לְסִיהֲרָא, וְאִינוּן דָּבְקִין בָּהּ, וְסָלְקִין לָהּ לְעֵילָא, דִּכְתִיב (דברים ד) וְאַתֶּם הַדְּבֵקִים בַּה' אֱלֹהֵיכֶם וְגו'.</p>"],[9514011022,"<p>(\"חילופי גירסאות\") מַתְנִיתִין. עֶשֶׂר סְפִירוֹת בְּלִימָה. א. תְּנַן אַרְבַּע תַּקִּיפִין רוּחֵי עָלְמָא, תְּרֵין סִטְרִין מַמָּשִׁין, מַטְלָנוֹי עָבִיד בְּגַוָּון. אַתְקִין חַד בְּלִי כְּלוּם. וְנָפֵיק מִצָּפוֹן, חַד סֵפֶר וְשַׁוֵּי עֲלוֹי תְּלַת אַתְוָון רְשִׁימָן. אַתְקֵין תְּחוֹתוֹי תְּלַת אָחֳרָנִין, רָשִׁים חַד עַל תְּרֵין, וְשַׁוֵּי עֲלוֹי אָת ת'. ב. אַפֵּיק מִצָּפוֹן סֵפֶר תִּנְיָין, בְּאַתְוָון אַרְבַּע, רְשִׁימִין תְּרֵין עַל חַד, וְשַׁוֵּי עֲלוֹי אָת ה'.</p>"],[9514011023,"<p>ג. אַשְׁטַח עַל קוּנְדָא בְּסֵפֶר תְּלִיתָאי, סִטְרָא חַד בְּאַתְוָותָא, חַד רְשִׁימָא בְּכִתְרָא דְמַלְכוּתָא, תָּלֵי לָהּ מְעֵילָא לְעֵילָא, וּמִינָהּ סִטְרָא חַד רָשִׁים אוּמָנָא, וְשַׁוֵּי בָהּ הַהוּא אָת. בְּהַהוּא אָת אוּמָנוּתָא אִשְׁתַּכְלֵל, וְאִשְׁתַּכְלֵל סְטַר צָפוֹן וְאִתְבְּרֵי מִינָהּ, תְּחוֹתוֹהִי אִשְׁתַּכְלָלוּ תְּלַת סִטְרוֹי מִתְּלַת זִיוִיתֵיהּ, וְשַׁוֵּי עֲלוֹי אָת וא\"ו.</p>"],[9514011024,"<p>ה', אַפֵּיק לְעֵילָא קַרְדְּנוּתָא דְּסִיהֲרָא, לָהּ אַרְבַּע רֵישִׁין, בְּסֵפֶר רְבִיעָאָה אַטְבַּע לֵיהּ, בִּכְסִיפָא דִּתְהוֹמָא רַבָּא, הוּא תְּהוֹמָא רַבָּא דְּדִינָא אִתְיְיהֵיב, אֲתַר בֵּי דִינָא מוֹתָבָא. הַהוּא דִּכְתִיב (תהלים לו) מִשְׁפָּטֶיךָ תְּהוֹם רַבָּה. אַשְׁרֵי עֲלוֹי תְּרֵין אַתְוָון רְשִׁימָן בְּעִזְקָתָא דְמַלְכָּא, הִיא עִזְקָא, בָּה נָטְלִין, בָּה שַׁרְיָין. שַׁוֵּי חַד עַל ד', וְאוֹתֵיב עֲלוֹי אָת אָלֶף.</p>"],[9514011025,"<p>ה, אַשְׁטַח עַל זִיוִיתָא דְּסֵפֶר חֲמִישָׁאָה פָּרוֹכְתָּא דִּפְרָסָא, לְאַפְרָשָׁא מִתַּתָּאִין לְעִילָּאִין, בָּהּ אִתְיְיהֵיב רְשׁוּתָא לְמַאן דְּרָשִׁים. מֵעִילוֹי מִינָהּ נָטְלִין בָּהּ תְּרֵין תַּקִּיפִין, אֶלֶף עָלְמִין בֵּיהּ, יְרוּתָא דְאַחְסָנָא סְמִיךְ עֲלוֹי, בֵּיהּ חָמֵשׁ אַתְוָון רְשִׁימִין בִּתְרֵין, תְּלַת עַל תְּרֵין. אַתְקֵין גַּבּוֹי תְּרֵין אָחֳרָנִין, רְשִׁימוּ בְּרָזָא דְּחָמֵשׁ, חָמֵשׁ גּוֹ חָמֵשׁ, שַׁוֵּי עֲלוֹי אָת יו\"ד.</p>"],[9514011026,"<p>ו, אַפֵּיק בְּזִיקִין דְּנוּר, עַל סֵפֶר שְׁתִיתָאָה, תְּרֵין סִטְרִין. סְטַר חַד, מַרְחִישׁ גְּבוּרָן. סְטַר חַד, רוּחַ חָכְמָה דִּבְהִיק. וְהַהוּא זִיוְיָא אִשְׁתַּטַח לִתְלַת אַנְפּוֹי. וְזִיוְיָא דְסִטְרוֹי, קַיָּים לִתְלַת לְתַתָּא. אַרְבַּע בְּאַרְבַּע רְשִׁימִין. חַד לָקֳבֵל חַד שַׁלִּיט. חַד רָכִיב. תְּרֵי אַתְוָון רְשִׁימִין בְּחַד. וְשַׁוֵּי עֲלוֹי אָת ו'.</p>"],[9514011027,"<p>ז, אַשְׁטַח עַל זִיוִיתֵיהּ דְּסֵפֶר שְׁבִיעָאָה, תּוֹקְפָא דִּבְלִי כְלוּם. הוּרְמָנֵי דִּבְרֵיְירֵי, וְעִילְּעוּלָא דְּקוּאַנְרִיתָא, קוּזְמִיטִין בִּשְׁבִיעָאָה, בְּלִימִין עַל שְׁבִיעֲתָא. אִתְנַהֲגָן וְלָא נָטְלָן. נָטְלָן וְלָא אָזְלָן. אָזְלָן וְלָא הַוְיָין. הַוְיָין וְלָא אִתְבָּרְיָין. אִתְבָּרְיָין וְלָא אִתְמַשְׁיָין. עִילָּאִין וְתַתָּאִין, נָחֲתִין סָלְקִין, תְּלַת רְכִיבִין, אַרְבַּע רְשִׁימִין, חַד אִתְחַזְּרוּ, חַד הוּא, דְּחֵילָא דְּחַד שְׁבִיל דְּשָׁארֵי עֲלוֹי, שַׁוֵּי עֲלוֹי אָת ד'.</p>"],[9514011028,"<p>ח, אַפֵּיק עַל עִילָתָא דְּסֵפֶר תְּמִינָאָה, רָשִׁים בְּכֹכָבָא חַד. וְהַיְינוּ בִּרְשִׁימָא חַד. הוּא עַל אַרְבַּע, אַרְבַּע עֲלוֹי. שַׁלִּיט חַד בְּחַד. דָּא קָאִים, דָּא יָתֵיב. דָּא נָסֵיב, דָּא שָׁבֵיק. דָּא סָלֵיק, דָּא נָחַת. מֵחַד תַּלְיָין, מֵחַד אִתְבָּרְיָין. קַדִּישָׁא הוּא. עִילָּאָה הוּא. הוּא הֲוֵי, הוּא חַד. רָשִׁים בְּגַוֵּיהּ אָת ה'.</p>"],[9514011029,"<p>ט, אַשְׁטַח עַל זִיוִתָא עִילָּאָה סֵפֶר תְּשִׁיעָאָה דָּא, וְלָא אִתְחֲזֵי. טְמִירָא בְּמָאתָן וְאַרְבְּעִין וּתְמַנִּין עָלְמִין דְּאָזְלִין בְּגַוֵּיהּ. שְׁקוּלָא בְּצַלְמָא דְּמָארֵי רְשִׁימָא. בְּחָמֵשׁ רְכִיבָא עַל חָמֵשׁ. מַלְכָּא דְּאִינוּן עָלְמִין פָּלְחִין לֵיהּ, נָחֲתָא בִּימָמָא דְּנָהֵיר. סָלְקָא בְּלֵילְיָא דְּאִתְחַשָּׁךְ. רָשֵׁים עֲלָהּ תְּלַת אַתְוָון. שַׁוֵּי עֲלָהּ אָת י'.</p>"],[9514011030,"<p>י', אַפֵּיק מֵרָזִין תְּמַנֵּיסַר אַלְפִין, סֵפֶר עֲשָׂרָה, בְּאָתִין עֲשָׂרָה, בִּשְׁמָא דְּאִתְגְּלַף בְּי', שַׁלִּיטָא בַּעֲשָׂרָה. כַּד מָטָא לְאִזְדַּעְזְעָא בִּתְמַנֵּיסַר עָלְמִין, אַרְבָּע אָתָאן אָזְלִין עֲלָהּ, עֲשָׂרָה בַּעֲשָׂרָה רָכֵיב עֲלָהּ, עִזְקָאן דְּעִזְקָאן אִתְאַחֲדָן מִנֵּיהּ. הוּא וְאִתְּתֵיהּ חַד הוּא.</p>"],[9514011031,"<p>אִתְפַּלְגוּ עֶשֶׂר סְפִירָן אִלֵּין, מֵעֶשֶׂר אָתְוָותִין עִילָּאִין דִּשְׁמֵיהּ קַדִּישָׁא. וּלְקָבֵיל דְּנָא, בַּעֲשָׂרָה אִתְבְּרֵי עָלְמָא, וְאַפֵּיק חֵילֵיהוֹן בְּעֶשֶׂר אֲמִירָן. שְׁמֵיהּ סָתִים, פָּרִישׁ לָא הֲוָה. עֶשֶׂר עַל חָמֵשׁ, חָמֵשׁ עַל עֶשֶׂר. שִׁיתָא עַל חָמֵשׁ, חָמֵשׁ עַל שִׁיתָא. בְּרִיךְ הוּא בְּרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין אָמֵן וְאָמֵן.</p>"],[9514011032,"<p>רַבִּי שִׁמְעוֹן פָּתַח (תהילים ק״ו:ב׳) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ וְגו'. (ירמיהו י׳:ז׳) מִי לֹא יִרָאֲךָ מֶלֶךְ הַגּוֹיִם כִּי לְךָ יָאָתָה וְגו'. בְּאַתְוָון רְשִׁימָן, דִּמְחַקְּקִין עַל גַּבֵּי סְתִימוּ דְּסִטְרָא דְּקִיּוּמָא, סָלְקָן רְתִיכִין בִּרְתִיכִין קַדִּישִׁין. כָּל רְתִיכָא וּרְתִיכָא סָלְקָא בְּאָת רְשִׁימָא. אִתְרְשִׁים אָת בְּקִיּוּמֵיהּ, סָלֵיק בְּגַוֵּיהּ הַהוּא רְתִיכָא. כָּל אָת וְאָת קָאִים עַל קִיּוּמֵיהּ דְּהַהוּא רְתִיכָא דְּאִתְחֲזֵי לֵיהּ. מֵהָכָא סָלְקָא מִלָּה, לְאִתְפָּרְשָׁא כָּל אָת וְאָת, בְּרָזָא דִּרְתִיכָא קַדִּישָׁא, בְּאַרְבַּע סִטְרֵי עָלְמָא.</p>"],[9514011033,"<p>רָזָא דְאָת קַדְמָאָה, סָלְקָא וְנָחֲתָא, סָלֵיק בְּעִטְרוֹי לְגַבֵּי מְאָה עָלְמִין. לְקַבֵּל דָּא, אָת יו\"ד סָלְקָא בִּרְעוּ דְּמַחֲשָׁבָה, וְאִסְתִּים וְלָא אִתְיְידָע.</p>"],[9514011034,"<p>אִתְחַפְיָיא תְּחוֹתֵיהּ חַד אֱגוֹזָא, דְּחַפְיָיא טְמִירָא בִּטְמִירוּ. וְאִיהוּ רְתִיכָא דְּקָיְימָא תְּחוֹת הַהוּא רָזָא טְמִירָא. וְהַהוּא אָת, קָיְימָא בִּגְנִיזוּ נְקוּדָה חָדָא תְּחוֹתֵיהּ. הַהוּא אֱגוֹזָא קָיְימָא בְּשִׁית סָמְכִין, וְסָמְכִין לָהּ בְּשִׁית סִטְרִין. אִינוּן שִׁית סִטְרִין גְּנִיזִין בְּגוֹ הַהוּא אֱגוֹזָא.</p>"],[9514011035,"<p>מִגּוֹ סִטְרָא דְּאָת דָּא, נָפְקָא רְתִיכָא חַד קַדִּישָׁא, וְאִיהוּ רְתִיכָא גָּנֵיז וְלָא אִתְגַלְיָיא, בַּר כַּד נָהֵיר נְהִירוּ דְּהַהִיא אֱגוֹזָא טְמִירָא, כְּדֵין אִתְגְּלֵי הַהוּא רְתִיכָא, וְהַהוּא רְתִיכָא טָמִיר וְגַלְיָא.</p>"],[9514011036,"<p>וְאִיהִי נָפְקָא מִגּוֹ נְצִיצוּ דְּבוּצִינָא, כַּד מָדִיד מִשְׁחָתָא תְּחוֹת קִשְׁרָא קַדְמָאָה, וְהוּא חַד נְצִיצוּ. כַּד מִשְׁחָתָא קָיְימָא, נָהֵיר דָּא, וְסָלְקָא וְנָחֲתָא, וְאִסְתְּמִיךְ תְּחוֹת אָת יו\"ד, וְאִיהִי נְקוּדָה חָדָא. וּלְבָתַר אִתְפַּשַּׁט הַהוּא נְצִיצוּ, וְאַפֵּיק תְּלַת נִיצוֹצִין אָחֳרָנִין, וְאִסְתַּמְּכִין תְּחוֹת קוּצָא תַּתָּאָה דְּיו\"ד.</p>"],[9514011037,"<p>לְבָתַר נָפְקָא מִגּוֹ קִשְּׁרָא תִּנְיָינָא נְצִיצוּ אָחֳרָא דְּנָהֵיר וְסַלְקָא וְנָחֲתָא, וְאִסְתְּמִיךְ תְּחוֹת אָת יו\"ד בְּסִטְרָא אָחֳרָא. לְבָתַר אִתְפַּשַּׁט הַהוּא נְצִיצוּ, וְאַפֵּיק תְּלַת נִיצוֹצִין אָחֳרָנִין, וְאִסְתַּמְּכָן בְּסִטְרָא דָא, תְּחוֹת אָת יו\"ד. לְבָתַר נָפְקָא מִגּוֹ קִשְׁרָא תְּלִיתָאָה נְצִיצוּ אָחֳרָא, וּמִגּוֹ דָא אִתְקַשַּׁר רָזָא דְּחו\"ל בְּמִשְׁחָתָא דְּבוּצִינָא.</p>"],[9514011038,"<p>אִשְׁתְּכָחוּ לְאָת יו\"ד, נְקוּדָה עִלָּאָה, תִּשְׁעָה סָמְכִין, עַל מַה דְּאִסְתַּמֵּיךְ. וְכָלְהוֹ רְתִיכָא לְגַבֵּי אָת דָּא. כְּדֵין אִתְנְהֵיר וְאִסְתַּמֵּיךְ עַל תֵּשַׁע סָמְכִין אִלֵּין, וּכְדֵין נָהֲרִין מִגַּוֵּיהּ תְּמַנְיָא אָחֳרָנִין, וְכָלְהוֹ קָיְימִין בְּרָזָא דְּאָת יו\"ד, נְקוּדָה עִלָּאָה טְמִירָא.</p>"],[9514011039,"<p>אִלֵּין תֵּשַׁע סָמְכִין דִּלְתַתָּא, סָלְקִין בִּשְׁמָא וְלָא סָלְקִין. בְּגִין דְּאִינוּן תֵּשַׁע דְּאִיקְרוֹן אֵין סוֹף. קָיְימִין וְלָא קָיְימִין, וְלָא אִתְיְידָעוּ, וְאִיקְרוֹן וְלָא אִיקְרוֹן, וְלָא יְדִיעוּ כְּלָל, וְאִלֵּין סָלְקִין בִּשְׁמָא וְלָא סָלְקִין.</p>"],[9514011040,"<p>וְרָזָא דָא (שמות ל״ג:י״ט) וְקָרָאתִי בְּשֵׁם ה' לְפָנֶי\"ךָ וְחַנּוֹתִי אֵת אֲשֶׁר אָחוֹן וְרִחַמְתִּי אֵת אֲשֶׁר אֲרַחֵם. לֵית מַאן דְּיָקוּם בְּהוֹן וּבִשְׁמָהָן דִּילְהוֹן, וְלָא אִתְגַלְּיָין לְמֵיקַם בְּאָרְחַיְיהוּ. וְעַל דָּא לָא קָאִים משֶׁה עֲלַיְיהוּ. בְּגִין דַּהֲווֹ מִקַּדְמַת דַּרְגָּא דִילֵיהּ דְּהַהוּא נְצִיצוּ קַדְמָאָה, כְּתִיב לְפָנֶיךָ. וְכֵן כּוּלְהוֹ קָיְימִין, אַקְדִּימוּ לְדַרְגָּא דִילֵיהּ. וְעַל דָּא לָא קָאִים בְּאוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּכָלְהוֹ סָלְקִין גּוֹ מַחֲשָׁבָה, וּמִתַּמָּן מִתְפַּשְׁטִין אוֹרְחוֹי לְכַמָּה סִטְרִין, בִּרְעוּתֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִתְיְידָעוּ כְּלָל.</p>"],[9514011041,"<p>סָלְקָא אָת דָּא, בְּאִלֵּין סָמְכִין לְעֵילָא, בָּטַשׁ מָאן דְּבָטַשׁ, דְּלָא יְדִיעַ, וְאֵין סוֹף נָהֵיר וְלָא נָהֵיר, וְנָחֲתָא, וְלָא יְדִיעַ מִמָּאן דְּנָהֵיר. כַּד נָחֵית אִתְכְּלִילָן בֵּיהּ אִינוּן סָמְכִין וְאִתְפַּשַּׁט. וְכַד אִתְפַּשַּׁט, נְפַק חַד נְהוֹרָא כָּלֵיל מִכּוּלָּן, וְאִתְחַפְיָין בֵּיהּ, כְּמַאן דְּעָיִיל בְּחַד הֵיכָלָא.</p>"],[9514011042,"<p>הַהוּא הֵיכָלָא קָיְימָא בִּתְרֵין סִטְרִין, דִּלְחַפְיָיא וְאִתְגַּלְּיָיא לְעֵילָא. וְאִינוּן תֵּשַׁע סָמְכִין, נָהֲרִין בְּגוֹ הַהוּא הֵיכָלָא, וְאָת יו\"ד אִגְנִיז בְּגוֹ הַהוּא הֵיכָלָא, בְּאִינוּן סָמְכִין. וְהַהוּא הֵיכָלָא אִיקְרֵי ה\"א.</p>"],[9514011043,"<p>זַמִּין וְלָא זַמִּין, אִתְגַּלְּיָיא וְלָא אִתְגַּלְּיָיא, וְלָא אִתְגַּלְּיָיא כְּלָל. בְּרָזָא דָא קָיְימָא אָת יו\"ד, וְכוֹלְהוֹ סָמְכִין, בְּגִין דְּאִיהִי טְמִירָא, וּבָהּ קָיְימָא כֹּלָּא לְאִתְעַטְרָא.</p>"],[9514011044,"<p>הַאי אִית לֵיהּ חָמֵשׁ רְתִיכִין, דְּנָפְקֵי מִגּוֹ הַהוּא נְהִירוּ דְבוּצִינָא, כַּד סָלְקָא לְאַתְרָהּ וְאִתְכְּנֵישַׁת, לְבָתַר דַּעֲבָדַת מִשְׁחָתָא.</p>"],[9514011045,"<p>וְאִלֵּין אִקְרוֹן נִפְלָאוֹת, נ' פְּלָאוֹת. רָזָא דָא בָּעָא דָּוִד מַלְכָּא לְמֵיקַם, עַל חָמֵשׁ רְתִיכִין אִלֵּין, כְּמָה דְאַתְּ אָמֵר גַּל עֵינַי וְאַבִּיטָה נִפְלָאוֹת מִתּוֹרָתֶךָ. וְאִלֵּין כַּד נָהֲרִין וְסָלְקִין לָהּ לְאִתְעַטְרָא, אִתְעֲבִידוּ חָמֵשׁ, לְנַהֲרָא גּוֹ חָמֵשׁ דִּלְתַתָּא, וּדְנָפְקוּ מִינָהּ.</p>"],[9514011046,"<p>וְאִינְהוּ נ' פְּלָאוֹת, נָהֲרִין וְסָלְקִין לָהּ לְעֵילָא וְאִתְעַטְרָן וְאִתְקַשְּׁרָן גּוֹ אִינוּן תֵּשַׁע סָמְכִין אָחֳרָנִין. וְאִינוּן תֵּשַׁע סָלְקִין לְאָת יו\"ד לְעֵילָא לְעֵילָא.</p>"],[9514011047,"<p>כַד נָחֲתִין, וְלָא יְדִיעַ מִמַּאן נָחֲתִין, הַאי ה\"א אִתְעַטְרַת בְּרָזָא דְּאִינוּן נ', וְאִינוּן פְּלָאוֹת, דְּאִינוּן חָמֵשׁ סָמְכִין לְגַוָּוהּ. וְכַד אִתְעַטְרַת וְאִתְפַּשְּׁטַת, אִתְהַדְּרַת מֵרָזָא דְּנו\"ן, לְגוֹ רָזָא דְּה\"א.</p>"],[9514011048,"<p>אִתְפַּשִּׁיטוּ אִילֵּין חָמֵשׁ סָמְכִין לְתַתָּא, וְקָיְימָא עֲלַיְיהוּ כְּדֵין. וְכַד אִתְנְהֵירַת בְּכוֹלְהוֹ, כְּדֵין נָפְקִין מִינָהּ ה' נְהוֹרִין אָחֳרָנִין, מִשְׁתַּנִּין וְלָא מִשְׁתַּנִּין, יָמִינָא וּשְׂמָאלָא.</p>"],[9514011049,"<p>מִכָאן וּלְהָלְאָה, קָיְימָא מִלָּה לְאִסְתַּמָּכָא עַל רָזָא עִלָּאָה, בְּרָזָא דִּשְׁמָא קַדִּישָׁא, לְמֶהֱוֵי סָתִים דָּא בְּדָא, וּלְאִשְׁתַּכְלְלָא רְתִיכָא קַדִּישָׁא.</p>"],[9514011050,"<p>וְאִלֵּין חָמֵשׁ, אִינוּן אַרְבַּע, וְאִינוּן חָמֵשׁ לָקֳבֵיל חָמֵשׁ סָמְכִין. וְאִינוּן אַרְבַּע לָקֳבֵיל אַרְבַּע סִטְרֵי עָלְמָא. וְכָל חַד וְחַד אִית לֵיהּ רְתִיכָא בִּלְחוֹדוֹי.</p>"],[9514011051,"<p>וְכָלְהוֹ רְתִיכִין, כָּלְהוֹ כְּלִילָן כָּל רְתִיכָא וּרְתִיכָא בִּנְהוֹרָא חַד, וְכָל נְהוֹרָא וּנְהוֹרָא אִתְכְּלֵיל בְּאִינוּן סְמָכִין, וְכָל סְמָכָא וּסְמָכָא אִתְכְּלֵיל בְּאָת ה\"א. וְהַאי אָת ה\"א אִתְכְּלֵיל בְּאִינוּן תֵּשַׁע סְמָכִין. וְכָל חַד וְחַד אִתְכְּלֵיל בְּאָת יו\"ד נְקוּדָה עִלָּאָה קַדְמָאָה, לְמֶהֱוֵי כֹּלָּא חַד.</p>"],[9514011052,"<p>מֵהָכָא אִשְׁתְּכָחוּ רְתִיכִין, דְּסָלְקִין עַל אָת ה\"א מִתַּתָּא לְעֵילָא, כ\"ה רְתִיכִין. וְרָזָא דָא, יְבָרְכוּ כ\"ה מִתַּתָּא לְעֵילָא.</p>"],[9514011053,"<p>מֵאָת ה\"א וּלְעֵילָא תֵּשַׁע רְתִיכִין, דְּקָיְימִין בִּלְחוֹדוֹי בְּלָא חוּשְׁבְּנָא, עַד רָזָא דְּיו\"ד, וְכֹלָּא אִסְתֵּים בְּגַוֵּיהּ. מִכָּאן וּלְהָלְאָה רָזָא דִשְׁמָא קַדִּישָׁא, דְּאִתְעַטְרָא בְּאִינוּן רְתִיכִין, וּלְאִתְכְּלָלָא דָּא בְּדָא, בְּאִלֵּין אַתְוָון יהו\"ה.</p>"],[9514011054,"<p>אָמַר רַבִּי שִׁמְעוֹן, קוּדְשָׁא בְּרִיךְ הוּא אִיקְרֵי אֶחָד, דִּכְתִיב (דברים ו) ה' אֱלֹהֵינוּ ה' אֶחָד. קוּדְשָׁא בְּרִיךְ הוּא אִיקְרֵי רִאשׁוֹן, דִּכְתִיב (ישעיהו מ״ד:ו׳) אֲנִי רִאשׁוֹן. קוּדְשָׁא בְּרִיךְ הוּא אִיקְרֵי אַחֲרוֹן, דִּכְתִיב וַאֲנִי אַחֲרוֹן. בְּרִיךְ הוּא וּבְרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמַיָא.</p>"],[9514011055,"<p>ה\"א רָזָא דִּכְתִיב וַאֲנִי אַחֲרוֹן, דָּא ה\"א בַּתְרָאָה דִּשְׁמָא קַדִּישָׁא. רְתִיכָא קַדִּישָׁא בָּאַחֲרוֹן, דִּכְתִיב (שם מא) וְאֶת אַחֲרוֹנִים אֲנִי הוּא. אַחֲרוֹן וְאַחֲרוֹנִים כָּלְהוֹ בְּרָזָא חָדָא אִתְכְּלִילוּ אִלֵּין בְּאִלֵּין. רָזָא דְּה\"א, אִינוּן ד', וְאִלֵּין ד' דְּאִיקְרוֹן אַחֲרוֹנִים, כָּלְהוֹ קָיְימִין מִסִּטְרָא דִּלְעֵילָא וּמִסִּטְרָא דִּלְתַתָּא.</p>"],[9514011056,"<p>רְתִיכָא דָא, מִיכָאֵל גַּבְרִיאֵל רְפָאֵל אוֹרִיאֵל, אִלֵּין אִינוּן אַרְבַּע, וְחָדָא נְקוּדָה דְּקָיְימָא עֲלַיְיהוּ אִינוּן ה\"א. וְלָא אִיקְרֵי ה\"א דָּא, אֶלָּא בְּרָזָא דְּאִלֵּין אַרְבַּע, וּנְקוּדָה בַּתְרָאָה דְּשַׁרְיָיא עֲלַיְיהוּ. וְרָזָא דְּה\"א דָּא דל\"ת הֲוַת, וְהַהוּא נְקוּדָה דְּשָׁרְיָיא עֲלַיְיהוּ בְּאֶמְצָעִיתָא אִתְעֲבֵיד ה\"א.</p>"],[9514011057,"<p>וּבְרָזָא דַּחֲנוֹךְ, אִית ה\"א אָחֳרָא לְתַתָּא, דְּקָיְימָא מִתְקַשְּׁרָא בְּהַאי ה\"א, וְכֹלָּא חַד בְּחַד, וּכְדֵין אִיהוּ עִידָן לְמִבְכֵּי, וְסִימָנֵיךְ אַהָה.</p>"],[9514011058,"<p>בְּגִין דְּסַחֲרָנוֹ בִּישָׁא לְתַתָּא, חַפְיָיא כְּגַוְונָא דְּדל\"ת, וְסַחֲרָא לְאִלֵּין אַרְבַּע, וּלְהַאי נְקוּדָה. וְקָיְימָא בְּהַאי נְקוּדָה קְלִיפָּא תַּקִּיפָא, לְחַפְיָיא עֲלָהּ. וּכְדֵין אִתְכַּסִּיאַת סִיהֲרָא, וּנְהִירוּ דִּילָהּ אִתְחַפְיָיא, וּכְדֵין אִתְיְיהֵב רְשׁוּ לְמֵידַן עָלְמָא בְּדִינִין בִּישִׁין. וְרָזָא דְּה\"א וְה\"א בַּתְרָאָה תַּרְוַויְיהוּ בְּחַד נְקוּדָה ה\"ה. דְּהָא כְּדֵין דִּינָא אִתְיְהֵיב בְּרָזָא דִּכְתִיב (דניאל ד׳:י״ד) בִּגְזֵרַת עִירִין פִּתְגָמָא וּמֵאמַר קַדִּישִׁין שְׁאֵלְתָא עַד דִּבְרַת וְגו'.</p>"],[9514011059,"<p>רְתִיכָא דָא קָיְימָא בְּה\"א בַּתְרָאָה, לָא אִיתְפָּרְשָׁן דָּא מִן דָּא לְעָלְמִין. וּבְכָל אֲתַר דְּיִשְׁתְּכַח מִיכָאֵל דְּאִיהוּ רֵישָׁא לְאִלֵּין, תַּמָּן אִיהִי שְׁכִינְתָּא. כֹּלָּא אִתְקַשַּׁר דָּא בְּדָא, וְאִינוּן מִתְקַשְּׁרִין גּוֹ הַהוּא נְקוּדָה וְכֹלָּא ה\"א.</p>"],[9514011060,"<p>וְכַד אִיהִי חַד ה\"א, וְאָת אל\"ף אוֹ אָת יו\"ד קָדְמָא לָהּ, וְאִיהִי בְּחַד נְקוּדָה, כְּדֵין אִיהִי אַתְיָיא לְאוֹטָבָא לְעָלְמָא, א\"ה אוֹ י\"ה, דְּהָא קְלִיפָּא בִּישָׁא אִיתַּבְרַת מִקַּמָּהּ, וְלָא חַפְיָיא עֲלָהּ. הָא' י', קָיְימָא בְּרָזָא דָא.</p>"],[9514011061,"<p>כְגַוְונָא דָא, לֵית לָךְ שְׁמָא קַדִּישָׁא בְּאַתְוָון רְשִׁימִין, דְּלָא קָיְימָא בְּהַהוּא אָת רְתִיכָא דִּילֵיהּ, בְּהַהוּא שְׁמָא, עַל מַה דְּאִיסְתַּמֵּיךְ. וְהַהוּא רְתִיכָא סְמָכָה דִילֵיהּ. דְּלֵית לָךְ מַלְכָּא דְּלָא אָתֵי בְּחֵילוֹי וְלָא אִשְׁתְּכַח יְחִידָאי, וְעַל דָּא ידו\"ד צְבָאוֹת כֹּלָּא כַּחֲדָא, דְּלָא אִיתְפַּרְשָׁן רְתִיכִין מִן שְׁמָא קַדִּישָׁא, וְכָל אָת וְאָת כָּלֵיל בְּגַוֵּיהּ רְתִיכָא דִּילֵיהּ, וּכְדֵין כֹּלָּא אִיהוּ שְׁמָא קַדִּישָׁא.</p>"],[9514011062,"<p>הַאי אָת ה\"א, אִית לָהּ רְתִיכָא, בְּאִינוּן שַׁלִּיטִין לְתַתָּא. בְּגִין דְּאָת דָּא אִיהִי בְּאִתְגַּלְּיָיא, זְעֵירָא דְּמִן חַבְרַיָיא. אֲבָל כָּלְהוֹ אַתְוָון אָחֳרָנִין, לֵית לוֹן רְתִיכָא, לְאִתְכְּלָלָא בְּאִינוּן אַתְוָון, בְּאִלֵּין תַּתָּאֵי, בַּר הַאי. בְּגִין דְּאָת דָּא אִתְכְּלֵיל בְּתַתָּאי דִּלְבַר, וְאַתְוָון אָחֳרָנִין אִתְכְּלִילוּ בְּהוֹן רְתִיכִין קַדִּישִׁין דְּלָאו אִינוּן לְבַר. בַּר, כַּד מִתְחַבְּרָן הֵיכָלִין בְּהֵיכָלִין, תַּתָּאֵי בְּעִילָּאֵי, אֲבָל לָא אִיתְכְּלִילָן בְּאִינוּן אַתְוָון לְמֶהֱוֵי חַד אָת.</p>"],[9514011063,"<p>וּבְגִין כָּךְ, כָּל שְׁמָא וּשְׁמָא מִן שְׁמָהָן קַדִּישִׁין, אִתְכְּלֵיל רְתִיכָא קַדִּישָׁא בְּגַוֵּיהּ וְדָא הוּא שְׁמָא קַדִּישָׁא כִּדְקָא יָאוֹת. וְכֵן לְכָל אָת וְאָת מֵאִינוּן אַרְבַּע. וְאִינוּן אַרְבַּע אַתְוָון, אִינוּן רָזָא דִרְתִיכָא, לְמַאן דְּלָא אִתְיְידָע. וּלְכָל אָת וְאָת, אִית לֵיהּ רְתִיכָא דְּאִתְכְּלֵיל בְּגַוֵּיהּ, וְאִתְרְשִׁים בְּהַהוּא אָת מַמָּשׁ.</p>"],[9514011064,"<p>הַאי ה\"א, אִיהִי תְּרֵיסַר. וְהַאי נְקוּדָה דְּקָיְימָא לְעֵילָא, אִיהִי תְּלֵיסַר. וְאִינוּן תְּלֵיסַר מְכִילָן דְּרַחֲמֵי לְתַתָּא, כְּגַוְונָא דִלְעֵילָא. הַנֵּי תְּרֵיסַר, אִינוּן תְּרֵיסַר תְּחוּמִין, וְאִינוּן לְד' סִטְרֵי עָלְמָא, תְּלַת תְּלַת לְכָל סְטַר.</p>"],[9514011065,"<p>וְאִינוּן תְּלַת, אִינוּן תִּשְׁעָה לְכָל סְטַר. לִסְטַר מִזְרָח תִּשְׁעָה. לִסְטַר מַעֲרָב תִּשְׁעָה. לִסְטַר צָפוֹן תִּשְׁעָה. לִסְטַר דָּרוֹם תִּשְׁעָה. וְהַאי נְקוּדָה דְּקָיְימָא עֲלַיְיהוּ בְּאֶמְצָעִיתָא. אִשְׁתְּכַח הַאי נְקוּדָה דְּאַשְׁלֵים לְכָל סְטַר לַעֲשָׂרָה, בְּגִין דְּקָיְימָא בְּאֶמְצָעִיתָא. לִסְטַר מִזְרָח עֲשָׂרָה. לִסְטַר מַעֲרָב עֲשָׂרָה. לִסְטַר צָפוֹן עֲשָׂרָה. לִסְטָר דָּרוֹם עֲשָׂרָה. עֶשֶׂר סְפִירָן לְכָל סְטַר. וְאִלֵּין אִינוּן מ' אַתְוָון, דְּקָיְימִין בְּרָזָא דִבְרֵאשִׁית לְתַתָּא, בְּרָזָא דִשְׁמָא קַדִּישָׁא, וּתְרֵין אִינוּן לְאַחֲדָא בְּיָמִינָא וּשְׂמָאלָא. וְכָלְהוֹ קָיְימִין בְּרָזָא דְּה\"א.</p>"],[9514011066,"<p>הַשְׁתָּא אִשְׁתְּכַח דְּה\"א דָא, בְּכָל אִינוּן רָזִין עִילָאִין: בְּהַהוּא רְתִיכָא קַדִּישָׁא. בְּאִינוּן תְּרֵיסַר. בְּרָזָא דְּעֶשֶׂר סְפִירָן. בְּרָזָא דְּמ\"ב אַתְוָון מְחַקְּקָן דְּבִשְׁמָא קַדִּישָׁא. כֹּלָּא אִתְכְּלֵיל בְּהַאי דִּיוּקְנָא דְּה\"א.</p>"],[9514011067,"<p>וְכָלְהוֹ קָיְימֵי בַּאֲלַכְסוֹנָא, בְּרָזָא דִּנְקוּדָה דְּקָיְימָא בְּאֶמְצָעִיתָא, דְּאַכְרַע לְכָלְהוֹ בְּאוֹרַח מֵישָׁר, סִטְרָא דָא בְּסִטְרָא דָא, וְכֵן לְד' סִטְרִין, כָּלְהוֹ קָיְימֵי בְּמַתְקְלָא, תַּקְלָא דְּקָיְימָא לְאַתְקָנָא כֹּלָּא.</p>"],[9514011068,"<p>בְּרָזָא דָא, אִתְבְּרִיאוּ וְאִתְתַּקָּנוּ כָּל הָנֵּי תַּתָּאֵי. עַל דָּא כְּתִיב (בראשית א׳:כ״ו) וַיֹּאמֶר אֱלֹהִים נַעֲשָׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ. נַעֲשֶׂה, וַדַּאי אִיהוּ ה\"א, וְכָל הַנֵּי דְּקָיְימִין לְתַתָּא, וְאִתְאַחֲדוּ בָהּ, בִּדְיוֹקְנָה מַמָּשׁ. כְּמָא דְאִיקְרֵי ה'. בַּר מַה דְּאִית חָדָא לְעֵילָא, בַּמֶּה דְּלָא אִתְחֲזֵי כְּלַל בִּדְיוֹקְנָהָא, וְלָא אִיתְרְשִׁים בָּהּ לְאִיתְחֲזָאָה.</p>"],[9514011069,"<p>כַד אִקְרֵי ה\"א, אִזְדַּמְּנַת בְּכָל הַנֵּי רָזִין. אִיהוּ כֹּלָּא, בְּגִין דָּא קָיְימָא הַאי נְקוּדָה גּוֹ אֶמְצָעִיתָא, בְּגִין דְּאִתְאַחִידַת בְּכוֹלָּא, אִלֵּין דְּלִסְטַר מִזְרָח, אִתְאֲחִידַת בָּהּ, וְאִיהוּ עִמְּהוֹן. אִלֵּין דְּלִסְטַר דָּרוֹם אִתְאֲחִידַת בָּהּ, וְאִיהִי עִמְּהוֹן. אִילֵּין דְּלִסְטַר צָפוֹן, אִתְאֲחִידַת עִמְּהוֹן וְאִיהִי עִמְּהוֹן, וּבְגִין כָּךְ אִיהִי בְּכֹלָּא, וְכֹלָּא בָּהּ, וְכֹלָּא ה\"א. וְעַל דָּא כְּתִיב, נַעֲשֶׂה אָדָם, וּכְתִיב וַיֹּאמֶר אֱלֹהִים, כֹּלָּא אִיהוּ בְּרָזָא עִילָּאָה כִּדְקָא חָזֵי.</p>"],[9514011070,"<p>וְכָל הַנֵּי רָזִין, וְכָל רָזִין עִילָּאִין, כָּלְהוֹ אִשְׁתְּמוֹדְעָן בְּהַנֵּי אַתְוָון, וְאִתְרְשִׁימוּ בְּהַהוּא אָת מַמָּשׁ, לְאִתְיַיחֲדָא שְׁמָא קַדִּישָׁא כִּדְקָא יָאוֹת. וְכֹלָּא רָזָא עִילָּאָה בִּשְׁמָא קַדִּישָׁא. עַד הָכָא אִיתְרְמִיזַת חָכְמָה עִילָּאָה, בְּרָזָא דְּאָת ה\"א בַּתְרָאָה דְּאַתְוָון אַרְבַּע. זַכָּאָה חוּלְקֵיהּ מַאן דְּעָאל וּנְפַק, וְיָדַע אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא לְמֵיעַל בְּלָא כִיסוּפָא לְעָלְמָא דְאָתֵי.</p>"],[9514011071,"<p>רָזָא דְּאָת ו\"ו רְתִיכָא קַדִּישָׁא עִילָּאָה, דְּקָיְימָא בְּקִיּוּמָא שְׁלִים הַאי אִתְפְּלַג לִתְרֵין אַתְוָון, דְּאִינוּן תְּרֵין וָוי\"ן ו\"ו, דָּא כְּגַוְונָא דְּדָא, וְאִינוּן תְּרֵיסַר רָזִין עִילָּאִין.</p>"],[9514011072,"<p>הַאי ו\"ו עִילָּאָה, אִיהוּ קָיְימָא בְּחָמֵשׁ סָמְכִין עִילָּאִין, דְּקָיְימָא עֲלַיְיהוּ אָת ה\"א עִילָּאָה. וְהַאי ו\"ו, אַף עַל גַּב דְּאִיהוּ שִׁית, וְרָזָא דְשִׁית, אִיהוּ חָמֵשׁ, וְרָזָא דְּחָמֵשׁ, וְכֹלָּא אִיהוּ כִּדְקָא חָזֵי.</p>"],[9514011073,"<p>שֵׁירוּתָא בְּסִטְרָא דְּיָמִינָא, רָזָא דִּנְהִירָא קַדְמָאָה דָא, קָיְימָא עַל רְתִיכָא חָדָא, דְּאִיהוּ תְּלַת תְּלַת, וְלָא אַרְבַּע. וְאַף עַל גַּב דְּלֵית רְתִיכָא אֶלָּא בְּאַרְבַּע, כֹּלָּא הָכָא בְּרָזָא בִּתְלַת תְּלַת. כְּמָה דְּאַתְוָון אָזְלִין בִּשְׁמָא קַדִּישָׁא. וּבְגִין כָּךְ כֹּלָּא אָזְלָא בִּתְלַת תְּלַת.</p>"],[9514011074,"<p>אָת ה\"א דְּקָאֲמַרְתְּ, אִיהִי רְבִיעֲתָא דְּאַתְוָון. וּבְגִין כָּךְ רְתִיכָא דִילָהּ אִיהִי בְּאַרְבַּע. וְאַף עַל גַּב דְּאִיהִי בְּאַרְבַּע, אִיהִי בִּתְלַת תְּלַת. וְכֹלָּא אָזְלָא בְּאֹרַח מֵישָׁר, לְסַלְקָא דָּא כְּגַוְונָא דְדָא, לְמֶהֱוֵי חָד.</p>"],[9514011075,"<p>רְתִיכָא דְּלִסְטַר דָּרוֹם, דְּאִיהוּ יָמִינָא, בִּתְלָתָא דִּי נָפְקָא מִגּוֹ בּוּצִינָא. כַּד סָלְקָא רוּחָא דְנָשִׁיב בְּי\"ב רוּחִין, דְּסָלְקִין רֵיחָא, וְלָא סָלְקִין, כָּלֵיל בִּתְלַת גְּוָונִין, נָהֵיר בִּנְהִירוּ, אִישְׁתָּאַב בְּגַוָּוהּ. חַד לָהִיט בְּאֶשָׁא, וְחַד לָהִיט בְּמַיָא, וְחַד לָהִיט בְּרוּחָא. וְהַאי אִתְפְּרַשׁ, וַהֲוֵי תְּלַת.</p>"],[9514011076,"<p>הַאי רוּחָא, כַּד אִתְפְּרַשׁ וַהֲוֵי תְּלַת גְּוָונִין, אִלֵּין לָאו אִינוּן אֶשָׁא, וְלָאו אִינוּן מַיָא, וְלָאו אִינוּן רוּחָא, אֶלָּא הַאי רוּחָא כַּד אִתְפְּרַשׁ, כָּל חַד וְחַד נָהֵיר וְלָהִיט וְיָהֵיב תּוּקְפָא לַאֲתַר דַּעֲלֵיהּ, וּלְבָתַר אִתְעֲבֵיד סֶמֶךְ תְּחוֹתוֹי.</p>"],[9514011077,"<p>גּווָֹנָא חַד אִתְלַהֵיט, וְאַתְקֵף בֵּיהּ אֶשָׁא, דְּאִתְכְּלֵיל בְּהַאי סִטְרָא דְּיָמִינָא. גּווָֹנָא אָחֳרָא אִתְלַהֵט, וְאִתְתַּקֵּף בֵּיהּ מַיָא, דְּאִתְכְּלִילוּ בְּיָמִינָא. גּווָֹנָא אָחֳרָא אִתְלַהֵיט, וְאַתְקֵף בֵּיהּ רוּחָא, דְּאִתְכְּלֵיל בְּהַאי סִטְרָא דְּיָמִינָא. וְאִלֵּין תְּלַת גְּוָונִין אִינוּן רְתִיכָא חָדָא לִסְטַר יָמִינָא, בְּרָזָא דְּאָת ו\"ו.</p>"],[9514011078,"<p>וְאִלֵּין אִינוּן כִּינּוּיִין, דְּאִית בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, בְּרָזָא דְּאִינוּן שְׁמָהָן דְּאִיקְרֵי בְּהוּ. וְעַל דָּא שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיקְרֵי בְּכַמָּה שְׁמָהָן, וְכָלְהוֹ אִתְכְּלִילָן בְּכָל רָזָא וְרָזָא מֵאִלֵּין סִטְרִין עִילָּאִין, דְּאִינוּן שְׁמָהָן דְּלָא נִמְחָקִין.</p>"],[9514011079,"<p>סְטַר דָּא דְּאִיהוּ יָמִינָא, אִיקְרֵי אֵל. רְתִיכָא דִּילֵיהּ אִיקְרֵי גָּדוֹל בִּכְלָלָא. כַּד אִתְפַּרְשָׁן הַאי רְתִיכָא דְּאִלֵּין, אִינוּן תְּלַת גְּוָונִין, הָכֵי אִינוּן שְׁמָהָן אִיקְרוֹן: גָּדוֹ\"ל, חֲסִי\"ן, קָדוֹ\"שׁ. הַנֵּי אִינוּן רְתִיכָא לְיָמִינָא, דְּאִיקְרֵי אֵל, רָזָא עִילָּאָה מֵאִינוּן שְׁמָהָן עֲשָׂרָה. כְּמָה דְּאוֹקִימְנָא.</p>"],[9514011080,"<p>הַנֵּי תְּלַת גְּוָונִין, דְּאִינוּן רְתִיכָא לִסְטַר יָמִינָא, לָהֲטִין וְנָהֲרִין. וְכָל גּווָֹון וְגווָֹן מֵהַנֵּי תְּלָתָא, אִתְפְּרֵישׁ לִתְרֵין אָחֳרָנִין לְכָל סְטַר. עַד דְּעָאלוּ בְּחוּשְׁבְּנָא תְּלַת תְּלַת, וְאִינוּן תֵּשַׁע. וְהַאי יָמִינָא דַּעֲלַיְיהוּ רָכֵיב, אַשְׁלִים לַעֲשָׂרָה. אוּף נָמֵי כָּל הַנֵּי אִיקְּרוֹן סְפִירָן עִילָּאִין וּזְעִירִין, וְכוֹלְהוֹ מִדִּין דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514011081,"<p>תְּרֵין דְּנָפְקוּ מִגּוֹ גּווָֹן חַד דְּאִתְתַּקֵּף בֵּיהּ מַיָא, חַד אִיקְרֵי רַחוּם, וְחַד אִיקְרֵי חַנּוּן, אִלֵּין אִינוּן מֵהַהוּא גּווָֹן דְּאִיתְתַּקֵּף בְּמַיָא. תְּרֵין דְּנָפְקוּ מֵהַהוּא גּוָֹון דְּאִיתְקֵף בֵּיהּ אֶשָׁא, חַד אִיקְרֵי אֶרֶךְ אַפַּיִם, וְחַד אִיקְרֵי רַב חֶסֶד. אִלֵּין אִינוּן מֵהַהוּא גּווָֹן דְּאִתְתַּקֵּף בֵּיהּ אֶשָׁא. תְּרֵין דְּנָפְקוּ מֵהַהוּא גּווָֹן דְּאִתְתַּקֵּף בֵּיהּ רוּחָא, חַד אִיקְרֵי חָסִיד וְחַד אִיקְרֵי סוֹלֵחַ. וּבְרָזָא דְּסִפְרָא דַּחֲנוֹךְ, הַאי אִיקְרֵי טוֹב, וְהַאי אִיקְרֵי יָשָׁר. וְסִימָנָךְ (תהילים כ״ה:ח׳) טוֹב וְיָשָׁר ה'.</p>"],[9514011082,"<p>וּמֵאִלֵּין מִתְפָּרְשִׁין נְהוֹרִין לְתַתָּא. וְכוֹלְהוֹ רְתִיכִין אִלֵּין לְאִלֵּין. וְכָלְהוֹ כִּנּוּיִין לְבַר, אֲבָל לָא מִתְדַּבְּקִין בְּאִלֵּין לְגַבֵּי עֵילָא. וְכָלְהוֹ כְּלִילָן בְּסִטְרָא דְּיָמִינָא. וְכָלְהוֹ חַד לְגַבֵּי הַאי סִטְרָא. וְכֹלָּא בְּרָזָא דְּאָת ו\"ו.</p>"],[9514011083,"<p>שֵׁירוּתָא בְּסִטְרָא דִשְׂמָאלָא, רָזָא דַּחֲשׁוֹכָא, דְּמִתְפַּשְּׁטָא בַּחֲשׁוֹכָא לְתַתָּא, עַד דְּאִיתְבְּרֵי מִנֵּיהּ גֵּיהִנֹּם, מְלַהֲטָא מֵהַהוּא חֲשׁוֹכָא דְּאֶשָׁא תַּקִּיפָא, סוּמְקָא אוּכְמָא. וְהָכָא מְלַהֲטִין שְׁבִיבִין תַּקִּיפִין, דְּנָגְדִין וְאִתְמַשְׁכָן לְתַתָּא. וְכָלְהוֹ מִגּוֹ חֲשׁוֹכָא דְּאִיהִי שְׂמָאלָא, לְהַאי סִטְרָא.</p>"],[9514011084,"<p>בַּר בּוּצִינָא סָלְקָא מִגּוֹ מְדִידוּ דְּמִשְׁחָתָא נָהֵיר לִסְטַר יָמִינָא, וּמֵהַהוּא נְהִירוּ נָהֵיר לְגַבֵּי חֲשׁוֹכָא, וּמָטִין לְגַבֵּי הַהִיא אֶשָׁא נְהוֹרִין, וְקָרְבִין לְגַבֵּי הַהוּא אֶשָׁא, לְגַבֵּי הַהוּא יָמִינָא, וְנָהֵיר מִנִּיהּ.</p>"],[9514011085,"<p>כְדֵין אִתְפְּשַׁט וְנָהֵיר מִגּוֹ בּוּצִינָא, רוּחָא אָחֳרָא, מְלַהֲטָא. הָא אִיהוּ אִתְפְּשַׁט לְמֶהֱוֵי רְתִיכָא לְהַהוּא סְטַר דִּשְׂמָאלָא. אִתְפְּשַׁט בְּרָזָא דִּתְלַת גְּוָונִין, לְגַבֵּי הַאי סְטַר דְּאִיקְרֵי צָפוֹן, וְהַאי רוּחָא לָא סָלֵיק בְּבוּסְמִין, וְלָא רֵיחָא, בְּגִין דְּהַאי שְׂמָאלָא אִיסְתְּמִיךְ עַל הַהוּא רוּחָא דְּאִתְפְּרַשׁ בִּתְלַת גְּוָונִין אִלֵּין.</p>"],[9514011086,"<p>אִלֵּין גְּוָונִין נָהֲרִין בִּתְלַת סִטְרִין דְּאֶשָׁא, דְּאִיהוּ סִטְרָא דִשְׂמָאלָא. אֶשָׁא גּוָֹון חָשׁוּךְ, אֶשָׁא גּווָֹן סוּמְקָא, אֶשָׁא גווָֹן אוּכְמָא. הַנֵּי תְּלַת גְּוָונִין דְּמִתְפָּרְשָׁן מֵהַהוּא רוּחָא דְּנָפְקָא מִגּוֹ בּוּצִינָא, סָמְכִין לִתְרֵין סִטְרִין.</p>"],[9514011087,"<p>גַּוְונָא חַד אִתְלַהֵט, וְאִתְתַּקֵּף בֵּיהּ אֶשָא גּווָֹן חָשׁוּךְ דְּאִיהוּ בִּסְטַר שְׂמָאלָא. גּווָֹן אָחֳרָא אִתְלַהֵט, וְאִיתְתַּקֵּף בֵּהּ אֶשָׁא גּווָֹן סוּמָק, דְּאִיהוּ בִּסְטַר שְׂמָאלָא. גּווָֹנָא תְּלִיתָאָה אִתְלַהֵיט, וְאִתְתַּקֵּן בֵּיהּ אֶשָׁא גּווָֹן אוּכָם, דְּאִיהוּ בְּהַהוּא סְטַר שְׂמָאלָא.</p>"],[9514011088,"<p>וְאִלֵּין תְּלַת גְּוָונִין, אִינוּן רְתִיכָא חָדָא לִסְטַר שְׂמָאלָא, בְּרָזָא דְּאָת ו\"ו. אִלֵּין אִיקְרוּן כִּינּוּיִין לְהַקָּדוֹשׁ בָּרוּךְ הוּא בְּרָזָא דִשְׂמָאלָא. חַד אִקְרֵי אַדִּיר. וְחַד אִיקְרֵי חָזָק. וְכֹלָּא בִּכְלָלָא חָדָא אִיקְרֵי גִבּוֹר. בְּגִין דְּסִטְרָא דָא דְּאִיקְרֵי שְׂמָאלָא, אִיהוּ אֱלֹהִים. וְהָא אוֹקִימְנָא לְכַמָּה סִטְרִין אִיקְרֵי אֱלֹהִים.</p>"],[9514011089,"<p>הַנֵּי תְּלַת גְּוָונִין דְּאִינוּן בִּסְטַר שְׂמָאלָא, מְלַהֲטִין נָהֲרִין לְתַתָּא, וְכָל גּווָֹן וְגווָֹן מֵהַנֵּי תְּלָתָא, אִיתְפְּרֵישׁ לִתְרֵין אָחֳרָנִין לְכָל סִטְרָא, עַד דְּעָאלוּ בְּחוּשְׁבְּנָא תְּלַת תְּלַת, אִינוּן תִּשְׁעָה, כְּמָה דְּאוֹקִימְנָא בְּסִטְרָא אוֹחֳרָא. וְהַאי שְׂמָאלָא דַּעֲלַיְיהוּ רְכֵיב, אַשְׁלִים לַעֲשָׂרָה.</p>"],[9514011090,"<p>תְּרֵין דְּנָפְקוּ מִגּוֹ גּווָֹן דְּחַד דְּאִתְכְּלֵיל גּוֹ אֶשָׁא גּווָֹן חָשׁוּךְ, חַד אִקְרֵי שׁוֹפֵט וְחַד אִיקְרֵי דַּיָּין. כְּמָה דְאַתְּ אָמֵר (תהלים נ) אֱלֹהִים שׁוֹפֵט, וּכְתִיב (שם סח) אֲבִי יְתוֹמִים וְדַיַּין אַלְמָנוֹת אֱלֹהִים.</p>"],[9514011091,"<p>תְּרֵין דְּנָפְקוּ מִגּוֹ גּווָֹן חַד דְּאִתְכְּלֵיל מִגּוֹ אֶשָׁא סוּמְקָא, חַד אִיקְרֵי כַּבִּיר כֹּחַ. וְחַד אִיקְרֵי אִישׁ מִלְחָמָה. תְּרֵין דְּנָפְקוּ מִגּוֹ גּווָֹן חַד דְּאִתְכְּלֵיל וְאִתְתַּקֵּף גּוֹ גּווָֹן אֶשָׁא אוּכְמָא. חַד אִיקְרֵי פּוֹקֵד עָוֹן, וְחַד אִיקְרֵי מְשַׁלֵּם גְּמוּל.</p>"],[9514011092,"<p>וּמֵהָכָא אִתְפָּרְשָׁן לְתַתָּא, לְכַמָּה גְבוּרָן דְּלֵית לוֹן חוּשְׁבְּנָא. וְכָלְהוֹ בִּסְטַר שְׂמָאלָא, וּבְכָלְהוֹ אִיקְרֵי קוּדְשָׁא בְּרִיךְ הוּא. וְכָלְהוֹ רְתִיכִין לְתַתָּא לְכָל סְטַר וּסְטַר. וְכֹלָּא בְּרָזָא דְּאָת ו\"ו.</p>"],[9514011093,"<p>בְּגִין דְּכָל אָת וְאָת מֵהַנֵּי ד' אַתְוָון דִּבְרָזָא דִּשְׁמָא קַדִּישָׁא, כָּלְהוֹ קָיְימִין עַל רְתִיכִין קַדִּישִׁין, סָמְכִין עַל מַה דְּאִסְתְּמִיכוּ. וְכָלְהוֹ רְשִׁימִין עֲלַיְיהוּ, כָּל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ, וְאִלֵּין רְתִיכִין אִינוּן כִּינּוּיִין לְהַהוּא שְׁמָא קַדִּישָׁא, עַל מַה דְּקָיְימֵי.</p>"],[9514011094,"<p>וְעַל דָּא מַאן דְּאָתֵי לְיַיחֲדָא שְׁמָא קַדִּישָׁא אִצְטְרִיךְ לְמִנְדַע כָּל חַד וְחַד מֵאִינוּן שְׁמָהָן דְּכִנּוּיִין עַל מָה קָיְימִין. וּמָאן אִיהוּ שְׁמָא דְּשַׁלִּיט עֲלַיְיהוּ, דְּהָא מֵהָכָא מִתְפָּרְשָׁן לְתַתָּא עַד דְּמָטוֹ לְאִינוּן שַׁלִּיטִין מְמַנָּן דְּאִינוּן רְתִיכִין לְתַתָּא וְכָלְהוֹ אִשְׁתְּמוֹדְעִין בְּרָזָא דְּהַהִיא שְׁמָא דְּשַׁלִּיט עֲלַיְיהוּ בְּהַהוּא סִטְרָא דְּקָיְימִין רְתִיכִין. וְכֹלָּא בְּרָזָא דִּשְׁמָא קַדִּישָׁא בְּאִלֵּין אַתְוָון ד' דְּאִקְרֵי קוּדְשָׁא בְּרִיךְ הוּא בְּהוֹן. זַכָּאִין אִינוּן צַדִּיקַיָא דְּאִינוּן אָזְלִין בְּאוֹרַח מֵישָׁר, זַכָּאִין אִינוּן בְּהַאי עָלְמָא, וְזַכָּאִין בְּעָלְמָא דְאָתֵי, דְּקוּדְשָׁא בְּרִיךְ הוּא רָחִים לְהוֹן.</p>"],[9514011095,"<p>שֵׁירוּתָא בְּסִטְרָא דְאֶמְצָעִיתָא, בְּפִתְחָא דְּמִזְרָח, דְּפִתְחָא דְּמִזְרָח אִיהִי קָיְימָא בְּאֶמְצָעִיתָא. נָטֵיל תְּרֵין סִטְרִין, לַעֲבָרָא לוֹן בַּעֲבָרִין וְדָשִׁין, בְּסִטְרָא דָא וּבְסִטְרָא דָא.</p>"],[9514011096,"<p>פִּתְחָא דָא אִיהִי כְּלִילָא מִכָּל הַנֵּי דְּקָאֲמָרָן. וְדָא קָיְימָא עַל רְתִיכָא עִילָּאָה וְאִיהִי רְתִיכָא דְּקָיְימָא בְּרָזָא דְּאָת ו\"ו. דְיהוּ ו\"ו כְּלִילָא דְּכָל הַנֵּי, וְדָא קָיְימָא בְּרָזָא דְּכָל שִׁית סִטְרִין עִילָּאִין. דָּא קָיְימָא עַל רְתִיכָא חָדָא, דְּאִיהוּ תְּלַת בְּיָמִינָא וּשְׂמָאלָא. נָפְקָא מִגּוֹ בּוּצִינָא. כַּד סָלְקָא רוּחָא, דְּנָשֵׁיב בְּי\"ב רֵיחִין דְּבוּסְמַיָא, דְּסָלְקִין רֵיחָא וְלָא סָלְקִין. הַאי רוּחָא נָהֵיר בִּנְהִירוּ, וְדָא אִיהוּ רוּחָא דְּאִיהוּ שְׁלָמָא, וְאִיקְרֵי שְׁלָמָא.</p>"],[9514011097,"<p>וְהָא רוּחָא כַּד אִתְפְּרַשׁ, אִתְפְּרַשׁ בִּתְלַת גְּוָונִין, מְלַהֲטִין בְּאֶשָׁא וְרוּחָא וּמַיָא, כְּמָה דְּאִתְּמָר בְּיָמִינָא. וְכַד אִתְפְּרַשׁ, כָּל חַד וְחַד לָהִיט בְּאַתְרֵיהּ, וִיהֵיב תּוּקְפָא.</p>"],[9514011098,"<p>הַאי נְהִירוּ דְּאִתְפְּשַׁט מֵהַהוּא רוּחָא לְכָל סִטְרָא וְסִטְרָא מֵהַנֵּי תְּלָתָא, גַּוְונָא חָדָא לָהִיט בְּאֶשָּׁא, וְאַתְקֵיף לֵיהּ. גַּוְונָא אָחֳרָא לָהִיט בְּמַיָא, וְאַפֵּישׁ לֵיהּ. גַּוְונָא תְּלִיתָאָה לָהִיט בְּרוּחָא, וּנְהֵיר לֵיהּ כְּאַרְגְּוָונָא, מְלַהֲטָא בִּתְרֵין סִטְרִין אִלֵּין. וְאִלֵּין תְּלַת גְּוָונִין, אִינוּן רְתִיכָא חָדָא, בְּרָזָא דְּאָת ו\"ו, וְאִיהוּ רָזָא דְּאָת ו\"ו.</p>"],[9514011099,"<p>וְאִלֵּין אִינוּן כִּינּוּיִין דְּאִיקְּרֵי בְּהוֹן קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְּאִתְּמָר דְּקוּדְשָׁא בְּרִיךְ הוּא אִיקְּרֵי בְּכָל הַנֵּי שְׁמָהָן, וְאִלֵּין כִּינּוּיִין אִתְכְּלִילָן בְּרָזָא דִּשְׁמָא קַדִּישָׁא, דְּהַאי סְטַר אֶמְצָעִיתָא אִיקְּרֵי בֵּיהּ. וְאַף עַל גַּב דְּהַאי אִיקְּרֵי בְּרָזָא דְאָת ו\"ו, דָּא נָטֵיל כָּל שְׁמָהָן עִלָּאִין וְתַתָּאִין, וְכָל ד' אַתְוָון דִּשְׁמָא קַדִּישָׁא בֵּיהּ אֲחִידָן, בְּגִין דְּנָטֵיל לְכָל סִטְרִין עֵילָא וְתַתָּא, וְדָא רָזָא יה\"ו, הָכָא תַּלְיָיא שְׁמָא דָּא.</p>"],[9514011100,"<p>וְאִיהוּ ידו\"ד, נָטֵיל תְּרֵין אַתְוָון לְעֵילָא, וְנָטֵיל חַד לְתַתָּא, וְאִיהוּ קָאִים בְּאֶמְצָעִיתָא בֵּין עֵילָא וְתַתָּא, וּמִתְּרֵין סִטְרִין כִּדְקָאֲמָרָן.</p>"],[9514011101,"<p>רְתִיכָא דִילֵיהּ אִיקְּרֵי נוּרָא בִּכְלָלָא. כַּד אִתְפְּרַשׁ הַאי רְתִיכָא דְּאִיהוּ הַאי רוּחָא כִּדְקָאֲמָרָן, וְאִתְפְּרַשׁ לִתְלַת גְּוָונִין אָחֳרָנִין, דְּאִיקְרוּן נוּרָא, אֱמֶ\"ת, נוֹצֵ\"ר חֶסֶ\"ד. הַנֵּי אִינוּן הַנֵּי תְּלַת, דְּאִינוּן רְתִיכָא קַדִּישָׁא, לְהַאי סִטְרָא דְּקָיְימָא בְּאֶמְצָעִיתָא.</p>"],[9514011102,"<p>הַנֵּי תְּלַת גְּוָונִין, דְּאִינוּן רְתִיכָא קַדִּישָׁא דְאָת ו\"ו, לָהֲטִין וְנָהֲרִין לְתַתָּא, וְכָל גּווָֹן מֵהַנֵּי תְּלָתָא, אִתְפְּרַשׁ לִתְרֵין אָחֳרָנִין לְכָל סִטְרָא, עַד דְּאִתְעֲבִידוּ בְּחוּשְׁבְּנָא תְּלַת תְּלַת לְכָל סְטַר, וְאִינוּן תִּשְׁעָה, וְהַאי שְׁמָא קַדִּישָׁא דְּשַׁלִּיט עֲלַיְיהוּ אַשְׁלֵים לַעֲשָׂרָה.</p>"],[9514011103,"<p>וְכָל חַד וְחַד מֵהַנֵּי סִטְרִין תְּלָתָא דְּקָאֲמָרָן, יָמִינָא וּשְׂמָאלָא וְאֶמְצָעִיתָא, כָּל חַד וְחַד בְּרָזָא דִּרְתִיכִין דִּילֵיהּ אִיהוּ עֲשָׂרָה, בְּגִין דְּכֹלָּא עֵילָא וְתַתָּא, בְּאַשְׁלָמוּתָא חָדָא אִינוּן עֶשֶׂר סְפִירָן, עֶשֶׂר אֲמִירָן. וְכָל הַנֵּי רְתִיכִין בְּהַהוּא סִטְרָא דְּשַׁלִּיט עֲלַיְיהוּ, אִיקְרוּן עֶשֶׂר סְפִירָן, עֶשֶׂר אֲמִירָן. וּבְגִין כָּךְ כָּל חַד וְחַד מֵהַנֵּי סִטְרִין, סָלְקָא לְעֶשֶׂר רְתִיכִין לְכָל סִטְרָא עַד דְּסָלֵיק כָּל חַד וְחַד לְחוּשְׁבַּן סַגְיָא. וְתָּא חֲזֵי, כָּל רְתִיכִין אִלֵּין כַּד מִתְפָּרְשָׁן לְסִטְרַיְיהוּ, כָּלְהוֹ אִיקְרוּן בְּהַהוּא שְׁמָא דְּשַׁלִּיט עֲלַיְיהוּ, וּבְרָזָא דְהַהוּא אָת מַמָּשׁ לְתַתָּא.</p>"],[9514011104,"<p>תְּרֵין דִּנְפָקוּ מִגּוֹ נְקוּדָה חָדָא, חַד אִיקְּרֵי נוֹשֵׂא עָוֹן, וְחַד אִיקְּרֵי עוֹבֵר עַל פֶּשַׁע. אִלֵּין אִינוּן מֵהַהוּא גּווָֹן דְּאִתְתְּקֵף בֵּיהּ מַיָא, תְּרֵין דְּנָפְקֵי מִגּוֹ גּווָֹן דְּאִתְתְּקֵף בֵּיהּ אֶשָׁא, חַד אִיקְּרֵי מָרוֹם, וְחַד אִיקְּרֵי רָם.</p>"],[9514011105,"<p>וּבְרָזָא דַּחֲנוֹךְ, שְׁמָהָן אִלֵּין כְּלִילָן בְּרָזָא דְּעָלְמָא דְאָתֵי. וְהָכָא בְּהַאי סִטְרָא, בּוֹחֵן לִבּוֹת, מָרוֹם, כְּמָה דְאַתְּ אָמֵר (תהילים י׳:ה׳) מָרוֹם מִשְׁפָּטֶיךָ מִנֶּגְדּוֹ, וּכְתִיב (שם צג) אַדִּיר בַּמָּרוֹם ה', וְאַף עַל גַּב דִּשְׁמָא דְּקָא קָאִים בְּעָלְמָא דְּאָתֵי, הָא כְּתִיב מָרוֹם. וְעַל דָּא אִשְׁתַּתֵּף עָלְמָא דְאָתֵי בְּכָל הַנֵּי, וְהָכֵי אִיקְּרֵי אֱלֹהִים כִּגְוָונִין דִּשְׂמָאלָא, וְכֹלָּא חָד.</p>"],[9514011106,"<p>גַּוְונָא תְּלִיתָאָה אִתְתַּקֵּף בֵּיהּ רוּחָא. אִינוּן תְּרֵין דִּנְפָקוּ מִנֵּיהּ, חַד אִיקְּרֵי שׁוֹכֵן עַד, וְחַד אִיקְּרֵי קָדוֹשׁ, וּמֵאִלֵּין אִתְפָּרְשָׁן נְהוֹרִין לְתַתָּא, וְכָלְהוֹ רְתִיכִין אִלֵּין לְאִלֵּין, וְכוֹלְהוֹ כִּינּוּיִין דְּאִיקְּרֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, וְכוֹלְהוֹ אִשְׁתְּמוֹדְעָן בִּסְטַר דְּשַׁלִּיט עֲלַיְיהוּ.</p>"],[9514011107,"<p>כְגַוְונָא דָא אִית סִטְרִין תְּלָתָא, דְּנָפְקִין מִגּוֹ אִלֵּין סִטְרִין עִילָאִין דְּקָאֲמָרָן, דְּאִינוּן יָמִינָא וּשְׂמָאלָא וְאֶמְצָעִיתָא, וְאִלֵּין נָפְקִין לְבַר מִנַּיְיהוּ, וְקָיְימִין תְּרֵין מִנַּיְיהוּ לְבַר, וְכָלְהוֹ נָטְלֵי רְתִיכִין לְתַתָּא, כְּגַוְונָא דְּאִלֵּין עִילָּאִין, וְלָאו עִילָּאִין כְּגִינַיְיהוּ.</p>"],[9514011108,"<p>וְאִלֵּין דִּלְתַתָּא דְּנָפְקֵי מִגּוֹ אִלֵּין סִטְרִין עִילָּאִין דְּקָאֲמָרָן, אִינוּן כְּגַוְונָא דִּילְהוֹן, חַד אִיקְּרֵי יָמִינָא וְחַד אִיקְּרֵי שְׂמָאלָא, וְחַד דְּקָאי בְּאֶמְצָעִיתָא. גּוֹ הַהוּא אֶמְצָעִיתָא דְּקָאֲמָרָן, וְכָלְהוֹ כְּלִילָן בְּהַנֵּי תְּלַת עִילָּאִין. וְכָלְהוֹ כְּלִילָן בְּרָזָא דְּאָת ו\"ו, דְּכָלֵיל כָּלְהוֹ. וְכָלְהוֹ בִּרְתִיכִין יְדִיעָן מִתְפָּרְשָׁן בְּסִטְרַיְיהוּ.</p>"],[9514011109,"<p>וְאִלֵּין לָא אִיקְרוּן בִּשְׁמָהָן יְדִיעָאן, בַּר בְּאִינוּן כִּינּוּיִין דִּלְתַתָּא, כְּגַוְונָא דְּאִינוּן כִּינּוּיִין עִילָּאִין, וְאִלֵּין תַּתָּאִין אֲחִידָן בְּעִילָּאִין, וְהַנֵּי תְּלָתָא אוֹחֲרָנִין כָּלְהוֹ רְתִיכִין לְבַר, וְהָא אוֹקִימְנָא.</p>"],[9514011110,"<p>תָּא חֲזֵי, הַנֵּי תְּרֵין קָיְימִין, אִינוּן סָמְכִין דִּלְבַר, וְאִינוּן יָמִינָא וּשְׂמָאלָא, וְאִיקְרוּן חַסְדֵּי דָּוִד, וְאִלֵּין צְבָאוֹת רְתִיכָא דִּילְהוֹן. תְּרֵין דְּקָיְימִין וְעָבְדִין שְׁלִיחוּתָא בִּנְבִיאֵי קְשׁוֹט.</p>"],[9514011111,"<p>וּמִתַּמָּן מִתְפָּרְשִׁין עוֹבָדִין בְּעָלְמָא בְּאִתְגַּלְּיָיא, וְרָזָא דָּא דִּכְתִיב, (תהילים קי״א:ב׳) גְּדוֹלִים מַעֲשֵׂי ה'. גְּדוֹלִים: דְּנָפְקֵי מִן גָּדוֹל. וְאִלֵּין אִיקְּרוּן (שם קיט) רַחֲמֶיךָ רַבִּים ה'. (שם פט) אַיֵּה חֲסָדֶיךָ הָרִאשׁוֹנִים ה'. (שם כה) זְכֹר רַחֲמֶיךָ ה' וַחֲסָדֶיךָ כִּי מֵעוֹלָם הֵמָּה. וְאַף עַל גַּב דְּאוֹקִימְנָא דְּאִינוּן לְעֵילָא. מֵעוֹלָם הֵמָּה לְתַתָּא.</p>"],[9514011112,"<p>וְעַל דָּא לָא אִיקְרוּן בִּשְׁמָהָן, כְּגַוְונָא דְּאִיקְרוּן בִּשְׁמָהָן אִינוּן דִּלְעֵילָא. וְאִינוּן כְּגַוְונָא דִלְעֵילָא, אֲבָל אִינוּן בִּכְלָלָא אִינוּן דְּקַיְימֵי לְבַר, וְאִינוּן סָמְכִין דְּאוֹרַיְיתָא דְּנָפְקֵי מֵרְתִיכִין עִילָּאִין. וְאִלֵּין הֲווֹ דְּאַדְכַּר דָּוִד מַלְכָּא, וְדָא אִיהוּ דְּאַדְכַּר תָּדִיר בִּכְלָלָא כְּמָה דְאוֹקִימְנָא.</p>"],[9514011113,"<p>תָּא חֲזֵי, כָּל הַנֵּי שְׁמָהָן עִילָּאִין מֵאִינוּן עֲשָׂרָה דְּקָאֲמָרָן דְּלָא נִמְחָקִין, יָאוֹת הוּא. רְתִיכִין אִלֵּין דִּילְהוֹן, דְּאִינוּן שְׁמָהָן דְּאִיקְרוּן כִּינּוּיִן, אַמַּאי נִמְחָקִין.</p>"],[9514011114,"<p>אֶלָּא רָזָא דָא, הָא אִתְּמָר גּוֹ סִפְרָא דְּרַב הַמְנוּנָא סָבָא, דְּכָל הַנֵּי שְׁמָהָן עִלָּאִין, אִינוּן קָיְימִין כְּגוּפָא לְנִשְׁמָתָא עִילָּאָה, דְּלָא אִתְיְדַע, וְלָא אִתְגַּלְיָין. וְאִלֵּין כִּנּוּיִין אִינוּן לְבוּשָׁא לְגוּפָא. כְּגַוְונָא דֶּאֱגוֹזָא, דְּאִית קְלִיפָּה לַקְלִיפָּה, אוֹ אִלֵּין לַבְלְבִין, דְּאִית לוֹן קְלִיפָּה לַקְלִיפָּה, וּמוֹחָא לְגוֹ.</p>"],[9514011115,"<p>הָכֵי נָמֵי דָא, אִלֵּין עֲשָׂרָה שְׁמָהָן כָּלְהוֹ, כְּגַוְונָא דְהַאי קְלִיפָּה לְמוֹחָא. וְאַף עַל גַּב דְּכָלְהוֹ מוֹחָא, כָּלְהוֹ נְהוֹרִין עִילָּאִין, וּבוּסְמִין עִילָּאִין, לֵית מָאן דְּקָאִים בְּקִיּוּמַיְיהוּ, אֲבָל כָּלְהוֹ כְּגַוְונָא דִּקְלִיפָּה לְגַבֵּי מַה דְּלָא יְדִיעַ, וְלָא קָיְימָא בְּחָכְמְתָא כְּלָל, וְכָּל שֶׁכֵּן רָזָא דְּאֵין סוֹף, וְהַנֵּי כִּינּוּיִין אִינוּן קְלִיפָּה לְגַבַּיְיהוּ, וְכוֹלָּא דָּא לְגוֹ מִן דָּא, וּמוֹחָא סְתִימָאָה לְגוֹ בְּגוֹ, דְּלָא אִתְיְידַע כְּלָל, וְעַל דָּא קְלִיפָּה בַּתְרָא לָא אִיכְפַּת לָן, וְאַף עַל גַּב דְּנִמְחָקִין, עִם כָּל דָּא לָא אִתְיְהֵיב רְשׁוּתָא לְמָחֲקָא, אֲפִלּוּ אוֹת זְעֵירָא דְּאוֹרַיְיתָא.</p>"],[9514011116,"<p>וְאִי תֵימָא, אִי הָכֵי, הַאי ה' בַּתְרָאָה דְּקָאֲמָרָן, אִיהִי קְלִיפָּה בַּתְרָאָה לְגַבֵּי אִלֵּין. לָאו הָכֵי, קְלִיפָּה אִיהִי לְגַבֵּי אִלֵּין עִילָּאִין, אֲבָל לְגַבֵּי אִינוּן כִּינּוּיִין לָאו. דְּהָא לָא מִשְׁתַּמְּשֵׁי בָּהּ, אֶלָּא אִינוּן שְׁמָהָן עִילָּאִין, וְלָאו אִינוּן כִּינּוּיִין.</p>"],[9514011117,"<p>אֶלָּא כַּד אִיהִי סָלְקָא לְאִתְעַטְרָא לְעֵילָא, וּלְאִתְאַחֲדָא בְּרָזָא דְּיָמִינָא וּשְׂמָאלָא, כָּל הַנֵּי רְתִיכִין דְּאִינוּן כִּינּוּיִין, כָּלְהוֹ סָחֲרִין לָהּ, וְחַפְיָין עֲלָהּ סַחְרָנָהָא, כְּבַעְלָהּ לְאִתְּתָא, דְּפָרֵישׂ גַּדְפֵיהּ עֲלָהָא, הָכֵי אִינוּן פְּרִישִׂין גַּדְפִין דְּבַעֲלָהּ עֲלָהָא, וְחַפְיָין לָהּ בְּכָל סִטְרָא, וְאִיהִי מְשַׁמְּשָׁא בְּבַעֲלָהּ, וְסִימָנָא דָא (יחזקאל ט״ז:ח׳) וָאֶפְרֹשׂ כְּנָפִי עָלַיִךְ, (רות ג׳:ט׳) וּפָרַשְׂתָּ כְנָפֶךָ עַל אֲמָתְךָ.</p>"],[9514011118,"<p>וּבְגִין כָּךְ אִינוּן לְבַר וְאִיהִי לְגָו, וְאִיהִי לְגָו וְאִיהִי לְבָר, וְהָכֵי כִּינּוּיִין אִינוּן לְגָו, וְאִינוּן לְבָר. מַה דְּאִיהוּ לְגָו קָיְימָא לְבָר, מַה דְּאִיהוּ לְבָר קָיְימָא לְגָו, וְכֹלָּא שַׁפִּיר אִיהוּ. זַכָּאָה חוּלָקֵיהוֹן דְּאִינוּן דְּיָדְעִין לְמֵיזַל בְּאוֹרַח מֵישָׁר, דְּלָא יָטְעִין לְיָמִינָא וּשְׂמָאלָא, כְּמָה דְּאוֹקִימְנָא, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי ה'.</p>"],[9514011119,"<p>מַבּוּעָא דְּבֵירָא דְּלָא פָּסֵיק לְעָלְמִין, הַאי קָיְימָא קִיּוּמָא, לְקָיְימָא כֹּלָּא, כָּלְהוֹ עִילָּאִין וְכָלְהוֹ תַּתָּאִין, קָיְימִין בְּהַאי לְרַחֲמָא דְּתֵיאוֹבְתָּא, בְּגִין דְּאִיהוּ תֵּיאוֹבְתָּא לְעֵילָא וְתַתָּא, לְאַנְהָרָא אַנְפִּין, וּלְאַשְׁקָאָה גִּנְתָּא.</p>"],[9514011120,"<p>בְּהָאי לָאו רְתִיכָא קָיְימָא בֵּיהּ לְאִתְגַּלְּיָא, אֶלָּא כֹּלָּא אִיהוּ סָתִים בִּסְתִימוּ, וְלָא קָיְימָא בְּאִתְגַּלְּיָא, אֶלָּא כָּלְהוֹ שְׁמָהָן עִילָּאִין, וְכָלְהוֹ רְתִיכִין, כָּלְהוֹ אָתָאן לְגַבֵּיהּ בִּלְחִישׁוּ.</p>"],[9514011121,"<p>כַד אִינוּן שְׁמָהָן אַתְיָין לְגַבֵּיהּ, אִלֵּין רְתִיכִין פְּרִישָׂאן וְחָפְיָין לְכָל סִטְרִין, לְדַרְגָּא דָּא וּלְדַרְגָּא דִּלְתַתָּא, וְאִלֵּין אִיקְרוּן גַּדְפִין דְּבַעֲלָה. לְחָפְיָיא עַל כֹּלָּא. וְהַאי דַרְגָּא עָאל בִּלְחִישׁוּ, כְּמַבּוּעָא גּוֹ בֵּירָא, דְּלָא פָּסְקִין מֵימוֹי לְעָלְמִין, וְלָא אִתְפְּרַשׁ מַבּוּעָא לְעָלְמִין. וְכֹלָּא אִיהוּ בְּאֵר, דִּכְתִיב (במדבר כ״א:י״ח) בְּאֵר חֲפָרוּהָ שָׂרִים (בראשית כ״ו:י״ט) בְּאֵר מַיִם חַיִּים. וְהָא אוֹקִימְנָא.</p>"],[9514011122,"<p>הַאי מַבּוּעָא דְּבֵירָא, אִיהוּ סָתִים לְגַבֵּי הַהוּא בֵּירָא, דְּעָאל לְגַבֵּיהּ בִּלְחִישׁוּ, וְהַאי כָּרֵי גּוֹ הַהוּא נְקוּדָה דְּקָאֲמָרָן, רָזָא דְה\"א בַּתְרָאָה, וְכָרֵי בָּהּ, וְעָאל לְגַבֵּהּ, וְלָא אִתְיְידַע כְּלָל.</p>"],[9514011123,"<p>וְהַאי אִיהוּ כְּמָא דְאוֹקִימְנָא לְעֵיל, דְּכַד אָלֶף אִתְחַבַּר בְּה\"א, אוֹ יו\"ד, הַאי ה\"א אִיהִי בִּנְקוּדָה חָדָא לְאוֹטָבָא לְעָלְמָא, כְּגוֹן א\"ה, אוֹ י\"ה. כְּדֵין הַהוּא מַבּוּעָא דְבֵירָא, כָּרֵי גּוֹ הַהוּא נְקוּדָה, וְעָאל לְגַוָּוהּ, וְלָא אִתְיְידַע.</p>"],[9514011124,"<p>וּכְדֵין הַהִיא נְקוּדָה קָיְימָא בְּרָזָא דְקֹדֶשׁ הַקֳּדָשִׁים. וְעַל דָּא רָזָא דְּדוּכְרָנָא דִילָהּ, אִיהוּ בְּרָזָא דְקֹדֶשׁ הַקֳּדָשִׁים, בַּאֲתַר דְּמַפְקָנוֹ דְרוּחָא קָיְימָא בְּבֵי גְרוֹנָא, אהי\"ה, בְּגִין דְּהַאי אִיהוּ אֲתַר דְּקָיְימָא קֹדֶשׁ הַקֳּדָשִׁים, קוֹל גָּדוֹל וְלָא אִשְׁתְּמוֹדָע, וְלָאו אִיהוּ רוּחַ מַמָּשׁ. וּכְדֵין אִיהוּ ה\"א בְּחִיבּוּרָא דְּאִינוּן אַתְוָון עִילָּאִין, וְכֹלָּא שְׁמָא חָדָא, לְאַנְהָרָא מֵעֵילָא וּמִתַּתָּא.</p>"],[9514011125,"<p>כַד כָּרֵי הַאי מַבּוּעָא בְּהַאי נְקוּדָה, וְעָאל בְּגַוֵּיהּ, כְּדֵין כָּל אִינוּן שְׁמָהָן עִילָּאִין, וְכָל אִינוּן סִטְרִין עִלָּאִין דְּקָאֲמָרָן, כָּלְהוֹ עָאלִין בְּגַוֵּיהּ, בְּתֵיאוּבְתָּא, בְּרוּחָא שְׁלִים לְעֵילָא, בְּתֵיאוּבְתָּא עָאלִין בָּהּ, וְלָא בְּמִלָּה אָחֳרָא. כּוֹלָּא בְּרוּחָא וְלָא בְּגוּפָא. כְּבַעֲלָהּ דְּאִשְׁתְּלֵיל מִכָּל לְבוּשׁוֹי, בְּשַׁעֲתָא דְּאָתֵי לְאִזְדַּוְּוגָא בְּאִיתְּתֵיהּ, הָכִי נָמֵי כָּל אִינוּן רְתִיכִין דְּקָאֲמָרָן דִּלְעֵילָא וְתַתָּא, כָּלְהוֹ סָחֲרִין לָהּ, וְאִינוּן חָפְיָין עֲלָהּ, וּבַעֲלָהּ אִשְׁתְּלֵיל מִכָּלְהוֹ. וְעַל דָּא לָא אַתְיָין כָּל אִינוּן שַׁיְיפִין לְאִתְחַבְּרָא בָהּ, אֶלָּא בְּרוּחַ מַמָּשׁ, וּכְדֵין כֹּלָּא אִיהוּ רְעוּתָא חָדָא.</p>"],[9514011126,"<p>וְעַל דָּא בְּשַׁעֲתָא דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְגַבָּהּ, וְיִשְׂרָאֵל לָאו אִינוּן זַכָּאִין דְּאִינוּן יְהוֹן פְּתִילָה לְאַנְהָרָא, מַה כְּתִיב, (שיר השירים ה׳:ג׳) פָּשַׁטְתִּי אֶת כֻּתָּנְתִּי אֵיכָכָה אֶלְבָּשֶׁנָּה רָחַצְתִּי אֶת רַגְלַי אֵיכָכָה אֲטַנְּפֵם. פָּשַׁטְתִּי אֶת כֻּתָּנְתִּי, אִלֵּין אִינוּן כִּינּוּיִין דְּקָאֲמָרָן, דְּכָלְהוֹ כַּד מִתְחַבְּרָן אִינוּן כֻּתָּנְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְכַד אִיהוּ זַמִּין לְגַבָּהּ, אִיהוּ אִשְׁתְּלֵיל מִכּוֹלְהוֹ, לְאִתְחַבָּרָא בַּהֲדָהּ, וְעַל דָּא פָּשַׁטְתִּי וְגו', לְאִתְתַּקְּנָא וּלְמֶהֱוֵי זַמִּין לְאוֹטָבָא לָךְ, וְאַתְּ לָא מִתְתַּקְּנָא כִּדְקָא יָאוֹת, הַשְׁתָּא אֵיכָכָה אֶלְבָּשֶׁנָּה, וְאִתְהַדַּר וְאִסְתַּלַּק מִינָּךְ.</p>"],[9514011127,"<p>רָחַצְתִּי אֶת רַגְלַי אֵיכָכָה אֲטַנְּפֵם, הָא אַסְחֵית רַגְלַי מֵהַהוּא טִינוֹפָא, וּמַאי אִיהוּ, בְּגִין דְּכַד אִתְתַּקְנֵית וְאִזְדַּמְנִית לְגַבָּךְ, אַעֲבָרִית הַהוּא סִטְרָא אוֹחֲרָא מְסָאֲבָא מִקַּמֵּי רַגְלַי. הַשְׁתָּא אֵיכָכָה אַהֲדַר לְשַׁוְּיָיא הַהוּא טִינּוֹפָא, לְחַפְיָיא עַל מַקְדְּשָׁא, הוֹאִיל וְאַתְּ לָא זְמִינַת בְּתִיקּוּנָךְ לְאִתְתַּקָּנָא לְגַבָּאי. הָכָא אוֹלִיפְנָא, דְּכַד רוּחַ מְסָאֲבָא אִתְעֲבַר מֵעָלְמָא, כְּדֵין אִתְרַבֵּי כֹּלָּא עֵילָא וְתַתָּא. וְעַל דָּא רָחַצְתִּי אֶת רַגְלַי, אֵיכָכָה אֲטַנְּפֵם כְּמִלְּקַדְּמִין.</p>"],[9514011128,"<p>וּבְגִין כָּךְ, כָּל אִינוּן כִּינּוּיִין אִתְפַּשְׁטוּ, בְּשַׁעֲתָא דְּהַאי מַבּוּעָא כָּרֵי בְּהַהוּא נְקוּדָה, וְאַסְתֵּים בְּגַוֵּיהּ. וּכְדֵין כַּד הַהוּא מַבּוּעָא אַסְתֵּים בְּגַוָּוהּ, כְּדֵין כֹּלָּא אַנְהֵיר וּבֵירָא אִתְמַלְּיָא מֵהַהוּא מַבּוּעָא דְּעָאל בְּגַוָּוהּ וְאַסְתֵּים בֵּיהּ בַּחֲשַׁאי. אִינוּן כִּינּוּיִין חָפְיָין עֲלָהּ וְאִתְפַּשְׁטוּ לִסְטַר דָּא וְלִסְטַר דָּא.</p>"],[9514011129,"<p>וְהַנֵּי אִינוּן גְּלִידִין דֶּאֱגוֹזָא קְלִישָׁא, דְּקָיְימָא וְחָפְיָיא לְגוֹ עַל מוֹחָא, וְהַהִיא קְלִיפָּא תַּקִּיפָא, אִתְבָּרַת וְלָא קָיְימָא תַּמָּן. וּכְדֵין כֹּלָּא אִיהִי בְּרָזָא עִילָּאָה, לְמֵיהַךְ בְּרָזִין אִלֵּין. זַכָּאִין אִינוּן דְּמִסְתַּכְּלִין בִּרְעוּתַיְיהוּ, מִלִּין דְּרָזִין עִילָּאִין, לְמֵיהַךְ בְּאוֹרַח קְשׁוֹט, לְמִזְכֵּי בְּהַאי עָלְמָא, וּלְאַנְהָרָא לוֹן בְּעָלְמָא דְאָתֵי. עֲלַיְיהוּ כְּתִיב, (דניאל י״ב:ג׳) וְהַמַּשְׂכִּילִים יַזְהִירוּ כְּזֹהַר הָרָקִיעַ וּמַצְדִּיקֵי הָרַבִּים כַּכּוֹכָבִים לְעוֹלָם וָעֶד. זַכָּאִין אִינוּן בְּעָלְמָא דֵין וּבְעָלְמָא דְאָתֵי.</p>"],[9514011130,"<p>דִּיוּקְנָא דְּאַתְוָון, בְּרָזָא קַדִּישָׁא ה\"א תַּתָּאָה דְּקָאֲמָרָן, רָזָא דְּמַקְדְּשָׁא, סִיהֲרָא כַּד שָׁלְטָא, וְאִתְקַשְּׁטַת לְגַבֵּי שִׁמְשָׁא, לְקַבְּלָא נְהוֹרָא מִנֵּיהּ. אִינוּן קָיְימִין כִּתְרִין רְחִימִין דָּא לָקֳבֵל דָּא, וְאִינוּן בְּתוּלָאן דְּקַיְימָן בַּהֲדָהּ, אִתְקַשְּׁטָן וְאִתְתַּקְּנָן בְּתִיקּוּנִין, חָדָא בַּתְרָאָה, וְחָדָא לְקַמָּאָה, וְחָדָא מִסִּטְרָא דָא, וְחָדָא מִסִּטְרָא דָא, וְאִיהִי קָיְימָא בְּאֶמְצָעִיתָא.</p>"],[9514011131,"<p>וְשִׁבְעִין וּתְרֵין סַנְהֶדְּרִין, קָיְימִין כְּפַלְגּוּ גּוֹרֶן עֲגוּלָּה, לְמֵיעְבַּד גּוּפָא לְסִיהֲרָא, לְאִתְקַשְּׁטָא מַטְרוֹנִיתָא לְגַבֵּי בַּעֲלָהּ, וְאִיהִי קָיְימָא כְּגַוְּונָא דָּא כ, כְּפַלְגּוּ סִיהֲרָא.</p>"],[9514011132,"<p>וְהָא נְקוּדָה בְּאֶמְצָעִיתָא. דְּהַהִיא נְקוּדָה נָטְלָה נְהוֹרָא מִן שִׁמְשָׁא, לְאַנְהָרָא לְכָל גּוּפָא. וְרָזָא דָא נְקוּדָה דְּקָיְימָא בְּפַלְגוּ דְּעֵינָא, דְּכוֹלָּא קָיְימָא בְּהַהִיא נְקוּדָה דְּקָיְימָא בְּאֶמְצָעִיתָא, דְּאִיהִי נָטְלָא כָּל נְהוֹרָא, לְאַנְהָרָא לְכָל עֵינָא. וְסִיהֲרָא לָא אִתְנְהֵירַת אֶלָּא מִגּוֹ חַד נְקוּדָה דְּקָיְימָא וְאַסְתֵּים גוֹ אֶמְצָעִיתָא. אַף עַל גַּב דְּלָא אִתְחַזְּיָיא בְּסִיהֲרָא.</p>"],[9514011133,"<p>תָּא חֲזֵי לֵית לָךְ עִיגּוּלָא בְּעָלְמָא, דְּלָא אִיתְעֲבֵיד מִגּוֹ נְקוּדָה חָדָא דְּקָיְימָא בְּאֶמְצָעִיתָא. וּבְגִין כָּךְ עִיגּוּלָא דְּסִיהֲרָא מִגּוֹ חַד נְקוּדָה דְּאַסְתֵּים בְּגַוָּוהּ בְּאֶמְצָעִיתָא, אִתְעֲבֵיד כֹּלָּא. וְהַאי נְקוּדָה דְּקָיְימָא בְּאֶמְצָעִיתָא נָטֵיל כָּל נְהוֹרָא, וְאַנְהֵיר לָהּ לְגוּפָא, וְאִתְנְהֵיר כֹּלָּא.</p>"],[9514011134,"<p>רָזָא דְּרָזִין, לְאִינוּן דְּמִסְתַּכְּלִין בְּרָזֵי דְחָכְמְתָא. הַאי ה\"א דְּאִיהִי פַּלְגוּ דְגוּפָא דְּסִיהֲרָא, וְאִיהִי בְּעִיגּוּלָא, כִּדְאֲמָרָן בְּגוֹ הַהוּא נְקוּדָה דְּקָיְימָא גּוֹ אֶמְצָעִיתָא, אַמַּאי אִיהוּ פַּלְגָא, לָאו, אֶלָּא סְתִימָא מִסִּטְרָא דָא, וּפְתִיחָא מִסִּטְרָא דָא, כְּנוּקְבָא דִּפְתִיחָא לְגַבֵּי דְכוּרָא לְקַבְּלָא לֵיהּ בְּגַוָּוהּ, וּלְאִתְנְהָרָא מִנֵּיהּ, וּלְאִתְחַבְּרָא בַּהֲדֵיהּ. וְעַל דָּא אִיהִי פְּתִיחָא לְגַבֵּיהּ לְקַבְּלָא לֵיהּ, וּכְדֵין אִיקְּרֵי ה\"א. מַאי ה\"א, כְּמַאן דַּאֲמַר הָא אֲנָא.</p>"],[9514011135,"<p>וְכַד אִיהִי אִתְנְהֵירַת מִנֵּיהּ, וְאִתְחַבְּרוּ דָּא בְּדָא, וְסִיהֲרָא אִתְמַלְּיָיא, כְּדֵין הַאי ה\"א אִשְׁתְּלֵים וְאִתְמַלְּיָא סִיהֲרָא מִכֹּלָּא. וּבְאַתְרָהּ דְּאִיהוּ ה\"א פַּלְגוּ דְּסִיהֲרָא, אִתְעֲבֵיד מ\"ם, סִיהֲרָא בִּשְׁלִימוּ.</p>"],[9514011136,"<p>וְקָיְימָא כְּגַוְונָא דְּאִימָּא עִילָּאָה, דְּאִיהִי מ' סְתִימָא. כְּמָא דְאוֹקִימְנָא, בְּרָזָא דִּלְםַרְבֶּה הַמִּשְׂרָה. וְהָשְׁתָּא קָיְימָא סִיהֲרָא בְּאַשְׁלָמוּתָא, עָלְמָא תַּתָּאָה, כְּגַוְונָא דְּעָלְמָא עִילָּאָה. וְדָא אִיהוּ רָזָא דְּאָת ם'.</p>"],[9514011137,"<p>וְתָּא חֲזֵי אָת דָּא ם', לָאו אִיהוּ אֶלָּא בְּעִיגּוּלָא. כֵּיוָן דְּקָיְימָא סִיהֲרָא בְּאַשְׁלָמוּתָא וְכֹלָּא מֵרָזָא דְּאָת ה' כְּמָא דְאִתְּמָר, אִיהִי בְּקַדְמִיתָא פְּתִיחָא בְּרָזָא דְּה\"א, לְקַבְּלָא לְבַעֲלָהּ. וּלְבָתַר דְּאִשְׁתְּלֵים מִנֵּיהּ, אִיתְמַלְּיָא בְּאַשְׁלָמוּתָא, אִתְעֲבֵיד ם', כְּגַוְונָא עִילָּאָה דְעָלְמָא דְאָתֵי כִּדְקָאֲמָרָן. וּבְגִין כָּךְ ה\"א עִילָּאָה, ה\"א תַּתָּאָה. ם' עִילָּאָה, ם' תַּתָּאָה. כֹּלָּא דָא כְּגַוְונָא דָא, וְדָא אִיהוּ רָזָא חָדָא, עִילָּאָה וְתַתָּאָה כַּחֲדָא.</p>"],[9514011138,"<p>תָּא חֲזֵי, עָלְמָא עִילָּאָה אִיהִי פְּתִיחָא בְּקַדְמִיתָא, בְּרָזָא דְה\"א. וְכַד אִתְמַלְּיָיא מֵאִינוּן שְׁבִילִין עִילָּאִין, וְאִתְנַהֲרָא לְאַנְהָרָא, אִתְפַּשְּׁטַת וְאִשְׁתְּלֵים וְאִתְעֲבֵיד ם', וְכֹלָּא בְּרָזָא חַד.</p>"],[9514011139,"<p>דִּיוּקְנָא דְאָת ו\"ו בְּרָזָא קַדִּישָׁא, הַאי אָת, עָלְמָא דִלְעֵילָא פָּשִׁיט פְּשִׁיטוּ לְאַנְהָרָא לְתַתָּא, וְהַהוּא פְּשִׁיטוּ, אִיהוּ בְּשִׁית סִטְרִין, כְּלִילָן כַּחֲדָא בְּחִיבּוּרָא חָדָא, דָּא כְּגַוְונָא דְדָא וְדָא כְּגַוְונָא דְדָא. וְכָלְהוֹ מִתְחַבְּרָן בְּאִינוּן רְתִיכִין דִּילְּהוֹן בְּאָת דָּא.</p>"],[9514011140,"<p>וְהַאי אָת אִיהוּ רְשִׁימוּ דִּבְשִׁית סִטְרִין כְּלִילָן כַּחֲדָא. וְדָא הוּא דְּאַנְהֵיר לְסִיהֲרָא בְּרָזָא דְשִׁית סִטְרִין כְּלִילָן. דְּהָא כַּד מִתְחַבְּרָן כַּחֲדָא, פְּשִׁיטִין מִפְּשִׁיטוּ, כֹּלָּא דִּיוּקְנָא דְּו\"ו, דִּיוּקְנָא דְּאָדָם וְאַף עַל פִּי דְּאִינוּן שִׁיתָּא סִטְרִין, לָא אִיתְחֲזוּ בִּפְשִׁיטוּ בַּר חַד גּוּפָא.</p>"],[9514011141,"<p>רָזָא דְרָזִין, לְאִינוּן דְּמִסְתַּכְּלִין בְּאוֹרַח מֵישָׁר, בִּדְיוֹקְנִין דְּאַתְוָון, הָכָא בְּהַאי אָת, כָּלְהוֹ בְּחִיבּוּרָא דָא, לְאַחֲזָאָה דְּכָלְהוֹ קָיְימִין בְּקִיּוּמָא דְגוּפָא, דְּאִיהוּ נָטֵיל כֹּלָּא. וְכַד הַאי אָת דְּאִיהוּ ו\"ו, קָיְימָא הָכֵי בְּחִיבּוּרָא חָדָא, הָא אִיהוּ זַמִּין לְגַבֵּי נוּקְבָא, פָּשִׁיט וְאִשְׁתְּלֵיל מִכֹּלָּא, רָזָא דִּיוּקְנָא דְגוּפָא, דִּיוּקְנָא דְאָדָם. וְכַד מִסְתַּכְּלִין, דְּרוֹעִין מִסִּטְרָא דָא וּמִסִּטְרָא דָא מִתְחַבְּרָן בְּהַאי גוּפָא, דְּלָא אִתְחַזְּיָין בַּר גּוּפָא בִּלְחוֹדוֹי, בְּגִין דְּכָלְהוֹ כְּלִילָן בֵּיהּ.</p>"],[9514011142,"<p>אֵימָתַי אִתְחֲזוּן. בְּשַׁעֲתָא דְּאָת דָּא אִתְפַּשְׁטַת, וְאִיקְּרֵי אָלֶף. כְּדֵין, תְּרֵין דְּרוֹעִין, דָּא מִסִּטְרָא דָא, וְדָא מִסִּטְרָא דָא, וְגוּפָא קָיְימָא בֵּינַיְיהוּ בְּאֶמְצָעִיתָא. א.</p>"],[9514011143,"<p>וְעַל דָּא אָלֶף רֵישָׁא לְכָל אַתְוָון, בְּגִין דְּתִיקּוּנָא דָא, כַּד קָאִים, אִיהוּ רֵישָׁא לְכָל מַאי דְּנָפֵיק מֵעָלְמָא דְאָתֵי. וְאַף עַל גַּב דְּרָזִין עִילָּאִין אַחֲרָנִין נֶאֶמְרוּ בְּרָזָא דְאָלֶ\"ף, אֲבָל דָּא אִיהוּ בְּרִירוּ דְּרָזָא דְמִלָּה כְּמָה דְאִיהוּ בְּסִפְרָא, וְהָכָא אִיהוּ בְּרִירוּ דְרָזָא. וּמֵהָכָא אִתְפַּשְּׁטוּ אַתְוָון אָחֳרָנִין, כָּלְהוֹ בְּסִטְרַיְיהוּ, כָּל חַד וְחַד כִּדְקָא חָזֵי לֵיהּ.</p>"],[9514011144,"<p>וְאָת דָּא כֹּלָּא אִיהוּ חַד, ו\"ו וְאָלֶ\"ף, בַּר דְּהַאי אַסְתֵּים כֹּלָּא בְּגַוֵּיהּ, וְהַאי אַחֲזֵי כָּל דְּיוֹקְנֵיהּ. וְאִי תֵימָא תְּרֵין יַרְכִין דְּלָא אִתְחַזְּיָין. הָכֵי הוּא וַדַּאי, דְּהָא תְּלַת סִטְרִין, אִינוּן רָזָא דִתְלַת אָחֳרָנִין.</p>"],[9514011145,"<p>וְתוּ, אִלֵּין אִינוּן רָזָא דְתוֹרָה שֶׁבִּכְתָב, כְּלָלָא דְּכוֹלָּא. וּמֵהָכָא נָפְקָן כָּל שְׁאָר. כְּגַוְונָא דָא, נְבִיאִים וּכְתוּבִים כָּלְהוֹ כַּחֲדָא. אָלֶ\"ף אִיהוּ חַד, רָזָא דִּתְלַת גְּוָונִין כַּחֲדָא, דְּאִינוּן אַבָּהָן. וְכַד אַבָּהָן מִתְחַבְּרָן כַּחֲדָא, אִינוּן חַד. וְעַל דָּא אִיקְּרֵי אָלֶף, חַד רֵישָׁא לְכָל אַתְוָון, רָזָא דְּתוֹרָה שֶׁבִּכְתָב, כְּמָא דְּאִיתְּמָר.</p>"],[9514011146,"<p>וְעַל דָּא, ו' וְאָלֶף רָזָא חָדָא אִינוּן. אָת ו' דִּיוּקְנָא דְּאָדָם, רֵישָׁא וְגוּפָא אִתְפַּשְׁטוּתָא חַד. אָלֶ\"ף אַשְׁלָמוּתָא דִּדְיוֹקְנָא לְאַחֲזָאָה. וְכִי תֵימָא, ו', דְּאִיהוּ אִתְפַּשְׁטוּתָא חַד, פְּשִׁיטוּ חַד בְּלָא דְּיוֹקְנִין אָחֳרָנִין, אַמַּאי רָזָא דִילֵיהּ שִׁיתָא, וְאָלֶף דְּאִיהִי תְּלַת דְּיוֹקְנִין, אַמַּאי רָזָא דִילֵיהּ חַד.</p>"],[9514011147,"<p>אֶלָּא מֵהָכָא, רָזִין דְּסָלְקִין בִּשְׁמָא קַדִּישָׁא, אָסוּר לְאַסְגָּאָה לוֹן בִּפְרָטָא, אֶלָּא לְחַבְּרָא כָּלְהוֹ, וּלְיַיחֲדָא לוֹן כַּחֲדָא, לְמֶהֱוֵי חָד. וְכַד אִינוּן כַּחֲדָא בִּכְלָלָא חָדָא, בִּדְיוֹקְנָא חָדָא, אִית לְפָרְשָׁא לוֹן, וּלְמֶעְבַּד פְּרָטִין דְּנָפְקֵי מֵהַהוּא כְּלָלָא דְּאִתְחֲזֵי.</p>"],[9514011148,"<p>וְעַל דָּא, כְּלַל אִתְהַדַּר לְמֶהֱוֵי פְּרָט. פְּרַט אִתְהַדַּר לְמֶהֱוֵי כְּלָל. כְּלַל דָּא ו\"ו, דְּאִתְהַדַּר לְמֶהֱוֵי פְּרָט, בְּרָזָא דְּשִׁית, וְאִיהִי פְּשִׁיטוּ חַד בִּלְחוֹדוֹי. פְּרָט אָלֶף, תְּלַת דְּיוֹקְנִין מִתְחַבְּרָן כַּחֲדָא, וְאִתְהַדַּר לְמֶהֱוֵי כְּלָל, בְּרָזָא דְּחָד. וְרָזָא דָא, כְּלָל וּפְרָט וּכְלָל, א' ו', וְכֹלָּא חַד.</p>"],[9514011149,"<p>אל\"ף פְּרָט דְּאִתְהַדַּר לְמֶהֱוֵי כְּלָל, וּלְבָתַר אִתְהַדַּר לְמֶהֱוֵי פְּרָט. וְאִיהוּ פְּרָט וּכְלָל וּפְרָט. ו\"ו כְּלָל, וְאִתְהַדַּר לְמֶהֱוֵי פְּרָט, וּלְבָתַר אִתְהַדַּר לְמֶהֱוֵי כְּלָל. וְדָא רָזָא כְּלָל וּפְרָט וּכְלָל.</p>"],[9514011150,"<p>אל\"ף פְּרָט, וְאִתְהַדַּר לְמֶהֱוֵי כְּלָל, כְּמָא דְאוֹקִימְנָא, וּלְבָתַר אִתְהַדַּר לְמֶהֱוֵי פְּרָט. בְּגִין דְּאִיהוּ אל\"ף, וְהָכֵי סָלְקָא בְּרָזָא דְּאָלֶף. דְּרוֹעִין וְגוּפָא, וְאִתְפָּרְשָׁן רָזִין לְמֵאָה, וּמִמֵּאָה לְאָלֶף. עַל דָּא אִקְרֵי אל\"ף, בְּרָזָא דְּאל\"ף, אָלֶף חַד כְּלָל. אָלֶף אַלְפָא פְּרָט.</p>"],[9514011151,"<p>ו\"ו כְּלָל, וְאִתְהַדַּר לְמֶהֱוֵי פְּרָט, בְּרָזָא דְאוֹקִימְנָא. וּלְבָתַר אִתְהַדַּר לְמֶהֱוֵי כְּלָל. רָזָא דְּאָדָם חַד. רָזָא חַד. וְכֹלָּא סָלְקָא בְּרָזָא חָדָא, וּבְמַתְקְלָא חָדָא לְמֶהֱוֵי כֹּלָּא חַד. ו\"ו אִתְהַדַּר לְמֶהֱוֵי כְּלָל חַד, נְהִירָא חָדָא, כְּלִילָן בְּשִׁית סִטְרִין.</p>"],[9514011152,"<p>וְרָזָא דָא (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. דָּא ו\"ו דְּהִיא אָזֵיל וְנָהֵיר בְּרָזָא דְּיָמִינָא, בִּכְלָלָא חָדָא. וּלְבָתַר וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחשֶׁךְ, אִתְהַדַּר אָת דָּא לְמֶהֱוֵי אָלֶף, תְּרֵין דְּרוֹעִין, דָּא מִסִּטְרָא דָא, וְדָא מִסִּטְרָא דָא. חַד אִתְקְרֵי אוֹר, וְחַד אִתְקְרֵי חשֶׁךְ. אִתְפְּלַג אָת ו\"ו בְּגַוַויְיהוּ, וּכְדֵין אִתְפְּלַג מַחְלוֹקֶת מִתְּרֵין סִטְרִין, דְּאִינוּן אוֹר וְחשֶׁךְ, דִּכְתִיב וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחשֶׁךְ. מַהוּ וַיַּבְדֵּל דְּאִיתְפְּרַשׁ מַחְלוֹקֶת הַהוּא, וְאִסְתַּכְּמוּ תְּרֵין סִטְרִין לְמֶהֱוֵי בִּשְׁלָם, וְהַבְדָּלָה דָא, הִיא הַבְדָּלַת מַחְלוֹקֶּת, לְאִסְתַּכְּמָא לְמֶהֱוֵי כֹּלָּא חַד, שְׁלִים כַּחֲדָא.</p>"],[9514011153,"<p>וּבְגִין כָּךְ, א\"ו כַּחֲדָא אִינוּן. וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם, דָּא סִטְרָא חָדָא דְרָזָא דְּאל\"ף. וְלַחשֶׁךְ קָרָא לָיְלָה, דָּא סִטְרָא חָדָא דְרָזָא דְּאָלֶף. לְבָתַר אִתְפְּרָשׁוּ תְּרֵין סִטְרִין לְמֵיעְבַּד עוֹבָדָא, חַד עָבִיד עָרֶב, וְחַד עָבִיד בֹּקֶר. כֵּיוָן דַּעֲבָדוּ עוֹבָדִין, אִסְתַּכְּמוּ תַּרְוַיְיהוּ, וְאִתְכְּלִילוּ בְּאָת ו\"ו.</p>"],[9514011154,"<p>הֲדָא הוּא דִכְתִיב וַיְהִי עֶרֶב וַיְהִי בֹקֶר, וַיְהִי עֶרֶב, מִסִּטְרָא דְחשֶׁךְ. וַיְהִי בֹקֶר, מִסִּטְרָא דְאוֹר. כֵּיוָן דַּעֲבָדוּ עוֹבָדִין, מִיָּד אִשְׁתַּכְלָלוּ לְחַד, דִּכְתִיב יוֹם אֶחָד. הָא רָזָא דְאָת ו\"ו, דְּאִתְכְּלִילָן בֵּיהּ לְמֶהֱוֵי חָד.</p>"],[9514011155,"<p>וְהָא הוּא רָזָא דִּכְתִיב וַיְהִי, וְלֹא כְתִיב וְהָיָה. וַיְהִי, כַּד אִתְחַזְּיָין בְּרָזָא דְּאָלֶף, וַעֲבָדוּ עוֹבָדִין, וְאַסְתִּימוּ וְלָא אִתְחַזּוּן, כְּדֵין כְּתִיב וַיְהִי: הֲוָה, וְהַשְׁתָּא לָא אִיהוּ הָכֵי, דְּהָא אִתְכְּלֵיל בְּרָזָא דְו\"ו, וְהַשְׁתָּא כֹּלָּא יוֹם אֶחָד (תהילים ק״ו:ב׳) מִי יְמַלֵּל גְּבוּרוֹת ה' יַשְׁמִיעַ כָּל תְּהִלָּתוֹ.</p>"],[9514011156,"<p>(בראשית א׳:ט׳) וַיֹּאמֶר אֱלֹהִים יִקָּווּ הַמַּיִם מִתַּחַת הַשָּׁמַיִם. דָּא סִטְרָא תַּתָּאָה, סִטְרָא חַד דִּבְרָזָא דְּאָלֶף, דְּאִיהִי סִטְרָא דְּאִקְרֵי חשֶׁךְ, וְדָא אִיהוּ מִתַּחַת הַשָּׁמַיִם. דְּהָא מֵהַהוּא סִטְרָא מִתְפָּרְשָׁן מַיִין, וְנָבְעֵי בִּנְגִידוּ דִטְמִירוּ, מִסִּטְרָא אָחֳרָא דִּלְעֵילָא, דְּאִיהוּ יָמִינָא.</p>"],[9514011157,"<p>אוֹר דְּאִתְגְּנִיז, בְּאָן אֲתַר אִתְגְּנִיז, בְּרָזָא דְּאָת ו\"ו. וְכַד אִיהִי אִתְגְּנִיז, כּוֹלָּא אִיתְגְּנִיזִין, סִטְרָא אָחֳרָא גָּנִיז עִמֵּיהּ. וְעַל דָּא מִתַּחַת הַשָּׁמַיִם אֶל מָקוֹם אֶחָד. וְדָא הוּא סִטְרָא דְּאִשְׁתָּאַר חַד, בְּלָא חַבְרֵיהּ כַּד אִתְגְּנִיז בְּקַדְמִיתָא. וּמֵהַהוּא סִטְרָא כַּד אִתְפַּלְּגוּ מַיָּא, וְאִתְכְּנִישׁוּ בְּגַוֵּיהּ, כְּדֵין אִיתְחֲזֵי יַבֶּשְׁתָּא מֵהַהוּא סִטְרָא. וְרָזָא דָא הַר צִיּוֹן יַרְכְּתֵי צָפוֹן קִרְיַת מֶלֶךְ רָב. דְּהָא מֵהַהוּא סִטְרָא אִיתְחֲזֵי וְאִתְגַּלְּיָא. לְבָתַר דְּאִיתְגְּנִיזוּ אִלֵּין תְּרֵין סִטְרִין, אִתְהַדַּר כֹּלָּא לְמֶהֱוֵי ו\"ו. וְאַסְתֵּים כֹּלָּא בְּגַוֵּיהּ, וַהֲוָה חָד.</p>"],[9514011158,"<p><Noneb> סִתְרֵי אוֹתִיּוֹת </b></p>"],[9514011159,"<p>(בראשית א׳:י״ד) וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת בִּרְקִיעַ הַשָּׁמָיִם, דָּא ו\"ו, דְּאִיהִי אָת דְּאִיקְרֵי שָׁמָיִם. רְקִיעַ הַשָּׁמָיִם, דְּאִתְפַּשַּׁט מִנֵּיהּ פְּשִׁיטוּ חַד, לְאַנְהָרָא לְאַרְעָא, וּלְאַשְׁקָאָה לְהַהוּא יַבֶּשְׁתָּא, וְהַאי אִיהוּ רְקִיעַ הַשָּׁמָיִם. מַאן אִיהוּ רְקִיעַ הַשָּׁמָיִם. דָּא הוּא פְּשִׁיטוּ דְּאִתְפַּשַּׁט מֵאָת ו\"ו, כְּגַוְּונָא דָא ג, דָּא אִיהוּ פְּשִׁיטוּ דְּאִתְפַּשַּׁט מֵאָת ו\"ו, לְאַנְהָרָא וּלְאַשְׁקָאָה לְאַרְעָא, כְּמָא דְּאִתְּמָר.</p>"],[9514011160,"<p>אָת ו\"ו, דִּיוּקְנָא דָא, אִשְׁתְּלֵיל מִכֹּלָּא, דְּלָא אִיתְחֲזוּן בֵּיהּ כְּלָל מִכָּל אִינוּן סִטְרִין אָחֳרָנִין, בַּר חַד פְּשִׁיטוּ דְּגוּפָא בִּלְחוֹדוֹי, בְּלָא דְרוֹעִין וְסַמְכִין, וְקָיְימָא הָכֵי בְּרָזָא דִשְׁמָא קַדִּישָׁא, בְּגִין לְמֶהֱוֵי זַמִּין לְגַבֵּי נוּקְבָא לְתַתָּא.</p>"],[9514011161,"<p>וְאַף עַל גַּב דְּאִלֵּין סִטְרִין אָחֳרָנִין, אִתְרְשִׁימוּ לְגַבֵּיהּ, הָכָא רָזָא דְרָזִין לְאִינוּן דְּיָדְעֵי רָזֵי דִמְהֵימְנוּתָא, לְמִנְדַע בְּאָן זִמְנָא אִיהוּ אָלֶ\"ף, וּבְאָן זִמְנָא אִיהוּ וָ\"ו.</p>"],[9514011162,"<p>בְּזִמְנָא דְקָיְימָא לְאַחֲזָאָה רָזֵי מְהֵימְנוּתָא, וּלְאַלָּפָא יִחוּדָא בְּרָזָא דִּשְׁמָא קַדִּישָׁא לְכָל עָלְמָא, כְּדֵין קָיְימָא בְּרָזָא. דְּא', אָלֶף לְעַיְינָא, דְּדָא רֵאשִׁיתָא דְּכֹלָּא, לְמֵילַף מְהֵימְנוּתָא דְּיִחוּדָא דְּקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא קָיְימָא רֵישׁ לְכָל אַתְוָון, דְּהָא לָא אָתָא בַּר נָשׁ לְעָלְמָא, אֶלָּא לְמֵילַף וּלְמִנְדַע לְמָארֵיהּ. וְקָיְימָא בִּדְיוֹקְנָא לְעֵינֵיהוֹן דְּכֹלָּא וַאֲמַר לֵיהּ אוֹלִיף חָכְמְתָא דִּמְהֵימְנוּתָא דְּמָארָךְ, וּלְמִקְצֵה הַשָּׁמַיִם וְעַד קְצֵה הַשָּׁמָיִם.</p>"],[9514011163,"<p>וְעַל דָּא אִתְרְשִׁים גַּבֵּיהּ, בִּדְיוֹקְנִין דִּבְרֵאשִׁית, דְּאִתְחֲזֵי לְמִשְׁאַל וּלְמִנְדַע, דִּכְתִיב, (דברים ד׳:ל״ב) כִּי שְׁאַל נָא לְיָמִים רִאשׁוֹנִים. וְדָא הִיא שְׁאֵלְתָּא קַמַּיְיתָא, לְאִשְׁתְּמוֹדַע בַּר נָשׁ לְמָארֵיהּ, דְּדָא אִיהוּ רֵאשִׁיתָא דְּכֹלָּא. וּכְדֵין אִיהוּ רָזָא דְּאָלֶ\"ף, רֵאשִׁיתָא דְּקָיְימָא לְכָל אַתְוָון.</p>"],[9514011164,"<p>וּבְזִמְנָא דְּקָיְימָא לְאִזְדַּוְּוגָא לְגַבֵּי נוּקְבָא, בְּרָזָא דִּשְׁמָא קַדִּישָׁא, קָיְימָא בְּרָזָא דְו\"ו, וְאִשְׁתְּלֵיל מִכֹּלָּא, וְלָא אִתְחֲזוּ בַּר גּוּפָא בִּלְחוֹדוֹי. וְכֹלָּא אִתְקַשַּׁר בְּנוּקְבָא. דְּרוֹעָא חַד, תְּחוֹת רֵישָׁא, וְחַד, דִּמְחַבְּקָא לָהּ.</p>"],[9514011165,"<p>וְעַל דָּא לָא אִיתְחֲזוּן בְּאָת ו\"ו יְרֵכִין, וְהַהוּא דִּרְקִיעָא, כֹּלָּא אִסְתִּים בְּגַוֵּיהּ, בִּסְתִימוּ בְּרָזָא דְרָזִין, וְאִיתְחֲזוּ ו\"ו בִּלְחוֹדוֹי, כְּמַאן דְּאִישְׁתְּלִילוּ מִכֹּלָּא. וּכְדֵין אִיהוּ זַמִּין וְאִתְקַשַּׁר לְגַבָּהּ דְּנוּקְבָא. וְעַל דָּא זַמִּין אָת ו\"ו, בְּרָזָא דִּשְׁמָא קַדִּישָׁא, לְאִתְחֲזָאָה כֹּלָּא. וְקָיְימָא ה\"א בַּתְרָאָה שְׁלֵימָא וּמַלְיָא כְּמָא דְּאִתְחֲזֵי. זַכָּאָה אִיהוּ חוּלָקֵיהּ, מַאן דְּעָאל וּנְפַק, וְיָדַע אוֹרחִין וּשְׁבִילִין בְּרָזָא דִמְהֵימְנוּתָא, לְאִשְׁתְּמוֹדְעָא לְמָארֵיהּ, זַכָּאָה אִיהוּ בְּעָלְמָא הָדֵין וּבְעָלְמָא דְאָתֵי.</p>"],[9514011166,"<p>דִּיוּקְנָא דְאָת יו\"ד, נְקוּדָא קַדְמָאָה דְּסָלְקָא בְּמַחֲשָׁבָה, וְאִסְתִּים וְלָא יְדִיעַ, הַאי נְקוּדָא קָיְימָא בִּסְתִימוּ דְמַחְשָׁבָה, בְּגִין דְּלָא אִתְפַּשַּׁט כְּלָל, וְלָא יְדִיעַ לְאָן אוֹרְחָא הוּא, וּלְאָן אָזִיל, וּמֵאָן אִיהוּ, וּמֵאָן נָפְקָא. וְעַל דָּא כָּלְהוֹ קָיְימִין בַּר בְּהַהוּא נְקוּדָה, דְּקָיְימָא בִּרְעוּ דְּמַחְשָׁבָה, דְּלָא אִתְיְדַע כְּלָל.</p>"],[9514011167,"<p>וְאִיהִי נְקוּדָה דְּקָיְימָא בְּאָת ה\"א עִילָּאָה, דְּקָיְימָא עַל כָּל אִינוּן תֵּשַׁע סָמְכִין דְּקָאֲמָרָן, וְאִינוּן חָמֵשׁ כִּדְקָאֲמָרָן, וְאִינוּן פְּלִיאוֹת. וְעַל דָּא אִיקְרֵי רָזָא דָא פֶּלֶא. וְאוֹת אָלֶף סָלְקָא הָכָא. וְהָכָא כֹּלָּא אוֹת פְּלָאוֹת. וְהָא אוֹקִימְנָא.</p>"],[9514011168,"<p>וְכָל אִלֵּין סָמְכִין, וְכָל אִלֵּין רְתִיכִין דְּקָאֲמָרָן, כַּד סָלְקָא ה\"א בַּתְרָאָה, לְאִתְקַשְּׁרָא בְּאָת וָא\"ו, אִינוּן רְתִיכִין דִּילָהּ פְּרִישָׂן עַל נוּקְבָא כִּדְקָאֲמָרָן, וְכָל אִינוּן רְתִיכִין דִּילָהּ כְּלִילָן בְּאִינוּן רְתִיכִין עִילָּאִין, כָּלְהוֹ חָפְיָין בְּסַחֲרָנָא דְנוּקְבָא.</p>"],[9514011169,"<p>רָזָא דָא, כַּד נוּקְבָא לָא אִתְקַשְּׁרַת בִּדְכוּרָא, חַפְיָא לָהּ חַד קְלִיפָּה תַּקִיפָא דְּסָתֵים נְהוֹרָהּ. וְכַד אִתְקַשְּׁרַת בִּדְכוּרָא, חַפְיָין לָהּ כָּל הַנֵּי רְתִיכִין עִילָּאִין וְתַתָּאִין, אִינוּן קְלִיפָּה קַדִּישָׁא דְּחָפְיָין לָהּ, וְאִתְלַבְּשַׁת בְּהוּ, וְהִיא אִתְקַשְּׁרַת בְּאָת ו\"ו.</p>"],[9514011170,"<p>לְעֵילָא נָטְלָא בְּהֵ\"א, דִּנְקוּדָה עִילָּאָה סָתִים בְּגַוָּוהּ. וְכַד אִיהִי נָטְלָא לוֹן, וְכָלְהוֹ בָּהּ, כְּדֵין אִיתְעֲבִידוּ כָּלְהוֹ, כְּגַוְונָא דָא. כּ וְאַסְתִּים נְקוּדָה עִילָּאָה דְּקָיְימָא בְּאֶמְצָעִיתָא, דְּאִיהוּ ו\"ו דְּאָזְלָא בְּעִיגּוּלָא, לְמֶעְבַּד גּוּפָא לְאַסְתְּמָא לְהַאי נְקוּדָה.</p>"],[9514011171,"<p>כְגַוְונָא דְּהֵ\"א אָחֳרָא, עָבִיד גּוּפָא בְּאִינוּן רְתִיכִין דִּילָהּ, וְאִיהִי נְקוּדָא דְּקָיְימָא בְּאֶמְצָעִיתָא, וּכְדֵין אִיקְּרֵי הֵ\"א. הָכִי נָמֵי הַאי אָת רָזָא דְּו\"ו, אִינוּן גּוּפָא, וְקָיְימָא בְּרָזָא דָא, וְהַאי נְקוּדָה בְּאֶמְצָעִיתָא, וּבְגִין כָּךְ כֹּלָּא חַד. וְהַאי נְקוּדָה עִילָּאָה, אִיקְּרֵי חָכְמָה עִילָּאָה. וְהַאי נְקוּדָה תַּתָּאָה, אִיקְּרֵי חָכְמָה תַּתָּאָה, חָכְמָה זְעֵירָא. וְהַאי הֵ\"א, וְהַאי הֵ\"א, בַּר דְּהַאי נְקוּדָה אִתְרְשִׁים בְּקַדְמִיתָא בִּנְקוּדָאָה.</p>"],[9514011172,"<p>י' נְקוּדָה חַד עִילָּאָה, דְּקָיְימָא עַל תִּשְׁעָה סָמְכִין, כְּמָא דְאוֹקִימְנָא. אִלִּין לָא אִיקְרוּן בִּשְׁמָהָן, בַּר בְּאִינוּן רְתִיכִין דִּילְהוֹן. אֲבָל הַנֵּי תִּשְׁעָה, נָפְקֵי מִגּוֹ בּוּצִינָא, וְאִתְרְשִׁימוּ תְּחוֹתוֹי דְּיוּ\"ד.</p>"],[9514011173,"<p>וְאִינוּן ט' נְקוּדִין, דְּאִתְפַּשְּׁטָן בְּכָל אַתְוָון. בְּגִין דְּכָל אַתְוָון נָפְקִין מִן יוּ\"ד, בְּאִינוּן שְׁבִילִין דִּילָהּ. וּכְמָא דְּאַתְוָון נָפְקִין מִן יוּ\"ד, הָכֵי נִיקּוּדִין. וְכָלְהוֹ הַנֵּי נְקוּדִּין תֵּשַׁע, נָפְקִין מֵאִינוּן תֵּשַׁע.</p>"],[9514011174,"<p>וְאַף עַל גַּב דַּאֲמָרָן, דְּהַנֵּי תֵּשַׁע אִינוּן תְּחוֹתֵיהּ דְּיוּ\"ד, עֲלֵיהּ דְּיוּ\"ד אִינוּן. אֲבָל אִינוּן סָמְכִין לָהּ, וְאִינוּן רְתִיכִין לְט' אָחֳרָנִין, דְּאִינוּן רָזָא דְּאֵין סוֹף, וְכָלְהוֹ קָיְימִין לְיוּ\"ד. וְכָל הַנֵּי דִּלְתַתָּא, אִסְתִּימוּ, וְאַהַדְרוּ לְהַאי נְקוּדָה. עַל דָּא כָּל יוֹמִין.</p>"],[9514011175,"<p>תָּא חֲזֵי, כַּמָּה אִית לוֹן לִבְנֵי נְשָׁא לְאִסְתַּמְּרָא מֵחוֹבֵיהוֹן, וּלְאִשְׁתַּדְּלָא בִּרְעוּתָא דְמָארֵיהוֹן. דְּהָא שִׁבְעָה זַכָּאִין דַּהֲווֹ בְּיִשְׂרָאֵל, דְּאִתְתַּקָּפוּ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא בְּלִבָּא שְׁלִים, וְאִינוּן שִׁבְעָה סַמְכִין דְּעָלְמָא מַמָּשׁ. בְּיוֹמֵיהוֹן, אִתְגַּבַּר בְּעָלְמָא יָמִינָא עַל שְׂמָאלָא. וְיִשְׂרָאֵל עַל עוֹבְדֵי כּוֹכָבִים.</p>"],[9514011176,"<p>וְכֵיוָן דְּאִשְׁתַּלִּימוּ אִינוּן, קָמוּ מִסִּטְרָא דִשְׂמָאלָא שִׁבְעָה בָּתֵּי דִינִין מַמָּשׁ, דְּכָלְהוֹ עוֹבְדֵי עֲבוֹדָה זָרָה, כְּמָה דְּאִתְעָרוּ חַבְרַיָיא, דְּלָא חָרְבָה אֶרֶץ יִשְׂרָאֵל, עַד דְּפָלְחוּ שֶׁבַע בָּתֵּי דִינִין עֲבוֹדָה זָרָה, וּדְאָתוֹ מִנְהוֹן. וְאִלֵּין אִינוּן: יָרָבְעָם בֶּן נְבָט. וּבַעֲשָׁא בֶּן אֲחִיָה. וְאַחְאָב בֶּן עָמְרִי. וְיֵהוּא בֶּן נִמְשִׁי. וּפֶקַח בֶּן רְמַלְיָהוּ. וּמְנַחֵם בֶּן גַּדִּי. וְהוֹשֵׁעַ בֶּן אֵלָה. הֲדָא הוּא דִכְתִיב, (ירמיהו ט״ו:ט׳) אוּמְלָלָה יוֹלֶדֶת הַשִּׁבְעָה. דָּא אַרְעָא קַדִּישָׁא, דִּילִידַת לוֹן.</p>"],[9514011177,"<p>תָּא חֲזֵי, כַּד בְּרָא לָא עָבִיד רְעוּתָא דַּאֲבוֹי, עַל אִימֵּיהּ רַמְיָא לְאַלְקָאָה לֵיהּ, וּלְדַבְּרָא לֵיהּ בְּאֹרַח מֵישָׁר, הֲדָא הוּא דִכְתִיב, (משלי לא) דִּבְרֵי לְמוּאֵל מֶלֶךְ מַשָּׂא אֲשֶׁר יִסְּרַתּוּ אִמּוֹ. מַאי אִמּוֹ. וַדַּאי בַּת שֶׁבַע אֵם שְׁלֹמֹה. וְלָא אֲבוֹי. מַאי טַעְמָא. בְּגִין דְּאִיהִי אִתְפַּקְּדָא עַל בֵּיתָא, וְכָל גְּנִיזִין, וְכָל מָאנֵי קְרָבָא בִּידָהּ אִתְמְסָרִית, וְאִיהִי בָּעְיָיא לְדַבְּרָא בְּנָהָא בְּאֹרַח מֵישָׁר, דְּיַעַבְדּוּן רְעוּתָא דְמַלְכָּא. וְעַל דְּאִיהִי לָא דַּבְּרַת לְהַנֵּי שֶׁבַע בְּאוֹרַח מֵישָׁר, וְלָא אַלְקַת לְהוֹן, אִסְתַּחָרוּ לְסִטְרָא דִשְׂמָאלָא, וְשָׁלְטָא שְׂמָאלָא עַל יָמִינָא, וְאָזְלַת עִמְּהוֹן בְּגָלוּתָא. הֲדָא הוּא דִכְתִיב, (ירמיה טו) אוּמְלָלָה יוֹלֶדֶת הַשִּׁבְעָה.</p>"],[9514011178,"<p>תָּא חֲזֵי, קַדְמָאָה דְּהֲוָה בְּהוּ דְּאִיהוּ יָרָבְעָם, אַתְעַר בְּעָלְמָא סִטְרָא דִשְׂמָאלָא, וְעָבִיד תְּרֵין עֲגָלִין דְּהָא עֶגְלָא מִסִּטְרָא דְשׁוֹר אִיהוּ, דְּאִיהוּ בִּשְׂמָאלָא. וּמַה דַּהֲווֹ תְּרֵי. רָזָא דִתְרֵי חֵילִין דִּשְׂמָאלָא אָתֵי מִינֵּיהּ. כְּדֵין שְׁרִיאַת סִיהֲרָא לְאִתְפָּגְמָא, עַד דְּאִשְׁתַּלִּימוּ אִינוּן ז' מִסִּטְרָא דִשְׂמָאלָא. כֵּיוָן דְּאָתֵי הוֹשֵׁעַ בֶּן אֵלָה, כְּדֵין אִתְפְּגִימַת סִיהֲרָא, וְגָלוּ יִשְׂרָאֵל, וּשְׁכִינְתָּא עִמְּהוֹן.</p>"],[9514011179,"<p>מַאי טַעְמָא. בְּגִין דִּכְנֶסֶת יִשְׂרָאֵל, בְּשִׁבְעָה סְלֵיקַת, וּבְשִׁבְעָה נָחֲתַת, בְּשִׁבְעָה אִשְׁתְּלִימַת, וּבְשִׁבְעָה אִתְפְּגִימַת. בְּשִׁבְעָה אִשְׁתְּלִימַת, כִּדְאוֹקִימְנָא בְּרָזָא דִמְהֵימְנוּתָא, וְזַכָּאִין דַּאֲחִידָן בָּהּ, אַבְרָהָם יִצְחָק וְיַעֲקֹב יוֹסֵף משֶׁה אַהֲרֹן דָּוִד. בְּשִׁבְעָה אִתְפְּגִימַת הַנֵּי שִׁבְעָה בָּתֵּי דִינִין וְאִתְתָּרְכַת מֵאַרְעָא קַדִּישָׁא.</p>"],[9514011180,"<p>דְּהָא תְּרֵיסַר בְּנִין רַשִּׁיעִין הֲווֹ לְהוֹ, לְאִינוּן ז' בָּתֵּי דִינִין. וּכְדֵין אִינוּן י\"ב סָמְכִין דִּלְעֵילָא אִתַּבָּרוּ, אִינוּן י\"ב שְׁבָטִין דְּסַחֲרָנֵי שְׁכִינְתָּא, וְיִשְׂרָאֵל אָזְלוּ בְּגָלוּתָא. אֶלָּא יְהוּדָה דְּאוֹרִיכוּ לֵיהּ, עַד עֲשָׂרָה.</p>"],[9514011181,"<p>תָּא חֲזֵי, עַד דַּהֲווֹ בִּיְרוּשָׁלִַם לְתַתָּא, עֲשָׂרָה מַלְכִין רַשִּׁיעִין, לָא אִתְחָרְבַת, וְלָא אִסְתַּלַּק קוּדְשָׁא בְּרִיךְ הוּא מִינָהּ, וּמִירוּשָׁלַיִם דִּלְעֵילָא, דְּאִיהִי עֲשִׂירָאָה, וּשְׁבִיעָאָה אִתְקְרִיאַת. וְאִינוּן עֲשָׂרָה מַלְכִין דִּלְתַתָּא: רְחַבְעָם. אֲבִיָה. יְהוֹרָם. אֲחַזְיָהוּ. אָחָז. מְנַשֶּׁה. אָמוֹן. יְהוֹאָחָז. יְהוֹיָקִים. יְהוֹיָכִין. וְכַד הֲוָה עֲשִׂירָאָה דִּבְהוֹ בִּישׁ וְלָא אִתְדַּבַּק בְּאוֹרַיְיתָא, כְּדֵין יָהֵיב אַתְרָא לְסִטְרָא דִשְׂמָאלָא, לְשַׁלְטָאָה עֲלֵיהּ, וְעַל יְרוּשָׁלַיִם. וּכְדֵין שְׁכִינְתָּא אִיסְתַּלְּקַת, וְיִשְׂרָאֵל דַּהֲווֹ בִּירוּשָׁלַיִם גָּלוּ. עַל דָּא כְּתִיב (ירמיהו ו׳:ד׳) אוֹי לָנוּ כִּי פָנָה יוֹם, דָּא הוּא חֶסֶד עִילָּאָה, דְּאִיקְּרֵי יוֹם. כִּי יִנָּטוּ צִלְלֵי עֶרֶב, דָּא רָזָא דִשְׂמָאלָא, דְּשָׁרֵי לְשַׁלְטָאָה, דְּהָא מֵהָכָא אָתֵי חֵילָא לְסִטְרָא דִשְׂמָאלָא.</p>"],[9514011182,"<p>תָּא חֲזֵי, שְׁלמֹה בְּאֶמְצָעִיתָא אִיהוּ, בֵּין סִטְרָא דְיָמִינָא לְסִטְרָא דִשְׂמָאלָא, וְחָכְמְתָא דִילֵיהּ אִסְתַּלְּקַת בְּרָזָא דְיָמִינָא, בְּרָזָא דִמְהֵימְנוּתָא, עַל כָּל בְּנֵי עָלְמָא. דְּהָא אִימֵּיהּ אוֹלִיפַת לֵיהּ, וּבְיוֹמוֹי קַיְימָא סִיהֲרָא בְּאַשְׁלָמוּתָא. בְּגִין דָּא כְּתִיב, (מלכים א ה׳:י״א) וַיֶּחְכַּם מִכָּל הָאָדָם דְּאִתְבְּנֵי בֵּי מַקְדְּשָׁא.</p>"],[9514011183,"<p>וּבְסוֹף יוֹמוֹי, שַׁרְיָא סִיהֲרָא לְאִתְפָּגְמָא, וּכְדֵין כְּתִיב, (שם יא) וַיַּעַשׂ שְׁלֹמֹה הָרַע בְּעֵינֵי ה', וְלֹא מִלֵּא אַחֲרֵי ה' כְּדָוִד אָבִיו. לֹא מִלֵּא דַּיְיקָא, לָא אַשְׁלִים מַה דְּאִיהוּ הֲוֵי לֵיהּ לְאַשְׁלָמָא כֹּלָּא בָּתַר דָּוִד, דְּאִיהוּ מֵאִינוּן שִׁבְעָה סַמְכִין, וְלָא מַלְיָיא סִיהֲרָא, אֶלָּא דְּאִיתְפְּגֵים.</p>"],[9514011184,"<p>בְּגִין כָּךְ, לָא מָנִינָן לֵיהּ, לָא עִם אִינוּן שִׁבְעָה זַכָּאִין סָמְכִין דְּעָלְמָא, וְלָא עִם אִינוּן דְּמָרְדוּ בְּמָארֵיהוֹן, אֶלָּא אִיהוּ בְּאֶמְצָעִיתָא, מִסִּטְרָא דְיָמִינָא שְׁלִים, וּמִסִּטְרָא דִשְׂמָאלָא פָּגִים.</p>"],[9514011185,"<p>בְּגִין כַּךְ כְּתִיב (מלכים א י״א:י״א) קָרוֹעַ אֶקְרַע אֶת הַמַּמְלָכָה, דָּא רָזָא, דְּמַלְכָּא בָּזַע פּוּרְפִּירָא דִילֵיהּ, דְּהָא מַמְלָכָה עֲלֵיהּ דִּשְׁלֹמֹה הִיא, וְאִמֵּיהּ אִיקְּרֵי, וְדָא בַּת שֶׁבַע. וּנְתַתִּיהָ לְעַבְדֶּךָ. בְּגִין כָּךְ כְּתִיב, (משלי ל׳:כ״ג) תַּחַת עֶבֶד כִּי יִמְלֹךְ וְשִׁפְחָה כִּי תִירַשׁ גְּבִירְתָּהּ. תָּא חֲזֵי, הַאי עֶבֶד לָא אִתְיְהֵיב לֵיהּ מַלְכוּת, אֶלָּא מֵהָכָא, הֲדָא הוּא דִכְתִיב וּנְתַתִּיהָ לְעַבְדֶּךָ, וּכְדֵין שַׁרְיָא שִׁפְחָה לְשַׁלְטָאָה.</p>"],[9514011186,"<p>תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב קָרוֹעַ, וּלְבָתַר אֶקְרַע. קָרוֹעַ זְעֵיר, דְּאִיתְקְרַע מִמֵּילָא, בְּגִין דְּהַהוּא שַׁעֲתָא שַׁרְיָיא סִיהֲרָא לְאִתְפָּגְמָא. וּלְבָתַר אֶקְרַע, דְּאִתְכַּסְּיָא בְּגָלוּתָא. וְזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲתָבָא שְׁכִינְתָּא לְאַתְרָאָה, וּלְיִשְׂרָאֵל לְאַתְרַיְיהוּ, וּלְאִתְפָּרְעָא מֵאִינוּן דְּסִטְרָא דִשְׂמָאלָא דְּעָאקוּ לוֹן. הֲדָא הוּא דִכְתִיב, (עובדיה א׳:כ״א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט. וְעָלוּ מוֹשִׁיעִים: צַדִּיק, וּכְנֶסֶת יִשְׂרָאֵל. בְּהַר צִיּוֹן: רָזָא דְיָמִינָא. לִשְׁפֹּט אֶת הַר עֵשָׂו: רָזָא דִשְׂמָאלָא.</p>"],[9514011187,"<p>תָּא חֲזֵי, הַאי הַר, (\"חילופי גרסאות\") לִישְׁנָא דִּתְקִיפוּ הוּא. אִינוּן הָרִים לְעֵילָא, וְאִלֵּין צַדִּיקִים דַּאֲחִידָן בִּכְנֶסֶת יִשְׂרָאֵל. וְאִקְרוּן הַר צִיּוֹן. אִינוּן הָרִים דְּסַחֲרָנֵי יְרוּשָׁלִַם, בְּגִין דְּאִינוּן מְצוּיָינִין וְאָמְרִין הַאי בְּהַאי, בְּסִתְרָא דְיִחוּדָא, לִשְׁפֹּט אֶת הַר עֵשָׂו, דְּקַטְרִיגוּ מְקַטְרְגָא מִסִּטְרָא דִשְׂמָאלָא.</p>"],[9514011188,"<p>בְּהַהוּא זִמְנָא (עובדיה א׳:כ״א) וְהָיְתָה לַיְיָ' הַמְלוּכָה. בְּקַדְמִיתָא אִקְרֵי מַמְלָכָה, בְּגִין דְּיָנְקָא לִתְרֵין סִטְרִין, לְיָמִינָא וְלִשְׂמָאלָא. וְהַשְׁתָּא מְלוּכָה אִקְּרֵי, בְּגִין דְּיָנְקָא לְיָמִינָא. הֲדָא הוּא דִכְתִיב, (הושע ב׳:כ״א) וְאֵרַשְׂתִּיךְ לִי לְעוֹלָם. וּבְגִין דְּגָלוּתָא לָאו לְעוֹלָם הוּא, דְּהָא יָתְבָא בְּגָלוּתָא.</p>"],[9514011189,"<p>תָּא חֲזֵי, דִסְמִיךְ לֵיהּ, (זכריה י״ד:ט׳) וְהָיָה יְיָ' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד. בְּגִין דְּעַד הַשְׁתָּא כַּד יִשְׂרָאֵל בְּגָלוּתָא, שְׁכִינְתָּא עִמְּהוֹן, וּמַלְכָּא בְּלָא מַטְרוּנִיתָא לָאו מַלְכָּא אִיהוּ. אֲבָל הַהוּא זִמְנָא, וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ בַּיּוֹם הַהוּא יִהְיֶה יְיָ' אֶחָד וּשְׁמוֹ אֶחָד. כַּד אִתְדַּבְּקַת שְׁכִינְתָּא בְּצַדִּיק, כְּדֵין הוּא יִחוּדָא. דְּהָכֵי אוֹלִיפְנָא בְּרָזָא דִּקְרִיאַת שְׁמַע, דְּבָעֵי בַּר נָשׁ לְיַחֲדָא לְמָארֵיהּ, וּלְקָשְׁרָא קִשְׁרִין דִּמְהֵימְנוּתָא בִּרְעוּתָא דְלִבָּא.</p>"],[9514011190,"<p>וְכַד מָטֵי לְאֶחָד, אִבָּעֵי לֵיהּ לְכַוְּונָא בְּא' סְתִימָא ב' עַתִּיקָא דְּכֹלָּא. וְח', תְּמַנְיָא דַרְגִּין עִלָּאִין, מֵחָכְמָה עִלָּאָה עַד צַדִּיק. וְד' רַבָּתָא, אִתְדַּבְּקוּתָא דִּכְנֶסֶת יִשְׂרָאֵל דְּאִיהוּ חוּלָקֵיהּ דְּדָוִד, דְּאִקְרֵי עָנִי וְאֶבְיוֹן, כַּד אִתְדַּבְּקָא לְאִינוּן דַּרְגִּין דִּלְעֵילָא דִּרְמִיזִין בְּא\"ח. כְּדֵין אִיהִי רַבָּתָא וְעָלְמָא כּוּלֵיהּ יָנִיקּ מִינָהּ, וְאִינוּן שָׁדַיִם, דְּאִינוּן כְּמִגְדָּלוֹת (שיר השירים ח׳:י׳) אָז הָיִיתִי בְּעֵינָיו כְּמוֹצֵאת שָׁלוֹם.</p>"],[9514011191,"<p>תָּא חֲזֵי, הַאי קְרָא עַל כְּנֶסֶת יִשְׂרָאֵל אִתְּמָר, כַּד אִיהִי בְּגָלוּתָא עִם בְּנָהָא, בֵּין אוּמִין דְּעָלְמָא, אִקְּרֵי זְעֵירָא, הֲדָא הוּא דִכְתִיב, (שם) אָחוֹת לָנוּ קְטַנָּה. וְכַד יִשְׂרָאֵל אִתְדַּבְּקוּ בְּאוֹרַיְיתָא, וְאָזְלִין בְּאֹרַח קְשׁוֹט, כְּדֵין אִתְמַלְיָיא, וְשָׁלוֹם אִתְחַבַּר בְּהוּ. אֲתֵיבַת אִיהִי וַאֲמָרַת, אֲנִי חוֹמָה וְשָׁדַי כַּמִּגְדָּלוֹת. בְּהַהוּא זִמְנָא דְּאִתְחַבַּר עִמִּי אָ\"ז, וְשָׁלוֹ\"ם. א': רָזָא דְּעַתִּיקָא קַדִּישָׁא דְּכֹלָּא. ז': שֶׁבַע דַּרְגִּין. וְשָׁלוֹם: דְּאִקְרוּן צַדִּיק. כֵּיוָן דְּהַנֵּי דַּרְגִּין מִתְחַבְּרִין, כְּדֵין אָ\"ז הָיִיתִי בְּעֵינָיו כְּמוֹצֵאת שָׁלוֹם. וּמָאן עַיְינִין. אִינוּן ז' דַּרְגִין דְּאִקְרוּן עֵינֵי יְיָ', פְּנֵי יְיָ'. וּכְדֵין שְׁלָמָא לְעָלְמָא, וְשַׁרְיָא טִיבוּ דְּעַתִּיקָא בַּאֲתַר דִּדְכַר וְנוּקְבָא. וּבְגִין כָּךְ פְּקַד משֶׁה בְּאוֹרַיְיתָא וַאֲמַר, (דברים ו׳:ד׳) שְׁמַע יִשְׂרָאֵל ה' אֱלֹקֵינוּ ה' אֶחָד. לְקַשְּׁרָא כָּלְהוֹ קְשִׁירִין דִּמְהֵימְנוּתָא.</p>"],[9514011192,"<p>תָּא חֲזֵי, כָּל הַמַּאֲרִיךְ בְּאֶחָד מַאֲרִיכִין לוֹ יָמָיו וּשְׁנוֹתָיו. מַאי טַעְמָא. בְּגִין דְּאִיהוּ אֲתַר, דְּכָל יוֹמִין וּשְׁנִין דְּעָלְמָא בֵּיהּ תָּלְיָין, בְּרָזָא דְּאִינוּן דַּרְגִּין דִּרְמִיזִין בְּאֶחָד, וְאִינוּן עֲשָׂרָה, וְכָלְהוֹ חָד, וְאִתְעָרוּ בֵּיהּ חַבְרַיָיא וַאֲמָרוּ וּבְדל\"ת, וְשַׁפִּיר, בְּגִין דְּהַאי אַתְרָא דְּדל\"ת הִיא, וְלֵית לָהּ נְהוֹרָא מִדִּילָהּ, וּבְעֵי בַּר נָשׁ לַאֲרָכָא בָּהּ, וּלְאַמְשָׁכָא לָהּ בִּרְכָאן, מֵאִינוּן שִׁית סִטְרִין, שִׁית בְּנִין עִלָּאִין עַל יְדֵי דְּצַדִּיק.</p>"],[9514011193,"<p>וְאִינוּן שִׁית סִטְרִין רְמִיזִין בְּח' בְּרָזָא דִתְמַנְיָא. שִׁית אִלֵּין, וּתְרֵין לְעֵילָא חָכְמָה וּבִינָה, אַבָּא וְאִימָּא לְאוֹסָפָא וּלְאַכְלָלָא לְהוֹ לְעֵילָא, וּלְמֵיהַב לְהוֹ בִּרְכָאן מֵאַבָּא וְאִמָּא עִלָּאָה. דְּהָא לָא שַׁרְיָא טִיבוּ דְּעַתִּיקָא, אֶלָּא בַּאֲתַר דִּשְׁלִים, בַּאֲתַר דְּאִשְׁתְּכַח דְּכַר וְנוּקְבָא. הֲדָא הוּא דִכְתִיב, (שיר השירים ג׳:י״א) צְאֶינָה וּרְאֶינָה בְּנוֹת צִיּוֹן בַּמֶּלֶךְ שְׁלמֹה וְגו', בְּיוֹם חֲתוּנָתוֹ וְגו', בְּיוֹם חֲתוּנָתוֹ דַּיְיקָא.</p>"],[9514011194,"<p>וְעַל דָּא אֲמָרוּ וּבִלְבָד שֶׁלֹּא יַחֲטוֹף בְּחי\"ת, אֶלָּא בָּעֵי לְאַמְשָׁכָא בִּרְכָאן מֵאֲתַר עִלָּאָה דְכֹלָּא, וְלַאֲרָקָא בְּאִינוּן שִׁית בְּנִין. לְבָתַר לְהַאי בַּת, דְּלֵית לָהּ אַחְסָנָא בְּבֵית אֲבוּהָ וְאִמָּא, אֶלָּא הַאי בְּרָא. וּמִכָּאן אוֹלִיפְנָא, דִּבְרָא יָרִית לְאַבָּא וּלְאִימָּא, וּבְרַתָּא לָא. אֶלָּא דְּאִית לָהּ מְזוֹנֵי מִן בְּרָא. אֶלָּא בָּעֵי לַאֲרָכָא בְּהַאי דל\"ת.</p>"],[9514011195,"<p>וְתַמָּן אָמְרֵי, כַּמָּה בָּעֵי בַּר נָשׁ לַאֲרָכָא בָהּ. כְּשִׁיעוּרָא דְּיַמְלִיךְ יָתָהּ לְעֵילָא וּלְתַתָּא, וּלְאַרְבַּע זָוְויָין דְּעָלְמָא. רָזָא דְשִׁית סִטְרִין עִלָּאִין, דְּכָלְהוֹ אִתְחַבְּרוּן עִמָּהּ, וְלָא יִתְפָּרְשׁוּן לְעָלְמִין. וְכַד בַּר נָשׁ מַאֲרִיךְ בְּהַאי, כָּל אִינוּן יוֹמִין וּשְׁנִין עִלָּאִין, מוֹסְרִין בִּרְכָאן עַל רֵישֵׁיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא קָרֵי לֵיהּ, (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאֵר.</p>"],[9514011196,"<p>תָּא חֲזֵי, כְּלָלָא דְאוֹרָיְיתָא בְּהַאי קְרָא רְמִיזִין, וּכְלָלָא דְּכל אִינוּן אֲמִירָן, דְּאִתְבְּרֵי בְּהוֹן עָלְמָא, בְּאֶחָד רְמִיזִין. הֲדָא הוּא דִכְתִיב, (איוב כ״ג:י״ג) וְהוּא בְּאֶחָד וּמִי יְשִׁיבֶנּוּ וְנַפְשׁוֹ אִוְתָה וַיָּעַשׂ. וּבְהוֹן אִתְבְּרֵי עָלְמָא. וְעַל דָּא תָּנִינָן, בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם וכו'. וְאוֹקִימְנָא דְּכָלְהוֹ י', וְכָלְהוֹ כְּלִילָן בִּקְרָא קַדְמָאָה דְּאוֹרָיְיתָא.</p>"],[9514011197,"<p>י (בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלֹהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, רָאשֵׁי תֵיבוֹת אהו\"ה, דְּבֵיהּ אִתְבְּרִיאוּ שְׁמַיָא וְאַרְעָא. א\"ה, בֵּיהּ אִתְבְּרִיאוּ שְׁמַיָא. ו\"ה, בֵּיהּ אִתְבְּרִיאַת אַרְעָא, וְכָל מַה דְּאִית בָּהּ. וְהוּא יָהֵיב תֵּיאוּבְתָּא בְּכָל אִילָנִין וְעִשְּׂבִין דִּי בְאַרְעָא. וְהוּא מַה דַּאֲמָרוּ, אֵין לְךָ עֵשֶׂב וְעֵשֶׂב מִלְּמַטָה שֶׁאֵין עָלָיו מַלְאָךְ מִלְּמַעְלָה שֶׁמַּכֶּה אוֹתוֹ וְאוֹמֵר לוֹ גְּדַל. שֶׁנֶּאֱמַר (איוב ל״ח:ל״ג) הֲיָדַעְתָּ חֻקּוֹת שָׁמָיִם אִם תָּשִׂים מִשְׁטָרוֹ בָאָרֶץ.</p>"],[9514011198,"<p>תָּא חֲזֵי, כְּתִיב (בראשית א׳:ד׳) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם, וּכְתִיב (שם) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, דְּהַאי אוֹר דִּלְתַתָּא, כַּד נָהֵיר, נָהֵיר מֵחֵילָא דְּאִתְיְהִיב לֵיהּ מִטוּב דִּלְעֵילָא.</p>"],[9514011199,"<p>וּבְגִין כָּךְ מִנְיַן יְמוֹת הַחַמָּה שס\"ה, מַאי טַעְמָא שְׁבוּעִין מִנְהוֹן, לָקֳבֵיל הַאי דַּרְגָּא דְּצַדִּיק, דְּאִיקְּרֵי טוֹב, וְאִיהִי שְׁבִיעִי, וְיָנִיק מִנֵּיהּ הַאי שִׁמְשָׁא דִּלְתַתָּא, שֶׁבַע שְׁבוּעִין שֶׁבַע זִמְנִין, לָקֳבֵל שֶׁבַע שְׁבוּעִין שֶׁבַע זִמְנִין, דְּאִיהוּ יָנִיק מֵאִימָּא עִילָּאָה, דְּאִיקְּרֵי יוֹבֵל. וּלְקִבְלָא שְׁנֵי יוֹבֵל דִּלְתַתָּא.</p>"],[9514011200,"<p>אִשְׁתָּאֲרוּ מִשס\"ה כ\"ב יוֹמִין, לָקֳבֵל כ\"ב אַתְוָון דְּאוֹרָיְיתָא, דְּעָלְמָא תַּתָּאָה אִתְקַיֵּים עֲלַיְיהוּ, דְּהָא צַדִּיק דִּלְעֵילָא תּוֹרָה שֶׁבִּכְתָב אִיתְקְרֵי. וְכַד אִשְׁתַּלִּימוּ אִינוּן שס\"ה יוֹמִין, תָּיְיבִין תִּנְיָינוּת לְקַבְּלָא מֵהַאי דַרְגָּא דְטוֹב, דְּהַאי דַרְגָא, וְכָל אִינוּן שֶׁבַע דַּרְגִּין עִילָּאִין, תָּיְיבִין תִּנְיָינוּת לְקַבְּלָא מִן אִימָּא עִלָּאָה.</p>"],[9514011201,"<p>וְהַאי דַרְגָּא דְּסִיהֲרָא דְּשָׁלְטָא בְּלֵילְיָא, יָנְקָא מֵהַאי דַרְגָּא דְּאִיתְקְרֵי צַדִּיק. וּבְגִין דְּהַהוּא צַדִּיק אַמְלֵי לָהּ מֵהַהוּא תַּפְנוּקִין עִילָּאִין, וְיָנְקָא מִנֵּיהּ, אִיקְּרֵי סִיהֲרָא. דְּכַמָּה דְּהַאי סִיהֲרָא תַּתָּאָה, לֵית לָהּ נְהוֹרָא מִגַּרְמָּהּ, אֶלָּא מַאי דְּאִתְיְהֵיב לָהּ מִן שִׁמְשָׁא. הָכֵי נָמֵי הַהוּא דַּרְגָּא דִלְעֵילָא.</p>"],[9514011202,"<p>וְהַאי דַרְגָּא אִיקְּרֵי יַמָּא דְחָכְמְתָא לְעֵילָא, וְקָיְימֵי תְּרֵיסַר שְׁבָטִין עִילָּאִין קַדִּישִׁין. תְּלָתָא לְצָפוֹנָא. וּתְלָתָא לְדָרוֹמָא. וּתְלָתָא לְמַעֲרָבָא. וּתְלָתָא לְמַדִּינְחָא. וְיַמָּא דְחָכְמְתָא עֲלַיְיהוּ. וּלְקִבְלֵיהוֹן לְתַתָּא, תְּרֵיסַר שְׁבָטִין, קָיְימִין סַחֲרָנֵי מַדְבְּחָא, כִּי הַאי גַוְונָא. וְלָקֳבֵל הַאי דַרְגָּא, עֲבַד שְׁלֹמֹה יַמָּא לְתַתָּא, (מלכים א ז׳:מ״ד) עוֹמֵד עַל שְׁנֵים עָשָׂר בָּקָר.</p>"],[9514011203,"<p>וְהַאי יַמָּא דִלְעֵילָא, מַאי טַעְמָא אִיקְּרֵי יַם. אֶלָּא בְּגִין הַהוּא דַּרְגָּא דְצַדִּיק, דְּאַמְלֵי לְהַאי יַם, אִקְּרֵי יוֹם, דִּכְתִיב (בראשית א׳:ה׳) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. וּכְתִיב (תהילים צ״ז:י״א) אוֹר זָרֻעַ לַצַּדִּיק. וְהַאי נָהֵיר בְּרָזָא דְּו\"ו דִּשְׁמָא קַדִּישָׁא, דְּבֵיהּ אַמְלֵי לְהַאי יַם, דְּאִקְּרֵי ה\"א תַּתָּאָה, בַּתְרָאָה דִּשְׁמָא קַדִּישָׁא.</p>"],[9514011204,"<p>הֲדָא הוּא דִכְתִיב, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם. כָּל: דָא דַּרְגָא דְּצַדִּיק, דְּאִיקְרֵי כָּ\"ל, בְּגִין דְּכָל תַּפְנוּקִין מִנֵּיהּ נָפְקִין. הַנְּחָלִים: אִינוּן חָמֵשׁ דַּרְגִּין, דְּעִמֵּיהּ הוֹלְכִים אֶל הַיָּם, לְמִמְלֵי לָהּ.</p>"],[9514011205,"<p>וְהַאי דַרְגָּא אִיקְּרֵי בַּת שֶׁבַע, וְכַד נָהֵיר הַאי צַדִּיק לְהַאי דַרְגָּא, בְּרָזָא דְּשֶׁבַע שְׁבוּעִין שֶׁבַע זִמְנִין, כְּדֵין שִׁמְשַׁא תַּתָּאָה נָהֵיר, בְּרָזָא דְּשֶׁבַע שְׁבוּעִין שֶׁבַע זִמְנִין לְסִיהֲרָא.</p>"],[9514011206,"<p>בְּגִין כַּךְ, שְׁנַת הַלְּבָנָה שנ\"ה יוֹמִין. מַאי טַעְמָא שְׁבוּעִין מִנְּהוֹן, לָקֳבֵיל הַאי דַּרְגָּא שְׁבִיעָאָה, יַמָּא עִילָּאָה דְּנָהֲרָא מִצַּדִּיק, בְּמ\"ט שְׁבוּעִין נְהוֹרִין עִלָּאִין, אִשְׁתָּאֲרוּ תְּרֵיסַר יוֹמִין לְחוּשְׁבַּן שָׁנָה. לָקֳבֵיל תְּרֵיסַר שְׁבָטִין דְּסַחֲרָנֵי הַאי יַמָּא, לְמִטַר מַטְרַת מַשְׁכְּנָא, בִּתְרֵיסַר תַּרְעִין עִלָּאִין, דְּאִית בִּיְרוּשָׁלִַם עִלָּאָה. וְאוֹרְחָא דְּאִנוּן תַּרְעִין, יַנְקִין אִינוּן שְׁבָטִין, מֵאִימָּא תַּתָּאָה, כָּל חַד לְסִטְרֵיהּ, כִּדְחָזֵי לֵיהּ, הֲדָא הוּא דִכְתִיב, (יחזקאל מ״ח:ל״א) שַׁעַר יְהוּדָה אֶחָד.</p>"],[9514011207,"<p>וְעַל דָּא כְּתִיב, (ישעיהו מ״ג:ז׳) כָּל הַנִּקְרָא בִּשְׁמִי, דָּא דַּרְגָּא דְצַדִּיק, דְּנָהֵיר בְּחֵילָא דִּשְׁמֵיהּ. וְלִכְבוֹדִי בְּרָאתִיו, לְאַנְהָרָא לְהַהוּא אֲתַר דְּאִקְּרֵי כָּבוֹד בְּרָאתִיו. וְדָא יַמָּא דְּחָכְמְתָא, דְּאִקְּרֵי כְּבוֹד ה', דְּאִתְגְּלֵי בְּמַשְׁכְּנָא. יְצַרְתִּיו, דָּא רָזָא דְּיוֹם דִּלְתַתָּא, דְּאִיהוּ לָקֳבֵל כָּל דִּלְעֵילָא. וְעַל דָּא כְּתִיב, (ישעיהו מ״ה:ז׳) יוֹצֵר אוֹר. וְהַאי צַדִּיק לְעֵילָא לָא כְּתִיב בֵּיהּ יְצִירָה, עַד דְּאִיתְגְּלֵי עֲבִידְתֵּיהּ לְתַתָּא, וְנָהֵיר עָלְמָא תַּתָּאָה מִנִּיהּ.</p>"],[9514011208,"<p>אַף עֲשִׂיתִיו, דָּא סִיהֲרָא לְתַתָּא, הֲדָא הוּא דִכְתִיב (שם) וּבוֹרֵא חשֶׁךְ. כַּד אִיתְחַבְּרוּ, כְּדֵין עוֹשֶׂה שָׁלוֹם, שְׁלָמָא לְעָלְמָא. הֲדָא הוּא דִכְתִיב, (בראשית א׳:ה׳) וַיְהִי עֶרֶב וַיְהִי בֹקֶר יוֹם אֶחָד. כְּדֵין יִחוּדָא דִּלְעֵילָא, יִחוּדָא לְתַתָּא, שְׁלָמָא לְעֵילָא שְׁלָמָא לְתַתָּא.</p>"],[9514011209,"<p>כְגַוְונָא דָא, יוֹסֵף לְתַתָּא, דְּהוּא אָחִיד בְּצַדִּיק דִּלְעֵילָא, כַּד אִישְׁתְּלִים לְתַתָּא, אוֹסֵיף שְׁלָמָא בְּכָלְהוֹ עָלְמִין, וּבְכָל יוֹמִין עִילָּאִין. כְּתִיב הָכָא, (שם לט) וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם, וּכְתִיב הָתָם, (תהילים ס״ח:כ׳) בָּרוּךְ ה' יוֹם יוֹם. כַּד לָא שְׁמַע לָהּ יוֹם יוֹם, כְּדֵין יוֹמִין עִילָּאִין בִּשְׁלָמָא וּבִרְכְּתָא בְּכָלְהוֹ עָלְמִין.</p>"],[9514011210,"<p>(בראשית ו׳:ז׳) וַיֹּאמֶר ה' אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנֵי הָאֲדָמָה. לַאֲפָקָא אָדָם דִּלְעֵילָא, וְאִי תֵימָא אָדָם דִּלְתַתָּא בִּלְחוֹדוֹי. לָאו לַאֲפָקָא כְּלָל, מִשּׁוּם דְּלָא קַיָּים דָּא בְּלָא דָּא.</p>"],[9514011211,"<p>וְאִלְמָלֵי חָכְמָה סְתִימָאָה דְּכֹלָּא, כֹּלָּא אִתְתַּקַּן כִּמְרֵישָׁא, הֲדָא הוּא דִכְתִיב, (משלי ח׳:י״ב) אֲנִי חָכְמָה שָׁכַנְתִּי עָרְמָה. אַל תִּקְרֵי שָׁכַנְתִּי, אֶלָּא שְׁכִינְתִי. וְאִלְמָלֵא הַאי, לָא קָאִים עָלְמָא, הֲדָא הוּא דִכְתִיב, (שם ג) ה' בְּחָכְמָה יָסַד אָרֶץ. וּכְתִיב (בראשית ו׳:ח׳) וְנֹחַ מָצָא חֵן בְּעֵינֵי ה'.</p>"],[9514011212,"<p>(בראשית ה׳:ג׳) וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ וַיִּקְרָא אֶת שְׁמוֹ שֵׁת, אוֹלִיפְנָא מֵהָכָא, דְּאָחֳרָנִין לָא הֲווֹ בִּדְיוֹקְנָא דִילֵיהּ, וְדָא הוּא בִּדְמוּתוֹ כְּצַלְמוֹ, אִתְעֲבֵיד בְּתִיקּוּנָא דְּגוּפָא, וּבְתִיקּוּנָא דְּנַפְשָׁא, בְּאוֹרַח מֵישָׁר כִּדְקָא יָאוֹת. תָּא חֲזֵי, נָחָשׁ אַטֵיל זוּהֲמָא בְּחַוָּה, וְהַהוּא זוּהֲמָא מְכַשְׁכְּשָׁא הֲוָה בִּמְעָהָא, וְלָא יָכֵיל לְאִצְטַיְירָא.</p>"],[9514011213,"<p>בְּגִין דְּעַד לָא חָטָא אָדָם, הֲוֵי אַתְוָון דְּאַלְפָא בֵּיתָא מִתְתַּקְּנָן בֵּיהּ, וּמִתְצַיְירִין בֵּיהּ בְּהַאי עָלְמָא, כֵּיוָן דְּמָטָא לְכָ\"ף דְּאִתְתַּקָּנוּ דְּכַר וְנוּקְבָא, בַּחֲבִיבוּ בְּגִנְתָא, וּמַלְאֲכֵי עִילָּאֵי קַמַּיְיהוּ, וּמִיָּד אַבְאֵישׁ לִסמאל בִּרְקִיעָא, וּנְחַת רָכֵיב עַל נָחָשׁ תַּקִּיף, וְאִתְחֲזֵי קַמֵּיהּ, מִיָּד אִתְעָרְבוּ אַתְוָון.</p>"],[9514011214,"<p>כְדֵין אִתְחַבַּר סמאל בְּהַהוּא נָחָשׁ, וְאִתְעֲבִידוּ חָד, וּנְטָלוּ אַתְוָון, וַעֲבָדוּ מִתַּמָּן וּלְהָלְאָה אוּמָנוּתָא בִּישָׁא, בְּאַתְוָון צ\"ד צי\"ד, וְהַיְינוּ צ\"ץ, וְצָדוּ לוֹן בְּפִתּוּיָיא בִּישָׁא, וַעֲבָדוּ אוּמָנוּתָא יַתִּיר בְּאַתְוָון ק\"ר, אוּמָנוּתָא דְּשִׁקְרָא, בְּגִין דְּאַהַדְּרָן לְאִתְהַפָּכָא אַתְוָון בְאוּמָנוּתָא בִּישָׁא, קוּ\"ף דְּלָא יָכִיל לְקָיְימָא, דְּלֵית לֵיהּ רַגְלִין, כְּקוֹפָא קַמֵּי בְּנֵי נְשָׁא לֵית לֵיהּ קִיּוּמָא. רי\"ש רָע. אִלֵּין אִתְהַפָּכוּ בְּאוּמָנוּתָא בִּישָׁא, עַד דְּנָפְלֵי אָדָם וְאִיתְּתֵיהּ.</p>"],[9514011215,"<p>וּבְאִלֵּין אַתְוָון ק\"ר אוֹלִידוּ בְּנִין, וְלָא בְּקִיּוּמָא. זוּהֲמָא דְּנָחָשׁ דְּאִשְׁתְּאֵיב בְּחַוָּה, מֵהַהוּא זוּהֲמָא אִתְיְלִיד קַיִן. וּבְגִין כָּךְ אִשְׁתְּכַח קָטוֹלָא, בְּגִין דְּנָחָשׁ אוּמָנוּתָא דִּילֵיהּ קָטוֹלָא הוּא, וְאִתְעַכָּבוּ אַתְוָון עַד הָכָא.</p>"],[9514011216,"<p>בְּשַׁעֲתָא דְּתָב אָדָם בִּתְיוּבְתָּא, וְאַהֲדַר כְּמִלְּקַדְּמִין לְשַׁמְּשָׁא בְּנוּקְבֵיהּ, מַה כְּתִיב, וַיּוֹלֶד בִּדְמוּתוֹ כְּצַלְמוֹ, דְּדָא הוּא מִתִּיקּוּנָא דְּגוּפָא וְרוּחָא כִּדְקָא יָאוֹת, וּכְתִיב (קהלת ח׳:י״ד) יֵשׁ הֶבֶל אֲשֶׁר נַעֲשָׂה עַל הָאָרֶץ, וְאַהֲדָרוּ אַתְוָון לְשֵׁירוּתָא דְּשי\"ן תיו, דִּכְתִיב (בראשית ד׳:כ״ה) כִּי שָׁת לִי אֱלֹהִים זֶרַע אַחֵר תַּחַת הֶבֶל. שֵׁת הֲוָה בְּצֶלֶם וּדְמוּת. דְּקַדְמָאי לָאו הָכֵי, וּמֵהָכָא אִתְבְּנֵי עָלְמָא בְּגַוְּונָא אָחֳרָא דְּאַלְפָא בֵיתָא, קֵינָן מַהֲלַלְאֵל יֶרֶד, אִתּוֹסַף אָת לְתַקְּנָא עֲקִימָא.</p>"],[9514011217,"<p>סִדּוּרָא דְעָלְמָא, בְּשֶׁבַע קִטְרִין סְגַלְגַּלָּן. שֶׁבַע אֲרָצוֹת אִינוּן, דָּא לְעֵילָא מִן דָּא. כְּמָא דְּאִינוּן שִׁבְעָה רְקִיעִין, דָּא לְעֵילָא מִן דָּא. וְאִינוּן: אֶרֶץ. אֲדָמָה. אַרְקָא. גֵּיא. נְשִׁיָּה. צִיָּה. תֵּבֵל. לְעֵילָא מִכָּלְהוֹ, תֵּבֵל, דִּכְתִיב (תהילים ט׳:ט׳) וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק.</p>"],[9514011218,"<p>כַד נְפַק אָדָם מִגִּנְתָא דְעֵדֶן, וְאִתְתָּרַךְ מִתַּמָּן, אִתְרַמֵּי לְהַהוּא דְּאִיקְּרֵי אֶרֶץ. דְּאִיהוּ אֲתַר חָשִׁיךְ, דְּלֵית תַּמָּן נְהִירוּ כְּלוּם, וְלָא מְשַׁמֵּשׁ כְּלוּם, כֵּיוָן דְּאָדָם עָאל תַּמָּן, דָּחֵיל דְּחִילוּ סַגֵּי, וְלַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת, הֲוָה מְלַהֲטָא גּוֹ סִטְרִין, גּוֹ הַהוּא אֶרֶץ.</p>"],[9514011219,"<p>כֵיוָן דִּנְפַק שַׁבָּת, וְהִרְהֵר בִּתְשׁוּבָה, אָרֵים לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וְסָלֵיק לֵיהּ לְהַהוּא אֲתַר דְּאִקְרֵי אֲדָמָה, דִּכְתִיב (בראשית ג׳:כ״ג) וַיְשַׁלְּחֵהוּ יְיָ' אֱלֹהִים מִגַּן עֵדֶן לַעֲבֹד אֶת הָאֲדָמָה. בְּהַאי אִית נְהִירוּ דְּנָהֵיר, וּדְיוֹקְנִין דְּכוֹכְבַיָא וּמַזָּלֵי.</p>"],[9514011220,"<p>וְתַמָּן צִיּוּרִין דִּבְנֵי נְשָׁא עִילָּאִין, גּוּבְרִין דִּנְפָקוּ מֵאָדָם קַדְמָאָה, בְּמֵאָה וּתְלָתִין שְׁנִין, דְּקָא הֲוָה מְשַׁמֵּשׁ בְּרוּחֵי נוּקְבֵי. וְאִינוּן עֲצִיבִין תָּדִיר, וְלֵית בְּהוּ חֶדְוָה, וְאִלֵּין מְשָׁטְטֵי וְנָפְקֵי לְעָלְמָא דָא, וּמִתְהַפְּכִין לְסִטְרָא בִּישָׁא, וּמְהַדְּרָן תַּמָּן, וְצַלָּאן צְלוֹתָא, וּמִתְיַישְׁבָן בְּדוּכְתַּיְיהוּ תַּמָּן. וְזָרְעִין זַרְעִין וְדָרְכִין וְאָכְלִין. וְחִטִין לֵית תַּמָּן, וְלָא חַד מִשֶּׁבַע זִינֵי תְּבוּאָה. בְּהַאי אֲתַר, אִתְיְלָדוּ קַיִן וְהֶבֶל.</p>"],[9514011221,"<p>כֵיוָן דְחָטָא קַיִן, אָחֵית לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, לְהַהוּא אֲתַר דְּאִיקְּרֵי אֶרֶץ, דִּכְתִיב (שם ד) הֵן גֵּרַשְׁתָּ אוֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה, מֵהַהוּא אֲתַר דְּאִקְּרֵי אֲדָמָה. וְהָיִיתִי נָע וָנָד בָּאָרֶץ, בְּגִין דְּתַמָּן אִתְדַּחְיָיא וְאִתְתָּרַךְ, וְהָיָה כָּל מוֹצְאִי יַהַרְגֵּנִי, הַהוּא לַהַט הַחֶרֶב הַמִּתְהַפֶּכֶת.</p>"],[9514011222,"<p>וַהֲוָה דָּחֵיל וְהִרְהֵר בִּתְשׁוּבָה, וְסָלֵיק לֵיהּ הַקָדוֹשׁ בָּרוּךְ הוּא לְאַרְקָא, וַהֲוָה תַּמָּן, וְאוֹלִיד בְּנִין. וּבְאַרְקָא אִית נְהִירוּ דְּנָהֵיר מִגּוֹ שִׁמְשָׁא. וְזָרְעִין זַרְעִין, וְנָטְעִין אִילָנִין, וְלֵית תַּמָּן חִטִין, וְלָא מֵאִינוּן שֶׁבַע זִינֵי תְּבוּאָה.</p>"],[9514011223,"<p>כָל אִינוּן דְּתַמָּן, אִינוּן מִתּוֹלְדוֹת קַיִן, וְאִינוּן בִּתְרֵין רֵישִׁין, מִנְּהוֹן גֻּבְרִין עִילָּאִין, וּמִנְּהוֹן זְעִירִין. לֵית לְהוֹ דַּעְתָּא שְׁלִים כִּשְׁאָר בְּנֵי נְשָׁא דְּהָכָא. זַכָּאִין אִינוּן לְזִמְנִין. וּלְזִמְנִין אֲהַדְּרָן לְסִטְרָא בִישָׁא, וּמוֹלִידִין וּמַיְיתִין כִּשְׁאָר בְּנֵי נָשָׁא.</p>"],[9514011224,"<p>אָדָם הֲוָה בַּאֲדָמָה, עַד דְּאוֹלִיד שֵׁת, וּמִתַמָּן סָלֵיק לְעֵילָא, אַרְבַּע דַּרְגִּין מִקַּיִן. וְסָלֵיק לְהַאי אֲתַר דְּאִקְּרֵי תֵּבֵל, כֵּיוָן דְּסָלֵיק סָלֵיק לַאֲתַר בֵּי מַקְדְּשָׁא. וְתֵבֵל דָּא עִילָּאָה עַל כָּלְהוֹ דַּרְגִּין, דְּאִקְּרֵי בְּאִינוּן שְׁמָהָן דְּהֲוָה דִּיּוּרֵיהּ בְּהוּ. אֶרֶץ אֲדָמָה הָכֵי אִקְּרֵי.</p>"],[9514011225,"<p>דָּלֵיג אָדָם תְּלַת דּוּכְתֵּי, גֵּי\"א נְשִׁיָּ\"ה צִיָּ\"ה. גֵּיא אִיהוּ אֲתַר, בְּדוּכְתָּא סַגֵּי כְּהַאי פּוּתְיָא וְאוֹרְכָּא דְּגֵיהִנֹּם. בְּגֵי\"א וּנְשִׁיָּ\"ה וְצִיָּ\"ה, אִתְבַּדָּרוּ אִינוּן דִּבְנוֹ מַגְדְּלָא, וְאוֹלִידוּ תַּמָּן. עַל דְּאַרְגִּיזוּ לְמַלְכָּא עִילָּאָה קַדִּישָׁא, בְּגִין דָּא קָרֵיב לְנוּרָא דְּדָלֵיק. תַּמָּן אִית בְּנֵי נְשָׁא בְּכָל יַקִּירוּ, בְּעוֹתְרָא וְעַפְרוֹת זָהָב, וְאַבְנִין יְקִירִין, מָאן דְּעָאל תַּמָּן וְהוּא מֵהָכָא מִתֵּבֵל, בַּחֲמִידוּ דְּהַהוּא עוֹתְרָא יָהֲבִין לֵיהּ, וְנָחֵית לְזִמְנִין לְדוּכְתָּא דְּאִקְּרֵי נְשִׁיָּה, בְּגִין דְּיִתְנְשֵׁי מִתַּמָּן, וְנָחֵית לְהַאי גֵּיא, דְּלָא יָדַע אֲתַר דְּהוּא מִתַּמָּן.</p>"],[9514011226,"<p>גֵּי\"א, דָּא הוּא בְּאֶמְצָעוּת דְּעֵילָא וְתַתָּא, דָּא אִקְּרֵי גֵּי בֶּן הִנֹּם, וּרְצוּעָה חָדָא נָפְקָא מִתַּמָּן לְעֵילָא לְהַאי תֵּבֵל, וְאִקְּרֵי אוּף הָכֵי גֵּי בֶּן הִנֹּם. וְתַמָּן פִּתְחָא דְּגֵיהִנֹּם. וְאִינוּן בְּנֵי אֱנָשָׁא דְּתַמָּן, בְּגִין דָּא כָּלְהוֹ יָדְעֵי בַּחֲרָשִׁין וְחָכְמָאן. וְתַמָּן זָרְעֵי וְנָטְעֵי אִילָנִין. וְלֵית תַּמָּן חִטִין, וְלָא חַד מִשִּׁבְעָה מִינִין.</p>"],[9514011227,"<p>בִּנְשִׁיָּ\"ה אִית בְּנֵי נְשָׁא קְטוּעִין זְעִירִין, וְלֵית לְהוֹן חוֹטְמִין, בַּר תְּרֵין נוּקְבִין, דְּנָפְקָא בְּהוּ רוּחָא. וְכָל מַה דְּעָבְדֵי, מִיָּד מִשְׁתַּכְּחֵי. וְעַל דָּא אִיקְּרֵי נְשִׁיָה. וְזָרְעֵי וְנָטְעֵי אִילָנִין, וְלֵית תַּמָּן חִטִים, וְלֹא מִשֶּׁבַע זִינֵי.</p>"],[9514011228,"<p>צִיָּה, הוּא אֲתַר כִּשְׁמֵיהּ, בְּיַבְשׁוּתָא בְּכֹלָּא. תַּמָּן בְּנֵי נְשָׁא שַׁפִּירָן בְּחֵיזוּ. וּמִגּוֹ דְּהַהוּא צִיָּה, כַּד יָדְעֵי אֲתַר דִּמְקוֹרָא דְּמַיִין נָבְעִין, עָאלִין תַּמָּן. וּלְזִמְנִין דְּסָלְקִין מִגּוֹ מַיִין, לְהַאי תֵּבֵל. וְאִינוּן בְּנֵי מְהֵימְנוּתָא יַתִּיר מִבְּנֵי נְשָׁא אָחֳרָנִין, וּבֵינַיְהוּ דִּיּוּרִין טָבָן, וְעוֹתְרָא סַגֵּי. וְזֶרַע זְעֵיר, מִגּוֹ יַבְשׁוּתָא דְּהָתָם, וְנָטְעֵי אִילָנִין וְלָא מַצְלִיחִין. וְתֵיאוּבְתָּא דִּלְהוֹן לִבְנֵי נְשָׁא דְּהָכָא.</p>"],[9514011229,"<p>וּמִכָלְהוֹ לֵית דְּאָכְלֵי נַהֲמָא, בַּר אִלֵּין דְּהָכָא בְּתֵבֵל. דְּהָא לְעֵילָא מִכָּל אִלֵּין תֵּבֵל, דִּכְתִיב וְהוּא יִשְׁפֹּט תֵּבֵל בְּצֶדֶק. כְּגַוְונָא דְּכָל אִלֵּין אַרְעָאן, אִית בְּהַאי תֵּבֵל. וְכָל אִלֵּין שְׁמָהָן אִית בְּהוֹן אוּף הָכֵי, בְּגִין דְּאִיהוּ שְׁבִיעָאָה. אִית הָכָא אוּף הָכֵי כְּגַוְונָא דְּהַהוּא דוּכְתָּא דִּלְתַתָּא, וְכָל אִלֵּין בְּדִיּוּרִין דִּבְנֵי נְשָׁא, מְשַׁנְיָין אִלֵּין מֵאִלֵּין, דִּכְתִיב (תהלים קד) מָה רַבּוּ מַעֲשֶׂיךָ ה'. עַד כָּאן.</p>"],[9514011230,"<p>תְּנַן, בַּעֲשָׂרָה מַאֲמָרוֹת נִבְרָא הָעוֹלָם. רַבִּי חִיָּיא וְרַבִּי נָתָן אוֹמְרִים, בְּמַאֲמָר אֶחָד נִבְרָא, וְאֵיזֶהוּ. דִּכְתִיב (תהילים ל״ג:ו׳) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ. וְרַבִּי אַבָּא אָמַר, דִּכְתִיב כִּי הוּא אָמַר וַיֶּהִי הוּא צִוָּה וַיַּעֲמוֹד, אֲמִירָה אַחַת בִּלְבָד.</p>"],[9514011231,"<p>ר' אֶלְעָזָר אָמַר, לֹא זֶה וְלֹא זֶה, אֶלָּא בְּאוֹת אַחַת נִבְרָא הָעוֹלָם, בְּלֹא אֲמִירָה. דְּתַנְיָא, רַבִּי אֶלְעָזָר אָמַר, אוֹת אַחַת נָטַל הַקָּדוֹשׁ בָּרוּךְ הוּא מִשְּׁמוֹ, וּבְאוֹתוֹ הָאוֹת נִבְרָא. וְהַיְינוּ דְּאָמַר רִבִּי אֶלְעָזָר, מַאי דִכְתִיב, (שמות ט״ו:י״א) מִי כָמֹכָה בָּאֵלִים ה', שֶׁיּוּכַל לִבְרֹא אֶת הָעוֹלָם.</p>"],[9514011232,"<p>אֶלָּא מַשְׁמַע בְּהֵ\"א נִבְרָא הָעוֹלָם, בְּאוֹת אַחַת מַמָּשׁ, וּבְמַאי נוֹקִים (תהילים ל״ג:ו׳) כִּי הוּא אָמַר וַיֶּהִי וְגו'. ד (שם לג) בִּדְבַר ה' שָׁמַיִם נַעֲשׂוּ. אֶלָּא אָמַר רִבִּי אֶלְעָזָר, לְאַחֲזָאָה לְעָלְמָא דְּהָא אִתְבְּרֵי הֲוָה, וְלָא הֲוָה מִתְגַּלְּיָא, וְאִצְטְרִיךְ כָּל חַד וְחַד לְאִתְגַּלָּאָה, לַאֲפָקָא כָּל חַד וְחַד עוֹבָדוֹי וְחֵילוֹ דְּאִיתְחֲזֵי לֵיהּ.</p>"],[9514011233,"<p>אָמַר רִבִּי אֶלְעָזָר, כָּל הָעוֹלָם כֻּלּוֹ, וְכָל תּוֹלְדוֹתֵיהֶם, בְּרֶגַע אֶחָד נִבְרְאוּ, בְּשָׁעָה אַחַת נִבְרְאוּ, וּבְיוֹם אֶחָד נִבְרְאוּ, דִּכְתִיב (בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם בְּיוֹם עֲשׂוֹת י\"י אֱלֹהִים, בְּאוֹתוֹ הַיּוֹם מַמָּשׁ, בְּאוֹתָהּ שָׁעָה מַמָּשׁ, וְאוֹתוֹ רֶגַע מַמָּשׁ.</p>"],[9514011234,"<p>וְתַנְיָא, אָמַר רִבִּי אַבָּא אָמַר רִבִּי יוֹחָנָן, קֹדֶם שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הָיָה הוּא וּשְׁמוֹ אֶחָד, וְהָיָה בְּדַעְתּוֹ לִבְרוֹא אֶת הָעוֹלָם, וּבָרָא קֹדֶם אֶלֶף עוֹלָמוֹת, שֶׁנֶּאֱמַר (שיר השירים ח׳:י״ב) הָאֶלֶף לְךָ שְׁלֹמֹה. וְאַחַר כָּךְ בָּרָא עוֹלָמוֹת אֲחֵרִים, לְהוֹדִיעַ שֶׁהַכֹּל נֶגְדּוֹ כְּאַיִן.</p>"],[9514011235,"<p>וְהַיְינוּ דְּאָמַר רִבִּי חִיָּיא, לָמָּה אָלֶף רִאשׁוֹנָה בָּאוֹתִיּוֹת. מִפְּנֵי שֶׁבַּתְּחִלָּה בָּרָא אֶלֶף עוֹלָמוֹת, שֶׁקָּדְמוּ לִשְׁאָר עוֹלָמוֹת, וְאַחֲרָיו בֵּי\"ת, שֶׁהוּא בִּנְיַן שָׁמַיִם וָאָרֶץ. רַב הוּנָא אָמַר, בַּתְּחִלָּה כִּסֵּא הַכָּבוֹד. שֶׁכָּתוּב בּוֹ, אֶלֶף אֲלָפִין יְשַׁמְשׁוּנֵהּ, וְאַחֲרָיו שְׁאָר הַמַּלְאָכִים, וְהָאָרֶץ, שֶׁהֵם בֵּית הָעוֹלָם. וְאַחֲרָיו גִימְנָא לָן, גַּן עֵדֶן, שֶׁהוּא גְּמוּל הַצַּדִּיקִים. וְאַחֲרָיו דָל\"ת, שֶׁהוּא הָאָדָם שֶׁנִּרְכַּב בְּד' רוּחוֹת.</p>"],[9514011236,"<p>אָמַר רִבִּי יִצְחָק אָמַר רִבִּי זְרִיקָא, קַלְטִיפִין דִּירוֹקִין, הֲוָה מַסְחַר עַל תְּהוֹמָא, וּתְהוֹמָא הֲוָה סָלֵיק וְנָחֵית, וְאָת אֶחָד הֲוָה פָּשִׁיט בִּתְלַת זִיוְויָיתֵיהּ עַל תְּהוֹמָא, וּתְהוֹמָא שָׁכֵיךְ. הֲדָא הוּא דִכְתִיב, (בראשית א) וְרוּחַ אֱלֹהִים מְרַחֶפֶת.</p>"],[9514011237,"<p>אָמַר רִבִּי אֶלְעָזָר לָאו מֵהָכָא מַשְׁמַע, אֶלָּא מֵהָכָא, דִּכְתִיב (תהילים ע״ז:י״ז) רָאוּךָ מַיִם אֱלֹהִים רָאוּךָ מַיִם יָחִילוּ אַף יִרְגְּזוּ תְהוֹמוֹת.</p>"],[9514011238,"<p>וְהַיְינוּ דִּתְנַן, אֶלֶף עָלְמִין הֲווֹ עַד דְּלָא אִתְבְּרֵי עָלְמָא, וְזִיו יְקָרֵיהּ הֲוָה מִתְפַּשֵׁט וּבָרָא עָלְמִין, וְסָתֵיר לוֹן, עַד דְּסָלֵיק בִּרְעוּתָא קַמֵּיהּ לְמִבְרֵי הַאי עָלְמָא, וְהַהוּא שַׁעֲתָא אִתְפַּשְּׁטוּ תְּרֵין אַתְוָון מִשְּׁמֵיהּ, וְקַיַּים לוֹן, וּתְרֵין אָחֳרָן אִתְגְּלִיפוּ לְעֵילָא וְתַתָּא, חַד גּוֹ חַד. גָּלִיף חַד, וְאִתְחֲזַר תְּלַת. וְגָלִיף חַד אָחֳרָא, וְאִתְחֲזַר תְּרֵין. עַד דְּסָלְקוּ עֲשָׂרָה. אִתְפְּלִיגוּ אִינוּן עֲשָׂרָה, וְאִתְחֲזָרוּ לִתְלָתִין וּתְרֵין. וְאִינוּן תְּלָתִין וּתְרֵין שְׁבִילֵי דְּחָכְמְתָא. אִלֵּין אִתְפַּלִּיגוּ בְּגִילוּפַיְיהוּ לַעֲשָׂרָה, וְאִתְחֲזָרוּ לְמ\"ב. מִכָּאן וּלְהָלְאָה, מָאן דְּיַשְׁגַּח יַשְׁגַּח בְּבִיעֲתוּתָא דְּלִבָּא, יַסְתִּים, וְלֵית דְּפָתְחִין לֵיהּ. וְעַל הַאי כְּתִיב (ישעיהו מ״ב:ח׳-ט׳) אֲנִי י\"י הוּא שְׁמִי וּכְבוֹדִי לְאַחֵר לֹא אֶתֵּן וּתְהִלָּתִי לַפְּסִילִים. וּכְתִיב (שמות כ׳:ד׳) לֹא תַעֲשֶׂה לְךָ פֶסֶל וְכָל תְּמוּנָה.</p>"],[9514011239,"<p>אָמַר רִבִּי אֶלְעָזָר, הַתְּהוֹם הָיָה נִשְׁקַע בְּאַרְבַּע אֲבָנִים, וְהוּטְבְּעוּ לְמַטָה עַל אֶבֶן אַחַת, שֶׁהוּא הָעַמּוּד, וְעַל זֶה הָעוֹלָם עוֹמֵד. הֲדָא הוּא דִכְתִיב, (איוב ל״ח:ו׳) עַל מָה אֲדָנֶיהָ הָטְבָּעוּ אוֹ מִי יָרָה אֶבֶן פִּנָּתָהּ. אָמַר רִבִּי זֵירָא, זוֹ הִיא אֶבֶן שֶׁמִּמֶּנָּהּ הוּשְׁתָּת הָעוֹלָם, וְעָלֶיהָ הָעוֹלָם עוֹמֵד, וְהוּא קֹדֶשׁ הַקֳּדָשִׁים, וְהִיא טִיבּוּרוֹ שֶׁל עוֹלָם, וּמִמֶּנָּהּ יָצְאוּ אֲבָנִים הַמְשׁוּקָּעוֹת בַּתְּהוֹם, וּמֵהֶם יוֹצְאִים מַיִם.</p>"],[9514011240,"<p>אָמַר רִבִּי אַחָא בַּר יַעֲקֹב, בִּשְׁלשָׁה אוֹתִיּוֹת נִשְׁקַע הַתְּהוֹם, וְנֶחְלַק בִּשְׁלשָׁה חֲלָקִים, וְהֵם עַמּוּדֵי הָאָרֶץ. וְאֶחָד לִשְׁלשׁ מֵאוֹת שָׁנָה, מִתְרוֹפְפִים מִמְּקוֹמָם, שֶׁנֶּאֱמַר (שם ט) הַמַּרְגִּיז אֶרֶץ מִמְּקוֹמָהּ וְעַמּוּדֶיהָ יִתְפַּלָּצוּן.</p>"],[9514011241,"<p>תָּאנֵי ר' שִׁמְעוֹן, עַל שִׁבְעָה עַמּוּדִים הָאָרֶץ עוֹמֶדֶת, שֶׁנֶּאֱמַר (משלי ט׳:א׳) חָצְבָה עַמּוּדֶיהָ שִׁבְעָה, וְהֵם תְּלוּיִים עַל הַמַּיִם, וּכְנֶגְדָם אָמַר דָּוִד הַמֶּלֶךְ עָלָיו הֲשָׁלוֹם שִׁבְעָה קוֹלוֹת, דִּכְתִיב (תהילים כ״ט:ג׳) קוֹל יְיָ' עַל הַמָּיִם.</p>"],[9514011242,"<p>הַכֹל תָּלוּי עַל שִׁבְעָה: עַמּוּדֵי שָׁמַיִם הֵם ז', וְהָרְקִיעִים ז'. וְהַכּוֹכָבִים שִׁבְעָה מַעֲלוֹת. ז' גּוֹיִם לְמַעְלָה. שִׁבְעָה גּוֹיִם לְמַטָה. שִׁבְעָה אֲרָצוֹת. שִׁבְעָה יַמִּים. שִׁבְעָה נְהָרוֹת. יְמֵי בְרֵאשִׁית שִׁבְעָה. וְהַשְּׁבִיעִי שַׁבָּת לַה', יוֹם שֶׁכּוּלּוֹ שַׁבָּת.</p>"],[9514011243,"<p>תְּנַן הָתָם, ר' יְהוּדָה בַּר אִלְעָאי אוֹמֵר, שִׁבְעָה גְּלוּסְמוֹי פְּרִיסָן, אִתְגְּלִיפוּ בִּתְלָתִין וּתְרֵין אַלְפִין פְּלִיגָאן, וַהֲוָה פָּרִיס בְּהוּ חַד שִׁיעוּרָא דְּעָלְמָא, עַד דִּמְתַח לֵיהּ לְאַרְבַּע זִיוְויָן, וְאַסְמַךְ עַל סַמְכֵיהּ. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ד:כ״ד) אָנֹכִי ה' כו' נֹטֶה שָׁמַיִם לְבַדִּי רֹקַע הָאָרֶץ (מי אתי) [מֵאִתִּ.</p>"],[9514011244,"<p>אָמַר רִבִּי שִׁמְעוֹן, מַאי דִכְתִיב, (שם מח) קֹרֵא אֲנִי אֲלֵיהֶם יַעַמְדוּ יַחְדָּו. אֶלָּא אָמַר רִבִּי שִׁמְעוֹן, כְּשֶׁעָלָה בְּמַחְשַׁבְתּוֹ לִבְרוֹא הָעוֹלָמוֹת, בְּאוֹתָהּ שָׁעָה נִבְרְאוּ עֶלְיוֹנִים וְתַחְתּוֹנִים, וְכָל מַה שֶּׁבָּהֶם. שֶׁנֶּאֱמַר קֹרֵא אֲנִי אֲלֵיהֶם יַעַמְדוּ יַחְדָּו, אַל תִּקְרֵי אֲלֵיהֶם, אֶלָּא אֱלֹהִים, מְלַמֵּד שֶׁבְּהֵ\"א בְּרָאָם. וְהַיְינוּ דִּכְתִיב (שמות ט״ו:י״א) מִי כָמֹכָה בָּאֵלִים יְיָ'. כְּמוֹ אַסְקוּפָה דְּמַלְיָיא מִכָּל צָרְכֵי בֵיתָא. וּכְדֵין יָדְעִין דְּתַמָּן כֹּלָּא, מַה דְּאִצְטְרִיךְ לוֹן.</p>"],[9514011245,"<p>אָמַר רִבִּי יְהוּדָה, בְּג' דְבָרִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת עוֹלָמוֹ, בְּסֹפֵר וְסֵפֶר וְסִפּוּר. כְּנֶגְדָם, בְּחָכְמָה בִּתְבוּנָה וּבְדַעַת. בְּחָכְמָה, דִּכְתִיב (משלי ג׳:כ׳) ה' בְּחָכְמָה וְגו'. בְּדַעַת, דִּכְתִיב (שם) בְּדַעְתּוֹ תְּהוֹמוֹת נִבְקָעוּ. רַבִּי נְחוּנְיָא אָמַר, בְּחָכְמָה בִּלְבַד נִבְרְאוּ כָּל הָעוֹלָמוֹת כֻּלָּם. הֲדָא הוּא דִכְתִיב בְּרֵאשִׁית בָּרָא אֱלֹהִים, וְרֵאשִׁית הִיא הַחָכְמָה. וְאַתְיָא כְּמַאן דְּאָמַר בְּה\"א בְּרָאָם, וּשְׁלָשְׁתָּן נִכְלָלִים בּוֹ.</p>"],[9514011246,"<p>מַתְנִיתִין, פִּתְחֵי אִתְפַּתָּחוּ. תַּרְעֵי הֲווֹ נְטִירִין, דְּעָיִיל לָא נָפֵיק, וּדְנָפֵיק לָא עָיֵיל, קַמֵּי פִּתְחָא הֲווֹ שִׁגְרָאן, סָלְקִין בְּגַוֵּיהּ רַבְרְבִין תַּקִּיפִין, סֶמֶךְ חַד קָאִים בְּגַוֵּיהּ, הַהוּא סֶמֶךְ הֲוָה נָעִיץ, וּתְלַת גְּוָונִין הֲווֹ בֵּיהּ. גַּוָּון חָשׁוּךְ, גַּוָּון חִוָּורָא, גַּוָּון יְרוֹקָא, בֵּיהּ סָלְקִין, בֵּיהּ נַחֲתִין, כֹּלָּא תְּאִיבִין לְמֵיעַל בְּגַוֵּיהּ, וְלֵית רְשׁוּתָא לְכוֹלָּא.</p>"],[9514011247,"<p>הוּא קַדְמָא לִבְרִיָּיתָא דְעָלְמָא. עֲלֵיהּ קָאִים חַד שָׁלְטָן, דְּאִגְנִיז בְּאֶלֶף עָלְמִין. מִנֵּיהּ אִתְבַּקָּעוּ כָּל גִּילּוּפֵי עָלְמָא. זַכָּאָה הוּא דְּיִשְׁרֵי בְּגַוֵּיהּ.</p>"],[9514011248,"<p>בַּתְרֵיהּ אִשְׁתְּכָחוּ תְּרֵין אַחִין אֲחִידָאן דָּא בְּדָא. חָדָא קַבֵּיל אוּשְׁפִּיזִין, וְהוּא חֵיזוּ דְחַיִּין, מַאן דְּאָכֵיל בִּפְתוֹרֵיהּ, קָאִים תְּדִירָא. וְחַד הוּא קַבֵּיל אוּשְׁפִּיזִין וְלָא קַבֵּיל, הוּא חֵיזוּ דְחַיִּין, חֵיזוּ דְמוֹתָא, מַאן דְּאָכֵיל בִּפְתוֹרֵיהּ, נָפֵיל וּמִית, לֵית לֵיהּ שֵׁיזָבָא, לֵית דְּאָחִיד בִּידֵיהּ. בַּתְרֵיהּ אִשְׁתְּכָחוּ רְחִימִין, תְּאֵיבִין לְמֶחֱמֵי, תְּאֵיבִין לְמִקְרַב לוֹן, כֹּלָּא מְשַׁבְּחָן לוֹן.</p>"],[9514011249,"<p>חַה עַוֵיר הֲוָה אָזֵיל קָרֵיב לְגַבּוֹן, לְאִבָּעָא חוּלָקֵיהוֹן. קָרֵיב לְהַהוּא חֵיזוּ דְחַיִּין וְחֵיזוּ דְמוֹתָא, אַתְקֵיף בֵּיהּ, אָחִיד בְּגוּפֵּיהּ, חַבְרָא דִילֵיהּ הֲוָה קָרֵי, (משלי כ״ג:ב׳) וְשַׂמְתָּ שַׂכִּין בְּלֹעֶךָ אִם בַּעַל נֶפֶשׁ אָתָּה. לָא אָצֵית, וְלָא אַרְכִין אוּדְנֵיהּ, עַד דְּנָפִיל וּמִית.</p>"],[9514011250,"<p>בָּתַר אִלֵּין, נָפַק חַד מִתְקָא, וְאִתְפְּלֵיג לְאַרְבַּע. וּמִכָּל חַד חָכְמְתָא נָפֵיק, מֵהַהוּא רַבָּא וְיַקִּירָא שֶׁבָּעָאן. וְכָל אִינוּן רַחֲמִין וּתְאֵיבִין לְמֶחֱמֵי, וְאִינוּן תְּרֵין אַחִין דַּאֲחִידָן דָּא בְּדָא.</p>"],[9514011251,"<p>בַּתְרוֹהִי תְּרֵין רַבְיָין עוּלֵמִין יָנוֹקִין, וְשִׁינָנָא דְסַיְיפָא דִּמְלַהֲטָא, אֶשָׁא בִּידֵיהוֹן. נָטְרִין אוֹרְחִין וּשְׁבִילִין, דְּלָא יֵיעוֹל חַד, וְלֹא יִפּוֹק חַד, בַּר הַהוּא דְּלָא אָכֵיל וְלָא שָׁתֵי, שֶׁנֶּאֱמַר וַיַּשְׁכֵּן מִקֶּדֶם, דְּאִתְבְּרִיאוּ קַמֵּי עָלְמָא דֵין. מִכָּאן וּלְהָלְאָה, אִשְׁתַּכְלָלוּ כָּל סִטְרוֹי דְעָלְמָא.</p>"],[9514011252,"<p>שׁוּרָיָא אָחֳרָא, סִטְרוֹי דִשְׂמָאלָא. סְטַר דְּנָפְלִין שְׂרִידִין. אֲתַר דְּנוּרָא הֲוָה דָּלֵיק יְמָמִין וְלֵילְיָן, לְמִרְמָא קַמָּהּ לְרָמֵי רוּחָא, דְּאָזְלִין לִשְׂמָאלָא. בֵּיהּ אִתְטַרְדּוּן, עַד עִדָּן עִדָּנִין. אִלֵּין אִינוּן יָמִינָא וּשְׂמָאלָא, אַקְדִּימוּ לִבְרִיָיתָא דְעָלְמָא. וּלְבָתַר זִוְיָיתְהוֹן דְּאַרְעָא.</p>"],[9514011253,"<p>פִּיסְקָא. אָמַר רִבִּי יְהוּדָה, אָמַר רַב, כְּתִיב (משלי ג׳:י״ט-כ׳) ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה בְּדַעְתּוֹ תְּהוֹמוֹת נִבְקָעוּ. בִּשְׁלשָׁה דְבָרִים הַלָּלוּ נִבְרָא הָעוֹלָם, וְעַל שְׁנַיִם מֵהֶן הוּא עוֹמֵד, עַל הַתְּבוּנָה וְעַל הַדַּעַת. וְהָא תָּנִינָן תְּלַת. אָמַר רִבִּי יִצְחָק, הַחָכְמָה נְטָלָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא לְמַעְלָה, וְהוּא שְׁמוֹ, לְהוֹדִיעַ לַעֲבָדָיו הַצַּדִּיקִים. וְהַשְּׁנַיִם עָמְדוּ בָּעוֹלָם, וְהֵם קִיּ וּמוֹ.</p>"],[9514011254,"<p>אָמַר רִבִּי אַבָּא, כָּלְהוֹ תְּלָתָא, אִתְרְמִיזוּ בְּחֵיזוּ זְעֵירָא. וְאִינוּן תְּלַת תְּנוּעוֹת פּוּמָא: עֶלְיוֹן, אֶמְצָעִי, וְהַתַּחְתּוֹן, בִּנְהוּגֵּי דְפוּמָא אִתְנַהֵיג בְּהוּ. אָמַר רִבִּי אַבָּא, וְהֵם חָכְמָה וּתְבוּנָה וָדַעַת.</p>"],[9514011255,"<p>מַאי מַשְׁמַע דְּהַאי תְּרֵין אִתְנַהֵיג בְּהוּ עָלְמָא, וְהֵם תְּבוּנָה וָדַעַת. דִּתְנִינָן, אִלֵּין מִנְהָגֵי עָלְמָא הַשָּׁמַיִם שֶׁנִבְרְאוּ בִּתְבוּנָה. וְהַתְּהוֹם בְּדַעַת. וְהַחָכְמָה הוּא שְׁמוֹ שֶׁל מָקוֹם, וְהוּא נִקְרָא חָכְמָה. וְתָנִינָן, הוּא וְהַחָכְמָה הַכֹּל דָּבָר אֶחָד.</p>"],[9514011256,"<p>דְּאָמַר רִבִּי יְהוֹשֻׁעַ, מַאי דִכְתִיב, (ישעיהו מ״ב:ח׳) אֲנִי ה' הוּא שְׁמִי. מְלַמֵּד שֶׁהוּא וּשְׁמוֹ אֶחָד הוּא. אָמַר רִבִּי אַבָּהוּ, הַכֹּל נָתַן, אֲבָל שְׁמוֹ הַגָּדוֹל לֹא נָתַן, וְלָא אוֹזִיף לְאָחֳרָן, דִּכְתִיב אֲנִי ה'. לְבַדִּי. מְלַמֵּד דְּשֵׁם זֶה לֹא נָתַן לְשׁוּם נִבְרָא.</p>"],[9514011257,"<p>וְאָמַר רִבִּי אַבָּהוּ, בֹּא וּרְאֵה כַּמָּה חָשַׁשׁ הַקָדוֹשׁ בָּרוּךְ הוּא עַל כְּבוֹד שְׁמוֹ יִתְבָּרַךְ, תֵּדַע לָךְ בִּזְּמַן שֶׁבּיה\"מ הָיָה קַיָּים, כָּל הַמַּקְרִיב קָרְבָּן, וְזוֹבְחוֹ לְשֵׁם זֶה הַנִּקְרָא אֱלֹהִים, חַיָּיב מִיתָה, שֶׁנֶּאֱמַר (שמות כב) זוֹבֵחַ לָאֱלֹהִים יָחֳרָם בִּלְתִּי לַה' לְבַדּוֹ. מְלַמֵּד שֶׁצָּרִיךְ לְהַזְכִּיר שְׁמוֹ הַמְיוּחָד בִּלְבָד.</p>"],[9514011258,"<p>וְעַל כֵּן כְּדֵי שֶׁלֹּא יִטְעֶה אָדָם, צִוָּה בַּקָּרְבָּנוֹת וְאָמַר, (ויקרא א׳:ב׳) אָדָם כִּי יַקְרִיב מִכֶּם קָרְבָּן לַה'. (שם כב) וְכִי תִזְבְּחוּ זֶבַח תּוֹדָה לַה'. (שם יט) וְכִי תִזְבְּחוּ זֶבַח שְׁלָמִים לַה'. (שם ב) וְנֶפֶשׁ כִּי תַקְרִיב קָרְבַּן מִנְחָה לַה'. הַכֹּל לַה', וְלֹא נֶאֱמַר לֵאלֹהִים.</p>"],[9514011259,"<p>מַאי טַעְמָא. אָמַר רִבִּי אַבָּהוּ, שֵׁם זֶה הוּא מְשׁוּתָּף, שֶׁהַמַּלְאָכִים נִקְרְאוּ אֱלֹהִים. בְּנֵי אָדָם נִקְרְאוּ אֱלֹהִים, הַדַּיָּינִים נִקְרְאוּ אֱלֹהִים, וְאֵין אָנוּ יוֹדְעִים לְמִי מֵהֶם זוֹבֵחַ, לְכָךְ צָרִיךְ לְהַזְכִּיר הַשֵּׁם הַמְיוּחָד לְבַדּוֹ.</p>"],[9514011260,"<p>אָמַר רִבִּי חִיָּיא, תָּא חֲזֵי, מַאן דִּמְקַלֵּל אֶת הַשֵּׁם, דִּכְתִיב (ויקרא כ״ד:ט״ו) אִישׁ אִישׁ כִּי יְקַלֵּל אֱלֹהָיו וְנָשָׂא חֶטְאוֹ, דְּהָא אִם קִלֵּל שֵׁם זֶה סְתָם, אֵינוֹ חַיָּב מִיתָה, וְאֵין מְנַדִּין אוֹתוֹ, דְּיָכוֹל לִטְעוֹן לְחַד מִן דַּיָּינָא, אוֹ לִגְדוֹל הַדּוֹר קָאֲמַר.</p>"],[9514011261,"<p>אָמַר רִבִּי אַבָּהוּ, מִיתָה אֵין מְחַיְיבִין אוֹתוֹ, אֲבָל נִידּוּי מְחַיְיבִין אוֹתוֹ, מִשּׁוּם לָאו דְּאוֹרַיְיתָא, דִּכְתִיב (שמות כ״ב:כ״ז) אֱלֹהִים לֹא תְקַלֵּל סְתָם. אֲבָל אִם קִלֵּל שֵׁם הַמְיוּחָד, חַיָּיב מִיתָה, דִּכְתִיב (ויקרא כ״ד:ט״ז) וְנֹקֵב שֵׁם ה' מוֹת יוּמָת, מְלַמֵּד שֶׁאֵינוֹ חַיָּיב עַד שֶׁיַּזְכִּיר שְׁמוֹ הַמְיוּחָד.</p>"],[9514011262,"<p>הַהוּא גַבְרָא דְּאַקְדִּישׁ בְּרֵיהּ, וַאֲמַר, הַאי בְּרָא דְּאִתְיְילֵיד, יְהֵא מְקוּדָּשׁ לֵאלֹהִים, שָׁמַע ר' חִיָּיא וְשַׁמְתֵּיהּ. אָמַר לֵיהּ, וּמַה עַל דְּאַקְדֵּישַׁת בְּרִי לְּקוּדְשָׁא בְּרִיךְ הוּא, לֶהֱוֵי הַהוּא גַבְרָא בְּשַׁמְתָּא. אָמַר לֵיהּ לָאו עַל כָּךְ עֲבָדִית, אֶלָּא עַל דְּאַקְדִּישְׁתֵּיהּ לַשֵּׁם הַנִּקְרָא אֱלֹהִים, וְהַתּוֹרָה אָמְרָה (שמות כ״ב:י״ט) זֹבֵחַ לָאֱלֹהִים יָחֳרָם. אֲמַר וְהֵיאַךְ הֲוָה לִי לְמֵימָר. אֲמַר לֵיהּ, הַאי בְּרָא דְּאִתְיְילִיד לִי לִיהֲוֵי מְקוּדָּשׁ לַה', וְלֹא לְשֵׁם אַחֵר. וּמְנָא לָן. מֵחַנָּה, דִּכְתִיב (שמואל א א׳:י״א) וּנְתַתִּיו לַה', וְלֹא אָמְרָה לֵאלֹהִים.</p>"],[9514011263,"<p>אָמַר רִבִּי שָׁלוֹם, וְהָא אוֹקִימְנָא דִּבְשֵׁם אֱלֹהִים נִבְרָא הָעוֹלָם, אִי הָכִי יָכִיל לְמִטְעַן הַאי גַבְרָא כְּהַאי גַוְונָא, דְּמַלְאָכִים הֲווֹ, אוֹ גְדוֹלֵי הַדּוֹר הֲווֹ, אוֹ דַיָּינֵי הֲווֹ. אָמַר רִבִּי אַבָּהוּ, הָא עָלְמָא אִתְבְּרֵי עַד דְּלָא יֵיתוֹן בְּנֵי נָשָׁא, וְעַד דְּלָא יֵיתוֹן דַּיָּינֵי דָרָא, וְרַבְרְבֵי דָרָא, וְלָא אִית לְמִשְׁגֵּא.</p>"],[9514011264,"<p>כְמָא דְּאָמַר רִבִּי אֶלְעָזָר חֲבִיבָא יַקִּירָא, דִּכְתִיב (שמות ט״ו:י״א) מִי כָמֹכָה בָּאֵלִים ה', שֶׁיּוּכַל לִבְרוֹא אֶת הָעוֹלָם, מַשְׁמַע דְּאֵלִים אֵינוֹ יָכוֹל לִבְרוֹא הָעוֹלָם, עַד שֶׁנָּטַל הַקָדוֹשׁ בָּרוּךְ הוּא אוֹת אַחַת מִשְׁמוֹ, וְהִיא אוֹת ה\"א, וּבוֹ נִבְרָא הָעוֹלָם. וְנַעֲשָׂה מִן אֵלִים אֱלֹהִים, וְנִבְנָה שְׁמוֹ אֱלֹהִים. וְעַל הַאי תְּנַן, בְּה\"א בְּרָאָם.</p>"],[9514011265,"<p>אָמַר רִבִּי יוֹסֵי, הָא חֲזִינָן דְּלֵית כִּתְרָא וּמַלְכוּתָא אֶלָּא בִּשְׁמֵיהּ קַדִּישָׁא. דְּלָא אוֹזְפֵיהּ לְאָחֳרָא, וְהוּא הַשֵּׁם יו\"ד ה\"א וא\"ו ה\"א. דְּאָמַר רִבִּי יוֹסֵי, בּוֹ נִכְלָלִים עֶלְיוֹנִים וְתַחְתּוֹנִים שָׁמַיִם וָאָרֶץ, וְכָל צְבָאָם, כִּסֵּא הַכָּבוֹד, וְחַיּוֹת הַקֹּדֶשׁ, וְכֻלָּם לְנֶגְדּוֹ כְּאַיִן וּכְלָא חֲשִׁיבִין, וְהוּא הָיָה, וְהוּא הוֶֹה, וְהוּא יִהְיֶה. בְּרִיךְ הוּא, בְּרִיךְ שְׁמֵיהּ. לְעָלַם וּלְעָלְמֵי עָלְמִין אָמֵן.</p>"],[9514011266,"<p>אָמַר רִבִּי יְהוּדָה, יִתְבָּרַךְ וְיִתְעַלֶּה שְׁמוֹ שֶׁל מֶלֶךְ מה\"מ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהוּא רִאשׁוֹן, וְהוּא אַחֲרוֹן, וּמִבַּלְעָדָיו אֵין אֱלֹהִים. וּבָרָא אֶת הָעוֹלָם בְּסוֹד שְׁלשָׁה עִנְיָינִים גְּדוֹלִים וְטוֹבִים, וְהֵם דַּעַת חָכְמָה וּבִינָה, שֶׁנֶּאֱמַר (משלי ג׳:י״ט-כ׳) ה' בְּחָכְמָה יָסַד אָרֶץ כּוֹנֵן שָׁמַיִם בִּתְבוּנָה בְּדַעְתּוֹ תְּהוֹמוֹת נִבְקָעוּ.</p>"],[9514011267,"<p>וְלָמָּה בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא הָאָרֶץ, שֶׁהוּא עוֹלָם הַשָּׁפֵל, בְּסוֹד הַחָכְמָה. וְהַשָּׁמַיִם, שֶׁהוּא עוֹלָם גָּדוֹל מִמֶּנּוּ, בִּתְבוּנָה, שֶׁהוּא דָּבָר קָטָן מִן הַחָכְמָה. וּכְבָר שָׁנִינוּ, אֵימָתַי נִקְרָא אָדָם חָכָם בְּחָכְמָה, כְּשֶׁשּׁוֹאֲלִים אוֹתוֹ בְּכָל דָּבָר, וְעוֹנֶה וּמֵשִׁיב כָּעִנְיָן, וְיָדוֹ בַּכֹּל, אָז נִקְרָא חָכָם בְּחָכְמָה, שֶׁהוּא גָּדוֹל עַל הַתְּבוּנָה וְעַל הַדַּעַת, עַל כֵּן הָיָה לוֹ יִתְבָּרַךְ לַעֲשׂוֹת הַשָּׁמַיִם בְּחָכְמָה, וְהָאָרֶץ שֶׁהִיא שְׁפֵלָה מֵהֶם בִּתְבוּנָה.</p>"],[9514011268,"<p>תֵּהַע כִּי הַחָכְמָה גְּדוֹלָה מִכּוּלָּם, וְעַל כֵּן נִקְרָא אָדָם חָכָם, מִפְּנֵי שֶׁהוּא חָכָם בְּכָל הַחָכְמוֹת. וְהַתְּבוּנָה קְטַנָּה מִן הַחָכְמָה, וְעַל כֵּן נִקְרָא אָדָם מֵבִין, כְּלוֹמַר, מֵבִין דָּבָר מִתּוֹךְ דָּבָר, הוּא מֵעַצְמוֹ וּמִלִּבּוֹ, מֵבִין דָּבָר מִתּוֹךְ דָּבָר אַחֵר. כְּלוֹמַר, בִּרְאוֹתוֹ יְסוֹד, בּוֹנֶה בִּנְיַן עָלָיו. וְכֵן הוּא הַמֵּבִין, בִּרְאוֹתוֹ דָּבָר אֶחָד אוֹ קְצָתוֹ, מַשְׁלִים הָעִנְיָן עָלָיו.</p>"],[9514011269,"<p>וְהַקָּדוֹשׁ בָּרוּךְ הוּא יִתְבָּרַךְ שְׁמוֹ, בָּרָא הַשָּׁמַיִם בְּסוֹד הַתְּבוּנָה, שֶׁהוּא עִנְיַן תְּבוּנָה מִתּוֹךְ הַיְסוֹד. וּבְרֵאשִׁית כָּל הַנִּבְרָאִים, בָּרָא צוּרַת הַמַּלְאָכִים הַקְּדוֹשִׁים, שֶׁהֵם תְּחִלַּת כָּל הַנִּבְרָאִים הַנֶּאֱצָלִים מִזִּיו אוֹר הֲדָרוֹ.</p>"],[9514011270,"<p>וַעֲשָׂרָה שֵׁמוֹת נִקְרְאוּ בְּסוֹדָם, וּבְתוֹךְ שְׁמוֹתָם נִקְרָא אֱלֹהִים. וְעַל כֵּן בָּא לְהוֹרוֹת בְּרֵאשִׁית בָּרָא אֱלֹהִים, כְּלוֹמַר בָּרָא יִתְבָּרַךְ שְׁמוֹ צוּרַת הַמַּלְאָכִים הַנִּקְרָאִים אֱלֹהִים, וְהֵם הַיְסוֹד מִכָּל הַנִּבְרָאִים הָאֲחֵרִים, וּמִתּוֹךְ זֶה הַיְסוֹד, נִבְרְאוּ הַשָּׁמַיִם לְאַחַר כֵּן בְּסוֹד הַתְּבוּנָה, כַּאֲשֶׁר הַתְּבוּנָה הוּא דָּבָר מִתּוֹךְ דָּבָר כָּךְ נִבְרְאוּ הַשָּׁמַיִם דָּבָר מִתּוֹךְ דָּבָר, שֶׁהֵם מִסּוֹד אוֹר צוּרַת הַמַּלְאָכִים. כְּלוֹמַר הֵם בִּנְיַן מִתּוֹךְ הַיְסוֹד, וְעַל כֵּן כּוֹנֵן שָׁמַיִם בִּתְבוּנָה.</p>"],[9514011271,"<p>אֲבָל הָאָרֶץ נִהְיָה מִתּוֹךְ יְסוֹד אַחֵר, אֶלָּא שֶׁהִיא תְּלוּיָה עַל הַמַּיִם. וְהַקָּדוֹשׁ בָּרוּךְ הוּא יָסַד לָהּ יְסוֹד עָשׂוּי בְּחָכְמָה, וְעַל כֵּן נֶאֱמַר ה' בְּחָכְמָה יָסַד אָרֶץ, כּוֹנֵן שָׁמַיִם בִּתְבוּנָה, דָּבָר מִתּוֹךְ דָּבָר.</p>"],[9514011272,"<p>וְאָמַר רִבִּי אַבָּהוּ, בֹּא וּרְאֵה כַּמָּה חָשַׁשׁ הַקָדוֹשׁ בָּרוּךְ הוּא עַל כְּבוֹד שְׁמוֹ הַגָּדוֹל שֶׁהוּא יהו\"ה, כִּי זֶהוּ שְׁמוֹ מַמָּשׁ. אֲבָל שֵׁם אֱלֹהִים, מְשֻׁתָּף הוּא עַל יֶתֶר הַנִּבְרָאִים. הַמַּלְאָכִים נִקְרָאִים אֱלֹהִים. בְּנֵי אָדָם נִקְרְאוּ אֱלֹהִים. הַדַּיָּינִים נִקְרְאוּ אֱלֹהִים.</p>"],[9514011273,"<p>וְעַל כֵּן חָשַׁשׁ הַמָּקוֹם עַל כְּבוֹד שְׁמוֹ. תֵּדַע לָךְ, כָּל הַמַּקְרִיב קָרְבָּנוֹ וְזִבְחוֹ לְשֵׁם זֶה הַנִּקְרָא אֱלֹהִים, חַיָּיב מִיתָה. שֶׁנֶּאֱמַר, (שמות כ״ב:י״ט) זֹבֵחַ לָאֱלֹהִים יָחֳרָם בִּלְתִּי לַה' לְבַדּוֹ. בִּשְׁבִיל שֶׁהוּא שֵׁם מְשׁוּתָּף, וְאֵין אָנוּ יוֹדְעִים אִם הוּא זוֹבֵחַ לַמַּלְאָכִים, אוֹ לִבְנֵי אָדָם, אוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא. וְעַל כֵּן אָמְרָה הַתּוֹרָה, זֹבֵחַ לָאֱלֹהִים יָחֳרָם בִּלְתִּי לַה' לְבַדּוֹ, כְּלוֹמַר, שֶׁצָּרִיךְ שֶׁיַּזְכִּיר שֵׁם יהו\"ה לְבַדּוֹ. וּלְפִיכָךְ נֶאֱמַר בַּקָּרְבָּנוֹת, (ויקרא כ״ב:כ״ט) וְכִי תִזְבְּחוּ זֶבַח תּוֹדָה לַה', וְכֵן בִּשְׁלָמִים, וְכֵן בְּעוֹלָה, וְלֹא נֶאֱמַר לָאֱלֹהִים אֶלָּא לַה' מַמָּשׁ.</p>"],[9514011274,"<p>וְשָׁמַיִם, נִבְרְאוּ מֵאוֹתוֹ הָאוֹר הַנִּשְׁפַּע בֵּאלֹהִים, עָשָׂה אוֹתָם דָּבָר מִתּוֹךְ דָּבָר, וּבְג' דְבָרִים הַלָּלוּ נַעֲשָׂה הַמִּשְׁכָּן, שֶׁנֶּאֱמַר (שמות ל״א:ג׳) וָאֲמַלֵּא אֹתוֹ רוּחַ אֱלֹהִים בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת. וּשְׁלָשְׁתָּן הֵם בְּמַתְּנַת עֶלְיוֹן, לְכָל אֲשֶׁר יַחְפּוֹץ יִתְּנֵם, שֶׁנֶּאֱמַר (משלי ב׳:ו׳) כִּי ה' יִתֵּן חָכְמָה מִפִּיו דַּעַת וּתְבוּנָה.</p>"],[9514011275,"<p>(בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלֹהִים. רַבִּי אַבָּא פְּתַח וַאֲמַר, (בראשית ט״ו:י״ח) בַּיּוֹם הַהוּא כָּרַת ה' אֶת אַבְרָם בְּרִית לֵאמֹר. בַּחֲמִשָּׁה עִנְיָנִים נֶאֱמַר הַבְּרִית, הָא' הוּא בְּרִית מִילָה, שֶׁנֶּאֱמַר (שם יז) וְהָיְתָה בְּרִיתִי בִּבְשַׂרְכֶם לִבְרִית עוֹלָם. הַב' בְּרִית הַקֶּשֶׁת, שֶׁנֶּאֱמַר (שם ט) וְהָיְתָה לְאוֹת בְּרִית. הַג' בְּרִית הַמֶּלַח, שֶׁנֶּאֱמַר (במדבר י״ח:י״ט) בְּרִית מֶלַח עוֹלָם. הַד' בְּרִית הַיִּסּוּרִין, שֶׁנֶּאֱמַר (דברים כ״ח:ס״ט) אֵלֶּה דִּבְרֵי הַבְּרִית. הה' בְּרִית הַכְּהוּנָּה, שֶׁנֶּאֱמַר (במדבר כ״ה:י״ג) וְהָיְתָה לוֹ וּלְזַרְעוֹ אַחֲרָיו בְּרִית כְּהֻנַּת עוֹלָם.</p>"],[9514011276,"<p>וְקוֹהֶם שֶׁנִּתְּנוּ הַה' בְּרִיתוֹת, לֹא הָיְתָה הַבְּרִית אֶלָּא בְּאֵשׁ. שֶׁנֶּאֱמַר (בראשית ט״ו:י״ז) וְהִנֵּה תַּנּוּר עָשָׁן וְלַפִּיד אֵשׁ וְגו'. וּכְתִיב (שם טו) בַּיּוֹם הַהוּא כָּרַת ה' אֶת אַבְרָם בְּרִית לֵאמֹר. וְהָאֵשׁ הָיְתָה בְּרִית בַּתְּחִלָּה. וְזֶהוּ בְּרֵאשִׁית, הוֹצֵא מִשָּׁם אֵשׁ, וְנִשְׁאָר בְּרִית. כְּלוֹמַר בְּרִי\"ת אֵ\"שׁ.</p>"],[9514011277,"<p>ר' יוֹחָנָן אָמַר, בְּרִית כְּרוּתָה כָּרַת הַקָּדוֹשׁ בָּרוּךְ הוּא עִם הָעוֹלָם, וְעַל מְנָת שֶׁיַּעֲמוֹד אַבְרָהָם, וְיִתְקַיֵּים הָעוֹלָם בִּזְכוּתוֹ. שֶׁנֶּאֱמַר, (בראשית ב׳:ד׳) אֵלֶּה תּוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּאַבְרָהָם. וְאוֹתָהּ שָׁעָה שֶׁכָּרַת עִמּוֹ הַבְּרִית בָּאֵשׁ, עָמַד הָעוֹלָם בְּקִיּוּמוֹ, וְזֶהוּ בְּרֵאשִׁית, בְּרִית אֵשׁ, בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ כְּדֵי שֶׁיַּעֲמוֹד אוֹתוֹ הַבְּרִית אֵשׁ.</p>"],[9514011278,"<p>וְהַחָכְמָה אוֹמֶרֶת, לָמָּה הֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא מַבּוּל מַיִם לָעוֹלָם, בִּתְחִלַּת דִּינוֹ, וְלֹא דָּבָר אַחֵר. אֶלָּא רָאָה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהָעוֹלָם נִבְרָא בִּבְרִית אֵשׁ, וְרָאָה שֶׁאִם יָדִין הָעוֹלָם בְּדִין אַחֵר, אֶפְשָׁר שֶׁיּוּכְלוּ הָרְשָׁעִים לַעֲמוֹד בָּעוֹלָם, מִפְּנֵי אוֹתוֹ בְּרִית אֵשׁ, כַּאֲשֶׁר נִבְרָא הָעוֹלָם. אֶלָּא מֶה עָשָׂה, דָּן אֶת הָעוֹלָם בַּמַּיִם, בְּדָבָר הָרָאוּי לְכַבּוֹת אֶת הָאֵשׁ, כְּדֵי לְהַעֲבִיר אֶת הָרְשָׁעִים מִן הָעוֹלָם, שֶׁנִּמְשְׁלוּ לְאֵשׁ, שֶׁנֶּאֱמַר (יחזקאל ט״ו:ז׳) מֵהָאֵשׁ יָצָאוּ וְהָאֵשׁ תֹּאכְלֵם. רְצוֹנוֹ לֹאמָר, מֵהָאֵשׁ יָצָאוּ בִּתְחִלַּת הָעוֹלָם כְּשֶׁנִּבְרָא.</p>"],[9514011279,"<p>לָכֵן בַּתְּחִלָּה אָמַר אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי בַּמַּיִם, שֶׁנֶּאֱמַר (ישעיהו נ״ז:כ׳) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ, לְאַחַר כֵּן נֶאֱמַר, מֵהָאֵשׁ יָצָאוּ וְהָאֵשׁ תֹּאכְלֵם, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא עַד כָּאן הָיוּ נִמּוֹקִים בַּמַּיִם, מִכָּאן וָאֵילָךְ מֵהָאֵשׁ יָצָאוּ וְהָאֵשׁ תֹּאכְלֵם.</p>"],[9514011280,"<p>וּכְשֶׁחָטְאוּ אַחַר כֵּן, דָּן אוֹתָם בָּאֵשׁ, שֶׁנֶּאֱמַר (בראשית י״ט:כ״ד) וַה' הִמְטִיר עַל סְדֹם וְעַל עֲמֹרָה גָּפְרִית וָאֵשׁ, וְאֵימָתַי נִתְבַּסֵּם הָעוֹלָם, כְּשֶׁעָמְדוּ עַל הַר סִינַי, וְנִתְמַלֵּא כֻּלּוֹ אֵשׁ, שֶׁנֶּאֱמַר (דברים ד׳:י״א) וְהָהָר בֹּעֵר בָּאֵשׁ עַד לֵב הַשָּׁמַיִם. ר' יִצְחָק אָמַר, וְהַתּוֹרָה נִהְיְתָה בְּרִית בֵּין הַשֵּׁם וְהָעוֹלָם, שֶׁנִּמְשְׁלָה בָּאֵשׁ, שֶׁנֶּאֱמַר (ירמיהו כ״ג:כ״ט) הֲלוֹא כֹה דְּבָרִי כָּאֵשׁ, וְזֶהוּ בְּרִית אֵשׁ בְּרֵאשִׁית.</p>"],[9514011281,"<p>ר' יוֹחָנָן פְּתַח, (משלי כ״ד:ג׳) בְּחָכְמָה יִבָּנֶה בָּיִת, שְׁלשָׁה דְבָרִים צָרִיךְ אָדָם לַעֲשׂוֹת בְּדַרְכֵי הָעוֹלָם, וְאֵלּוּ הֵן: לִבְנוֹת בֵּית מוֹשָׁבוֹ, וְלִיטַע כֶּרֶם לְהִתְפַּרְנֵס בּוֹ, וְאַחַר כַּךְ לָקַחַת לוֹ אִשָּׁה, וּלְהוֹלִיד בָּנִים, לְפַרְנְסָם בָּהֶם. וְלֹא כְּדֶרֶךְ הַשּׁוֹטִים, הַלּוֹקְחִים אִשָּׁה בַּתְּחִלָּה, וְאַחַר כָּךְ נוֹטְעִים כָּרֶם, וְאַחַר כָּךְ בּוֹנִים בָּיִת.</p>"],[9514011282,"<p>כִי הָא דְּאָמַר רִבִּי סִימוֹן, כָּל הַלּוֹקֵחַ לוֹ אִשָּׁה, וְאֵין לוֹ בַּתְּחִלָּה בַּמֶּה שֶׁיּוּכַל לְפַרְנְסָהּ, הֲרֵי זֶה חָפְשִׁי מִן הַמִּצְוֹת, כַּמֵתִים הַנִּקְרָאִים חָפְשִׁים, שֶׁנֶּאֱמַר (תהילים פ״ח:ו׳) בַּמֵּתִים חָפְשִׁי. וְלָמָּה נִקְרָא חָפְשִׁי. לְפִי שֶׁהוּא חָפְשִׁי מִן הַמִּצְוֹת, מִפְּנֵי שֶׁלֹּא יוּכַל לְהִשְׁתַּדֵּל בַּעֲבוֹדַת בּוֹרְאוֹ, אֶלָּא בַּעֲבוֹדַת אִשְׁתּוֹ.</p>"],[9514011283,"<p>ר' יְהוּדָה אוֹמֵר, כְּאִלּוּ לוֹקֵחַ עֲבוֹדָה זָרָה לְעַצְמוֹ. דְּאָמַר רִבִּי יְהוּדָה, בַּתְּחִלָּה הָיוּ הַחֲכָמִים וְהַחֲסִידִים לוֹקְחִין אִשָּׁה, וְלֹא הָיָה לָהֶם דֵּי פַּרְנָסָתָם, וּמְמִיתִים עַצְמָם בָּרָעָב וּבַצָּמָא, וּמַנִּיחִים כָּל חַיֵּי הָעה\"ז, וְעוֹסְקִים בַּתּוֹרָה וּבַמִּצְוֹת וּבַעֲבוֹדַת בּוֹרְאָם. אֲבָל בַּזְּמַן הַזֶּה שֶׁהָעוֹלָם טָרוּד אַחַר הַפַּרְנָסָה, צָרִיךְ לְכוֹנֵן בַּיִּת בַּתְּחִלָּה, וּלְזַמֵּן מְזוֹנוֹתָיו, וְאַחַר כַּךְ לָקַחַת אִשָּׁה, וְיָכוֹל לַעֲבֹד בּוֹרְאוֹ, וְלַעֲסֹק בַּתּוֹרָה. כִּי הָא דְּאָמְרוּ רַבּוֹתֵינוּ זִכְרוֹנָם לִבְרָכָה, אִם אֵין קֶמַח אֵין תּוֹרָה.</p>"],[9514011284,"<p>וְאָמַר רִבִּי יְהוּדָה, מֵאַחַר שֶׁהָאָדָם נוֹשֵׂא אִשָּׁה, אָז נִקְרָא עֶבֶד ה', מִפְּנֵי שֶׁלִּבּוֹ פָּנוּי מִלְּהִסְתַּכֵּל בַּעֲבֵירָה וּבַנָּשִׁים, וּמִלָּתוּר אַחַר לְבָבוֹ וְעֵינָיו, כְּמָה דְאַתְּ אָמֵר (במדבר ט״ו:ל״ט) וְלֹא תָתוּרוּ אַחֲרֵי לְבַבְכֶם וְאַחֲרֵי עֵינֵיכֶם וְגו'. לְפִיכָךְ צָרִיךְ אָדָם לְהִשְׁתַּדֵּל לְכוֹנֵן בַּיִת בָּרֹאשׁ, וְלַעֲשׂוֹת יִשּׁוּב בַּבַּיִת.</p>"],[9514011285,"<p>וּמִמִּי אַתָּה לָמֵד, מֵהַקָּדוֹשׁ בָּרוּךְ הוּא. קֹדֶם בָּנָה בַּיִת וְכוֹנְנוֹ, וְזִימֵּן כָּל הַפַּרְנָסָה וְהַמְזוֹנוֹת, קֹדֶם שֶׁיָּבֹא אָדָם לָעוֹלָם. הָאֵיךְ. בָּרָא אֶת הָעוֹלָם בָּרֹאשׁ, שֶׁהוּא הַבַּיִת. וְזִימֵּן כָּל הַפַּרְנָסָה הָאֵיךְ. בָּרָא אֶת הַבְּהֵמוֹת, וְאֶת הַחַיּוֹת, וְאֶת הָעוֹפוֹת וְהַדָּגִים הַצְּמָחִים וְהָאִילָנוֹת, שֶׁהֵם זִימּוּן כָּל הַפַּרְנָסָה. לְאַחַר שֶׁהֵכִין הַבַּיִת וְהַפַּרְנָסָה, הֵבִיא אֶת הָאָדָם, וּבָרָא אוֹתוֹ וְאֶת אִשְׁתּוֹ וְהוֹלִידוּ בָנִים וְעָשׂוּ יִשּׁוּב בַּבַּיִת. וְעַל כֵּן נֶאֱמַר בְּרֵאשִׁית, בֵּית רֹאשׁ. כַּאֲשֶׁר תָּבִין בָּאוֹתִיּוֹת, תִּמְצָא בי\"ת רֹאשׁ. וְכֵן הִתְחִילָּה הַתּוֹרָה בְּרֵאשִׁית, כְּלוֹמַר בֵּית רֵאשִׁית, וְהַכֹּל עִנְיָן אֶחָד.</p>"],[9514011286,"<p>וְעִם כָּל זֶה צָרִיךְ הָאָדָם לְהִשְׁתַּדֵּל בְּדֶרֶךְ אֶרֶץ, וְלַעֲשׂוֹת עִתִּים לַתּוֹרָה, וְלִהְיוֹת עֲמָלוֹ בִּשְׁנֵי הַדְּרָכִים הָאֵלּוּ, מִפְּנֵי שֶׁיְגִיעַת שְׁנֵיהֶם מַשְׁכַּחַת עָוֹן. וְשֶׁמָּא יֹאמַר אָדָם הֲרֵינִי בֶּן אֲבוֹת הָעוֹלָם, מִמִּשְׁפָּחָה גְדוֹלָה, אֵינִי רָאוּי לַעֲשׂוֹת מְלָאכָה וְלֹא לְהִתְבַּזּוֹת. אֱמֹר לוֹ, שׁוֹטֶה, כְּבָר קִדְמָךְ יוֹצְרָךְ, שֶׁנֶּאֱמַר בְּרֵאשִׁית בָּרָא אֱלֹהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְהוּא עָשָׂה מְלָאכָה קוֹדֶם שֶׁבָּאתָ לָעוֹלָם. וּמְנָא לָן. שֶׁנֶּאֱמַר (בראשית ב) מִכָּל מְלַאכְתּוֹ אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת. קָרָא אוֹתָהּ מְלָאכָה. וְכֵן (שם) וַיִּשְׁבֹּת בַּיּוֹם הַשְּׁבִיעִי מִכָּל מְלַאכְתוֹ אֲשֶׁר עָשָׂה.</p>"],[9514011287,"<p>וְכִי הָא דְּאָמַר ר' יוֹחָנָן, בֹּא וּרְאֵה, לָמָּה בָּרָא הַקָדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם אַחֲרוֹן לְכָל הַנִּבְרָאִים. אֶלָּא לְלַמֶּדְּךָ, שֶׁעָשָׂה בְּכָל יוֹם וָיוֹם מְלַאכְתּוֹ, וּבָרָא הָעוֹלָם וְכָל צְבָאָם, וּבַיּוֹם הַשִּׁשִּׁי שֶׁהוּא אַחֲרוֹן לִמְלַאכְתּוֹ, בָּרָא בּוֹ אֶת הָאָדָם. אָמַר לֵיהּ לָאָדָם, עַד כָּאן הָיִיתִי אֲנִי מִשְׁתַּדֵּל בַּמְּלָאכָה, מִכָּאן וָאֵילָךְ אַתָּה תִּשְׁתַּדֵּל בָּהּ, וְזֶהוּ בְּרֵאשִׁית בָּרָא אֱלֹהִים, קוֹדֶם שֶׁיָּבֹא אָדָם לָעוֹלָם.</p>"],[9514011288,"<p>וְאָמַר רִבִּי יוֹחָנָן, לָמָּה נִבְרָא אָדָם בְּצֶלֶם אֱלֹהִים. שֶׁנֶּאֱמַר (שם א) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. מָשָׁל לְמֶלֶךְ שֶׁהָיָה מוֹשֵׁל עַל הַמְדִינָה, וְהָיָה בּוֹנֶה בִּירָנִיּוֹת וְתִיקּוּנִין לָעִיר, וְכָל בְּנֵי הָעִיר מִשְׁתַּעְבְּדִין תַּחְתָּיו. יוֹם א' קָרָא לְכָל בְּנֵי הָעִיר, וּמִינָּה עֲלֵיהֶם שַׂר אֶחָד שֶׁלּוֹ, אָמַר, עַד כָּאן הָיִיתִי טוֹרֵחַ בְּכָל צָרְכֵי הָעִיר, וְלַעֲשׂוֹת מִגְדָּלִים וּבִירָנִיּוֹת, מִכָּאן וָאֵילָךְ הֲרֵי זֶה כָּמוֹנִי.</p>"],[9514011289,"<p>כְעִנְיַן זֶה נֶאֱמַר בָּאָדָם, וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, וְאָמַר לֵיהּ רְאֵה בָּנִיתִי כָּל הָעִיר וְכָל אֲשֶׁר בָּהּ, וְכַאֲשֶׁר הָיִיתִי מוֹשֵׁל עָלֶיהָ וּבוֹנֶה אוֹתָהּ כְּכָל חֶפְצִי, כָּךְ אַתָּה תִּבְנֶה וְתַעֲשֶׂה מְלֶאכֶת הָעוֹלָם. מִכָּאן וָאֵילָךְ יִהְיֶה הַכֹּל מָסוּר בְּיָדְךָ, וְכוּלָּם יִהְיוּ מְשׁוּעְבָּדִים תַּחְתֶּיךָ, וִירֵאִים מִמְךָ, כַּאֲשֶׁר הָיוּ יְרֵאִים מִמֶּנִּי, שֶׁנֶּאֱמַר (שם ט) וּמוֹרָאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ. וְעַל כֵּן בְּצֶלֶם אֱלֹהִים עָשָׂה אוֹתוֹ. וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ, לַעֲשׂוֹת כָּל צָרְכֵי הָעוֹלָם וְתִיקּוּנָיו, כַּאֲשֶׁר הוּא עָשָׂה בַּתְּחִלָּה.</p>"],[9514011290,"<p>בְּרֵאשִׁית, כְּתִיב (משלי ח׳:כ״ב) ה' קָנָנִי רֵאשִׁית דַּרְכּוֹ קֶדֶם מִפְעָלָיו מֵאָז, הַפָּסוּק הַזֶּה חוֹזֵר עַל כָּל הַתּוֹרָה, שֶׁהִיא הָיְתָה רֵאשִׁית דַּרְכֵי אֵל, שֶׁהַתּוֹרָה נִבְרֵאת אַלְפַּיִם שָׁנָה קוֹדֶם שֶׁנִּבְרָא הָעוֹלָם.</p>"],[9514011291,"<p>דְּאָמַר רִבִּי אֶלְעָזָר, שִׁבְעָה דְבָרִים נִבְרְאוּ עַד שֶׁלֹּא נִבְרָא הָעוֹלָם. וְאֵלּוּ הֵם: הַתּוֹרָה. וְגַּן עֵדֶן. וְגֵיהִנֹּם. וְכִסֵּא הַכָּבוֹד. וּבֵית הַמִּקְדָּשׁ. וּשְׁמוֹ שֶׁל מָשִׁיחַ. וְהַתְּשׁוּבָה. וּבַתּוֹרָה בָּרָא אֶת הָעוֹלָם, שֶׁנֶּאֱמַר (שם) ה' קָנָנִי וְגו'. וְזֶהוּ בְּרֵאשִׁית בָּרָא אֱלֹהִים, רְצוֹנוֹ לֹאמָר עִם רֵאשִׁית, שֶׁהִיא הַתּוֹרָה, בָּרָא אֱלֹהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. אָמַר רִבִּי יְהוּדָה בֹּא וּרְאֵה כַּמָּה הֶפְרֵשׁ יֵשׁ בֵּין הַתּוֹרָה וְהָעוֹלָם, שֶׁהָעוֹלָם נִבְרָא בְּשֵׁשֶׁת יָמִים, וְהַתּוֹרָה בְּאַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה.</p>"],[9514011292,"<p>רַבִּי יוֹחָנָן הֲוֵי אָזִיל מִקֵּסָרִי לְלוּד, וְהָיָה מְטַיֵּיל עִמֵּיהּ ר' חִיָּיא בַּר אַבָּא, כַּד מָטוֹ חַד בֵּי חֲקַל, אָמַר רִבִּי יוֹחָנָן, הַאי הֲוֵי דִידִי, וְזַבִּינְתֵּיהּ, כְּדֵי לְמִזְכֵּי בְּאוֹרַיְיתָא. בָּכָה ר' חִיָּיא בַּר אַבָּא, אָמַר לֵיהּ וְלָמָּה אַתְּ בָּכֵי. אָמַר לֵיהּ, דְּלָא שַׁבְקַת לְסִיבוּתִיךְ כְּלוּם.</p>"],[9514011293,"<p>אָמַר לֵיהּ, חִיָּיא בְּנִי, קַלָּה הוּא בְּעֵינֶךָ מַה דַּעֲבָדִית, דְּשַׁבְקִית דָּבָר שֶׁנִּבְרָא בְּשִׁשָּׁה יָמִים, בַּעֲבוּר דָּבָר שֶׁנִּבְרָא בְּאַרְבָּעִים יוֹם, שֶׁנֶּאֱמַר (שמות ל״ד:כ״ח) וַיְהִי שָׁם עִם ה' אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה וְקָנִיתִי דְּבָרִים גְּדוֹלִים וְטוֹבִים שֶׁאֵינָם בָּעוֹלָם, וְהֵם עֵצָה וְתוּשִׁיָּה וְחָכְמָה וּגְבוּרָה, שֶׁנֶּאֱמַר (משלי ח׳:י״ד) לִי עֵצָה וְתוּשִׁיָּה אֲנִי בִּינָה לִי גְּבוּרָה.</p>"],[9514011294,"<p>ר' יוֹחָנָן כַּד הֲוָה לָעֵי בְּאוֹרָיְיתָא, הֲווֹ אַנְפּוֹי זְהִירִין כְּזוֹהֲרָא דְּשִׁמְשָׁא, יוֹמָא חַד פָּגַע בֵּיהּ ר' יוֹסֵי, אֲמַר לֵיהּ חָמָא אַנְפָּךְ זְהִירִין כְּזָהֳרָא דְּשִׁמְשָׁא, אָמַר לֵיהּ לָאו הוּא אֶלָּא שְׁמַעְתָּא דְּנָהֲרָא לִי. קָרָא עֲלֵיהּ (שופטים ה׳:ל״א) וְאוֹהֲבָיו כְּצֵאת הַשֶּׁמֶשׁ בִּגְבוּרָתוֹ.</p>"],[9514011295,"<p>ר' יִצְחָק אָמַר, הַתּוֹרָה נִקְרֵאת תּוּשִׁיָּה בַּתְּחִלָּה. וְאַחַר כַּךְ גְּבוּרָה, שֶׁנֶּאֱמַר לִי עֵצָה וְתוּשִׁיָּה וְגו', תֵּדַע לָךְ כִּי בַּתְּחִלָּה נִקְרֵאת תּוּשִׁיָּה, שֶׁמַּתֶּשֶׁת כֹּחוֹ שֶׁל אָדָם, מִפְּנֵי שֶׁיֵּשׁ לוֹ לְהִלָּחֵם עִם יֵצֶר הָרָע, וּלְכַתֵּת כָּל גּוּפוֹ בְּבֵית הַמִּדְרָשׁ, עַד שֶׁיַּרְגִּיל אוֹתוֹ בַּתּוֹרָה. כֵּיוָן שֶׁהוּא רָגִיל לַעֲסוֹק בַּתּוֹרָה, אָז יֵשׁ לוֹ שִׂמְחָה וּגְבוּרָה, שֶׁנֶּאֱמַר אֲנִי בִינָה לִי גְבוּרָה, רְצוֹנוֹ לֹאמָר כְּשֶׁאָדָם רָגִיל בַּתּוֹרָה וּבַחָכְמָה, אָז יֵשׁ לוֹ תִּפְאֶרֶת, וְאֵיזוֹ הִיא גְּבוּרָה, לְהִלָּחֵם מִלְחָמוֹת ה', שֶׁנֶּאֱמַר (במדבר כ״א:י״ד) עַל כֵּן יֵאָמַר בְּסֵפֶר מִלְחֲמֹת ה', שָׁם תְּהֵא הַמִּלְחָמָה וְהַגְּבוּרָה.</p>"],[9514011296,"<p>וּבַתּוֹרָה בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, שֶׁנֶּאֱמַר (משלי ח׳:ל׳) וָאֶהְיֶה אֶצְלוֹ אָמוֹן, אַל תִּקְרֵי אָמוֹן, אֶלָּא אוּמָּן. וְזֶהוּ בְּרֵאשִׁית בָּרָא אֱלֹהִים, עִם רֵאשִׁית בָּרָא אֱלֹהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ, וְזוֹ הִיא הַתּוֹרָה.</p>"],[9514011297,"<p>ר' יְהוּדָה אוֹמֵר, לֹא נִבְרָא אֶלָּא בִּשְׁבִיל הַיִּרְאָה, שֶׁנִּקְרֵאת רֵאשִׁית, שֶׁנֶּאֱמַר (משלי א׳:ז׳) יִרְאַת ה' רֵאשִׁית דָּעַת. וּמְנָא לָן שֶׁהָעוֹלָם נִבְרָא עַל פִּי הַיִּרְאָה, שֶׁנֶּאֱמַר (קהלת ג׳:י״ד) וְהָאֱלֹהִים עָשָׂה שֶׁיִּירְאוּ מִלְּפָנָיו. עָשָׂה אֶת הָעוֹלָם, כְּדֵי שֶׁיִּירְאוּ מִלְּפָנָיו, וְעַל פִּי הַיִּרְאָה שֶׁהִיא רֵאשִׁית, בָּרָא אֱלֹהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ.</p>"],[9514011298,"<p>בְּרֵאשִׁית, רַבִּי אֶלְעָזָר פְּתַח, (תהילים ק״כ:א׳) שִׁיר הַמַּעֲלוֹת אֶל ה' בַּצָּרָתָה לִי קָרָאתִי וַיַּעֲנֵנִי. שִׁירִים תְּאֵבִים בָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בִּבְרִיאַת שָׁמַיִם וָאָרֶץ, כְּדֵי לְהַלְּלוֹ וּלְשַׁבְּחוֹ, שֶׁהוּא יוֹצֵר הַכֹּל. הַשָּׁמַיִם אוֹמְרִים שִׁירָה לְפָנָיו, שֶׁנֶּאֱמַר (תהילים י״ט:ב׳) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל, וְהָאָרֶץ אוֹמֶרֶת שִׁירָה, שֶׁנֶּאֱמַר (שם צו) שִׁירוּ לַה' כָּל הָאָרֶץ.</p>"],[9514011299,"<p>וְעוֹד, שֶׁכָּל הָעוֹלָם תְּאֵבִים וּשְׂמֵחִים לְפָאֵר לְיוֹצְרָם, בַּחֲזוֹתָם נִפְלְאוֹתָיו בַּשָּׁמַיִם וּבָאָרֶץ, וְזֶהוּ בְּרֵאשִׁית. עַיֵּין בָּאוֹתִיּוֹת וְתִרְאֶה, שִׁי\"ר תָּאֵ\"ב. כְּלוֹמַר, תָּאֵ\"ב לֵאמֹר שִׁי\"ר, עַל נִפְלְאוֹתָיו בַּשָּׁמַיִם וּבָאָרֶץ, אֵיזֶה הוּא אוֹתָם הַמַּעֲלוֹת שֶׁהָיָה דָּוִד הַמֶּלֶךְ עָלָיו הֲשָׁלוֹם אוֹמֵר. אֵלּוּ הֵם אוֹתָם הַשִּׁירִים שֶׁל אוֹתָן הַמַּעֲלוֹת, שֶׁהֵם הַשָּׁמַיִם, שֶׁנֶּאֱמַר (עמוס ט׳:ו׳) הַבּוֹנֶה בַּשָּׁמַיִם מַעֲלוֹתָיו. וְדָוִד תָּאַב לָהֶם, וְהָיָה אוֹמְרִים, וְזֶהוּ שִׁיר תָּאֵב.</p>"],[9514011300,"<p>וְאָמַר רִבִּי אֶלְעָזָר, כְּתִיב (איוב ל״ח:ז׳) בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. מָאן אִינוּן בְּנֵי הָאֱלֹהִים. אֵלּוּ הֵם הַמַּלְאָכִים, שֶׁהֵם אוֹמְרִים שִׁירָה לִפְנֵי יוֹצֵר בְּרֵאשִׁית בְּכָל לַיְלָה, כְּנֶגֶד שָׁלשׁ מִשְׁמָרוֹת דַּהֲוֵי הַלַּיְלָה. וּבְכָל מִשְׁמָרָה וּמִשְׁמָרָה, כָּל כַּתְּ וְכַתְּ אוֹמֶרֶת שִׁירָה. וּבַמִּשְׁמָרָה הָאַחֲרוֹנָה שֶׁהִיא בְּסוֹפָהּ, וְהִיא לְעֵת הַבֹּקֶר, כָּל הַכּוֹכָבִים וְהַמַּזָּלוֹת, וְהַמַּלְאָכִים הַנִּקְרָאִים בְּנֵי הָאֱלֹהִים, הֵם אוֹמְרִים שִׁירָה, שֶׁנֶּאֱמַר, בְּרָן יַחַד כּוֹכְבֵי בֹקֶר וְגו'.</p>"],[9514011301,"<p>וְכָל אֶחָד כְּפִי מַעֲלָתוֹ. לְהוֹרוֹת כִּי גָּבוֹהַּ מֵעַל גָּבוֹהַּ שׁוֹמֵר, כִּי מַעֲלוֹת יֵשׁ לָהֶם אֵלֶּה לְמַעְלָה מֵאֵלֶּה, עַל כֵּן נֶאֱמַר שִׁיר הַמַּעֲלוֹת, מִמַּעֲלוֹת הַמַּלְאָכִים שֶׁהֵם אוֹמְרִים שִׁירָה, וְזֶהוּ בְּרֵאשִׁית, שִׁי\"ר תָּאֵ\"ב, בָּרָא אֱלֹהִים אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ.</p>"],[9514011302,"<p>רַבִּי חִזְקִיָּה הֲוָה אָזִיל בְּאוֹרְחָא, וַהֲוָה עִמֵּיהּ ר' יוֹסֵי בַּר חֲלַפְתָּא, קָמוּ לְמֵיזַל. בָּתַר פַּלְגוּת לֵילְיָא, עַד דַּהֲווֹ אָזְלֵי, אָמַר רִבִּי יוֹסֵי לְרַבִּי חִזְקִיָּה, מַאי עָבֵידְנָא, דְּהָא תָּנִינָן לְעוֹלָם יֵצֵא אָדָם בְּכִי טוֹב.</p>"],[9514011303,"<p>אָמַר לֵיהּ רַבִּי חִזְקִיָּה, יוֹסֵי בְּרִי, תָּא שְׁמַע הֲדַר נְעִימוּת קָל גַּלְגַּלֵּי חַיּוּתָא, דְּאִינוּן מְשַׁבְּחָן שִׁירָתָא קָדָם אֱלָהָנָא. עַד דְּאַרְכִין אוּדְנֵיהּ, שְׁמַע קָל תּוּשְׁבְּחָא נְעִימוּתָא, דַּהֲווֹ אָמְרֵי (תהילים ט׳:ז׳-ח׳) וַה' לְעוֹלָם יֵשֵׁב וְגו'.</p>"],[9514011304,"<p>אָמַר לֵיהּ רַבִּי חִזְקִיָּה, בְּרִי, שָׁמַעְתָּ כְּלוּם. אֲמַר לֵיהּ, קָל נְעִימוּתָא. וּמִן נְעִימוּתָא וְתוּשְׁבַּחְתָּא מֵהַאי פְּסוּקָא דִּשְׁמָעִית, כְּעָן יְדַעְנָא פֵּירוּשׁוֹ, דִּכְתִיב וַה' לְעוֹלָם יֵשֵׁב כּוֹנֵן לַמִּשְׁפָּט כִּסְּאוֹ. דִּבְכָל שַׁעֲתָא וְשַׁעֲתָא דְּדַיְינֵי דִינָא שְׁכִינְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, דְּהוּא כּוּרְסָא יְקָרֵיהּ מִתְתַּקֵּן תַּמָּן, מַשְׁמַע שֶׁנֶּאֱמַר כּוֹנֵן לַמִּשְׁפָּט כִּסְּאוֹ.</p>"],[9514011305,"<p>אָמַר לֵיהּ יָדַעְתָּ אֵיזוֹ הִיא מִשְׁמָרָה מִמַּלְאֲכֵי הַשָּׁרֵת אָמְרֵי דָא. אָמַר לֵיהּ לָאו. אָמַר לֵיהּ, מִשְׁמֶרֶת אוֹתָם הַמַּלְאָכִים, הַנִּקְרָאִים אֱלֹהִים הִיא. דְּתַנְיָא, עֲשָׂרָה מִשְׁמָרוֹת שֶׁל מַלְאֲכֵי הַשָּׁרֵת אִיכָּא בִּרְקִיעָא, וְאִינוּן מִתְחַלְּקִין בִּשְׁלשָׁה מִשְׁמָרוֹת דַּהֲוֵי הַלַּיְלָה.</p>"],[9514011306,"<p>וְתֵהַע לָךְ הָאֵיךְ, כַּד יִשְׂרָאֵל מְסַיְּימִים צְלוֹתְהוֹן בְּלֵילְיָא, נָסְבִין שִׁירָתָא בַּתְרֵיהוֹן, אִינוּן דְּנִקְרָאִים אִישִׁים, וְאָמְרֵי שִׁירָתָא. וּמַאי שִׁירָתָא אָמְרִין. (שם ה) מָה אֱנוֹשׁ כִּי תִזְכְּרֶנּוּ וְגו' וַתְּחַסְּרֵהוּ מְעַט מֵאֱלֹהִים וְכָבוֹד וְהָדָר תַּעְטְרֵהוּ וְגו' ה' אֲדוֹנֵינוּ מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ. בְּמִשְׁמָרָה שְׁנִיָּה נָסְבִין שִׁירָתָא, אִינוּן דְּנִקְרָאִים מַלְאָכִים וְחַשְׁמַלִּים וְאֶרְאֶלִים. וּמַאי אָמְרֵי, (שם כט) הָבוּ לַה' בְּנֵי אֵלִים.</p>"],[9514011307,"<p>בְּפַלְגוּת לֵילְיָא מַמָּשׁ, עַד דְּסַיֵּים מִשְׁמָרָה שְׁנִיָּה, דְּהַהִיא שַׁעֲתָא הִיא דְּקוּדְשָׁא בְּרִיךְ הוּא מִסְתַּכֵּל בְּעֵדֶן מַמָּשׁ, דְּגָנִיז לַצַּדִּיקִים לֶעָתִיד לָבוֹא. פָּתְחֵי חַיּוֹת הַקֹּדֶשׁ, וּבַתְרֵיהוֹן שְׂרָפִים וְאוֹפַנִּים וּכְרוּבִים, וְאָמְרֵי (שם לא) מָה רַב טוּבְךָ אֲשֶׁר צָפַנְתָּ לִירֵאֶיךָ (שם סח) סוֹלוּ לָרוֹכֵב בָּעֲרָבוֹת בְּיָהּ שְׁמוֹ.</p>"],[9514011308,"<p>בִּתְחִלַּת מִשְׁמָרָה תְּלִיתָאָה, נָסְבִין שִׁירָתָא אִינוּן דְּנִקְרָאִים אֱלֹהִים, וְאָמְרֵי וַה' לָעוֹלָם יֵשֵׁב וְגו'. כַּד אָתֵי צַפְרָא, פָּתְחֵי שְׁמַיָא וְאָמְרֵי, (שם יט) הַשָּׁמַיִם מְסַפְּרִים כְּבוֹד אֵל וְגו'. כּוֹכְבֵי בֹקֶר אָמְרֵי, (שם קמז) מוֹנֶה מִסְפָּר לַכּוֹכָבִים וְגו', גָּדוֹל אֲדוֹנֵינוּ וְרַב כֹּחַ. אוֹתָם הַמַּלְאָכִים הַנִּקְרָאִים בְּנֵי אֱלֹהִים פָּתְחֵי וְאָמְרֵי, (תהילים כ״ט:א׳) הָבוּ לַה' בְּנֵי אֵלִים הָבוּ לַה' כָּבוֹד וָעֹז.</p>"],[9514011309,"<p>עַד דַּהֲווֹ אָזְלֵי, חָמוֹ דְּקָדְרָא שַׁחֲרָא, וְהָדַר נְהוֹרָא. אָמַר רִבִּי חִזְקִיָּה לְרַבִּי יוֹסֵי, תָּא וְאַחֲזֵי לָךְ דְּכָךְ הִיא גְּאוּלָּתָן שֶׁל יִשְׂרָאֵל. בְּעִידְנָא דְּיִנְהַר לְהוֹן שִׁמְשָׁא דִּגְאוּלָּתָא, יֵתֵי לְהוֹן עָקָא בָּתַר עָקָא, וְקַדְרוּתָא בָּתַר קַדְרוּתָא, עַד דְּאִינוּן בָּהּ, יִנְהַר עֲלֵיהוֹן נְהוֹרָא דְקוּדְשָׁא בְּרִיךְ הוּא, שֶׁנֶּאֱמַר (הושע ו׳:ג׳) כְּשַׁחַר נָכוֹן מֹצָאוֹ. וּכְתִיב (מלאכי ג׳:כ׳) וְזָרְחָה לָכֶם יִרְאֵי שְׁמִי שֶׁמֶשׁ צְדָקָה וּמַרְפֵּא בִּכְנָפֶיהָ.</p>"],[9514011310,"<p>וּבְזִמְנָא הַהִיא מִלְחָמוֹת יִתְעוֹרְרוּ בָּעוֹלָם, גּוֹי בְּגוֹי, וְעִיר בְּעִיר, וְצָרוֹת רַבּוֹת יִתְחַדְּשׁוּ עַל שׂוֹנְאֵיהֶם שֶׁל יִשְׂרָאֵל. עַד שֶׁיֻּקְּדְרוּ פְּנֵיהֶם כְּשׁוּלֵי קְדֵרָה, וְאַחַר כַּךְ יִתְגַּלֶּה עֲלֵיהֶן גְּאוּלָּתָן מִתּוֹךְ שַׁאֲגַת לַחֲצָם וְדָחְקָם.</p>"],[9514011311,"<p>וְזֶהוּ שֶׁאָמַר דָּוִד הַמֶּלֶךְ עָלָיו הֲשָׁלוֹם, (תהילים כ״ב:א׳) לַמְנַצֵּחַ עַל אַיֶּלֶת הַשַּׁחַר. אַיֶּלֶת הַשַּׁחַר, אַיֶּלֶת הַבּוֹקֶר הֲוָה לֵיהּ לְמֵימַר. אֶלָּא עַל אַיֶּלֶת וְחוֹזֶק דְּשַׁחֲרוּתָא דְיִשְׂרָאֵל. כְּמָה דְאַתְּ אָמֵר (שם פח) כְּגֶבֶר אֵין אֱיָל. בְּהַהִיא שַׁעֲתָא יִזְעֲקוּן בְּנֵי יִשְׂרָאֵל, וְיֵמְרוּן אֵלִי אֵלִי לָמָּה עֲזַבְתָּנִי, מִגּוֹ עָקַתְהוֹן, לְבָתַר מַה כְּתִיב, (תהילים ל׳:י״ב) פִּתַּחְתָּ שַׂקִּי וַתְּאַזְרֵנִי שִׂמְחָה.</p>"],[9514011312,"<p>רַבִּי אוֹמֵר, הַשִּׁיתִּין מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית נִבְרְאוּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא שִׁית. וְזֶהוּ בְּרֵאשִׁית, כְּלוֹמַר, בָּרָא שִׁית. אֵילוֹ שֶׁל יִצְחָק, קוּשְׁטָא הוּא דְּנִבְרָא מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית. וְהַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָא שִׁי\"ת, תַּיִּ\"שׁ בְּהִפּוּךְ אוֹתִיּוֹת.</p>"],[9514011313,"<p>בְּרֵאשִׁית, יִתְבָּרַךְ שְׁמוֹ שׁל מֶּלֶךְ מַלְכֵי הַמְּלָכִים הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבָּרָא כָּל הָעוֹלָם, וְהֵכִינוֹ בְּחָכְמָה וּבִתְבוּנָה וּבְדַעַת, וּכְנֶגְדָן בָּרָא ג' עוֹלָמוֹת, עוֹלָם הָעֶלְיוֹן, וְעוֹלָם הַתַּחְתּוֹן, וְעוֹלָם הַתִּיכוֹן. וְנָתַן בָּעוֹלָם הַתַּחְתּוֹן הַקָּטָן, צוּרַת שְׁלָשְׁתָּן. צוּרַת הַמְדַבֶּרֶת, וְצוּרַת הַצּוֹמַחַת, וְצוּרַת הַשִּׂכְלִית.</p>"],[9514011314,"<p>וְתֵהַע לָךְ, כִּי הָעוֹלָם הַתַּחְתּוֹן מִתְקַיִּים בָּאֲוִיר, כַּאֲשֶׁר תִּרְאֶה כִּי הַגּוּף מִתְקַיִּים בַּנֶּפֶשׁ, וְהַנֶּפֶשׁ מִתְקַיְּימֶת בָּאֲוִיר, וְהָאֲוִיר בַּבּוֹרֵא יִתְבָּרַךְ. תֵּדַע לָךְ, שֶׁהַבּוֹרֵא יִתְבָּרַךְ בָּרָא הָאָדָם, וּבָרָא אוֹתוֹ בְּצֶלֶם וּבְצוּרָה.</p>"],[9514011315,"<p>וְהֵכִינוֹ מֵאַרְבָּעָה דְבָרִים מוּבְדָּלִים זֶה מִזֶּה, מֵאֵשׁ, מֵרוּחַ, מִמַּיִם, מֵעָפָר. שֶׁנֶּאֱמַר (בראשית א׳:א׳-ב׳) וְהָאָרֶץ הָיְתָה תֹהוּ וָבֹהוּ וְחשֶׁךְ עַל פְּנֵי תְהוֹם וְרוּחַ אֱלֹהִים. אֵלּוּ הֵם הַד' דְּבָרִים הַנִּזְכָּרִים, כְּמָה דְאַתְּ אָמֵר, מָקוֹם יֵשׁ בִּכְרַכֵּי הַיָּם, שֶׁקּוֹרִין לְאֵשׁ תּוֹהוּ, וְזֶהוּ הַיְסוֹד הָרִאשׁוֹן. וָבֹהוּ וְחשֶׁךְ, הֵם הַמַּיִם וְהֶעָפָר. וּמְנָא לָן דְּחשֶׁךְ הוּא הֶעָפָר. שֶׁנֶּאֱמַר (קהלת ו׳:ד׳) וּבַחשֶׁךְ שְׁמוֹ יְכֻסֶּה. וְאָמְרוּ שֶׁזֶּהוּ גּוּשׁ הֶעָפָר. וְהָרוּחַ, הוּא רוּחַ מַמָּשׁ.</p>"],[9514011316,"<p>וְאָמְנָם כִּי הָאֵל יִתְבָּרַךְ, בָּרָא אֶת הָאָדָם, שֶׁהוּא נִקְרָא עוֹלָם הַתַּחְתּוֹן, כְּנֶגֶד עוֹלָם הָעֶלְיוֹן הַגָּדוֹל, וְנָתַן בּוֹ קִיּוּם הַנֶּפֶשׁ, הַמֵּנִיעַ לַגּוּף כֻּלּוֹ, וְעַל כֵּן הִבְדִּילוֹ מִכָּל הַנִּבְרָאִים אֲשֶׁר לְמַטָה עִמּוֹ, וּבַמֶּה הָאָדָם מוּבְדָּל מִיֶּתֶר הַנִּבְרָאִים. מִפְּנֵי זֹאת הַנֶּפֶשׁ, וְאֵיזֶהוּ הִיא, נֶפֶשׁ הַמְדַבֶּרֶת.</p>"],[9514011317,"<p>שָׁאַל ר' יְהוּדָה לְר' דּוֹסְתָּאי, הַנֶּפֶשׁ אֲשֶׁר בָּאָדָם הַנִּקְרֵאת שִׂכְלִית, אֵיזֶהוּ נֶפֶשׁ הִיא, וְאֵיזֶהוּ מְקוֹמָהּ. אָמַר לֵיהּ, הֲלֹא יָדַעְתָּ כִּי הָאָדָם בָּרָא אוֹתוֹ הַמָּקוֹם יִתְבָּרַךְ בִּשְׁמוֹ, וְכַאֲשֶׁר הוּא גָּדֵל וְרוֹאֶה עִנְיְנֵי הָעוֹלָם, וּמַבִּיט בְּלִבּוֹ, הוּא מֵעַצְמוֹ מֵרִיחַ הַנֶּפֶשׁ הַזֹּאת, כִּי הוֹאִיל וְהוּא מַבִּיט וְרוֹאֶה נִפְלָאוֹת הַבּוֹרֵא, וְחִידּוּשׁ הָעוֹלָם, וְזִרוּחַ הַמְאוֹרוֹת עֶרֶב וָבֹקֶר, וְכִי כָּל הָעוֹלָם כֻּלּוֹ תָּלוּי בְּכֹחוֹ יִתְבָּרַךְ, הוּא מִשְׁתַּדֵּל בְּעַצְמוֹ לַחֲקוֹר וּלְהַשִּׂיג הַשָּׂגָה קְדוֹשָׁה וּבָרָה, וְאָז יֵשׁ לוֹ נֶפֶשׁ הַשִּׂכְלִית, מִפְּנֵי שֶׁהוּא מַשְׂכִּיל לָדַעַת לַחֲקוֹר בַּחָכְמָה.</p>"],[9514011318,"<p>רַבִּי עֲזַרְיָה אוֹמֵר, הַנֶּפֶשׁ מְקוֹמָהּ בַּלֵּב, וְהִיא מֵּנִיעָה לְכָל הַגּוּף, וְהִיא מוּנַּחַת בְּאֶמְצַע הַגּוּף, וּמֵאִירָה לְכָל הַגּוּף. כַּאֲשֶׁר נִתַּן הַשֶּׁמֶשׁ בַּחֲצִי הַשָּׁמָיִם. וְהַגּוּף מִתְקַיֵּים בַּנֶּפֶשׁ, וְהַנֶּפֶשׁ בָּאֲוִיר, וְהָאֲוִיר בַּבּוֹרֵא. וְהַבּוֹרֵא יִת' סוֹבֵל כָּל הָעוֹלָמוֹת בְּכֹחוֹ, שֶׁנֶּאֱמַר (ישעיהו מ״ו:ד׳) אֲנִי עָשִׂיתִי וַאֲנִי אֶשָֹׁא וַאֲנִי אֶסְבֹּל.</p>"],[9514011319,"<p>רַבִּי יְהוּדָה אוֹמֵר לָמָּה הִזְכִּיר הַקָּדוֹשׁ בָּרוּךְ הוּא בְּרִיאַת שָׁמַיִם וְהָאָרֶץ תְּחִלָּה, וַהֲלֹא כִּסֵּא הַכָּבוֹד וְהַמַּלְאָכִים, נִבְרְאוּ תְּחִלָּה. אֶלָּא, כְּדֵי שֶׁלֹּא יְהַרְהֵר אָדָם דְּבָרִים הַסְּתוּמִים מֵהָעַיִן וַאֲשֶׁר לֹא גִּלָּה בָּרֹאשׁ.</p>"],[9514011320,"<p>רַבִּי אוֹמֵר, כְּדֵי לְהַרְאוֹת לָאָדָם, שֶׁאֵינוֹ בַּעַל חָכְמָה, וְאֵינוֹ רָאוּי לְגַלּוֹת לוֹ סִתְרֵי תּוֹרָה. דְּאָמַר רִבִּי יִצְחָק, אֵין מְגַלִּין סִתְרֵי תּוֹרָה, אֶלָּא לְאָדָם חָכָם, וְקוֹרֵא וְשׁוֹנֶה, וְתַלְמוּדוֹ מִתְקַיִּים בְּיָדוֹ, וְהוּא יְרֵא שָׁמַיִם, וּבָקִי בְּכָל דָּבָר. וְאָדָם שֶׁאֵינוֹ בְּעִנְיַן זֶה, וְיִשְׁאַל עַל הַסְּתָרִים וְהַנְּעלָמִים שֶׁלְּמַעְלָה, אֱמוֹר לוֹ מָה אַתָּה שׁוֹאֵל, שָׂא נָא עֵינֶיךָ וּרְאֵה, כִּי בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, תֵּדַע לָךְ שֶׁלֹּא גִילְתָה הַתּוֹרָה יוֹתֵר.</p>"],[9514011321,"<p>וְאִם תֹּאמַר שֶׁאֵין סְתָרִים בַּתּוֹרָה, תֵּדַע לָךְ כִּי עַל כָּל דָּבָר וְדָבָר יֵשׁ תִּלֵּי תִּלִּים שֶׁל סוֹדוֹת וַהֲלָכוֹת וּפֵירוּשִׁים, שֶׁנֶּאֱמַר (שיר השירים ה׳:י״א) קְוֻצּוֹתָיו תַּלְתַּלִּים, עַל כָּל קוֹץ וְקוֹץ תִּלֵּי תִּלִּים. כִּי הָא דְּרַבָּן יוֹחָנָן בֶּן זַכַּאי, הֲוָה אָמַר עַל הַאי פְּסוּקָא, (בראשית ל״ו:ל״ט) וְשֵׁם אִשְׁתּוֹ מְהֵיטַבְאֵל בַּת מַטְרֵד בַּת מֵי זָהָב, שְׁלשׁ מֵאוֹת הֲלָכוֹת פְּסוּקוֹת, וְלֹא רָצָה לְגַלּוֹת אוֹתָם אֶלָּא לְר' אֶלְעָזָר בֶּן עֲרָךְ, וּלְר' אֶלְעָזָר בֶּן הוֹרְקְנוּס תַּלְמִידָיו, דַּהֲוֵי עָסְקֵי בְּמַעֲשֵׂה מֶרְכָּבָה עִמּוֹ.</p>"],[9514011322,"<p>אָמַר רִבִּי, בֹּא וּרְאֵה מַה כְּתִיב בִּשְׁלֹמֹה, (מלכים א ה׳:י״ב-י״ג) וַיְדַבֵּר שְׁלשֶׁת אֲלָפִים מָשָׁל וַיְהִי שִׁירוֹ חֲמִשָּׁה וָאָלֶף. עַל כָּל דָּבָר וְדָבָר הֲוָה אוֹמֵר בּוֹ אֶלֶף וַחֲמִשָּׁה טַעֲמִים. וּמַה שְּׁלֹמֹה, שֶׁהָיָה עֶבֶד שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, הָיָה אוֹמֵר עַל כָּל דָּבָר וְדָבָר ג' אֲלָפִים מָשָׁל, וְאֶלֶף וַחֲמִשָּׁה טַעֲמִים, הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא מְגַלֶּה עֲמִיקְתָּא וּמִסְתַּתְּרָא, וְהוּא הַנּוֹתֵן הַחָכְמָה וְהַבִּינָה, שֶׁנֶּאֱמַר (משלי ב׳:ו׳) כִּי ה' יִתֵּן חָכְמָה מִפִּיו דַּעַת וּתְבוּנָה עַל אַחַת כַּמָּה וְכַמָּה.</p>"],[9514011323,"<p>ר' לֵוִי אָמַר, כְּתִיב (תהילים צ״ב:ו׳) מַה גָּדְלוּ מַעֲשֶׂיךָ ה' מְאֹד עָמְקוּ מַחְשְׁבוֹתֶיךָ. מַה גָּדְלוּ מַעֲשֶׂיךָ ה', זֶה מַעֲשֵׂה בְרֵאשִׁית, שֶׁהֵם מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. מְאֹד עָמְקוּ מַחְשְׁבוֹתֶיךָ, אֵלּוּ סִתְרֵי תּוֹרָה.</p>"],[9514011324,"<p>ר' אֱלִיעֶזְר הַגָּדוֹל אוֹמֵר, כְּתִיב (מלכים א ה׳:כ״ו) וַה' נָתַן חָכְמָה לִשְׁלֹמֹה כַּאֲשֶׁר דִּבֶּר לוֹ, מְלַמֵּד שֶׁעָמַד עַל דִּקְדּוּקֵי תוֹרָה, אֲבָל עַל עָמְקֶיהָ לֹא עָמַד, וּכְשֶׁבִּקֵּשׁ לַעֲמוֹד עָלֶיהָ, אָמַר (קהלת ז׳:כ״ג) אָמַרְתִּי אֶחְכְּמָה וְהִיא רְחוֹקָה מִמֶּנִּי.</p>"],[9514011325,"<p>שָׁאַל ר' דוֹסְתָּאי לְר' אֱלִיעֶזְר הַגָּדוֹל, אָמַר לֵיהּ רַבִּי, הַעֲמִידֵנִי עַל סוֹד זֶה הַפָּסוּק, (במדבר כ״ח:ו׳) עוֹלַת תָּמִיד הָעֲשׂוּיָה בְּהַר סִינַי לְרֵיחַ נִיחוֹחַ אִשֶּׁה לַה'. אָמַר לֵיהּ, בְּנִי, חַיֶּיךָ דָּבָר אָמַרְתָּ לִי, שֶׁעֲדַיִן אֵינְךָ רָאוּי לַעֲמוֹד עָלָיו, וְלֹא שְׁאָלַנִי אָדָם עַל זֶה, זוּלָתִי עֲקִיבָא תַּלְמִידִי, וַעֲדַיִּן הַשָּׁרָשִׁים בְּיָדִי, שָׁמַע רַבִּי עֲקִיבָא, אָמַר כֵּיוָן שֶׁהֵנֵצוּ הַפְּרָחִים, אָכַלְתִּי הַשָּׁרָשִׁים. אָמַר לֵיהּ עֲקִיבָא עֲקִיבָא, מוּכָן תִּהְיֶה לְרֵיחַ נִיחוֹחַ לַה'. וַעֲדַיִין בְּלִיעַת הַמָּתוֹק נִשְׁאָר.</p>"],[9514011326,"<p>יוֹמָא חַד הֲווֹ אָזְלֵי בְּאוֹרְחָא, אָמַר לֵיהּ, אִי כְּדֵין אֲכַלְתְּ שָׁרְשִׁים דַּאֲמַרְתְּ. אָמַר לֵיהּ רַבִּי, מִשֶּׁאָמַרְתָּ לִי הַסּוֹד, עָמַדְתִּי עַל תְּכוּנָתוֹ. וְסָח לוֹ הָאֵיךְ. אָמַר לֵיהּ עָמַדְתָּ וְאָכַלְתָּ, וַעֲדַיִן הַבְּלִיעָה מֵהַמָּתוֹק נִשְׁאָר. וְאוֹתָהּ שָׁעָה גִּלָּה לוֹ אַרְבָּעִים סוֹדוֹת בַּתּוֹרָה.</p>"],[9514011327,"<p>עַד דַּהֲווֹ אָזְלֵי, חָמֵי חַד מַעֲיָינָא דְמַיָא, יָתְבוּ תַּמָּן. אָמַר לֵיהּ ר' אֱלִיעֶזְר, עֲקִיבָא, תָּא וְאַחֲזֵי לָךְ נְבִיעָא דְמַיָא, דְּקָא פָּתְחֵי מַיָא, וּצְלִילִין וְנָזְלִין, כְּהָא דִכְתִיב, (שיר השירים ד׳:ט״ו) בְּאֵר מַיִם חַיִּים וְנוֹזְלִים מִן לְבָנוֹן. וְעַל הֲדָא פְּסוּקָא, גִּילָּה לוֹ שִׂיחַת מַלְאֲכֵי הַשָּׁרֵת, שִׂיחַת כּוֹכָבִים וּמַזָּלוֹת, וִידִיעַת חַלּוֹנֵי חַמָּה בְּעִתּוֹתָיו וּזְמַנָּיו, שִׂיחַת דְּקָלִים וְעוֹפוֹת, שִׂיחַת הָרוּחוֹת, יְדִיעַת הַתְּקוּפוֹת וְהָעִיבּוּרִים.</p>"],[9514011328,"<p>בְּאוֹתָהּ שָׁעָה, בָּכָה רַבִּי עֲקִיבָא. אָמַר לֵיהּ עַל מַה קָא בָּכִיתָ. אָמַר לוֹ, אוֹ לַדּוֹר שֶׁיִּהְיוּ יְתוֹמִים מִמְךָ. אָמַר לוֹ, אַל תֹּאמַר כָּךְ, אֶלָּא וַוי לַדּוֹר שֶׁיִּהְיוּ יְתוֹמִים בְּלִי אָב, בְּלִי חָכָם מוֹרֶה, וְלֹא תַּלְמִיד הוֹגֶה. וְיָמִים יָבוֹאוּ, שֶׁכָּל הַדּוֹר יִהְיוּ חֲצוּפִים וְעַזִּי פָנִים, וְתִשְׁתַּכַּח תּוֹרָה, וְאֵין דּוֹרֵשׁ וְאֵין מְבַקֵּשׁ. וְהַמִּתְעוֹרֵר לִבּוֹ בַּתּוֹרָה, יִהְיֶה נִבְזֶה וַחֲדַל אִישִׁים, וַוי לְדָרָא הַהוּא כַּד יֵיתֵי הַהוּא דָרָא.</p>"],[9514011329,"<p>אָמַר לֵיהּ לֵית הַהוּא דָרָא מִתְקַיִּים, אֶלָּא בְּהֶבֶל פִּיהֶם שֶׁל תִּינוֹקוֹת שֶׁל בֵּית רַבָּן, כַּד אִינוּן רְכִיכִין בִּלְבָד, וְכַד אִינוּן קְשִׁישִׁין, אוֹרַיְיתָא מִשְׁתַּכְּחַת מִנְּהוֹן. כִּי הָא דְאָמַר רִבִּי יְהוּדָה, מַאי דִכְתִיב, (שמואל א א׳:כ״ז) אֶל הַנַּעַר הַזֶּה הִתְפַּלָּלְתִּי, הֲוָה לֵיהּ לְמֵימַר אֶל הַבֵּן הַזֶּה הִתְפַּלָּלְתִּי. אֶלָּא אָמְרָה חַנָּה, יְהִי רָצוֹן, שֶׁבְּשָׁעָה שֶׁיִּגְדַּל יִשְׁתַּדֵּל בַּעֲבוֹדַת הַמָּקוֹם, כְּמוֹ עַכְשָׁיו שֶׁהוּא נָעַר.</p>"],[9514011330,"<p>וְכָל אָדָם שֶׁיִּזְכֶּה לִהְיוֹת בְּזִקְנוּתוֹ כְּמוֹ בְּנַעֲרוּתוֹ, יִזְכֶּה לְמַעֲלַת שְׁמוּאֵל הַנָּבִיא, דִּכְתִיב (שם ב) וּמְעִיל קָטָן תַּעֲשֶׂה לוֹ אִמּוֹ וְהֶעֶלְתָה לוֹ מִיָּמִים יָמִימָה. וְכִי תַעֲלֶה עַל דַּעְתְּךָ כָּךְ, אֶלָּא צִדְקָתוֹ וּזְכוּתוֹ הָיָה גָּדֵל עִמּוֹ תָּמִיד, כִּתְפִלַּת אִמּוֹ. וּלְדַעְתֵּיהּ דְּר' יְהוּדָה, מְעִיל מַמָּשׁ הוּא.</p>"],[9514011331,"<p>וְאָמַר רַבִּי, מַאי דִכְתִיב, (ויקרא י״ט:ל״ב) מִפְּנֵי שֵׂיבָה תָּקוּם וְהָדַרְתָּ פְּנֵי זָקֵן. אָמַר רַבִּי, בּוֹ הוּא מוּסָר לְיָנִיקָא, כְּלוֹמַר מִפְּנֵי שֵׂיבָה תָּקוּם, קוֹדֶם שֶׁתַּעֲלֶה לְשֵׂיבָה וּלְזִקְנָה, תָּקוּם לִהְיוֹת טוֹב. וְכַאֲשֶׁר תִּשְׁתַּדֵּל לִהְיוֹת טוֹב בְּבַחֲרוּתֶיךָ, לְאַחַר כֵּן וְהָדַרְתָּ פְּנֵי זָקֵן. וְסֵיפָא דְהַאי פְּסוּקָא מוֹכִיחַ עָלָיו, שֶׁעַל זֶה נֶאֱמַר, מַשְׁמַע דִּכְתִיב וְיָרֵאתָ מֵאֱלֹהֶיךָ.</p>"],[9514011332,"<p>רַבִּי יִצְחָק אָמַר תְּחִלַּת כָּל הָעוֹלָם וּבִנְיָינוֹ, לֹא נִבְרָא אֶלָּא עַל הַיִּרְאָה, לִהְיוֹת אָדָם בַּעַל יִרְאָה לַשָּׁמַיִם, וּבַעַל יִרְאָה לַבְּרִיּוֹת, מִדִּכְתִיב (בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. אֵת הַשָּׁמַיִם, לִהְיוֹת יָרֵא לַשָּׁמַיִם. וְאֵת הָאָרֶץ, לִהְיוֹת יָרֵא לַבְּרִיּוֹת. כְּמוֹ כֵן מְלַמֵּד, שֶׁכָּל הָעוֹלָם לֹא נִבְרָא אֶלָּא עַל הַיִּרְאָה, שֶׁנִּקְרֵאת רֵאשִׁית, שֶׁנֶּאֱמַר (תהילים קי״א:י׳) רֵאשִׁית חָכְמָה יִרְאַת ה', וְזֶהוּ דִּכְתִיב בְּרֵאשִׁית.</p>"],[9514011333,"<p>(בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. רַבִּי חִיָּיא פָּתַח, (תהילים צ״ז:י״א) אוֹר זָרוּעַ לַצַּדִּיק וּלְיִשְׁרֵי לֵב שִׂמְחָה. הַקָּדוֹשׁ בָּרוּךְ הוּא רָאָה וְצָפָה, שֶׁהָעוֹלָם אֵינוֹ יָכוֹל לַעֲמֹד בִּלְתִּי הַיְסוֹד, וְאֵיזֶהוּ הַיְסוֹד שֶׁהָעוֹלָם עוֹמֵד עָלָיו, הוּא הַצַּדִּיק, שֶׁנֶּאֱמַר (משלי י׳:כ״ה) וְצַדִּיק יְסוֹד עוֹלָם. וְזֶהוּ יְסוֹד הָרִאשׁוֹן שֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא בְּעוֹלָמוֹ. וְהוּא נִקְרָא אוֹר, שֶׁנֶּאֱמַר אוֹר זָרוּעַ לַצַּדִּיק. וְעוֹד, מִמַּה דִּכְתִיב, וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. נֶאֱמַר כָּאן כִּי טוֹב, וְנֶאֱמַר לְהַלָּן (ישעיהו ג׳:י׳) אִמְרוּ צַדִּיק כִּי טוֹב.</p>"],[9514011334,"<p>רַבִּי אוֹמֵר, זֶה הָאוֹר, אוֹר הַמַּלְאָכִים, הוּא שֶׁנִּבְרְאוּ תְּחִלָּה קֹדֶם כָּל הָעוֹלָם. וְאִי תֵימָא וַהֲרֵי אָנוּ רוֹאִים שֶׁהַשָּׁמַיִם וְהָאָרֶץ נִבְרְאוּ תְּחִלָּה. לֹא קַשְׁיָא, דְּהָא שֶׁנֶּאֱמַר לְמַעְלָה עַד כָּאן, סִפּוּר הוּא דְּאָמַר. אֶלָּא זֶה וַיְהִי, הוּא הָרִאשׁוֹן, וּמִכָּאן הִתְחִילוּ כָּל הַנִּבְרָאִים.</p>"],[9514011335,"<p>ר' יְהוּדָה אוֹמֵר, זֶהוּ אוֹר הַכִּסֵּא מַמָּשׁ. וּמִזֶּה הָאוֹר, נִבְרְאוּ שְׁאָר כָּל הַנִּבְרָאִים. מִמֶּנּוּ נִבְרְאוּ הַשָּׁמַיִם, וְכִסֵּא נִבְרָא בַּתְּחִלָּה, שֶׁנֶּאֱמַר (ירמיהו י״ז:י״ב) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן.</p>"],[9514011336,"<p>רַבִּי אֱלִיעֶזֶר הַגָּדוֹל אוֹמֵר, אוֹר הַמַּלְאָכִים נִבְרָא בַּתְּחִלָּה. דִּכְתִיב, וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב וַיַּבְדֵּל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחשֶׁךְ. כְּלוֹמַר, הַבְדָּלָה נָתַן הַקָדוֹשׁ בָּרוּךְ הוּא יִתְבָּרַךְ, בֵּין זֶה הָאוֹר, וּבֵין הַחוֹשֶׁךְ, שֶׁהוּא הָעוֹלָם הַזֶּה. וְהַשָּׁמַיִם הֵם הַמַּבְדִּילִים בֵּין הָעוֹלָם הַזֶּה, וּבֵין אוֹר הַמַּלְאָכִים, וְהֵם הַמַּבְדִּילִים בֵּינְתַיִם, בֵּין הָאוֹר וּבֵין הַחשֶׁךְ.</p>"],[9514011337,"<p>רַבָּן יוֹחָנָן בֶּן זַכַּאי אוֹמֵר, נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא מֶמְשָׁלָה לַמַּלְאָכִים עַל הַשָּׁמַיִם, וְהַשָּׁמַיִם עַל הָאָרֶץ. וְכֻלָּם נִתְלִים בְּכִסְּאוֹ יִתְבָּרַךְ שְׁמוֹ, לְהוֹרוֹת כִּי גָּבוֹהַּ מֵעַל גָּבוֹהַּ שׁוֹמֵר.</p>"],[9514011338,"<p>(בראשית א׳:ג׳) יְהִי אוֹר. רַבִּי אֲלֶכְּסַנְדְּרָאי אוֹמֵר, הָרוֹאֶה הַכּוֹכָבִים בִּמְסִלּוֹתָם חַיָּיב לְבָרֵךְ. מַאי מְבָרֵךְ, בָּרוּךְ הַמְסַדֵּר אֶת הַכּוֹכָבִים בָּרָקִיעַ. רָאָה כּוֹכָב אֶחָד, אֵינוֹ מְבָרֵךְ. שְׁנַיִם, מְבָרֵךְ. וְאֵימָתַי, כַּד הֲוֵי לֵילְיָא, מְבָרְכִין בָּרוּךְ הַמַּעֲרִיב עֲרָבִים. רַבִּי אוֹמֵר אִלֵּין כּוּפְרָנֵי אֲדַקִּיקַיָיא, דְּאוֹרְחַתְהוֹן מִסְתַּלְּקִין עַל הַהוּא יְמָמָא, מִדְּחִילוּ דְּחַיּוּתָא, מְבָרְכִין שׁוֹמֵר עַמּוֹ לָעַד. וּלְפִיכָךְ תִּקְנוּ עַל דֶּרֶךְ זֶה כָּל תְּפִלַּת הָעַרְבִית.</p>"],[9514011339,"<p>ר' אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן, אָזַל לְמֶחֱמֵי לְר' יוֹסֵי בְּר' שִׁמְעוֹן בֶּן לָקוֹנְיָיא חָמוֹי. סָמוּךְ לְקִרְיָיתָא, רָמַשׁ לֵילְיָא. אֲמַר לְר' יוֹסֵי דְּהֲוָה אָזִיל עִמֵּיהּ, חָמִית אִלֵּין כּוֹכְבַיָא דִּנְהִירִין. אֲמַר חָמֵי אֲנָא דָא כּוֹכְבָא דְּשַׁרְבִיטָא עִידְנָא סַגִּיאָה הוּא דַּאֲנָא מַשְׁגַּחְנָא בֵּיהּ, וּמִן יוֹמָאי לָא אֲמָרוּ לִי עַל דָּא כְּלוּם.</p>"],[9514011340,"<p>אָמַר לֵיהּ תְּרֵי עִנְיָינֵי שְׁמַעְנָא. חָדָא הִיא, דְּכָל מַה דַּעֲבַד קוּדְשָׁא בְּרִיךְ הוּא בֵּין שְׁמַיָא, וְכוֹכְבַיָא וּמַזָּלַיָא, אִית בְּהוּ יְדִיעָא וְסוּכְלְתָנוּ. וְכָלְהוֹן עָבְדֵי שְׁלִיחוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא. וְהַאי כּוֹכְבָא דְּאַתְּ אֲמַרְתְּ, לָא תֵימָא וְלָא תִיסַק עַל דַּעְתָּךְ דְּחַד הוּא, אֶלָּא סַגִּיאִין אִינוּן, דְּחַד תֶּחֱמֵי בְּהַאי גִיסָא, וְחַד בְּהַאי גִיסָא, וְזִמְנִין דְּכָלְהוֹן בְּחַד שַׁעֲתָא.</p>"],[9514011341,"<p>וַאֲנָא שְׁמַעְנָא מֵאַבָּא, דְּשֶׁבַע אִינוּן. וּבְזִמְנָא דְּמָטָא עִידָנָא דְּכָל חַד מִנְּהוֹן לְמֵימַר שִׁירָתָא, מִסְּגִיאוּת חֶדְוָותָא דְּאִית בְּהוֹן, שָׁלְחִין זִיוַותְהוֹן וְאָזְלִין לְמֵימַר שִׁירָתָא.</p>"],[9514011342,"<p>וְעִנְיָנָא אַחֲרִינָא, דְּאִלֵּין שֶׁבַע כּוֹכְבַיָא, לָא אָזְלִין וְלָא נָטְלִין מֵאַתְרֵיהוֹן, בַּר בְּעִידָנָא דְּקָרֵי לְחַד מִנְּהוֹן רִבּוֹן עָלְמָא לְמִנְהַר בַּאֲתַר דְּהוּא צָבֵי. דִּכְתִיב, (ישעיהו מ׳:כ״ו) לְכֻלָּם בְּשֵׁם יִקְרָא. וְכַד נָטְלִין, שָׁלְחִין זִיוַתְהוֹן עִמְּהוֹן לְמֵיזַל.</p>"],[9514011343,"<p>כַד מָטוֹ לְבֵי חָמוֹי, לָא הֲוָה תַּמָּן. כַּד אָתָא, אֲמַר אַתְּ הָכָא, וַאֲנָא אָתֵי לְמֶחֱמֵי חַד כּוֹכָבָא, דְּהֲוָה אָזִיל לְמִשְׁלַם רְעוּתֵיהּ דְּמָארֵיהּ. אָמַר לֵיהּ, מַאי הוּא. אָמַר לֵיהּ, כּוֹכָבָא דְּשָׁבִיט. וְחַד מִנְהוֹן חָמִית, דְּהֲוָה אָזִיל לְפִיקּוּדַיָא דְּמָארֵיהּ. יָתְבוּ תַּמָּן תְּלָתִין יוֹמִין.</p>"],[9514011344,"<p>לְבָתַר כֵּן אַשְׁכִּימוּ לְמֵיזַל, כַּד הֲוָה אָתֵי נְהוֹרָא, וְאָזִיל עִמֵיהּ חָמוֹי כְּפַלְּגוּת מִיל. בָּרְכֵיהּ חָמוֹי, אֲמַר דָּא הִיא שַׁעֲתָא דְּמִתְקַיֵּים בִּרְכְּתָא דְצַדִּיקַיָא. מְנָא לָן, דִּכְתִיב (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. כְּתִיב הָכָא כִּי טוֹב, וּכְתִיב הָתָם (במדבר כ״ד:א׳) כִּי טוֹב בְּעֵינֵי ה' לְבָרֵךְ אֶת יִשְׂרָאֵל. אָמַר לֵיהּ, אֲפִילּוּ בִּרְכְּתָא דְּכָל אָדָם, מִתְקַיְּימָא בְּהַאי שַׁעֲתָא, דִּשְׁמַיָא וְכוֹכְבַיָא וּמַלְאָכַיָא אָמְרֵי שִׁירָתָא.</p>"],[9514011345,"<p>וְעוֹד שְׁמַעְנָא מֵאַבָּא, דְּבִרְכְּתָא יְתֵירָא הוֹסָפַת לֵיהּ, וְדָא הִיא חֶדְוָותָא. מִשּׁוּם דְּהַאי שַׁעֲתָא אָמְרֵי שְׁמַיָא, וְהוּא כְּחָתָן יוֹצֵא מֵחֻפָּתוֹ. מַה הַחָתָן כְּשֶׁיּוֹצֵא יָשִׂישׂ, כָּךְ הַיּוֹצֵא לַדֶּרֶךְ יָשִׂי\"שׂ בְּהַא\"י שַׁעֲתָ\"א.</p>"],[9514011346,"<p>(בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר. תַּמָּן תָּנִינָן, אָמַר רִבִּי יוֹסֵי, מַהוּ דִּכְתִּיב, (ישעיהו כ״א:י״א) מַשָּׂא דּוּמָה אֵלַי קֹרֵא מִשֵּׂעִיר שֹׁמֵר מַה מִּלַּיְלָה שֹׁמֵר מַה מִּלֵּיל וְגו'. אָזְלָא הָא מִלְּתָא, כִּי הָא דְאָמַר רִבִּי יוֹחָנָן, כָּל הַגָּלֻיּוֹת שֶׁגָּלוּ יִשְׂרָאֵל מֵאַרְצָם, כָּלְהוֹ הָיָה גָּלוּי לַכֹּל, וְגָלוּתָא רְבִיעָאָה, לֹא נִגְלָה לְעוֹלָם, וְאֵיזֶהוּ גָּלוּת הָרְבִיעִי. זֶהוּ שֶׁהוּא מִשֵּׂעִיר, שֶׁהוּא עֵשָׂו, דִּכְתִיב (בראשית ל״ו:ח׳) וַיֵּשֶׁב עֵשָׂו בְּהַר שֵׂעִיר.</p>"],[9514011347,"<p>אָמַר רַבִּי לָמָּה נִקְרָא שְׁמוֹ שֵׂעִיר. עַל שֵׁם תּוֹקֶף וְחוֹזֶק, הָעוֹל הַכָּבֵד, שֶׁמּוֹנְעִין מֵהֶם הַתּוֹרָה וְהָעֲבוֹדָה, וְזֶהוּ עוֹל עַל נִשְׁמָתָם שֶׁנּוֹתְנִין עַל יִשְׂרָאֵל. שֵׂעִי\"ר הוּא תֹּקֶ\"ף בְּגימ'. וְזֶהוּ הַגָּלוּת שֶׁיִּשְׂרָאֵל יוֹשְׁבִים בָּהּ, הִיא מַשָּׂא דּוּמָה. כְּלוֹמַר, בַּחֲשַׁאי. דָּבָר שֶׁלֹּא נִגְלָה מֵהַלֵּב לַפֶּה.</p>"],[9514011348,"<p>רַבִּי יִצְחָק פָּתַח, וַיִּקְבֹּר אֹתוֹ בַגַּי בְּאֶרֶץ מוֹאָב מוּל בֵּית פְּעוֹר. וּכְתִיב (דברים ל״ד:ו׳) וְלֹא יָדַע אִישׁ אֶת קְבוּרָתוֹ עַד הַיּוֹם הַזֶּה. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, שׁוֹטִים הֵם הַמְחַשְּׁבִים קִצֵּי מְשִׁיחָא, דָּבָר שֶׁלּא גִלִּיתִי לָעוֹלָם, שֶׁנֶּאֱמַר (ישעיהו ס״ג:ד׳) כִּי יוֹם נָקָם בְּלִבִּי, לִבָּא לְפוּמָא לָא גַלְיָא, וְאִינוּן מִשְׁתַּדְּלֵי לְמֶחֱשַׁב קִצִּי.</p>"],[9514011349,"<p>בְּהַאי, נֶחֱזֵי תְּלָתָא סִימָנֵי, כְּתָבִית וַאֲחֵזִית לְדָרֵי עָלְמָא, בִּקְבוּרְתֵּיהּ דְּמשֶׁה עָבְדֵי. וְאִלֵּין אִינוּן בַּגַּיא, בְּאֶרֶץ מוֹאָב, מוּל בֵּית פְּעוֹר. אֲחֵזִית, וִיהָבִית סִימָנִים לְכָלְהוֹן דְּעָלְמָא, וְלָא יָדְעֵי קְבוּרְתֵּיהּ, דִּכְתִיב וְלֹא יָדַע אִישׁ אֶת קְבוּרָתוֹ. דָּבָר שֶׁלֹּא גִּלִּיתִי וְלֹא הֶרְאֵיתִי, הֵיאָךְ אָמְרֵי שְׁטוּתָא וְשִׁקְרוּתָא קָמֵּי קוּדְשָׁא בְּרִיךְ הוּא בְּהַךְ.</p>"],[9514011350,"<p>הֲדָא הוּא דִכְתִיב, (ישעיהו כ״א:י״א) מַשָּׂא דּוּמָה אֵלַי קוֹרֵא מִשֵּׂעִיר, אֵלּוּ יִשְׂרָאֵל, שֶׁקּוֹרְאִין לְהַקָּדוֹשׁ בָּרוּךְ הוּא, מֵעוֹל כָּבֵד שֶׁל בְּנֵי שֵׂעִיר. וּמַאי אָמְרֵי, (ישעיהו כ״א:י״א) שֹׁמֵר מַה מִּלַּיְלָה וְגו'. רְצוֹנוֹ לֹאמָר, רִבּוֹנוֹ שֶׁל עוֹלָם אַתָּה הוּא שׁוֹמֵר יִשְׂרָאֵל ה'. עַד מָתַי אָנוּ בָּזֶה הַגָּלוּת שֶׁדּוֹמֶה לְלַיְלָה, אֱמוֹר לָנוּ, מַה מִּלַּיְלָה, מַה תְּהֵא מִזּוֹ הַלַּילָה, אֵימָתַי תּוֹצִיאֵנוּ מִמֶּנָּהּ.</p>"],[9514011351,"<p>בֹּא וּרְאֵה מַאי דִּכְתִיב בַּתְרֵיהּ, (שם) אָמַר שֹׁמֵר אָתָא בֹקֶר וְגַם לָיְלָה, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר יִשְׂרָאֵל, אָתָא בֹקֶר, הֵבֵאתִי וְהוֹצֵאתִי אֶתְכֶם מִן הַגָּלוּת, וְלֹא זְכִיתֶם לִהְיוֹת בַּבֹּקֶר, וְגַם לָיְלָה, הֵבֵאתִי לָכֶם הַלָּיְלָה וְהֶאֱפַלְתִּי אֶתְכֶם בְּבוֹר הַגָּלוּת הַזֶּה שֶׁהוּא כַּלַּיְלָה. אִם תִּבְעָיוּן בָּעְיוּ, אִם אַתֶּם מְבַקְּשִׁים לָדַעַת קֵץ גְאוּלַּתְכֶם אֵימָתַי תִּהְיֶה, וְאֵימָתַי תָּבוֹאוּ לְאַרְצְכֶם. שׁוּבוּ אָתָיוּ. כִּי הָא דְאָמַר רִבִּי יְהוּדָה, אֵין קֵץ הַגָּלוּת נִתְלָה אֶלָּא בִּתְשׁוּבָה, שֶׁנֶּאֱמַר (תהילים צ״ה:ז׳) הַיּוֹם אִם בְּקוֹלוֹ תִשְׁמָעוּ.</p>"],[9514011352,"<p>וְכֵיוָן שֶׁנִּבְרָא הָעוֹלָם, נִרְמַז הָרֶמֶז הַגָּדוֹל הַזֶּה, בְּרָזֵי הַסְּתָרִים, שֶׁנֶּאֱמַר (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. כְּלוֹמַר, יְהִי רָז. וְרָז וְאוֹר, דָּבָר אֶחָד הוּא. וַיַּרְא אֱלֹהִים לָזֶה הָרָז, כִּי טוֹב לִהְיוֹת בְּרָז וְסוֹד, כְּדֵי שֶׁלֹּא יִתְגַּלֶּה לְשׁוּם אָדָם, שֶׁאִלְמָלֵי יִתְגַּלֶּה, כַּמָּה פְּרִיצִים מִבְּנֵי עַמֵּנוּ יֵלְכוּ לַאֲבַדּוֹן.</p>"],[9514011353,"<p>וְעַל שֶׁהָיָה בְּרָזָא וְסוֹד, הִבְדִּיל אֱלֹהִים בֵּין הָאוֹר וּבֵין הַחשֶׁךְ, בֵּין אוּמָּתוֹ שֶׁהוּא הָאוֹר. וּבֵין הָאוּמּוֹת שֶׁהֵם הַחשֶׁךְ. שֶׁנֶּאֱמַר (שמואל א ב׳:ט׳) וּרְשָׁעִים בַּחשֶׁךְ יִדַּמּוּ. וְעוֹד כְּתִיב, (תהלים פב) בַּחֲשֵׁכָה יִתְהַלָּכוּ. (בראשית א׳:ה׳) וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם. אָמַר רִבִּי, זֶה יוֹם קֵץ הַגְּאוּלָּה. שֶׁנֶּאֱמַר (זכריה י״ד:א׳) הִנֵּה יוֹם בָּא לַה', זֶה יוֹם הַקֵּץ.</p>"],[9514011354,"<p>ר' יוֹסֵי בֶּן חֲלַפְתָּא, הֲוָה יָתֵיב קַמֵּיהּ דְּר' יִצְחָק, אָמַר לֵיהּ מִידֵי שְׁמִיעַ לֵיהּ לְמַר, עַל מָה אִתְאֲרַךְ יוֹמָא דִמְשִׁיחָא מִן גָּלוּתָא דָא. אָמַר לֵיהּ, לָא אִתְאֲרַךְ אֶלָּא עַל בִּיטוּל אוֹרַיְיתָא. דְּהָכֵי שְׁמַעְנָא מֵרַב הַמְנוּנָא סָבָא, תְּלָתָא גָּלֻיּוֹת גָּלוּ יִשְׂרָאֵל, וְחָזְרוּ בִּזְכוּתְהוֹן דִּתְלָתָא אָבוֹת. וְגָלוּתָא רְבִיעָאָה בִּזְכוּתָא דְמשֶׁה יִתְחַזְּרוּן.</p>"],[9514011355,"<p>תָּא וְאַחֲזֵי לָךְ, לָא אִיתְגָּלוּ יִשְׂרָאֵל אֶלָּא עַל בִּיטוּל תּוֹרָה. שֶׁנֶּאֱמַר (ירמיהו ט׳:י״ב) וַיֹּאמֶר ה' עַל עָזְבָם אֶת תּוֹרָתִי. אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, בַּגָּלֻיּוֹת הָרִאשׁוֹנוֹת, חָזְרוּ בִּזְכוּת אַבְרָהָם יִצְחָק וְיַעֲקֹב, עַכְשָׁיו, הֵם חָטְאוּ בַּתּוֹרָה שֶׁנָּתַתִּי לְמשֶׁה, וְנִקְרֵאת עַל שְׁמוֹ, שֶׁנֶּאֱמַר (מלאכי ג׳:כ״ב) זִכְרוּ תּוֹרַת משֶׁה עַבְדִּי. כַּד יְתוּבִין וְיִתְעַסְּקוּן בְּתוֹרָתוֹ, בִּזְכוּת משֶׁה אֲנִי גּוֹאֲלָם.</p>"],[9514011356,"<p>עַל כֵּן נֶאֱמַר בַּתּוֹרָה, (דברים ל״ג:ד׳) תּוֹרָה צִוָּה לָנוּ משֶׁה, כְּדֵי לְשָׁמְרָהּ וְלַעֲסוֹק בָּהּ. וְאִם לָאו, מוֹרָשָׁה קְהִלַּת יַעֲקֹב, מוֹרָשָׁה: דָּא מִסְכְּנוּתָא הוּא. כְּמָה דְאַתְּ אָמֵר (שמואל א ב׳:ז׳) ה' מוֹרִישׁ וּמַעֲשִׁיר, מְלַמֵּד דְּלָא אַתְיָא מִסְכְּנוּתָא לִבְרַתֵּיהּ דְּיַעֲקֹב, אֶלָּא עַל דְּלָא אִתְעַסְּקוּ בְּפִיקּוּדִין דְּאוֹרַיְיתָא.</p>"],[9514011357,"<p>רַבִּי חִזְקִיָּה אֲמַר, אֲנָא הֲוֵית בְּאַתְרֵיהוֹן דְּעַרְבִיָא, וַחֲמֵית גּוּבְרִין דַּהֲווֹ מִתְטַמְּרִין בֵּינֵי טוּרַיָא, בִּמְעַרְתָּא, וַאֲתוֹ מֵעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת לְבָתֵּיהוֹן. אֲמָרִית לְהוֹן, מָה דֵין דְּאַתּוּן עָבְדִין. אֲמָרוּ לִי, פְּרִישֵׁי עָלְמָא אֲנַן, וּמִתְעַסְּקָן בְּאוֹרַיְיתָא כָּל יוֹמָא וְיוֹמָא, וְזִמְנִין לֵית אֲנַן אָכְלִין בַּר מֵעִשְׂבֵּי בָּרָא.</p>"],[9514011358,"<p>אֲמָרִית לְהוֹן, וּשְׁאָר זִמְנִין בַּמָּה אַתּוּן מִתְפַּרְנְסִין. אֲמָרוּ לִי, אֲנַן אַשְׁכְּחָן בְּמַדְבְּרָא אָעַיָּיא דְּמַצְמִיחִים בּאלוד, וַאֲנַן אָכְלִין יַתְהוֹן. כַּד נְהִירָא לָן שְׁמַעְתָּא, מִסְגִּיאוּת חֶדְוָותָא, מִשְׁתַּמְטֵי חַד מִינָן, וּמְבַשְּׁלִין לְהוֹן וְאָכְלִינָן. וְיוֹמָא הַהוּא חָשִׁיב לָן דְּהוּא כִּי טוֹב. וּבְזִמְנָא דְּלָא צָמְחֵי אִינוּן אָעַיָּיא, אֲנַן אָכְלִין עִשְׂבִּין דְּמַשְׁכַּחְנָא, וּמְבַשְּׁלֵי לְהוֹן וְאָכְלִינָן.</p>"],[9514011359,"<p>אֲמָרִית לְהוֹן, תְּהִי חֶלְקִי עִמְּכוֹן לְעָלְמָא דְאָתֵי. אַשְׁרֵיכֶם בָּעוֹלָם הַזֶּה, וְטוֹב לָכֶם לָעוֹלָם הַבָּא. כְּעָן יָדַעְנָא דְּלָא תֶהֱווֹן בְּכִיסּוּפָא, כַּד יֵיתֵי משֶׁה לְמִתְבַּע עוּלְבָּנָא דְאוֹרַיְיתָא. אֲמָרִית לְהוֹן, בָּנַי, חַיֵּיכוֹן, יוֹמָא דָא מַה חִידּוּשׁ אִתְחַדֵּשׁ לְכוֹן.</p>"],[9514011360,"<p>אֲמָרוּ לִי, הַאי פְּסוּקָא (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. וְתָאנֵי רַבִּי כְּרוּסְפְּדָאי, גָּדוֹל הַתּוֹסֶפֶת מֵהָאוֹר. שֶׁהָיָה אוֹר שֶׁלֹּא הָיָה כָּמוֹהוּ, זֶה הוּא אוֹר הַשֵּׂכֶל הַגָּדוֹל, שֶׁנִּתְהַוָּה מֵאוֹר זִיו הוֹדוֹ, וְזֶהוּ הָעוֹמֵד מֵאֲחוֹרֵי הַפַּרְגּוֹד.</p>"],[9514011361,"<p>דְּתָנִינָן, מַאי דִכְתִיב, (תהילים ק״ד:ב׳) עוֹטֶה אוֹר כַּשַּׂלְמָה, מְלַמֵּד שֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא שְׁאָר הַמַלְאָכִים, בְּאוֹתוֹ הָאוֹר הָרִאשׁוֹן, מֵאוֹתוֹ הָאוֹר מַמָּשׁ. סַלְּקָא דַּעְתָּךְ כָּמוֹהוּ. אֶלָּא מַה הוּא דָּבָר מוּבְדָּל וּמוּשְׂכָּל, כָּךְ שְׁאָר הַמַּלְאָכִים דְּבָרִים מוּבְדָּלִים וּמוּשְׂכָּלִים. אֲבָל אֵין הַשָּׂגָתָם כְּהַשָּׂגָתוֹ. דְּתָאנֵי ר' כְּרוּסְפְּדָאי, הַשָּׂגַת הַמַּלְאָכִים הִיא הַשָּׂגָה גְדוֹלָה, מַה שֶּׁאֵין כֵּן לְמַטָה מֵהֶם.</p>"],[9514011362,"<p>הַשָּׂגָה שְׁנִיָה הִיא, הַשָּׂגַת הַשָּׁמַיִם, שֶׁמַּשִּׂיגִים הַשָּׂגָה, מַה שֶּׁלְּמַטָה מֵהֶם אֵין מַשִּׂיגִים כְּמוֹתָם. הַשָּׂגָה שְׁלִישִׁית, הִיא הַשָּׂגַת הַמַּדְרֵגָה הַתַּחְתּוֹנָה אֲשֶׁר מֵעָפָר יְסוֹדָהּ, וְהִיא הַשָּׂגַת בְּנֵי אָדָם, מַה שֶּׁאֵין מַשִּׂיגִין שְׁאָר הַנִּבְרָאִים.</p>"],[9514011363,"<p>וּכְנֶגֶה שָׁלשׁ מַעֲלוֹת הַלָּלוּ, יֵשׁ בָּאָדָם שָׁלשׁ צוּרוֹת נַפְשִׁיּוֹת. צוּרָה הָרִאשׁוֹנָה הִיא הַנֶּפֶשׁ הַשִּׂכְלִית. הַשְּׁנִיָה, הִיא הַנֶּפֶשׁ הַמְדַבֶּרֶת. הַשְּׁלִישִׁית, הִיא הַנֶּפֶשׁ הַבַּהֲמִית, הַמִּתְאַוֵּת תַּאֲוֹת, וְהִיא הַנֶּפֶשׁ אֲשֶׁר תִּמְעוֹל מַעַל.</p>"],[9514011364,"<p>וְאִיתֵימָא הָכֵי, הַנֶּפֶשׁ הָרִאשׁוֹנָה הִיא נֶפֶשׁ הַבַּהֲמִית, כְּנֶגֶד הַמַּדְרֵגָה הַתַּחְתּוֹנָה שֶׁאָמַרְנוּ. נֶפֶשׁ הַמְדַבֶּרֶת, כְּנֶגֶד הַשָּׁמַיִם, שֶׁהִיא מַעֲלָה יְתֵירָה עַל הָרִאשׁוֹנָה. נֶפֶשׁ הַשִּׂכְלִית, כְּנֶגֶד מַדְרֵגַת הַמַּלְאָכִים, שֶׁהִיא הַמַּעֲלָה הָעֶלְיוֹנָה עַל כָּל אֵלֶּה.</p>"],[9514011365,"<p>(בראשית א׳:ו׳) וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם. ר' אֶלְעָזָר פָּתַח, (תהילים ס״ג:ב׳) אֱלֹהִים אֵלִי אַתָּה אֲשַׁחֲרֶךָֹּ, תָּא חֲזֵי, שֶׁאֵין מָקוֹם בָּעוֹלָם פָּנוּי בְּלֹא מַיִם, מִפְּנֵי שֶׁהָאָרֶץ תְּלוּיָה עַל הַמָּיִם. שֶׁנֶּאֱמַר, (שם כד) כִּי הוּא עַל יַמִּים יְסָדָהּ וְעַל נְהָרוֹת יְכוֹנְנֶהָ. וְכִי תַעֲלֶה עַל דַּעְתְּךָ, שֶׁהַמַּיִם הֵם מִתַּחַת לָאָרֶץ, וְהָאָרֶץ שֶׁהִיא כְּבֵדָה מִכָּל הַיְסוֹדוֹת עוֹמְדוֹת עַל הַמָּיִם. אֶלָּא שֶׁהַמַּיִם עַל הָאָרֶץ, וּלְמַעְלָה לַשָּׁמָיִם.</p>"],[9514011366,"<p>אָמַר לֵיהּ רַב חִסְדָּא וְהָא כְתִיב הַמַּיִם אֲשֶׁר מֵעַל לָרָקִיעַ. אָמַר לֵיהּ, לָאו הַאי, אֶלָּא כְּתַרְגּוּמוֹ, בִּמְצִיעוּת מַיָא, שֶׁהָרָקִיעַ מַבְדִּיל בֵּינֵיהֶם. כִּי הַמַּיִם אֲחָדִים הָיוּ, אֲבָל מִפְּנֵי שֶׁנִּכְנַס הָרָקִיעַ בָּאֶמְצַע, נֶחְשְׁבוּ כִּשְׁנַיִם. וְהָרָקִיעַ כַּדּוּר, וּבָא בְּמֵימֵי אוֹקְיָינוּס, כְּמַבְדִּיל בֵּין הַמַּיִם, נִמְצְאוּ מַיִם מִמַּעַל, וּמַיִם מִתָּחַת.</p>"],[9514011367,"<p>אָמַר רִבִּי יְהוּדָה, רְקִיעִים הֵם הַסּוֹבְבִים, לִפְעָמִים מִמִּזְרָח לְמַעֲרָב, וְלִפְעָמִים מִמַעֲרָב לְמִזְרָח, וּבָאִים בְּאֶמְצַע הַיָּם, וּמַבְדִּילִים בֵּינְתַיִם. וְזֶהוּ וַיַּבְדֵּל בֵּין הַמָּיִם.</p>"],[9514011368,"<p>וּמִפְּנֵי מָה מֵי הַיָּם מְלוּחִים. מִפְּנֵי חֲמִימוּת הָרָקִיעַ וּרְתִיחָתוֹ. בֹּא וּרְאֵה, קְדֵירָה הָעוֹמֶדֶת עַל הָאוּר, וְכָל מַה שֶּׁמִּתְעַכֶּבֶת עַל הָאוּר, יוֹתֵר הַתַּבְשִׁיל נִמְלַח מֵרוֹב חֲמִימוּת הָאֵשׁ. וְאָמַר רִבִּי יְהוּדָה אִלְמָלֵא הָרָקִיעַ הָיָה קַיָּים בֵּין הַמַּיִם, כָּל הַמַּיִם הָיוּ נִקְפָּאִים כַּמֶּלַח, אֶלָּא הוֹלֵךְ וְסוֹבֵב וְאֵינוֹ מִתְקַיִּים בֵּין הַמַּיִם.</p>"],[9514011369,"<p>אר\"י, בֹּא וּרְאֵה לָמָּה לֹא נֶאֱמַר כִּי טוֹב בַּשֵּׁנִי. מִפְּנֵי שֶׁעִנְיַן זֶה חוֹזֵר עַל יִחוּדוֹ, לְהוֹרוֹת כִּי אֵין שֵׁנִי לְנֶגְדּוֹ, וְאֵין טוֹב בַּשֵּׁנִי, עַל כֵּן נֶאֱמַר בַּיּוֹם הָרִאשׁוֹן יוֹם אֶחָד.</p>"],[9514011370,"<p>דְּתָנֵי ר\"י, לָמָּה לֹא נֶאֱמַר רִאשׁוֹן בִּמְקוֹם אֶחָד. לְהוֹרוֹת, דְּאִלּוּ נֶאֱמַר רִאשׁוֹן, עַל כָּל פָּנִים הָיָה רָאוּי לִהְיוֹת שֵׁנִי. כִּי רִאשׁוֹן מָחֳרָת לְשֵׁנִי. אֲבָל אֶחָד, אֵינוֹ מָחֳרָת לְשֵׁנִי.</p>"],[9514011371,"<p>רַבִּי יְהוּדָה אוֹמֵר, וַהֲרֵי נֶאֱמַר (ישעיהו מ״א:ד׳) אֲנִי ה' רִאשׁוֹן. אָמַר לֵיהּ, מִלְתֵיהּ מְסַיֵּיעַ לְקַמַּיְיתָא, מִדִּכְתִיב וְאֶת אַחֲרוֹנִים אֲנִי הוּא, אַף עַל פִּי שֶׁיֵּשׁ אַחֲרוֹנִים לָרִאשׁוֹן, אֲנִי הוּא. וְכִי אַחֲרוֹנִים יֵשׁ לָרִאשׁוֹן. אֵין. שְׁמוֹ הַמְיוּחָד. שֶׁהוּא רֹאשׁ וּמְיוּחָד. אֲחֵרִים הֵם: אָלֶ\"ף דָּלֶ\"ת נוּ\"ן יוּ\"ד, אֱלֹהִי\"ם, שַׁדַּ\"י, אֵ\"ל, צְבָאוֹ\"ת. וְהֵם מִתְכַּנִּים בְּיִחוּדוֹ, וְהוּא הוּא יִתְבָּרַךְ מַמָּשׁ, דִּכְתִיב וְאֶת אַחֲרוֹנִים אֲנִי הוּא.</p>"],[9514011372,"<p>ר' יוֹסֵי בַּר חֲלַפְתָּא, וְר' יְהוּדָה בֶּן פַּזִּי, וְר' יִצְחָק, הֲווֹ אָכְלֵי בִּסְעוּדָתָא בְּהִילּוּלָא דְּרַבִּי אֶלְעָזָר בְּרַבִּי שִׁמְעוֹן. ר' חִיָיא רַבָּה, הֲוָה יְנוּקָא, וַהֲוָה יָתִיב תַּמָּן. אָמַר רִבִּי יוֹסֵי לְרַבִּי שִׁמְעוֹן, לָמָּה לֹא נֶאֱמַר כִּי טוֹב בַּשֵּׁנִי. אָמַר לֵיהּ, מִפְנֵי שֶׁלֹּא נִגְמְרָה הַמְלָאכָה בַּשֵּׁנִי, וּכְשֶׁנִּגְמְרָה בַּשְּׁלִישִׁי, אָמַר כִּי טוֹב תְּרֵי זִמְנִי.</p>"],[9514011373,"<p>אָמְרוּ, נִשְׁאַל לְהַאי יְנוּקָא, דְּמִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ נִמְצֵאת הַנְּבוּאָה בְּפִי הַתִּינוֹקּוֹת, אוּלַי נִמְצָא דָבָר בְּפִיו. אָמַר לֵיהּ חִיָּיא בְּרִי, אֵימָא לָן, לָמָּה לָא נֶאֱמַר כִּי טוֹב בַּשֵּׁנִי. אָמַר לָהֶם, מִפְּנֵי שֶׁאֵין טוֹב אֶלָּא בְּאֶחָד. אָתָא רַבִּי שִׁמְעוֹן וּנְשָׁקֵיהּ, קָרֵי עֲלֵיהּ (ירמיהו א׳:ט׳) הִנֵּה נָתַתִּי דְּבָרַי בְּפִיךָ.</p>"],[9514011374,"<p>אָמְרוּ שַׁעֲתָא קָיְימָא לֵיהּ, נִשְׁאַל בֵּיהּ, אָמְרוּ לֵיהּ, מַאי (שופטים ה׳:ל״א) וְאוֹהֲבָיו כְּצֵאת הַשֶּׁמֶשׁ בִּגְבוּרָתוֹ. מַה שֶּׁבַח הוּא זֶה לַצַּדִּיקִים. אָמַר לֵיהּ, מַה הַשֶּׁמֶשׁ כְּשֶׁיּוֹצֵא בִּגְבוּרָתוֹ, אִית דְּבַדְחֵי בֵּיהּ, וְאִית דְּלָא בַדְחֵי בֵּיהּ. כָּךְ הַצַּדִּיקִים, צַדִּיקִים כְּמוֹתָם, יָשִׂישׂוּ, וְהָרְשָׁעִים לֹא יָשִׂישׂוּ. אִית לְמַאן דְּעָבִיד רְפוּאָה, וְאִית לְמַאן דְּלָא עָבִיד. כָּךְ הַצַּדִּיקִים, יִהְיוּ רְפוּאָה לַטוֹבִים. וּמַכָּה לָרְשָׁעִים.</p>"],[9514011375,"<p>אָמְרוּ לֵיהּ, חִיָּיא בְּרִי, לָמָּה לֹא נִזְכַּר שֵׁם הַמְיוּחָד בְּמַעֲשֵׂה בְרֵאשִׁית, אָמַר לוֹן, אֵין נָאֶה לְמֶלֶךְ הַכָּבוֹד לְהַזְכִּיר שְׁמוֹ עַל הַמֵּתִים, וְעַל דָּבָר הַנֶּאֱבָד. כְּדֵי שֶׁלֹּא יֹאמְרוּ, כְּשֵׁם שֶׁכָּל הַבְּרִיּוֹת שֶׁבְּרָאָם הֵם כָּלִים וְנֶאֱבָדִים, כָּךְ שְׁמוֹ חַס וְשָׁלוֹם. וְלֹא הִזְכִּיר שְׁמוֹ הַמְיוּחָד, עַד שֶׁנִּבְרְאוּ כָּל הַבְּרִיּוֹת שֶׁהֵם כָּלִים וְנֶאֱבָדִים. וּלְאַחַר כֵּן, הִזְכִּיר שְׁמוֹ עַל דָּבָר שֶׁהוּא קַיָּים לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים, שֶׁנֶּאֱמַר (בראשית ב׳:ד׳-ה׳) בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם. וּמִשְּׁאָר כָּל הַבְּרִיּוֹת שֶׁבָּרָא לֹא הִזְכִּיר בְּכָאן, אֶלָּא דָּבָר הַקַּיָּים, וְלֹא נֶאֱמַר בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים, אֶרֶץ וְשָׁמָיִם אָדָם וְחַיּוֹת וּבְהֵמוֹת וְעוֹפוֹת, שֶׁהֵם דְּבָרִים כָּלִים, אֶלָּא דָּבָר הָעוֹמֵד לְעוֹלָם, וְהֵם אֶרֶץ וְשָׁמָיִם.</p>"],[9514011376,"<p>אָמְרוּ לֵיהּ, מַאי דִכְתִיב, (שם א) וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ וַיַּבְדֵּל בֵּין הַמַּיִם וְגו'. מַה צּוֹרֶךְ הָיָה לוֹ לְהַקָדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת רָקִיעַ לְהַבְדִּיל בֵּין הַמַּיִם. אָמַר לְהוּ, כְּבָר כְּתִיב (משלי ט״ז:ד׳) כֹּל פָּעַל ה' לַמַּעֲנֵהוּ. לֹא בָּרָא הַקָדוֹשׁ בָּרוּךְ הוּא דָּבָר שֶׁלֹּא לְצוֹרֶךְ. וּבָרָא הָרָקִיעַ, וּכְשֶׁהוּא חוֹזֵר אֵינוֹ חוֹזֵר אֶלָּא לְעִתִּים יְדוּעִים. וְסִילוֹן אֶחָד שֶׁל מַיִם יוֹצֵא מִתְּהוֹמוֹת, וְסִילוֹן שֶׁל מַיִם יוֹצֵא מִגֵּיהִנֹּם, וְיוֹרֵד בְּצִינוֹר לְסִילוֹן הַתְּהוֹם. הֲדָא הוּא דִכְתִיב, (תהילים מ״ב:ח׳) תְּהוֹם אֶל תְּהוֹם קוֹרֵא לְקוֹל צִנּוֹרֶיךָ. וְהָרָקִיעַ נִכְנַס בְּאֶמְצַע מִשְּׁנֵיהֶם. וְאִלְמָלֵא שֶׁנִּכְנַס בֵּנְתַיִם, הָיוּ הוֹרְגִים לְשׁוֹתֵיהֶם. הֲדָא הוּא דִכְתִיב, (בראשית א׳:ז׳) וַיַּבְדֵּל בֵּין הַמַּיִם אֲשֶׁר מִתַּחַת לָרָקִיעַ וּבֵין הַמַּיִם אֲשֶׁר מֵעַל לָרָקִיעַ.</p>"],[9514011377,"<p>אָמַר רִבִּי יוֹסֵי הַאי יְנוּקָא בְּרוּחַ הַקֹּדֶשׁ אֲמָרוֹ, דְּהָכֵי הַוְיָא מַמָּשׁ, דִּכְתִיב יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם, בְּתוֹךְ מַמָּשׁ, בְּאֶמְצָעִית מַיָיא. בְּהִכָּנֵס הָרָקִיעַ בָּאֶמְצַע, מַחֲזִיר הַמַּיִם הָרָעִים הַיּוֹצְאִים מִגֵּיהִנֹּם לִמְקוֹמָן. וְלָא נָפִיק לְעָלְמָא מֵאִינוּן מַיָא, אֶלָּא כִּמְלֹא לוֹגָא, בִּימֵי אֱלִישָׁע. וְנֶאֱמַר בָּהֶם, (מלכים ב ב׳:י״ט) וְהַמַּיִם רָעִים וְהָאָרֶץ מְשַׁכֶּלֶת. כְּלוֹמַר, בִּשְׁבִיל שֶׁהַמַּיִם רָעִים, הָאָרֶץ מְשַׁכֶּלֶת מִבְּנֵי אָדָם, שֶׁכָּלִים בִּשְׁבִילָם.</p>"],[9514011378,"<p>אָמַר רִבִּי יְהוּדָה, כּוֹלָא הַאי קְרָא מַסְהִיד עֲלֵיהּ. דְּאָמַר רִבִּי יְהוּדָה, כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא עָשָׂה דָּבָר לְבַטָלָה, וּמִפְּנֵי שֶׁהָיָה גָּלוּי לְפָנָיו, שֶׁאוֹתָם הַמַּיִם הַיּוֹצְאִים מִגֵּיהִנֹּם, וְיִתְעָרְבוּ בַּמַּיִם הָאֲחֵרִים וְיַנְזִּיקוּ בְּרִיּוֹתָיו. עָשָׂה אֶת הָרָקִיעַ, לְהִכָּנֵס בְּאֶמְצַע שְׁנֵיהֶם, לְהַבְדִּיל בֵּינְתַיִם. הֲדָא הוּא דִכְתִיב וִיהִי מַבְדִּיל בֵּין מַיִם לָמָיִם, בֵּין מַיִם הָרָעִים, לַמַּיִם הַטוֹבִים. וּבְאוֹתָהּ שָׁעָה מַמָּשׁ, שֶׁהַמַּיִם יוֹצְאִים לְהִתְעָרֵב בַּמַּיִם הַטוֹבִים, אָז הָרָקִיעַ חוֹזֵר וְנִכְנַס בֵּינְתַיִם, וּמַחֲזִירָם לְאָחוֹר.</p>"],[9514011379,"<p>תָּא שְׁמַע, אָמַר רִבִּי אֶלְעָזָר, הַנֵּי מַיָיא דְּאִינוּן לְחַיָּיא עָלְמָא, וּלְתִקּוּנֵיהוֹן דִּבְרִיָּיתָא, הֵיאַךְ יִתְקָרוֹן. אָמַר רִבִּי בְּרֶכְיָה, הַמַּיִם אֲשֶׁר מֵעַל הַשָּׁמַיִם, דְּאִינוּן מַיָיא טָבִין.</p>"],[9514011380,"<p>ר' חִיָּיא בַּר אַבָּא, הֲוָה אָזִיל בְּאוֹרְחָא, וְלָאָה מִתְּקִיפוּתָא דְּשִׁמְשָׁא, וַהֲוָה צָחֵי לְמִשְׁתֵּי מַיָא. פָּגַע בְּהַאי מַדְבְּרָא, וְאַשְׁכַּח חַד אִילָנָא, יָתִיב תְּחוֹתֵיהּ, עַד דְּזָקֵיף עֵינוֹהִי, חָמָא חַד מַעֲיָינָא דְמַיָא דָקִיק. חָדֵי לְמִשְׁתֵּי מִנְּהוֹן. שָׁתֵי מִן מַיָא, וַהֲווּ מְרִירָן, אֲמַר לְשַׁמָּשֵׁיהּ, הַיְינוּ טַעֲמָא דְר' אֶלְעָזָר, דְּאָמַר רִבִּי אֶלְעָזָר, לֵית לָךְ בְּעָלְמָא, דְּלֵית תַּמָּן תַּמְצִיתָא מֵהַהוּא סִילוֹנָא דְּגֵיהִנֹּם, בַּר אַרְעָא דְיִשְׂרָאֵל. וְאִלְמָלֵא דְּשָׁתָן כָּל עָלְמָא מֵהַהוּא תַּמְצִיתָא דְּאַרְעָא דְיִשְׂרָאֵל, לָא יָכִיל לְמִשְׁתֵּי מִנַּיְיהוּ.</p>"],[9514011381,"<p>אָמַר רִבִּי הוּנָא, הַאי רָקִיעַ דִּכְתִיב וַיַּעַשׂ אֱלֹהִים אֶת הָרָקִיעַ, הוּא הָרָקִיעַ הַיָּדוּעַ לְמַעְלָה שֶׁעַל רָאשֵׁי הַחַיּוֹת. דִּכְתִיב (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא. אָמַר רִבִּי יִצְחָק, הַאי חַיּוֹת, חַיָּה כְּתִיב חָדָא, לָמָּה נֶאֱמַר רָאשֵׁי. אָמַר רִבִּי הוּנָא, אִית חַיָּה חַד רַבָּא, וְשַׁלִּיטָא עַל כָּל שְׁאָר חֵיוָתָא קַדִּישָׁא, וְזִיוֹהִי רַבְרְבִין סַגִּיאִין. לֵיהּ רֵישִׁין דְּזִיוָוא סַגִּיאִין, וּכְדֵין כְּתִיב רָאשֵׁי הַחַיָּה. וְדָא הִיא הַחַיָּה, דְּחָמָא יְחֶזְקֵאל בְּחֵיזוּ נְבוּאָתָא. וְאִי סַלְקָא דַעְתָּךְ דְּהוּא הַחַיּוֹת. תָּא שְׁמַע, כְּתִיב (שם) וָאֵרֶא הַחַיּוֹת וְגו', חָמָא הַאי, וְחָמָא הַחַיּוֹת.</p>"],[9514011382,"<p>הַאי רָקִיעַ לְמַאי אָתָא. אָמַר רִבִּי חִזְקִיָּה, לְאַפְרָשָׁא בֵּין מַלְאָכִין קַדִּישִׁין דְּמִתְּחוֹת הַהוּא רְקִיעָא, וּבֵין מַלְאָכִין קַדִּישִׁין דְּזָכוּ דְּאִינוּן לְעֵילָא. הֲדָא הוּא דִכְתִיב, וַיַּעַש אֱלֹהִים אֶת הָרָקִיעַ וַיַּבְדֵּל בֵּין הַמַּיִם אֲשֶׁר מִתַּחַת לָרָקִיעַ וּבֵין הַמַּיִם אֲשֶׁר מֵעַל לָרָקִיעַ. בֵּין הַמַּיִם אֲשֶׁר מִתַּחַת לָרָקִיעַ, מַלְאָכַיָא דְּאִינוּן תְּחוֹת הַהוּא רְקִיעָא. וּבֵין הַמַּיִם אֲשֶׁר מֵעַל לָרָקִיעַ, מַלְאָכַיָא דְּאִינוּן מִלְּעֵילָא. אָמַר רִבִּי יִצְחָק, שְׁמַע מִינָּהּ דְּהוּא פַרְגּוֹד דְּמַפְסִיק בֵּינְתַיִם.</p>"],[9514011383,"<p>רַבִּי אֱלִיעֶזְר שָׁאַל לְרַבָּן יוֹחָנָן בֶּן זַכַּאי, אָמַר לֵיהּ, הַאי רָקִיעַ דְּאִתְבְּרֵי בַּשֵּׁנִי, מַאי הוּא, אָמַר לֵיהּ, רָזָא עִילָּאָה הוּא, דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא מְמוּנֶה תְּחוֹת יְדֵיהּ, וּבָחַר בֵּיהּ, וְשַׁלְטֵיהּ עַל כָּל חֵילֵי שְׁמַיָא, וּבְגִין הַהוּא עִנְיָנָא, לֹא נֶאֱמַר כִּי טוֹב בַּשֵּׁנִי. אַף עַל פִּי דְּשׁוּלְטָנָא יְתֵירָא אִית לֵיהּ, דְּכוֹלָא תְּחוֹת יְדֵיהּ, לְאַחֲזָאָה לְכָל עָלְמָא, דְּלֵית טִיבוּ וִיקָרָא וּפִרְקוֹנָא וְגֵאוּתָא, אֶלָּא בְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹהִי.</p>"],[9514011384,"<p>וְעוֹד אָמַר רַבָּן יוֹחָנָן בֶּן זַכַּאי, מַאי דִכְתִיב, (שיר השירים ו) אֶל גִּנַּת אֱגוֹז יָרַדְתִּי לִרְאוֹת בְּאִבֵּי הַנָּחַל. זֶהוּ מַה שֶּׁרָאָה יְחֶזְקֵאל, בְּאוֹתוֹ הָרָקִיעַ שֶׁנִּבְרָא בַּשֵּׁנִי. שֶׁבְּרָאוֹ הַקָדוֹשׁ בָּרוּךְ הוּא, וּסְתָמוֹ מִכָּל רִבְבוֹת קוֹדֶשׁ שֶׁלּוֹ. וְאוֹתָן הָעוֹלָמוֹת דְּכָסֵיף בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא, סְתָמָם מִמֶּנּוּ, וִיקַר הֲדָרוֹ סָתִים. מֵאוֹתָן עוֹלָמוֹת וּלְמַעְלָה סָתִים. וְהִטְמִין מִכּוּלָּם, וְכוּלָּם שׁוֹאֲלִים וְאוֹמְרִים, אַיֵּה מְקוֹם כְּבוֹד מַלְכוּתוֹ (יחזקאל ג) בָּרוּךְ כְּבוֹד ה' מִמְקוֹמוֹ.</p>"],[9514011385,"<p>תָּא חֲזֵי, מַאי קָאָמַר אֶל גִּנַּת אֱגוֹז יָרַדְתִּי, בְּגִנַּת אֱגוֹז לֹא כְתִיב, אֶלָּא אֶל גִּנַת אֱגוֹז. כְּמַאן דְּנָחֵית וּמַקְרִיב לְגִנְתָּא, וְלָא עַיִּיל בָּהּ, כָּל שֶׁכֵּן דְּלָא קָרֵיב לֶאֱגוֹז אֶלָּא לְגִינָּה. וְכָּל שֶׁכֵּן דְלָא חָזָא מַה שֶּׁבְּתוֹךְ הָאֱגוֹז. וְכָּל שֶׁכֵּן דְּאָמַר לִרְאוֹת, וְלֹא אָמַר רָאִיתִי. כְּלוֹמַר לַגִּינָּה שֶׁהוּא חוּצָה, קָרַבְתִּי וְיָרַדְתִּי לִרְאוֹת, וְלֹא אָמַר שֶׁרָאָה אֲפִילּוּ הַגִּינָּה שֶׁהִיא חוּצָה.</p>"],[9514011386,"<p>וְעוֹד אָמַר רַבָּן יוֹחָנָן בֶּן זַכַּאי, כַּמָּה נִצְטַעֵר הַהוּא גַבְרָא, דִּכְתִיב בֵּיהּ, (במדבר יב) לֹא כֵן עַבְדִּי משֶׁה בְּכָל בֵּיתִי נֶאֱמָן הוּא, לְמֶחֱזֵי חַד שַׁמָּשָׁא דִּמְשַׁמְּשָׁא קַמֵּיהּ, וְלָא אִיתְיְהִיבַת לֵיהּ רְשׁוּתָא, דִּכְתִיב (שמות לג) הַרְאֵנִי נָא אֶת כְּבוֹדֶךָ. אָמַר רַבָּן יוֹחָנָן בֶּן זַכַּאי, הוּא דִּכְתִיב בֵּיהּ (תהלים יט) כְּבוֹד אֵל. וְהוּא מטטרו\"ן שַׂר הַפָּנִים.</p>"],[9514011387,"<p>וְהָאֵיךָ שָׁאֵיל משֶׁה לְמֶחֱמֵי דָּא. אֶלָּא משֶׁה סָבַר, כֵּיוָן דְּחָמָא גּוּפֵיהּ אַרְבְּעִין יוֹמִין וְאַרְבְּעִין לֵילִין, דְּלָא אָכֵיל וְשָׁתֵי, וַהֲוֵי נִיזוֹן מֵאַסְפַּקְלַרְיָא דִּלְעֵילָא, סָבַר דִּכְדַאי הוּא לְמִישְׁאַל דָּא.</p>"],[9514011388,"<p>וּמָה אָתֵיב לֵיהּ, לֹא תוּכַל לִרְאוֹת אֶת פָּנָי, הוּא מָארֵיהּ דְּאַפַּיָיא, וְלָא יָהֵיב לֵיהּ רְשׁוּתָא, עַד דְּנָפַק נִשְׁמָתֵיהּ. לְקַיֵּים מַה שֶּׁנֶּאֱמַר (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי. וְכָל נִשְׁמָתָא דְצַדִּיקַיָא, אִתְיְהֵיב לֵיהּ רְשׁוּתָא לְמִנְדַע, וּלְאִדַּבְּקָא מַה דְּלָא יָכֵיל בְּעָלְמָא דֵין.</p>"],[9514011389,"<p>תָּנוּ רַבָּנָן, כָּל יוֹמָא וְיוֹמָא, קוּדְשָׁא בְּרִיךְ הוּא עָבִיד מַלְאָכִין קַדִּישִׁין, וְאִילֵין אִינוּן נִשְׁמַתְהוֹן דְּצַדִּיקַיָא. הֲדָא הוּא דִכְתִיב, (תהלים קד) עוֹשֶׂה מַלְאָכָיו רוּחוֹת מְשָׁרְתָיו אֵשׁ לוֹהֵט. עָשָׂה לֹא נֶאֱמַר, אֶלָּא עוֹשֶׂה, מַשְׁמַע שֶׁהוּא עוֹשֶׂה בְּכָל יוֹם.</p>"],[9514011390,"<p>אָמַר רִבִּי אַבָּהוּ, לֹא תִּקְשֵׁי לָךְ הַאי, דְּהָא אִית מַלְאָכִים שֶׁנִּבְרְאוּ מִכִּסֵּא הַכָּבוֹד, וְהֵם שְׁלוּחִים מְמוּנִים בִּשְׁלִיחוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. אִי שְׁאָר מַלְאָכַיָא דַּהֲווֹ מִכִּסֵּא הַכָּבוֹד כָּךְ, נִשְׁמַתְהוֹן דְּצַדִּיקַיָא דַּהֲווֹ מִתַּמָּן, וְקָיְימֵי אוֹרַיְיתָא, עַל אַחַת כַּמָּה וְכַמָּה דְּעָבִיד לְהוֹן קוּדְשָׁא בְּרִיךְ הוּא מַלְאָכִין עִילָּאִין קַדִּישִׁין.</p>"],[9514011391,"<p>אָמַר רִבִּי פִּנְחָס, כָּלַל הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָדָם אַרְבָּעָה דְבָרִים, אֵ\"שׁ רוּ\"חַ מַיִ\"ם עָפָ\"ר. אָמַר רִבִּי יְהוּדָה, וְהָא מְהוּפָּכִין אִינוּן בְּאוֹרַיְיתָא. אָמַר לֵיהּ רַבִּי פִּנְחָס, וּבְאוֹרַיְיתָא אִיכָּא אִינוּן, אָמַר לֵיהּ הֵן. וְאֵלּוּ הֵן רוּ\"חַ אֵ\"שׁ מַיִ\"ם עָפָ\"ר. תְּרֵין אִינוּן דְּאִתְגְּזָרוּ מִשַּׁמָּשַׁיָּא מִלְּעֵילָא, וּתְרֵין אִינוּן דְּאִתְגְּזָרוּ מִלְּרַע. מְנָא לָן, דִּכְתִיב (שם) עוֹשֶׂה מַלְאָכָיו רוּחוֹת, הָא רוּחַ. מְשָׁרְתָיו אֵשׁ לוֹהֵט, הָא אֵשׁ. יָסַד אֶרֶץ עַל מְכוֹנֶיהָ, כְּמַשְׁמָעוֹ. תְּהוֹם כַּלְּבוּשׁ כִּסִּיתוֹ עַל הָרִים יַעַמְדוּ מָיִם, הָא מָיִם. כָּלְהוֹ מִתְחַבְּרָן דָּא עִם דָּא, רוּחַ אֵשׁ עָפָר מַיִם. אָמַר רִבִּי פִּנְחָס, אַף עַל גַּב דְּמִתְהַפְּכֵי, לֵית לָן בָּהּ, וְשַׁפִּיר קָאָמַר רַבִּי יְהוּדָה.</p>"],[9514011392,"<p>וְאָמַר רִבִּי יְהוּדָה, כָּלְהוֹ כְּלָלָם הַקָּדוֹשׁ בָּרוּךְ הוּא בָּאָדָם. אָמַר לֵיהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲנִי בָּרָאתִי אוֹתְךָ עֶלְיוֹן, וְהִמְלַכְתִּיךָ עַל כָּל בְּרִיּוֹתַי, נָתַתִּי בְּךָ כֹּחַ מִן הַמַּלְאָכִים, וְכֹחַ מִן הַמְשָׁרְתִים, שֶׁהֵם לְמַעְלָה, וְכֹחַ הַתְּהוֹם, וְכֹחַ הָאָרֶץ, וְנָתַתִּי בְּךָ שֵׂכֶל טָהוֹר הַגָּזוּר מִכִּסְּאִי, וְאַתְּ חָטֵי קֳדָמַי.</p>"],[9514011393,"<p>אָמַר רִבִּי יִצְחָק, רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא לַעֲשׂוֹת לָאָדָם עֶלְיוֹן עַל כָּל בְּרִיּוֹתָיו, לְמֶהֱוֵי יָחִיד בְּהַאי עָלְמָא, כְּמָה דְּאִיהוּ יְחִידָאי לְעֵילָא. כֵּיוָן שֶׁחָטָא, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, הֵן הָאָדָם הָיָה כְּאַחַד מִמֶּנּוּ, הָיָה בְּדַעְתִּי לַעֲשׂוֹתוֹ כְּאֶחָד, עַכְשָׁיו, וְעַתָּה פֶּן יִשְׁלַח יָדוֹ.</p>"],[9514011394,"<p>אָמַר רִבִּי יְהוּדָה, רָקִיעַ אֶחָד עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִמֶּנּוּ נִתְהַוּוּ הַשָּׁמַיִם. שֶׁנֶּאֱמַר (בראשית א׳:ח׳) וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם. אָמַר רִבִּי יְהוּדָה, וְלֹא זוֹ בִּלְבָד, אֶלָּא כָּל מַה שֶּׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בְּמַעֲשֵׂה בְרֵאשִׁית, לֹא עָשָׂה אֶלָּא דָּבָר א' מֵהַכֹּל, וְאוֹתוֹ דָּבָר הוֹצִיא כָּל פְּעוּלוֹתָיו לְמִינוֹ, כְּגוֹן הַשָּׁמַיִם, עָשָׂה מִמֶּנּוּ אֶחָד, אוֹתוֹ הַמְשׁוּבָּח מִכֻּלָּם. וְאֶרֶץ עָשָׂה אֶחָד.</p>"],[9514011395,"<p>תָּא שְׁמַע, אָמַר רִבִּי יְהוּדָה, מֵהַכֹּל עָשָׂה אֶחָד, אוֹתוֹ הַמְשׁוּבָּח מִכּוּלָּם, וְזֶהוּ הָרָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא, שֶׁמִּמֶּנּוּ נִתְהַוּוּ הַשָּׁמַיִם. הֲדָא הוּא דִכְתִיב וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם. וְאֶרֶץ אוֹתָהּ הַמְשׁוּבַּחַת מִכּוּלָּן, וְזוֹ אֶרֶץ יִשְׂרָאֵל, וּמִמֶּנָּהּ נִתְהַוּוּ שְׁאָר הָאֲרָצוֹת, הֲדָא הוּא דִכְתִיב (משלי ח׳:כ״ו) עַד לֹא עָשָׂה אֶרֶץ וְחוּצוֹת, אֶרֶץ, זוֹ אֶרֶץ יִשְׂרָאֵל, וְחוּצוֹת, שְׁאָר הָאֲרָצוֹת שֶׁבְּחוּצָה לָאָרֶץ. הָאָדָם אֶחָד, וּמִמֶּנּוּ נִתְהַוּוּ כָּל הַשְּׁאָר, דִּכְתִיב (שם) וְרֹאשׁ עַפְרוֹת תֵּבֵל. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אָמַר רִבִּי יִצְחָק, מְנָא לָן. מֵהַאי קְרָא דְּאָמַר דָּוִד, (תהילים קמ״ח:א׳) הַלְּלוּ אֶת ה' מִן הַשָּׁמָיִם, מֵאוֹתוֹ שֶׁנַּעֲשׂוּ הַשָּׁמַיִם מִמֶּנּוּ.</p>"],[9514011396,"<p>תָּנוּ רַבָּנָן, זִמְנָא חָדָא הֲוָה אָזִיל רַבִּי יוֹחָנָן לְמֶחֱמֵי לְרַבִּי שִׁמְעוֹן, וַהֲוֵי רַבִּי יוֹסֵי אָזִיל עִמֵּיהּ, אָמַר לֵיהּ רַבִּי יוֹסֵי, לְאָן אַתְּ אָזִיל. אָמַר לֵיהּ, לְמֶחֱמֵי לְרַבִּי שִׁמְעוֹן. אָמַר, לְמָארֵי פְּלוּגְתָּא דִילָךְ, אַתְּ אָזִיל לְמֶחֱמֵי. אָמַר שְׁמַע מִינָּהּ, דְּרַבִּי שִׁמְעוֹן לְשֵׁם שָׁמַיִם קָא מִפְלִיג, וְהוֹאִיל וְכָךְ הוּא חֲבִיבוּתָא דְלִיבָּאי אִשְׁתַּכְּחַת בֵּיהּ. אַסְכִּימוּ לְמֵיזַל, וַהֲוָה לֵילְיָא, אֲמָרוּ נֵיתִיב הָכָא, עַד דְּיֵיתֵי נְהוֹרָא, וְנִתְעַסֵּק בְּאוֹרַיְיתָא, יָתְבוּ.</p>"],[9514011397,"<p>אָמַר רִבִּי יוֹחָנָן, הַאי רָקִיעַ שֶׁנִּבְרָא בַּשֵּׁנִי, הוּא הָרָקִיעַ הָעֶלְיוֹן. וְתָנָא הוּא הַפַּרְגּוֹד הַמַּפְסִיק בֵּינְתַיִם. דִּכְתִיב (יחזקאל א׳:כ״ב) וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ כְּעֵין הַקֶּרַח הַנּוֹרָא. וּמִזֶּה הָרָקִיעַ נַעֲשׂוּ כָּל שְׁאָר הָרְקִיעִים, הַסּוֹבְבִים וְשֶׁאֵינָם סוֹבְבִים, וְכוּלָּם אֲדוּקִים בָּזֶה הָרָקִיעַ, וְקָרָא לוֹ רָקִיעַ, וְקָרָא לוֹ שָׁמַיִם, דִּכְתִיב (בראשית א׳:ח׳) וַיִּקְרָא אֱלֹהִים לָרָקִיעַ שָׁמָיִם. עַל שֶׁנִּתְהַוּוּ מִמֶּנּוּ.</p>"],[9514011398,"<p>עַד דַּהֲווֹ יָתְבֵי, קָרֵיב בְּרֵיהּ דְּר' יוֹסֵי לַאֲבוּהִי, אָמַר לֵיהּ הַאי דְּאָמַר שְׁלֹמֹה, (מלכים א ח׳:ל״ט) וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם מְכוֹן שִׁבְתְּךָ, הֲוָה לֵיהּ לְמֵימַר מִן הַשָּׁמַיִם. שָׁמַע רַבִּי יוֹחָנָן, אָמַר לֵיהּ אֵימָא בְּרִי אֵימָא, דְּמִלָּה דְּפוּמָךְ מִלָּה קַדִּישָׁא הִיא. אָמַר רִבִּי יוֹסֵי, הַאי פְּסוּקָא שָׁאֵיל, וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם מְכוֹן שִׁבְתְּךָ. מִן הַשָּׁמַיִם הֲוָה לֵיהּ לְמֵימַר.</p>"],[9514011399,"<p>אָמַר לֵיהּ רַבִּי יוֹחָנָן, מִקְרָא חָסֵר הוּא, כְּמוֹ שַׁוְעַת עֲנִיִּים, הֲוָה לֵיהּ לְמֵימַר מִן עֲנִיִּים. וְכֵן צַעֲקַת עֲנָוִים, וְכֵן הַרְבֵּה. קָרֵיב לַאֲבוּהִי, וְאָמַר לֵיהּ מִלָּה שְׁמַעְנָא בֵּיהּ, אָמַר לֵיהּ רַבִּי יוֹחָנָן, אֵימָא בְּרִי אֵימָא.</p>"],[9514011400,"<p>אֲמַר, שְׁמַעְנָא דִּי בְּעִידָנָא דִּי בָּעוֹן יִשְׂרָאֵל צְלוֹתְהוֹן וּבָעוּתְהוֹן בְּבָתֵּי צְלוֹתְהוֹן, מטטרו\"ן מָארֵי דְּאַפַּיָא, נָטֵיל כָּל צְלוֹתְהוֹן דְּיִשְׂרָאֵל וְסָלֵיק לְהוֹ בְּהַאי רָקִיעַ, וְכַד בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְאַשְׁגָחָא בִּזְכוּתְהוֹן דְּיִשְׂרָאֵל, מְעַיֵּין בְּהַהוּא רְקִיעָא דְּאִתְקְרֵי שָׁמַיִם, דְּתַמָּן בָּעוּתְהוֹן דְּיִשְׂרָאֵל, וּמְרַחֵם עֲלַיְיהוּ. דִּכְתִיב וְאַתָּה תִּשְׁמַע הַשָּׁמַיִם, מַמָּשׁ. כֵּן אָמַר דָּוִד, הַלְּלוּ אֶת ה' מִן הַשָּׁמַיִם, דְּתַמָּן הוּא תּוּשְׁבַּחְתָּא דְיִשְׂרָאֵל. אָתָא ר' יוֹחָנָן וּנְשָׁקֵיהּ עַל רֵישֵׁיהּ, וּבָרְכֵיהּ, אֲמַר מַרְגְּלָא הָדָא הֲוַות תְּחוֹת יְדָיךְ, מַרְגְּלָא תְּהֵא בְּדָרָךְ.</p>"],[9514011401,"<p>אָמַר רִבִּי יִצְחָק, תָּא חֲזֵי, עָבִיד קוּדְשָׁא בְּרִיךְ הוּא הָרָקִיעַ הַזֶּה, וְעָבִיד מִנֵּיהּ שָׁמַיִם, דִּי מְמַנָּן תְּחוֹתוֹהִי, רְקִיעָא לְעֵילָא, וּשְׁמַיָיא לְתַתָּא. וְעָבַד תְּחוֹת אִלֵּין, שְׁמַיָיא אָחֳרָנִין, דְּאִתְקְרוּן רְקִיעַ הַשָּׁמַיִם, דִּמְמַנָּן בֵּיהּ כָּל בּוּצִינַיָיא דְּנָהֲרִין.</p>"],[9514011402,"<p>תָּא חֲזֵי בֵּין רְקִיעָא דָא, דְּאִתְקְרֵי רְקִיעַ הַשָּׁמַיִם, עַד הָרָקִיעַ הַנָּטוּי עַל הַחַיּוֹת, אִית תְּלַת מְאָה וְתִשְׁעִין רְקִיעִין אָחֳרָנִין, וּשְׁבַע אַלְפִין וְאַרְבַּע מְאָה וְחַמְשִׁין חוֹלְקִין, סָמְכִין אַתְּרֵין דְּבוּצִינַיָיא אוֹחֳרָנִין, וּמֵאִלֵּין בּוּצִינַיָיא נָטַל קוּדְשָׁא בְּרִיךְ הוּא וַאֲנַח בְּהַאי רְקִיעָא דִשְׁמַיָא, לְאַנְהָרָא עַל אַרְעָא.</p>"],[9514011403,"<p>פָּרָשָׁה ד (בראשית א׳:כ״ד) וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. רַבִּי בָּא פָּתַח בְּהַאי קְרָא, (ירמיהו י׳:ט״ז) לֹא כְּאֵלֶּה חֵלֶק יַעֲקֹב כִּי יוֹצֵר הַכֹּל הוּא. תָּא חֲזֵי, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, צָפָה וְרָאָה, שֶׁעֲתִידִין יִשְׂרָאֵל לַעֲמוֹד וּלְקַבֵּל תּוֹרָתוֹ, וְגָזַר מִכִּסְּאוֹ כָּל אוֹתָם הַנְּשָׁמוֹת הָעֲתִידוֹת לְהִנָּתֵן בָּהֶם.</p>"],[9514011404,"<p>וְעָשָׂה לְמַעְלָה אוֹצָר א', אֲשֶׁר כָּל הַנְּשָׁמוֹת הַגְּזוּרוֹת מִכִּסְּאוֹ, עוֹמְדוֹת שָׁם. וְקָרָא לוֹ גּוּפֵי הַנְּשָׁמוֹת. וְלָמָּה נִקְרָא גּוּף הַנְּשָׁמוֹת. אָמַר רִבִּי בָּא, מִפְּנֵי שֶׁכָּל הַנְּשָׁמוֹת כְּשֶׁיּוֹצְאוֹת מִן הָעוֹלָם הַזֶּה, עוֹשֶׂה לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא דִּיוּקְנָא שֶׁל גּוּפוֹת, כְּמוֹ שֶׁהָיוּ בָּזֶה הָעוֹלָם, וּמַנִּיחָם בָּזֶה הָאוֹצָר.</p>"],[9514011405,"<p>וְזֶה הָאוֹצָר, בְּאֵיזֶה מָקוֹם הוּא. אָמַר רִבִּי יוֹחָנָן אָמַר רִבִּי יִצְחָק, בַּמָּקוֹם שֶׁגִּנְזֵי גְשָׁמִים שָׁם, וְגִנְזֵי חַיִּים טוֹבִים, וְנִקְרָא עֲרָבוֹת. וּבַעֲרָבוֹת יֵשׁ גְּנָזִים הַרְבֵּה, וְגִנְזֵי הַנְּשָׁמוֹת שָׁם. וְהָא אָמַר רַבִּי בָּא שֶׁאוֹצָר אֶחָד הוּא, וְהָכָא תָּנִינָן גְּנָזִים.</p>"],[9514011406,"<p>אָמַר רִבִּי יוֹחָנָן, לֹא תִּקְשֵׁי לָךְ, שְׁנַיִם אוֹצָרוֹת הֵם: אוֹצַר הַנְּשָׁמוֹת, שֶׁעֲתִידִין לְהִנָּתֵן בִּבְנֵי אָדָם. דְּהָא תָּנִינָן, בְּהַהוּא צוּרָה, וּבְהַהִיא דִּיוּקְנָא מַמָּשׁ, שֶׁעָתִיד לַעֲמוֹד בָּזֶה הָעוֹלָם, בְּהַהוּא דִּיוּקְנָא הוּא שָׁם. וְנִקְרָא גּוּף הַנְּשָׁמוֹת, מִפְּנֵי שֶׁעוֹשֶׂה לָהֶם גּוּף, כְּמוֹ שֶׁעֲתִידִין לִהְיוֹת. וְאוֹצָר אֶחָד כְּנֶגְדוֹ, לְאוֹתָן הַנְּשָׁמוֹת שֶׁהָיוּ בָּעוֹלָם הַזֶּה, וְקִיְּימוּ הַתּוֹרָה, וְנִקְרָא גִּנְזֵי חַיֵּי הָעוֹלָם. וְהַיְינוּ דְּהֲוָה אָמַר רִבִּי שִׁמְעוֹן, בְּגִנְזֵי חַיֵּי עָלְמָא תְּהֵא פְּלַנְיָא, דְּנָפֵיק מֵעָלְמָא דֵין.</p>"],[9514011407,"<p>תָּנוּ רַבָּנָן, כָּל יוֹמָא וְיוֹמָא כָּרוֹזָא קָרֵי, אִתְעָרוּ בְּנֵי קַדִּישָׁא עִילָּאָה, וַעֲבִידוּ פּוּלְחָנָא דְּמָארֵיכוֹן, דְּאַפְרֵישׁ לְכוֹן מִן שְׁאָר עַמִין, וִיהַב בְּכוֹן נִשְׁמָתָא קַדִּישָׁא, דְּאִתְגְּזָרַת מִכּוּרְסֵי יְקָרֵיהּ.</p>"],[9514011408,"<p>אָמַר רִבִּי יוּדָא, אִם כֵּן שְׁאָר עַמִין, נִשְׁמַתְהוֹן מֵאָן אֲתַר. אִזְדַּמַּן לֵיהּ רַבִּי אֶלְעָזָר, אֲמַר, תָּא חֲזֵי, דִּכְתִיב (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, דָּא הִיא נִשְׁמָתָא קַדִּישָׁא, דְּאִתְגְּזָרַת מִכּוּרְסֵי יְקָרָא דְמַלְכָּא עִילָּאָה. מַאי כְּתִיב בֵּיהּ. (שם) וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה. אָמַר רִבִּי אֶלְעָזָר, זוֹ הִיא הַכֹּחַ שֶׁנִּיתַּן לַבְּהֵמוֹת וְלַחַיּוֹת וְלַדָּגִים. שֶׁנִּבְרֵאת מִן הָאֲדָמָה, דִּכְתִיב (שם א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ.</p>"],[9514011409,"<p>אָמַר רִבִּי יִצְחָק, אוֹרַיְיתָא אִתְקַבָּלַת עַל אָדָם, וַאֲמָרַת, קוּדְשָׁא בְּרִיךְ הוּא בְּרָא לְבַּר נָשׁ, וִיהַב בֵּיהּ נִשְׁמָתָא קַדִּישָׁא, לְמֶהֱוֵי לֵיהּ חַיִּין לְעָלְמָא דְאָתֵי, וְהִיא אִתְחֲזַר בְּחוֹבֵיהּ לְהַהוּא נַפְשָׁא חַיְּיתָא, דְּאִתְגְּזָרַת מִן אַרְעָא, לִבְעִירָתָא וּלְחַיָּיתָא.</p>"],[9514011410,"<p>אָמַר רִבִּי יְהוּדָה, מִמַּשְׁמַע דִּכְתִיב וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, וַיַּעֲשֵׂהוּ לֹא נֶאֱמַר, אֶלָּא וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה. מְלַמֵּד שֶׁהוּא בְּעַצְמוֹ גָּרַם, לַחֲזוֹר לְאוֹתָהּ נֶפֶשׁ הַגְּזוּרָה מֵהָאֲדָמָה.</p>"],[9514011411,"<p>אָמַר רִבִּי יוֹחָנָן, אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא, אָדָם, אֲנִי בָּרָאתִי אוֹתְךָ עֶלְיוֹן עַל כָּל בְּרִיּוֹתַי, וְנָפַחְתִּי בְּךָ נִשְׁמַת חַיִּים, הַנּוֹתֶנֶת חַיִּים לִבְעָלֶיהָ, הַגְּזוּרָה מִכִּסְּאִי. וְאַתָּה חָזַרְתָּ לְאוֹתָהּ נֶפֶשׁ חַיָּה שֶׁבָּרָאתִי מִן הָאֲדָמָה לַבְּהֵמוֹת. חַיֶּיךָ, מִכָּאן וָאֵילָךְ, כָּל הָעוֹסֵק בְּתוֹרָתִי, וְיִשְׁמוֹר אוֹתָהּ, אֶתֵּן לוֹ אוֹתָהּ הַנְּשָׁמָה הַגְּזוּרָה מִכִּסְּאִי, שֶׁהִיא נוֹתֶנֶת חַיִּים לִבְעָלֶיהָ. וְכָל אוֹתָם שֶׁלֹּא יַעַסְקוּ בְּתוֹרָתִי, יִהְיֶה חֶלְקָם בְּאוֹתָהּ נֶפֶשׁ חַיָּה שֶׁבָּחֲרוּ לְמַעַן יִכְלוּ עִמָּהּ.</p>"],[9514011412,"<p>אָמַר רִבִּי יִצְחָק, תָּא חֲזֵי, מַאי דִכְתִיב, (קהלת ג׳:כ״א) מִי יוֹדֵעַ רוּחַ בְּנֵי הָאָדָם, הָעוֹלָה הִיא לְמַעְלָה וְרוּחַ הַבְּהֵמָה הַיּוֹרֶדֶת הִיא לְמַטָה לָאָרֶץ. רוּחַ בְּנֵי הָאָדָם הָעוֹלָה הִיא לְמַעְלָה, דָּא הִיא נִשְׁמָתָא קַדִּישָׁא דְּצַדִּיקַיָּיא. וְרוּחַ הַבְּהֵמָה, דָּא הִיא נַפְשָׁא חַיְּיתָא דְּאִתְגְּזָרַת מִן אַרְעָא לִבְעִירָא, דְּתִשְׁתֵּצֵי וְתֵחוֹת לְאִשְׁתְּצָאָה מִן עָלְמָא.</p>"],[9514011413,"<p>אָמַר רִבִּי חִיָּיא, אִם כֵּן אֵין לָהֶם נְשָׁמָה לַגּוֹיִם אֶלָּא אוֹתָהּ הַנֶּפֶשׁ הַחַיָּה. אָמַר רִבִּי יוֹחָנָן כֵּן הוּא. אָמַר רִבִּי אֶלְעָזָר, וּלְיִשְׂרָאֵל מַאן יָהֲבָא. תָּוָהּ רַבִּי חִיָּיא. אָמַר רִבִּי אֶלְעָזָר תָּא חֲזֵי, דִּתְנַן בָּא לִיטָהֵר מְסַיְּיעִין אוֹתוֹ. מַאי סִיּוּעַ יָהֲבִין לֵיהּ, אֶלָּא הַהוּא נִשְׁמָתָא קַדִּישָׁא, לְמֶהֱוֵי לֵיהּ סֶמֶךְ, דְּיָהֲבִין לֵיהּ לְסַיְּיעָא לֵיהּ בְּעָלְמָא דֵין וּבְעָלְמָא דְּאָתֵי.</p>"],[9514011414,"<p>אָמַר רִבִּי אֶלְעָזָר, עַד תְּלֵיסַר שְׁנִין, אִשְׁתַּדְלוּתֵיהּ דְּבַּר נָשׁ בְּהַהוּא נֶפֶשׁ חַיָּיתָא. מִתְּלֵיסַר שְׁנִין וּלְעֵילָא, אִי בָּעֵי לְמֶהֱוֵי זַכָּאָה, יַהֲבִין לֵיהּ הַהִיא נִשְׁמָתָא קַדִּישָׁא עִלָּאָה, דְּאִתְגְּזָרַת מִכּוּרְסֵי יְקָרָא דְמַלְכָּא. אָמַר רִבִּי יְהוּדָה, הַיְינוּ טַעֲמָא דְּתָנִינָן, בִּתְלַת עָשָׂר מְכִילָן דְּרַחֲמֵי, בְּמַתְנִיתָּא דְרַבִּי אֶלְעָזָר.</p>"],[9514011415,"<p>רַבִּי שִׁמְעוֹן בֶּן יוֹחָאי, זַמִּין לְמָארֵי מַתְנִיתָּא לְמֵיכַל בִּסְעוּדָתָא רַבָּה דַּעֲבַד לְהוֹ, וְחָפָא כָּל בֵּיתָא בְּמָאנֵי דִּיקָר, וְאוֹתִיב לְרַבָּנָן בְּהַאי גִיסָא, וְהוּא בְּהַאי גִיסָא, וַהֲוָה קָא בָּדַח טוּבָא.</p>"],[9514011416,"<p>אֲמָרוּ לֵיהּ מַאי בְּדִיחוּתָא דְּמַר בְּהַאי יוֹמָא דֵּין מִשְּׁאָר יוֹמִין. אֲמַר לְהוֹ, דְּיוֹמָא דֵין נָחֲתָא נִשְׁמָתָא קַדִּישָׁא עִילָּאָה, בְּאַרְבַּע גַּדְּפִין דְּחֵיוָתָא, לְרַבִּי אֶלְעָזָר בְּרִי, וּבְהִילּוּלָא דָּא, יְהֵא לִי בְּדִיחוּתָא שְׁלֵימָתָא.</p>"],[9514011417,"<p>אוֹתְבֵיהּ לְר' אֶלְעָזָר בְּרֵיהּ לְגַבֵּיהּ, אֲמַר תִּיב בְּרִי תִּיב, דְּיוֹמָא דֵין אַתְּ קַדִּישָׁא, וּבְעַדְבָא דְקַדִּישִׁין. אָמַר רִבִּי שִׁמְעוֹן מִלָּה חַד, וְאַסְחַר אֶשָׁא בְּבֵיתָא. נָפְקֵי רַבָּנָן, חָמוּ קִיטוֹרָא דְּהֲוָה סָלֵיק מִבֵּיתָא כָּל הַהוּא יוֹמָא.</p>"],[9514011418,"<p>אָתָא רַבִּי יוֹסֵי בֶּן רִבִּי שִׁמְעוֹן בֶּן לָקוֹנְיָא, אַשְׁכַּח לְרַבָּנָן דַּהֲווֹ תְּוָוהוּ, וְקָיְימֵי בְּשׁוּקָא. אֲמַר לְהוֹ, מַאי הוּא. אֲמָרוּ לֵיהּ, חָמֵי הַאי קִיטוֹרָא מֵאֶשָׁא דִלְעֵילָא. הַאי הוּא דְקָא מַכְתִּירִין יוֹמָא דֵין, בְּכִתְרָ\"א קַדִּישָׁא לְרַבִּי אֶלְעָזָר. וְחָמוּ רַבָּנָן, אַרְבַּע גַּדְפִין דְּנִשְׁרָא, דְּנָחֲתוּ בְּאֶשָׁא, דְּאַסְחַר לֵיהּ וּלְרַבִּי שִׁמְעוֹן אֲבוּהִי. יָתֵיב תַּמָּן רַבִּי יוֹסֵי, עַד דַּאֲזַל אֶשָׁא.</p>"],[9514011419,"<p>עָאל קֳדָמוֹהִי, אָמַר לֵיהּ, אַכִּתְרָא וְסִיתְרָא, גַּבְהוּתָא עַל כֹּלָּא, הַאי הִילּוּלָא לֶהֱוֵי שְׁלֵימְתָא. אֲמַר רַבִּי שִׁמְעוֹן מַאי דַעְתִּיךְ. אָמַר רִבִּי יוֹסֵי, הָא בְּרַתִּי לְרַבִּי אֶלְעָזָר בְּרָךְ. אֲמַר וַדַּאי יְהֵא כָךְ. קָרְאוּ לְרַבָּנָן וִיהַב לֵיהּ בְּרַתֵּיהּ.</p>"],[9514011420,"<p>יָתְבֵי תַּמָּן תְּלַת יוֹמִין, וְלָעוֹ בְּאוֹרַיְיתָא קַמֵּיהּ, וְלָא שָׁבְקוּ סִתְרָא דְּמַתְנִיתִין, דְּלָא אוֹלִיף לְהוֹ רַבִּי שִׁמְעוֹן. אֲמָרוּ עָלָיו עַל ר' שִׁמְעוֹן, שֶׁלֹּא נִתְרָאֶה קֶשֶׁת בְּיָמָיו. דְּהָא הוּא סִימָנָא בְּעָלְמָא הֲוָה.</p>"],[9514011421,"<p>אָמַר רִבִּי יִצְחָק, נִשְׁמָתָא הִיא קָיְימָא בְּקִיּוּמָא לְעָלְמִין. מַה הַקָּדוֹשׁ בָּרוּךְ הוּא קַיָּים, אַף הִיא קַיֶּימֶת. אֲבָל עַל הַהִיא נַפְשָׁתָא חַיָּיתָא, אֲמַר קְרָא, (במדבר ט״ו:ל״א) הִכָּרֵת תִּכָּרֵת הַנֶּפֶשׁ הַהִיא עֲוֹנָהּ בָּהּ.</p>"],[9514011422,"<p>אָמַר רִבִּי יוֹסֵי, מַאי חָזָא אוּנְקְלוּס, דַּאֲמַר (בראשית ב׳:ז׳) וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה, וְתִרְגֵּם לְרוּחַ מְמַלְּלָא, אִי נַפְשָׁא דִּבְעִירָתָא הִיא, לָמָּה לָא מְמַלְּלָן.</p>"],[9514011423,"<p>אָמַר רִבִּי יִצְחָק, עַל דְּאִתְגַּבָּלוּן מֵעוֹבְיָיא רַבָּה דְּעַפְרָא, יַתִּיר מִבְּנֵי נָשָׁא, וְלָא זָקְפִין רֵישָׁא, וְלָא מִסְתַּכְּלִין בִּרְקִיעָא כִּבְנֵי נָשָׁא. דְּאִלּוּ אִתְגַּבָּלוּ מִקְלִילָא דְּעַפְרָא כִּבְנֵי נָשָׁא, וְזָקְפָן רֵישָׁא וְאִסְתַּכָּלוּ בִּרְקִיעָא, הֲווֹ מְמַלְּלָן.</p>"],[9514011424,"<p>אָמַר רִבִּי יוֹסֵי, גַּבָּלוּתָא וְזָקְפָן רֵישָׁא תֵּינַח, אֲבָל אִסְתַּכְּלוּתָא בִּרְקִיעָא, לְמַאי. אָמַר לֵיהּ, הַהוּא סִיּוּעָא רַבָּה דִּבְנֵי נָשָׁא. תָּא חֲזֵי, נְבוּכַדְנֶצַּר כַּד הֲוָה טָרִיד, וַהֲוָה בְּעִירָא בְּטוּרַיָיא, לָא הֲוָה לֵיהּ סִיּוּעָא, עַד דְּאִסְתַּכַּל בִּרְקִיעָא, הֲדָא הוּא דִכְתִיב, (דניאל ד׳:ל״א) אֲנָא נְבוּכַדְנֶצַּר עֵינַי לִשְׁמַיָא נָטְלַת, וּמִנְדְּעֵי עָלַי יָתֵיב. דְּעַד לָא יִסְתַּכֵּל בִּרְקִיעָא, לָא הֲוָה מִנְדְעֵיהּ עִילוּיֵהּ.</p>"],[9514011425,"<p>אָמַר רִבִּי כְּרוּסְפְּדָאי, הַגּוֹיִם וְעַמָּא דְאַרְעָא, דְּלָא מְהֵימְנֵי בְּקוּדְשָׁא בְּרִיךְ הוּא, וְלָא עָסְקֵי בְּאוֹרַיְיתָא, לֵית לְהוּ בַּר הַהִיא נַפְשָׁא חַיָּיתָא דְּאִתְנְפָקָא מֵאַרְעָא, וְעַל כָּךְ לֵית לְהוֹ מְהֵימְנוּתָא. אֲבָל יִשְׂרָאֵל דִּי מְהֵימְנֵי בְּקוּדְשָׁא בְּרִיךְ הוּא, וְעָסְקֵי בְּאוֹרַיְיתָא, וְנָטְרֵי פִּקּוּדוֹהִי, אֲמַר הַקָדוֹשׁ בָּרוּךְ הוּא, (ירמיהו י׳:ט״ז) לֹא כָּאֵלֶּה חֵלֶק יַעֲקֹב וְגו'. לֹא יְהֵי לְהוֹן נַפְשָׁא חַיָּתָא, אֲבָל מָה יְהֵא לְהוֹן. כִּי יוֹצֵר הַכֹּל הוּא. הַכֹּל: הוּא שְׁכִינְתֵּיהּ. וְאִתְגְּזָרַת נִשְׁמָתָא קַדִּישָׁא מִינָהּ, לְמֶהֱוֵי חוּלָקָא דְיַעֲקֹב. מַאי הוּא, כְּלוֹמַר, הַכֹּל הוּא נִשְׁמָתָא, הוֹאִיל וְאִתְגְּזָרַת מִינָּהּ.</p>"],[9514011426,"<p>אָמַר רִבִּי יְהוּדָה, אִי לְעֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לֵית מְהֵימְנוּתָא, הָא חֲזִינָן דְּאָזְלֵי לְטַעֲוַותְהוֹן, חִגְרִין וְסוּמִין, וּמַלְיָין מָחִין וּמַרְעִין, וְאִיתְּסָאן. אָמַר לֵיהּ, לְאוֹבָדָא לְהוֹ לְעָלְמָא דְאָתֵי, הֲדָא הוּא דִכְתִיב, (איוב י״ב:כ״ג) מַשְּׂגִיא לַגּוֹיִם וַיְאַבְּדֵם.</p>"],[9514011427,"<p>וְעוֹד, הָא תָּנִינָן (דברים כ״ח:נ״ט) וָחֳלָיִים רָעִים וְנֶאֱמָנִים, מַאי נֶאֱמָנִים. דְּעָבְדֵי מְהֵימְנוּתָא. כַּד מָטָא זִמְנָא, נָפְקֵי מֵהַהוּא גַבְרָא. וְזִמְנִין דְּאִישְׁתְּכַח לְאִינוּן טַעֲוָון. דְּאִינוּן אָזְלִין בְּמַרְעֵיהוֹן לְטַעֲוַותְהוֹן, וְאִתְּסָאן, וְאָמְרֵי דְּהַהוּא טַעֲוָותָא הוּא דְּעָבִיד.</p>"],[9514011428,"<p>וְאָמַר רִבִּי יוֹחָנָן, זִמְנָא חָדָא סָח לִי יְהוּדָאי חָד, דַּהֲווֹ לֵיהּ מַרְעִין סַגִּיאִין, וְלָא אִיתְּסֵי, חָמָא לְאִינוּן טָעְיָין דַּהֲווֹ אָזְלֵי בְּמַרְעֵיהוֹן לְטַעֲוַותְהוֹן, וְאִתְּסָאן, אֲמַר אֵיזֵיל הָתָם, וְאַף עַל גַּב דְּאִיהוּ אָסוּר, אֲבָל לְמֶחֱמֵי מַאי הוּא.</p>"],[9514011429,"<p>וְאָזַל הָתָם, וְעָאל בְּגַוַּיְיהוּ, וּבָת תַּמָּן בֵּינֵי אִינְשֵׁי דַּהֲווֹ מָחְיָין וּמַרְעִין. כָּלְהוֹ אִדְּמָכוּ, וְאִיהוּ לָא אִדְמִיךְ, עַד דְּחָמָא חַד שִׂטְנָא, דְּהֲוָה אָזֵיל בֵּינַיְיהוּ, וּמָאנֵי דְאַסְוָותָא בִּידֵיהּ, וַהֲוֵי שַׁוֵּי עַל כָּל חַד וְחַד, וְאִתְּסֵי. אַעֲבַר עֲלֵיהּ, וְלָא שַׁוֵּי עֲלֵיהּ. אָמַר לֵיהּ, מָארֵי, הָא אֲנָא מִבְּנֵי מַרְעִין שַׁוֵּי עָלַי.</p>"],[9514011430,"<p>אָמַר לֵיהּ לֹא כָּאֵלֶּה חֵלֶק יַעֲקֹב, דְּאִלֵּין אִתְפַּקָּדוּ לִי לְאוֹבָדָא לְהוֹן לְעָלְמָא דְּאָתֵי, אֲבָל בְּנוֹי דְּיַעֲקֹב לָאו כְּאִלֵּין. וּמִן קֳדָם מָה, עַל כִּי יוֹצֵר הַכֹּל הוּא. מַה הַיּוֹצֵא סָתַר וּבָנֵי, אַף הַקָּדוֹשׁ בָּרוּךְ הוּא מָחֵי וּמַסֵּי, וְסָתַר וּבָנֵי. נָפַק הַהוּא גַבְרָא, וְסָח לִי עוֹבָדָא, אֲמָרִית בְּרִיךְ רַחֲמָנָא דְּשַׁדְּרָךְ הָתָם לְמֶחֱמֵי דָא, וּלְמִשְׁמַע כְּדֵין מִפּוּמֵיהּ. וּכְדֵין סָח לִי יוֹסֵי חָרָשָׁא.</p>"],[9514011431,"<p>אָמַר רִבִּי יִצְחָק אָמַר רַב אַחָא, מַאי דִּכְתִיב (איוב ל״ב:ח׳) וְנִשְׁמַת שַׁדַּי תְּבִינֵם. אֶלָּא הַנְּשָׁמָה הִיא מְבִיאָה לָאָדָם לְהַכִּיר אֶת קוֹנוֹ, וּלְהַכְנִיסוֹ בַּתּוֹרָה וּבְמַעֲשִׂים טוֹבִים, וְאַשְׁרֵיהֶם אוֹתָם שֶׁנִּכְנָסִין בְּדֶרֶךְ הַתּוֹרָה, בְּדֶרֶךְ הַנְּשָׁמָה, שֶׁבִּשְׁבִילָהּ יִזְכּוּ לְחַיֵּי הָעוֹלָם הַבָּא, וּלְמַעֲלַת הַקְּדוֹשִׁים.</p>"],[9514011432,"<p>אָמַר רִבִּי יִצְחָק אָמַר רִבִּי אַחָא, כָּל הָעוֹסֵק בַּתּוֹרָה הוּא קוֹנֶה הַנְּשָׁמָה מֵעַצְמוֹ. הַיְינוּ דְּתָנִינָן, בָּא לִיטָהֵר מְסַיְּיעִין אוֹתוֹ. אוֹי לָהֶם לָרְשָׁעִים, שֶׁהֵם נִדְבָּקִים בְּכֹחַ הָאֲדָמָה שֶׁהִיא נִקְרֵאת נֶפֶשׁ חַיָּה הַנִּבְרֵאת מִן הָאֲדָמָה, שֶׁבִּשְׁבִילָהּ יִכְלוּ לְעוֹלָם וּלְעוֹלְמֵי עוֹלָמִים.</p>"],[9514011433,"<p>שָׁאַל רַבִּי דּוֹסְתָּאי לְרַבִּי אֱלִיעֶזְר, אָמַר לֵיהּ, אוֹתָהּ נֶפֶשׁ חַיָּה מַאי הֲוֵי מִינָהּ לְעָלְמָא דְאָתֵי. אָמַר לֵיהּ, לֹא תֵימָא הָכֵי, אֶלָּא אֵימָא מַאי הֲוֵי מִינָהּ תָּדִיר.</p>"],[9514011434,"<p>תָּא שְׁמַע, אָמַר רִבִּי בָּא, מַאי דִכְתִיב, (במדבר ט״ו:ל״א) הִכָּרֵת תִּכָּרֵת הַנֶּפֶשׁ הַהִיא. אֶלָּא כְּהֶבֶל דְּנָפֵיק מִפּוּמֵיהּ דְּבַּר נָשׁ, דְּלָא יָכִיל לְסָלְקָא לְעֵילָא, אֲפִילּוּ כִּמְלֹא עֵינָיו, וּמִיָּד תִּכְלֶה. כָּךְ הִיא אוֹתָהּ הַנֶּפֶשׁ הַחַיָּה, כְּאוֹתָהּ הֶבֶל שֶׁנִּכְרַת מִן הַפֶּה מְהֵרָה, וְתִכְלֶה, וְאֵינוֹ נִרְאֶה בָּעוֹלָם, וְהָיָה כְּלֹא הָיָה.</p>"],[9514011435,"<p>אָמַר רִבִּי יוֹסֵי, וְהָא תְּנַן נַפְשׁוֹתָם שֶׁל רְשָׁעִים הֵן הֵם הַמַּזִּיקִין שֶׁבָּעוֹלָם. אָמַר לֵיהּ ר\"י, שַׁפִּיר קָאֲמַרְתְּ, שֶׁהֵן הַמַּזִיקוֹת לְבַעֲלֵיהֶן, וּמוֹנְעוֹת כֹּחַ הַנְּשָׁמָה מֵעֲבוֹדַת בּוֹרְאָן, שֶׁאֵין מַזִּיק לָאָדָם אֶלָּא אוֹתָהּ הַנֶּפֶשׁ, עַל שֶׁנִּכְרְתָה וְכָלְתָה עִם הַגּוּף. וְאָמַר רִבִּי אַחָא, לָא תְּנַן הָכֵי, אֶלָּא נַפְשׁוֹתָם שֶׁל רְשָׁעִים כְּשֶׁיּוֹצְאוֹת מִן הַגּוּף, הֵן הֵם הַמַּזִּיקִים שֶׁבָּעוֹלָם.</p>"],[9514011436,"<p>אר\"י, וְכָךְ וְכָךְ שַׁפִּיר, כְּשֶׁיּוֹצְאוֹת מִן הַגּוּף, אָז נִמְצָא הַנֶּזֶק. וְהֵיאַךְ מַזִּיק אוֹתוֹ נֶפֶשׁ לַגּוּף. וְהַכֹּל תְּמֵהִים הֵיאַךְ הֵם אוֹתָם הַנְּפָשׁוֹת מַזִּיקִין שֶׁבָּעוֹלָם עַל שֶׁדְּבֵקִים בִּבְנֵי אָדָם.</p>"],[9514011437,"<p>תָּנוּ רַבָּנָן, אָמַר רִבִּי יְהוּדָה בַּר יַעֲקֹב, תָּמֵהַּ אֲנִי עַל אַנְשֵׁי הַדּוֹר, אִם רוּבָּם נַעֲשִׂים בְּכַשְׁרוּת. תָּא חֲזֵי, מַה כְּתִיב, (ויקרא י״א:מ״ד) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים, מְלַמֵּד שֶׁצָּרִיךְ אָדָם לְקַדֵּשׁ עַצְמוֹ בִּשְׁעַת תַּשְׁמִישׁ.</p>"],[9514011438,"<p>מַאי קִידּוּשָׁא שַׁיָּיךְ הָכָא. אָמַר רִבִּי יְהוּדָה בַּר יַעֲקֹב, שֶׁלֹּא יַעֲשׂוּ פְּרִיצוּתָא וַחֲצִיפוּתָא, וְלֹא לְשׁוּם זְנוּת כִּבְהֵמוֹת. שֶׁהַבְּהֵמוֹת אֵינָן עוֹשׂוֹת אֶלָּא לְכָךְ.</p>"],[9514011439,"<p>דְּהָא תְּנַן כָּל הַבּוֹעֵל לְשׁוּם זְנוּת, אוֹ לְשׁוּם מַה דַּאֲמָרָן, וְלֹא יִשְׁמוֹר אֶת עַצְמוֹ מֵאוֹתָן הַדְּבָרִים הַצְּרִיכִין, דְּתָנִינָן בְּמַתְנִיתָּא, הַהוּא עוּבָּרָא דְּאִתְיְילִיד, לִיהֲוֵי פָּרִיץ חָצוּף זוֹנֶה רָשָׁע, וְאֵינוֹ בִּכְלַל זֶרַע אֱמֶת.</p>"],[9514011440,"<p>וְכָל הַבּוֹעֵל לְשֵׁם מִצְוָה, וּמְקַדֵּשׁ עַצְמוֹ, וּמְכַוֵּין לִבּוֹ לְשֵׁם שָׁמַיִם. הֲווֹ לֵיהּ בְּנִין דְּמַעֲלֵי, צַדִּיקִים וַחֲסִידִים, יִרְאֵי שָׁמַיִם, קַדִּישִׁין הֲדָא הוּא דִכְתִיב, (שם) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים.</p>"],[9514011441,"<p>אָמַר רִבִּי יְהוּדָה, הָרְשָׁעִים עַל שֶׁאֵינָן מוֹלִידִים אֶלָּא לְשֵׁם זְנוּת, בְּעַזּוּת וּבַחֲצִיפוּת, אֵין לָהֶם אֶלָּא אוֹתָהּ הַנֶּפֶשׁ הַחַיָּה הַנְּתוּנָה לַבְּהֵמוֹת, שֶׁעִנְיָינָם אֵינָם אֶלָּא כִּבְהֵמָה.</p>"],[9514011442,"<p>אֲבָל צַדִּיקִים הַיּוֹדְעִים לְקַדֵּשׁ עַצְמָם, כְּתִיב בְּהוּ (ירמיהו ב׳:כ״א) וְאָנֹכִי נְטַעְתִּיךְ שׂוֹרֵק כֻּלֹּה זֶרַע אֱמֶת. מַאי אֱמֶת, אָמַר רִבִּי אַחָא, אֱמֶת בְּכָל שֶׁאֵינוֹ מְהַרְהֵר בְּאִשָּׁה אַחֶרֶת, וְיֵשׁ לוֹ אֱמֶת עִם אִשְׁתּוֹ.</p>"],[9514011443,"<p>רַב הוּנָא אָמַר, לְכַוֵּין וּלְקַדֵּשׁ עַצְמוֹ לְשֵׁם שָׁמַיִם, שֶׁנֶּאֱמַר (תהילים קכ״ז:א׳) אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ. כְּלוֹמַר, אִם אֵין הַכַּוָּנָה לְשֵׁם שָׁמַיִם, לִבְנוֹת הַבַּיִת וּלְהוֹלִיד בָּנִים, שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, שֶׁמַּכְנִיס בְּאוֹתוֹ הַוְּלַד עָמָל שֶׁל שָׁוְא. וְאֵיזֶהוּ עָמָל שֶׁל שָׁוְא. זוֹ נֶפֶשׁ חַיָּה, שֶׁתִּכְלֶה וְתִכָּרֵת, כְּהֶבֶל הַיּוֹצֵא מִן הַפֶּה, שֶׁהוּא שָׁוְא, וְהוֹאִיל וְהוּא מַכְנִיסוֹ בְּאוֹתוֹ הַוְּלַד, הֲרֵי עֲמָלוֹ שֶׁל שָׁוְא.</p>"],[9514011444,"<p>אָמַר רִבִּי יִצְחָק, אֱמֶת הוּא נוֹטָרִיקוֹן. א', אֱמֶ\"ת. מ\"ם מֵאֶרֶ\"ץ. תי\"ו, תִּצְמָ\"ח. כְּלוֹמַר (תהילים פ״ה:י״ב) אֱמֶת מֵאֶרֶץ תִּצְמָח. מַאי מַשְׁמַע, אָמַר רִבִּי יִצְחָק, בִּשְׁעַת הַחִיבּוּר, שֶׁצָּרִיךְ לִהְיוֹת שָׁם הָאֱמֶת וְהַיּוֹשֶׁר, בְּשָׁעָה שֶׁנִּתְהַוָּה מֵאֶרֶץ וְנִתְיַיסֵּד, וְלֹא בְּשָׁעָה שֶׁנִּתְגַּבֵּל. וְהַיְינוּ דְּאָמַר רַב הוּנָא, כָּל בִּנְיָן שֶׁאֵין בּוֹ יְסוֹד, אֵינוֹ כְּלוּם. וְאֵיזֶהוּ יְסוֹד, שֶׁצָּרִיךְ הָאָדָם בִּשְׁעַת הַחִיבּוּר, כִּדְקָאֲמָרָן.</p>"],[9514011445,"<p>רַבִּי זֵירָא אָמַר, זִמְנָא חָדָא הֲוָה אָזְלִינָא בְּמַדְבְּרָא, וְאַשְׁכַּחְנָא חַד עַרְבָאי, דְּהֲוָה מָטֵיל אַכִּתְפֵיהּ מְטוֹל י' סְאִין, וַהֲוָה סָבָא, וַאֲמַרְנָא לֵיהּ, חֵילָא דָא בָּעֵי לְמִלְעֵי בְּאוֹרַיְיתָא. אֲמַר, לָא עֲבָדוּ לִי אַבָּא וְאִימָּא בְּגִין כָּךְ, אֶלָּא לְעוֹבָדָא דָא.</p>"],[9514011446,"<p>דַּאֲנָא שְׁמָעִית לַאֲבוֹי דִּבְשַׁעְתָּא דְּעָבִיד לִי, דְּכִסּוּפֵיהּ לְבַר הֲוָה, דִּיְהֵא לֵיהּ חֵילָא לְאַיְיתֵי עִיבּוּרָא מִן חַקְלָא. וּבְהַאי עֵיטָא אִימְלַךְ בְּהַהִיא שַׁעֲתָא, וְהָא אֲנָא סָבָא מַאי אִיעֲבַד.</p>"],[9514011447,"<p>אָמַר רִבִּי יְהוּדָה, אַשְׁרֵי מִי שֶׁאֲבוֹתָיו הִרְהֲרוּ בְּדָבָר טוֹב. מְנָא לָן, מִן בַּת שֶׁבַע אֵם שְׁלֹמֹה, דִּקְרָא מַסְהִיד עֲלֵיהּ, שֶׁהִיא אֵם שְׁלֹמֹה מַמָּשׁ. מִשּׁוּם דְּאִתְיַיסֵיד מִמֶּנָּהּ, מֵעִנְיָינָהּ, וּמֵהִרְהוּרָהּ, וּמֵהִשְׁתַּדְּלוּתָהּ, שֶׁנֶּאֱמַר (משלי ל״א:ב׳) מַה בְּרִי וּמַה בַּר בִּטְנִי וְגו'.</p>"],[9514011448,"<p>אִימֵּיהּ תֵּינַח, אֲבוּהִי מְנָא לָן. דִּכְתִיב (תהילים קכ״ז:א׳) שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ. וְכִי שְׁלֹמֹה אָמַר זֶה הַמִּזְמוֹר. אָמַר ר\"י חַס וְשָׁלוֹם, אֶלָּא דָּוִד אֲמָרוֹ בְּרוּחַ הַקֹּדֶשׁ עַל שְׁלמֹה, בְּשָׁעָה שֶׁאָמַר הַנָּבִיא לְדָוִד, (דברי הימים א כ״ב:ט׳) הִנֵּה בֵּן נוֹלַד לְךָ כו', כִּי שְׁלֹמֹה יִהְיֶה שְׁמוֹ, אָמַר דָּוִד בֵּן אֶחָד הָיָה לִי מִבַּת שֶׁבַע, וּמֵת, עַכְשָׁיו אַחֵר יוּלַד לִי, מִן שְׁמַיָא הוּא בָּא. וְאָמַר שִׁיר זֶה, וְנִתְכַּוֵּון בּוֹ לְשׁוּם שָׁמַיִם, הֲדָא הוּא דִכְתִיב שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה, בִּשְׁבִיל שְׁלֹמֹה.</p>"],[9514011449,"<p>אָמַר אִם ה' לֹא יִבְנֶה בַּיִת, אִם סִיעָתוֹ לֹא יְסַיֵּיעַ בַּכַּוָּונָה הַשְּׁלֵימָה שֶׁלִּי, שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, לַשָּׁוְא נַעֲמוֹל כְּמוֹ שֶׁהָיָה בָּרִאשׁוֹנָה, שֶׁעָמַלְנוּ לַשָּׁוְא, וּבְגִין הַהוּא חוֹבָה מֵת. וַאֲנָא אִית לִי לְאִתְטָרְדָא מִן יְרוּשָׁלַיִם, וּבְעוֹד שֶׁאֲנִי אֵצֵא, אִם ה' לֹא יִשְׁמָר עִיר מִכָּל אָדָם, שָׁוְא שָׁקַד שׁוֹמֵר. אָמַר רִבִּי יִצְחָק, שֶׁהִנִּיחַ עֶשֶׂר נָשִׁים פִּילַּגְּשִׁים לִשְׁמוֹר הַבַּיִת, וַהֲוָה מַה דְּהֲוָה. וְעַל כָּל פָּנִים, שָׁוְא שָׁקַד שׁוֹמֵר.</p>"],[9514011450,"<p>אָמַר רִבִּי יְהוּדָה, בִּשְׁבִיל שְׁלֹמֹה נֶאֱמַר שִׁיר זֶה, שֶׁנִּתְכַּוֵּון דָּוִד עָלָיו לְשׁוּם שָׁמַיִם. וְאִמּוֹ ג\"כ נִתְכַּוְּונָה לְשׁוּם שָׁמַיִם. וְיָצָא מֵהֶם שְׁלֹמֹה, דִּכְתִיב בֵּיהּ (דברי הימים א כט) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ. אָמַר רִבִּי יִצְחָק, לְפִיכָךְ נִקְרָא (משלי לא) לְמוּאֵל, מַאי לְמוּאֵל, כְּמוֹ לְמוֹ פִי. מְלַמֵּד, שֶׁשְּׁנֵיהֶם נִתְכַּוְּנוּ לְמוֹ אֵל.</p>"],[9514011451,"<p>וּמִכָאן לָמַדְנוּ, כָּל הַמִּתְכַּוֵּין לְשֵׁם שָׁמַיִם. בְּאוֹתָהּ שָׁעָה, נָפִיק מִנֵּיהּ בַּר דְּמַעֲלֵי. וּמְנָא לָן, מִשְׁמוּאֵל, שֶׁנִּתְכַּוְּונָה אִמּוֹ עָלָיו תָּמִיד לְשׁוּם שָׁמַיִם, דִּכְתִיב (שמואל א א) וּנְתַתִּיו לַה', וְכֵן (שם ב) אֶל הַנַּעַר הַזֶּה הִתְפַּלָּלְתִּי. וְכֵן אָמַר דָּוִד, אִם יִהְיֶה לִי הַבֵּן הַזֶּה, מִכָּאן יִהְיֶה זָמִין לְמוּאֵ\"ל. כְּלוֹמַר, נָתוּן הוּא לָאֵל.</p>"],[9514011452,"<p>תָּנוּ רַבָּנָן, אָמַר רִבִּי יוֹסֵי בֶּן פַּזִּי, זִמְנָא חָדָא הֲוֵינָא אָזֵיל בְּאוֹרְחָא, וְעַרְעָנָא בְּהַהוּא טוּרָא דִּכְפַר קַרְדוֹ, וַהֲווּ גּוּבְרֵי בְּדִיחֵי בְּחוּלָקֵיהוֹן, וּבָאִית תַּמָּן לֵילְיָא דְשַׁבַּתָּא, וַאֲפוּקֵי שַׁבַּתָּא. וַחֲמֵיתִי לְאוּשְׁפִּיזָאי דְּהֲוָה בָּעֵי לְמִשְׁכַּב עִם דְּבִיתְהוּ, קָאִים הַאי מֵהַךְ גִּיסָא וְצַלֵּי, וְקָמַת הִיא מֵהָאֵיךְ גִּיסָא וְצַלַּת. אַמְרֵינָא לְהוֹן, מַאי צְלוֹתְכוֹן בְּשַׁעֲתָא דָא.</p>"],[9514011453,"<p>אֲמָרוּ לִי, עִידָּנָא דִידָן, לְזִוּוּגָא מִשַּׁבָּת לְשַׁבָּת, וּמְצַלֵּינָן צְלוֹתָנָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דִּיהֵא לָנָא בַּר, דְּיִפְלַח פּוּלְחָנֵיהּ, בַּר דָּחֵיל חַטָאָה, בַּר דְּמֶעֱבֵיד פִּיקּוּדוֹהִי, וְלָא יִסְטֵי מֵאוֹרַיְיתָא לְיָמִינָא וְלִשְׂמָאלָא. אַמְרִינָא לְהוֹ, יְהֵא רַעֲוָא דִּיהֵא לְכוֹן בָּעוּתְכוֹן, דְּהָא לְשׁוּם שָׁמַיִם קָא עֲבִדְתִּין.</p>"],[9514011454,"<p>אָמַר רִבִּי יוֹסֵי, אֶחֱזֵי אַנְפֵּי שְׁכִינְתָּא, דִּלְבָתַר יוֹמִין עֲרָעִית תַּמָּן, וְחָזֵית הַהוּא בְּרָא דְּאִתְיְילֵיד לְהוֹ, וַהֲוָה בַּר שֶׁבַע שְׁנִין, חָמֵי לִי בְּבֵיתָא, וְלָא בָּעָא לְמַלָּלָא עִמִּי. אָמַר לֵיהּ אֲבוּהָ, זִיל לְקַמֵּיהּ, דְּגַבְרָא רַבָּא הוּא.</p>"],[9514011455,"<p>אֲמַר, מִסְתָּפֵינָא לְאִשְׁתְּעוּיֵי בַּהֲדֵיהּ, וּלְאִתְקְרָבָא עִמֵּיהּ, דְּהָא לָא יָדַעְנָא אִי אִית לֵיהּ נִשְׁמָתָא קַדִּישָׁא, אִי לָאו. דְּהָכֵי אוֹלִיף לִי מוֹרִי יוֹמָא דֵין, דְּכָל מַאן דְּלֵית לֵיהּ נִשְׁמָתָא קַדִּישָׁא, אָסוּר לְאִשְׁתְּעוּיֵי בַּהֲדֵיהּ, וּלְאִתְקָרָבָא עִמֵּיהּ. אָמַר לֵיהּ, חַס וְשָׁלוֹם, דְּגַבְרָא רַבָּא וַחֲכִימָא דְדָרָא הוּא.</p>"]]});
